INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtar', 'kurtar-burhanettin-akdag-n7t1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlahi birliğin hakkı çün kurtar

Acizi nefs ile şeytan elinden

Mizanın günahla sevabı tartar

Kurtar nefis ile şeytan elinden

Haramileyin yolumu ol bağlar

Onlara kul olan durmayıp ağlar

Yaz gelir yeşile bürünür dağlar

Kurtar nefis ile şeytan elinden

Delilin ihlasdır ehadsın birsin

Acizin halin pek ala bilirsin

Bir gün adüye neden uydun dersin

Kurtar nefis ile şeytan elinden

İçimi dışımı aşkınla doldur

Burda ağlat orda sen bizü güldür

Nefis ile şeytanı sen vurup öldür

Kurtar nefis ile şeytan elinden

Hamdülillah bizi insan yarattın

Bizim için ne nimetler donattın

Ömür verdin bizi bunda yaşattın

Kurtar nefis ile şeytan elinden

Onları tut bizi hiç azdırmasın

Senin rızan olanı bozdurmasın

Bizi doğru yoldan ol caydırmasın

Kurtar nefis ile şeytan elinden

Ey Allah''ım sensiz ona yetmez güç

Bize yaptırırlar istenmeyen suç

Zalimler toplanır başa iki üç

Kurtar nefis ile şeytan elinden

Mağfiretin diler aşık eder murat

Bizleri sen koru verme bir fırsat

Hak hukuk bilmeyen inat mı inat

Kurtar nefis ile şeytan elinden.

(31.08.2005)', 'İlahi birliğin hakkı çün kurtar Acizi nefs ile şeytan elinden Mizanın günahla sevabı tartar Kurtar nefis ile şeytan elinden Haramileyin yolu...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kurtar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Konuş ve git', 'konus-ve-git-turkan-sari-3jvhc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'konuş ve git

gözlerin öfkeli sözlerin suskun

nidaların nefretli sevgilerin frenli

konuşma ve git

beklentilerinle sen hedefi şaşan bir ok

kış günü yem arayan karınca

yaz günü düşen bir cığsın

konuş ve git

sen öfke yüklü bir bulut

çaglayan bir fırtına

akıllara zararsın

konuşma ve git

ihtimallerin bahsine

hayatını ziyan ederek

feryatların ağlarken güler gibi görünerek

sevdiğini söylerken bahse giren

son şansları haykırıp

kayıplarının hesabını

bana tutturansın

gidersin biliyorum

konuşmak önmeli değil 

susmak sana yakışandır sence', 'konuş ve git gözlerin öfkeli sözlerin suskun nidaların nefretli sevgilerin frenli konuşma ve git beklentilerinle sen hedefi şaşan bir ok kış...', ARRAY['Türk Edebiyatı','Şiir','Türkan Sarı']::text[], 8.5, '{"poet":"Türkan Sarı","poet_slug":"turkan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/konus-ve-git-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oyuncu', 'oyuncu-turkan-sari-jzcap', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'cok özledim hayeller kurdum

ben kara yazğının kara kurduyum,

normal bir kadın değilim bildiğin gibi

ben hayatın negatif enerjisiyim,

donuk yüregim sevginle dolu,

avuntularını bozan oyunu oynamam

seninle var olan yolcuyum sensiz

ben oyunun oynamayan oyuncusuyum.......', 'cok özledim hayeller kurdum ben kara yazğının kara kurduyum, normal bir kadın değilim bildiğin gibi ben hayatın negatif enerjisiyim, donuk y...', ARRAY['Türk Edebiyatı','Şiir','Türkan Sarı']::text[], 8.5, '{"poet":"Türkan Sarı","poet_slug":"turkan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/oyuncu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı kalan', 'sakli-kalan-turkan-sari-heytn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayalleri satmak varya

hedefleri negatife indirğemek

avansları tüketmek

hayatı veresiye gecirmek

hayatın pazarlığı varya

düşüncelerin bedavacılığı

ellerinden kayan hayatların

anlamını çözemediğin sırların

kayıplar varya

külhanbeyli kayıplar

dillerin söylemediği

küskünlüklerin hediyelerle

ertelendiği

hedefler vardı ya

tükenmeler önünde direnmedi

hep güldümya

ağladıklarımı bilenlerin azlığından

battaniye sıcaklığını tutmadı elim

güllerin hep vardıya

renginin kokusunu 

söylemedin

saklı kalan oldun.', 'hayalleri satmak varya hedefleri negatife indirğemek avansları tüketmek hayatı veresiye gecirmek hayatın pazarlığı varya düşüncelerin bedava...', ARRAY['Türk Edebiyatı','Şiir','Türkan Sarı']::text[], 8.5, '{"poet":"Türkan Sarı","poet_slug":"turkan-sari","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sakli-kalan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah De Daim', 'allah-de-daim-burhanettin-akdag-ermi0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşla gözümü

Yıka yüzümü

Pak et özümü

Allah de daim

Sözünü sakla

Kendini yokla

Rızai hakla

Allah de daim

Eyle çok sabrı

Hatırla kabri

Adet et fehmi

Allah de daim

Eyle hak fikri

İdesin şükrü

Çok eyle zikri

Allah de daim

Nefse hakim ol

Zikre daim ol

Rizasını bul

Allah de daim

Ferde hor bakma

Kötü ad takma

Ateşle yanma

Allah de daim

Tut doğru yolu

Ol hakkın kulu

İhsanı dolu

Allah de daim

Zikre ver dili

Boş geçme yılı

Olmadan ölü

Allah de daim

Rahmet Kur''an da

Yad et her anda

Durma bu anda

Allah de daim

Müşgül asandır

Bu hal ne haldır

Yağ ile baldır

Allah de daim

Gafletten uyan

Nar-ı aşka yan

Dilinde her an

Allah de daim

Şeytanı kör et

Allah''a yol et

Rıza talep et

Allah de daim

Azgındır zaman

Dile sen aman

Hal olsun yaman

Allah de daim

Aşık kendin bil

Affın talep kıl

Rıza ara bul

Allah de daim.

(31.08.2005)', 'Yaşla gözümü Yıka yüzümü Pak et özümü Allah de daim Sözünü sakla Kendini yokla Rızai hakla Allah de daim Eyle çok sabrı Hatırla kabri Adet e...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/allah-de-daim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendime Öğüt', 'kendime-ogut-i-sa-tekin-ne341', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen sen ol arkadaş

Yitirme güvenini

Asla eskisi gibi olamazsın 

Bu kırılma noktasıdır', 'Sen sen ol arkadaş Yitirme güvenini Asla eskisi gibi olamazsın  Bu kırılma noktasıdır...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kendime-ogut-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Say Eyle', 'say-eyle-burhanettin-akdag-omo9r', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey aşık ey aşıkan

Bu yolda ol sadıkan

Gece gündüz salikan

Allah için say eyle

Boş oturma bir nefes

Sevsinler seni herkes

Haktan gayre ümit kes

Gece gündüz say eyle

Allah çıkmasın kalbden

Seni yarattı yoktan

İste muradın haktan

Gece gündüz say eyle

Teşvişlerin yok olur

Çok sevdiğin hak olur

Ol verir kul şad olur

Gece gündüz say eyle

Bütün varlıklar anda

Kazanılırsa bunda

Rüsvay olmaz divanda

Gece gündüz say eyle

Gafil emekler boşa

Geçerse gitmez hoşa

Çal başın taştan taşa

Gece gündüz say eyle

Gel bu sözden almaya

Dostuna ram olmaya

Hak rızasın bulmaya

Gece gündüz say eyle

Herkesle hoşça geçin

Rasul havzından için

Aşık gafilsin niçin

Gece gündüz say eyle.

831.08.2005)', 'Ey aşık ey aşıkan Bu yolda ol sadıkan Gece gündüz salikan Allah için say eyle Boş oturma bir nefes Sevsinler seni herkes Haktan gayre ümit k...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/say-eyle-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selâm Söyleyin Özgür Dağlarımıza', 'sel-m-soyleyin-ozgur-daglarimiza-i-sa-tekin-2wn1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Selâm söyleyin 

Özgür dağlarımıza

Artık çağlayanlarından

Su içemeyeceğim

Koşamayacağım özgürce

Türküler söyleyemeceğim sevdam adına

Çünkü ülkem adına tutsağım', 'Selâm söyleyin  Özgür dağlarımıza Artık çağlayanlarından Su içemeyeceğim Koşamayacağım özgürce Türküler söyleyemeceğim sevdam adına Çünkü ül...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/selam-soyleyin-ozgur-daglarimiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baykuş Gagası', 'baykus-gagasi-berrak-su-rrhj2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Karanlıkta yön buluyor baykuş,

Sinsi, devrik gülümsemesiyle.

Odalar var girmek istediği,

Büyük felaketler ıslıklayacak.

Kaçışların kalk borucusu ''o''

Doğuşların denge bozucusu.

Kıyılara varacak,

Heybesinde cesetlerle.

Katmerleyecek ağıtlarda sesini.

Yasanın koyucusu ''o'' biliyor.

Vazgeçmiyor,

Yanlarında ne çiçekler eziyor, 

Görüyor,

Vazgeçmiyor.

Ama bilmiyor ki; 

Matemli sarkaçlarda,

Akşam sefaları sunuluyor sofalara...

Berrak Su', 'Karanlıkta yön buluyor baykuş, Sinsi, devrik gülümsemesiyle. Odalar var girmek istediği, Büyük felaketler ıslıklayacak. Kaçışların kalk boru...', ARRAY['Türk Edebiyatı','Şiir','Berrak Su']::text[], 8.5, '{"poet":"Berrak Su","poet_slug":"berrak-su","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/baykus-gagasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu gece ki kutlu ve Nurlu Miraç', 'bu-gece-ki-kutlu-ve-nurlu-mirac-umut-gungor-hkbr8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ellerimi açtım bak kulaç kulaç,

Bu gece ki kutlu ve nurlu Miraç,

Gönlüm ruhum sana muhtaç,

Bu gece ki kutlu ve nurlu Miraç.

Bu gece kandil meftun oldu bu dil,

Yürek mahzun gönül mutedil,

Bu gece miraç bu gece kandil,

Bu gece ki kutlu ve nurlu Miraç.', 'Ellerimi açtım bak kulaç kulaç, Bu gece ki kutlu ve nurlu Miraç, Gönlüm ruhum sana muhtaç, Bu gece ki kutlu ve nurlu Miraç. Bu gece kandil m...', ARRAY['Türk Edebiyatı','Şiir','Ümüt Güngör']::text[], 8.5, '{"poet":"Ümüt Güngör","poet_slug":"umut-gungor","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-gece-ki-kutlu-ve-nurlu-mirac-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İskele ve Ramazan', 'i-skele-ve-ramazan-ahmet-erinanc-68p2r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşluk utanıyordu

O gün

gölgede kırkbeş derece sıcaklığın öğle güneşinde

iskelenin sekizinci katında,

kaba sıva atan Ramazan''ı

hiçlik 

saçmalık

boşluk,yaşamın anlamsızlığı

seyrediyordu.

Sekizinci kat,

Yirmibeş santimlik kalas ve 

üstündekinin ayağı kaydırılınca

boşluk utanıverdi:

Ramazan''ın malasıyla kendisine kaba sıvayı attı.

Kabayı yumuşatan su fırçasıyla,

hiçliği soğuk sudan geçirdi.

Sıva süngerinin temiz yüzünü,

yaşamın anlamsızlık çıkıntılarında,okşaya okşaya 

dolaştırarak

daireler,dünyalar çizerek,ince sıvayı tamamladığında boşluk hala utanıyordu.', 'Boşluk utanıyordu O gün gölgede kırkbeş derece sıcaklığın öğle güneşinde iskelenin sekizinci katında, kaba sıva atan Ramazan''ı hiçlik  saçma...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Erinanç']::text[], 8.5, '{"poet":"Ahmet Erinanç","poet_slug":"ahmet-erinanc","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iskele-ve-ramazan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avrupa da Kolumuz Var', 'avrupa-da-kolumuz-var-sahin-kars-6zztt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Avrupa icat olalı 

Birkaç çeşit dilimiz var

Dolar, gülden, mark kazandık

Paramız var pulumuz var.

Geçti karnımızın açı

Uzattık sakalı saçı

Hep olduk politikacı

Sağımız var solumuz var.

Burada gördük her şeyi

Çoğumuz döndü köşeyi

Unuttuk  Fatma  Ayşe''yi

Yetimimiz dulumuz var.

Yarı ciddi yarı şaka

Birçoğumuz bastı faka

N''olur ödersek nafaka

Mariya dan oğlumuz var.

Çalışmak tek sorunumuz 

Garantili yarınımız

Helmut  kızdan torunumuz

Avrupada  kolumuz var.

Sokaklarda yatan mı yok

Gururunu satan mı yok

Sanki benim hatam mı yok 

Acınacak  halımız var.

Şahin der dönelim geri

Zeh''roldu gurbetin kârı

Türkiye petek biz arı

Bal yapacak gülümüz var.', 'Avrupa icat olalı  Birkaç çeşit dilimiz var Dolar, gülden, mark kazandık Paramız var pulumuz var. Geçti karnımızın açı Uzattık sakalı saçı H...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/avrupa-da-kolumuz-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Önce Vatan', 'once-vatan-sedat-kocabey-tqa0f', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu toprağa nice canlar verildi,

Haindir ülkemi satan diyorum.

Zalimler ordusu yere serildi,

Önce vatan sonra vatan diyorum.

Toprağını sürdüm ekini biçtim,

Ekmeğini yedim suyunu içtim,

Asker olmak için sıraya geçtim,

Önce vatan sonra vatan diyorum.

Bir elimde silah birinde Kur’an,

Geldi diyorlar bak şehitlik sıran,

Babam bile olsa karşımda duran,

Önce vatan sonra vatan diyorum.

Gözümü kırpar da durursam beri,

Korkar da bir adım atarsam geri,

Kalbime saplayın tüm süngüleri,

Önce vatan sonra vatan diyorum.

Mehmetçik sınırda nöbet tutuyor,

Bütün sevdikleri rahat yatıyor,

Kalbi vatan vatan diye atıyor,

Önce vatan sonra vatan diyorum.

Ağlamasın anam ağlamasın yar,

Vatan için ölmek olur mu hiç ar,

Size ahirette şefaatim var,

Önce vatan sonra vatan diyorum.

Dikkat! Önce vatan isimli bu şiirim  birçok şahıslar tarafından 

değişik linklere konu edilmiş.Sizlerden ricam şiirimi benden habersiz olarak

linklere taşımamanız.şiirin beğenilmesi beni onure etmekle birlikte,haber verilmesi takdirde daha fazla sevindirici olacağı kanaatindeyim.Haber verdiğiniz takdirde en azından bir teşekkür etme hakkınıda vermiş olursunuz.

