INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama Sakın', 'aglama-sakin-sedat-kocabey-52vbv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gönül hikâyemiz burada bitti,

Yüzüne sitemli tavrını takın.

Sana bu gitmeden son nasihatti,

İnanmam arkamdan ağlama sakın.

Kaç kere denedik olmadı işte,

Gerçekle bir oldu kurduğun düşte,

Dönüşü olmayan bu son gidişte,

İnanmam arkamdan ağlama sakın.

Sevgini kalbimde taşıyacağım,

Sensiz zor olsa da yaşayacağım,

Artık sağ yanım boş üşüyeceğim,

İnanmam arkamdan ağlama sakın.

Umutlar tükendi ömür tükendi,

Her konuştuğumuz sanki dikendi,

Tüm çıkış yolları bir bir tıkandı,

İnanmam arkamdan ağlama sakın.

Az mı çekti gönül senin elinde,

Aklından geçeni tutma dilinde,

Kıvılcım arama sönmüş külünde,

İnanmam arkamdan ağlama sakın.', 'Gönül hikâyemiz burada bitti, Yüzüne sitemli tavrını takın. Sana bu gitmeden son nasihatti, İnanmam arkamdan ağlama sakın. Kaç kere denedik ...', ARRAY['Türk Edebiyatı','Şiir','Sedat Kocabey']::text[], 8.5, '{"poet":"Sedat Kocabey","poet_slug":"sedat-kocabey","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/aglama-sakin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Paket', 'son-paket-sahin-kars-5aqhy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Feryadımız göğe çıktı

Bir kez olsun duyun bizi

Zaten düzen vurup yıktı

Gücü yeten dövün bizi.

Çalıştık  V W''de Ford''ta

Hepimizin başı dertte

Bize bir yer yokmu yurt ta

Gelir isek kovun bizi

Bize almancı dediniz

Dövüz gönderdik yediniz

Hep şey  yerine koydunuz

Birde İnsan sayın bizi.

Politika yapmam asla

Benim ne haddime haşa

Hiç olmazsa arasıra

Pof poflayın  övün bizi

Biz, ama, lakin, fakatız

Hepimiz baştan  sakatız

Uçakta ki son paketiz

Kokuşmadan yeyin bizi.', 'Feryadımız göğe çıktı Bir kez olsun duyun bizi Zaten düzen vurup yıktı Gücü yeten dövün bizi. Çalıştık  V W''de Ford''ta Hepimizin başı dertte...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/son-paket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Sebebiyye', 'ask-i-sebebiyye-sait-kucuk-b42fn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözlerim 

gözlerinle

buluştuğu gün

düştü aşkın

yüreğime

ve ardından

vuku buldu beynimde

büyük patlama

parçalandı 

her hücrem

bölündü

milyar kere

aşkının yüzü suyu

hürmetine oluştu

vucut coğrafyamda

yüz bin galeksi

ki her zerrem 

pervane kesildi

senin çevrende

mayası sen oldun

ateşin

toprağın

havanın

suyun

yaşam seninle başladı

sonsuz evrende', 'gözlerim  gözlerinle buluştuğu gün düştü aşkın yüreğime ve ardından vuku buldu beynimde büyük patlama parçalandı  her hücrem bölündü milyar ...', ARRAY['Türk Edebiyatı','Şiir','Sait Küçük']::text[], 8.5, '{"poet":"Sait Küçük","poet_slug":"sait-kucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/ask-i-sebebiyye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutsuz Çoban...', 'mutsuz-coban-mehmet-demir-atmali-yi9ul', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mutsuz Çoban

Anadolu''da garip bir çobandı,

Yoksulluk onun bağrında çıbandı.

Herşeye rağmen, namuslu biriydi,

Yalan söylemez, sözünün eriydi.

Alamanya için kağıdı geldi,

Yoksulluk yönünden, kefeni deldi.

O yayla havasına alışmıştı,

Lağımda fare gibi çalışmıştı...

Perişandı Osmanlı''nın torunu,

Köle olmuştu, eski kölelerine...

Bıyık gitti, kabak gibi kavlandı,

Alamancı bir karıyla evlendi.

Derken iki çocuk dünyaya geldi,

Çocuk Kilise''de vaftiz edildi...

Uzun zaman memlekete dönmedi,

Bir türlü vatan hasreti dinmedi.

Karıcığı evliliği duymuştu,

Çoktan yabancı bacağı deymişti...

Sılada ayrı boynuzlanıyordu,

Gurbette ayrı boynuzlanıyordu...

Billocan, Banker efendi olmuştu,

Memlekete Mercedes''le gelmişti.

Meydan veriyordu, at vermiyordu,

At veriyor, Mezhep genişliyordu...

Herkes ona acıyarak bakıyordu,

Çobansa, gözlerinden okuyordu...

Önce fakirdi ama, namusluydu...

Bu sefer zengin ama, boynuzluydu...

Avrupa üyesi böyle olmalı(!) 

Ar-namus demeden suya çalmalı(!) 

Güya yoksulluğa boyun eğmedi,

Ürküttüğü Kurbağa''yı deymedi...

Bu durum Mehmetler''e dokunuyor,

Türk''ün değerleri bir bir tükeniyor...

25.7.1980', 'Mutsuz Çoban Anadolu''da garip bir çobandı, Yoksulluk onun bağrında çıbandı. Herşeye rağmen, namuslu biriydi, Yalan söylemez, sözünün eriydi....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mutsuz-coban-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Bu Şiiri Yazdım', 'sana-bu-siiri-yazdim-sahin-kars-eitcz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine bütün anıları karşıma 

Getirip sana bu şiiri yazdım

Hasretinden  karlar yağdı başıma

Oturup sana bu şiiri yazdım.

Hayalin karşıma geldi gitmedi

Uğraştım gönlüme gücüm yetmedi

Sensizlikten yine uyku tutmadı

Oturup sana bu şiiri yazdım

Gönül sevdiğine kalmaz duygusuz

Nice gecelerim geçer uykusuz

Yine bir yetmişlik mezesiz, susuz

Bitirip sana bu şiiri yazdım.

Efkar bastı yine açtım saklımı

Senin sevgin benimkinden farklı mı? 

Hasretinle başta kalan aklımı 

Yitirip sana bu şiiri yazdım.

Görme perişandır halim bu sıra

Dilim dolaşıyor bakma kusura 

Umutları, hayalleri hasıra

Yatırıp sana bu şiiri yazdım.

Şahin''den en güzel dilekler ama

Bilemez ki nasıl iletsin sana 

Kırık dökük heceleri yan yana

Getirip sana bu şiiri yazdım.', 'Yine bütün anıları karşıma  Getirip sana bu şiiri yazdım Hasretinden  karlar yağdı başıma Oturup sana bu şiiri yazdım. Hayalin karşıma geldi...', ARRAY['Türk Edebiyatı','Şiir','Şahin Kars']::text[], 8.5, '{"poet":"Şahin Kars","poet_slug":"sahin-kars","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/sana-bu-siiri-yazdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabiha Sertel''in Mezarında', 'sabiha-sertel-in-mezarinda-orhan-uravelli-evprg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dediler ki ıssız kalan türbende

karıncalar varmış, çatlamış mermer; 

Doğacağı yeri seçemez bende,

öleceği yeri seçermiş meğer. 

Dediler ki naçiz garip soydaşın,

Yedi yıldır sonsuz uykusundadır

Dostu, arkadaşı Nazım yoldaşın

kabrinde, Hazar’ın kıyısındadır

Kiril harfleriyle taşında adın,

soyadın, malum tarihler irice.

Baş ucunda öyle dikildim kaldım, 

Yasin okudu poyraz serserice  

Görmediğim İstanbul’a, Paris’e

hayrandım, hastasıydım rokla cazın.

Aklım ermedi sırrına her neyse

Selanikli merhum kadıncağızın

Eşiniz kızınız, Paris’teymişler,

Sovyet cennetinden epey uzakta.

Hem altmış sekizde tövbe etmişler,

Tanklar çamları devirirken Prag’da

Sıcak, soğuk savaşların laneti -

Onun askeriydin artçı rütbesiz. 

Bende on sekiz yaşımın cehaleti

Yaktım Avrora’mı acı, filtresiz 

Altmış sekiz, son durak, devrim falan    

votkaya mezeydi şık törenlerde. 

Baku bir çınarsız, kubbesiz liman

Servinin gölgesi  aymaz mermerde.

(Baku 1975 - 1980)', 'Dediler ki ıssız kalan türbende karıncalar varmış, çatlamış mermer;  Doğacağı yeri seçemez bende, öleceği yeri seçermiş meğer.  Dediler ki n...', ARRAY['Türk Edebiyatı','Şiir','Orhan Uravelli']::text[], 8.5, '{"poet":"Orhan Uravelli","poet_slug":"orhan-uravelli","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sabiha-sertel-in-mezarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Omuzumdaki Masumiyet', 'omuzumdaki-masumiyet-ufuk-coban-ja9aq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir zamanlar gözleri kapalı bir sevgiydi omuzumdaki,

Bir vazgeçilmezdi masmavi gönlümdeki,

Sonunda ellerin yolunda bir umursamazlığa yüklendi,

Aldı beni yağmurlardan şimdi bir kurak yer gibi.

Günlerde hiç atmadım hasret adımlarımı,

Hiç tadmadım gecelerdeki yalnızlığımı,

Aklımda hiç kalmadı sessizliğin bakışları,

Koyamadım ellerimi yanyana, anlarlar diye sensizliğimi.

Düşlerimi bile aldın benden giderken,

Hiç birşey bırakmadın içimde bir isim bile senden.

Bilmem ki ne hatırlasın şimdi çiçeklere bakarken,

Bir papatya sen kaldın aklıma, baharı beklerken.

Gitmek bazen kalmaktan daha çok şey anlatıyor,

Bilmiyorum benim eski papatyam şimdi ne yapıyor,

Kokusunu hala duyduğum bir hüzünle,

Omuzumda hala bir masumiyet uyuyor...

25/03/2004', 'Bir zamanlar gözleri kapalı bir sevgiydi omuzumdaki, Bir vazgeçilmezdi masmavi gönlümdeki, Sonunda ellerin yolunda bir umursamazlığa yüklend...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Çoban']::text[], 8.5, '{"poet":"Ufuk Çoban","poet_slug":"ufuk-coban","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/omuzumdaki-masumiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '**Sus', 'sus-nurten-altinok-7vjof', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hoşgeldiniz 



Bu gece yanımda olabilmeliydin 

Gölgeni seyredebilmeliydim holde gezinen 

Mutfaktan bir şeyler aramalıydın ve 

Kırılmadıydı bir bardak mermerde, en kıymetlisinden 

-Canın sağ olsun, seslenebilmeliydim, - boş ver aldırma 

Yüreğinin atışını duyabilmeliydim bu gece, dalga dalga 

Şekerini karıştıran bir kaşığın bardak sesine karışmalıydı sesin 

–Sen de ister misin? 

Bu gece yanımda olabilmeliydin 

Demleyebilmeliydik zamanı seninle 

Demlenebilmeliydik 

Korumasızdır yavruları kumruların / biraz saf, uçmaya hevesli 

Taşıyamaz kanatları oysa acemi uçuşları 

En uslu dokunuşlarım gezinebilmeliydi saçlarında / düşmeden önce 

Çenenden tutup yüzünü bana doğru kaldırabilmeliydim 

Körkuyu gözlerinde dibe vurabilmeliydim özlediğim 

Kozasında büyümeliydi mavi şafak renginde ipekten bir sevgi 

Ayrılık nedir bilmemeliydi ve öğrenmemeliydi 

Ölüme bir türlü sonsuzluk dendiğini 

İbadetine diz çökmüş bir bekleyişin dualarında 

Kokun dokunuyor önce bam teline sızımın / pan flüt eşliğinde 

Arka fonda gözü kan çanağı yarasa geceler bekçim 

Resimlerinde flu bir bulut / kir beyazı, pamuk duman 

Çalmayın mavimi diyorum gözlerimin mayasından 

Acıtıyor dudaklarımı filtresinden yanan ateş 

Bu kaçıncı bilmem 

Bu kaçıncı sigaram 

Bu gece yanımda olabilmeliydin, çırılçıplak soyunup geçmişinden 

Harman yeri savrulmuş duygularıma yenik düşmüşlüğümde 

Küfürlerin binini bir paraya savurduğum bu yazgıya 

Öpebilmeliydin dudaklarımdan 

- Sus..! 

Bu gece yanımda olabilmeliydin 

İmansız bir acının terkisinde kırbaç ıslığı sesim 

..........Sus / tura 

....................bilmeliydin 

..........Sus / a 

....................bilmeliydim 

Bu gece yanımda olabilmeliydin...

 Nurten Altınok



Seslendiren:   NEG', 'Hoşgeldiniz  Bu gece yanımda olabilmeliydin  Gölgeni seyredebilmeliydim holde gezinen  Mutfaktan bir şeyler aramalıydın ve  Kırılmadıydı bir...', ARRAY['Türk Edebiyatı','Şiir','Nurten Altınok']::text[], 8.5, '{"poet":"Nurten Altınok","poet_slug":"nurten-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/sus-237-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Kuşu', 'gece-kusu-osman-karaduman-lku8r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sakın ha ardından ağlayacağımı sanma

Her batan güneşin ardından elbet bir ay doğacak

Ben senin yüzünü hep ay ışığında görmüştüm

Eminim güneşte yüzün kaybolacak...

2001 - DALYAN', 'Sakın ha ardından ağlayacağımı sanma Her batan güneşin ardından elbet bir ay doğacak Ben senin yüzünü hep ay ışığında görmüştüm Eminim güneş...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gece-kusu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Felekten bir gece*', 'felekten-bir-gece-kubilay-enginol-lvgo3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Felekten bir gece araklamalı! 

Haberi olmasın ama feleğin.

Gani mezelerde olmalı hani,

Balığın da envaisi.

Masa denize kurulmuş olsun

Ayaklarımız suda.

Muhabbete dalalım

Yüzdürelim sonra anasonda.

Söyleşelim bir ağızdan

Kâh mutlu kâh hüzünlü türküleri.

Fasıla geçelim yüreklerimiz neşeli.

İlerlerdi gece Ay’ı tef yapıp çaldılar.

Bitince şarkılar yerine astılar.

Güneş doğarken hınzırlar sizi der gibi,

Pür neşe ama yorgun sabahı selamladılar...', 'Felekten bir gece araklamalı!  Haberi olmasın ama feleğin. Gani mezelerde olmalı hani, Balığın da envaisi. Masa denize kurulmuş olsun Ayakla...', ARRAY['Türk Edebiyatı','Şiir','Kubilay Enginol']::text[], 8.5, '{"poet":"Kubilay Enginol","poet_slug":"kubilay-enginol","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/felekten-bir-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahçemde Bir Çiçek Açtı', 'bahcemde-bir-cicek-acti-cahit-pehlivan-5cmhe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Daha dündü, bahçemde geziyordum.

Ama, bütün çiçeklerim solmuştu.

Nedenini, niçinini bilemiyordum.

Ama, bütün çiçeklerim solup, yok olmuştu.

Hazan değildi mevsim, peki neden, neden? 

Soldu ki çiçeklerim. Nedenini bilmeden,

Şimdi büyük özlem çekiyorum. İçten, içten,

Çünkü çiçeklerim çok uzaklarda, senden.

Ama, o da ne? Bir çiçek açmış, bir çiçek,

Gonca, gonca gül, gül açılmıştı bir çiçek,

Tanrım! çok şaşırdım. Bulamıyorum diyecek.

Birtek kelime bile bulamıyorum, bu bir çiçek.

Evet, açan bu çiçek beni büyüledi,

Nasıl olup, nasıl açmıştı? Bu çiçek bu mevsimde,

Hem de hazan mevsiminde, bahçemde açan bir çiçekti.

Hayır artık, ömrüm ve mevsimler hazan desem de,

Bunun için oturup, ağlayıp inlesem de,

Tanrım''a şükürler olsun, bir çiçek açmıştı bahçemde.

ANKARA', 'Daha dündü, bahçemde geziyordum. Ama, bütün çiçeklerim solmuştu. Nedenini, niçinini bilemiyordum. Ama, bütün çiçeklerim solup, yok olmuştu. ...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bahcemde-bir-cicek-acti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can Ellerimiz', 'can-ellerimiz-cahit-pehlivan-iw0i1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Duyguları, düşünceleri kalemle yazan,

Duyguları, düşünceleri güllerle anlatan.

Sevgiliyede gonca, gonca gülleri uzatan,

Sizler değilsinizde, kimdir?  Can ellerimiz.

Sevgiliyi  kolkola  gezdirmek için,

Sevgilinin o, hoş kokulu zülfüne,

Çiçek takıp sevip okşamak için,

Sizlerden yararlanmıyor muyuz? Can ellerimiz.

Sevgiliye, güzel görünmek için,

Ayna karşısında kendimizi prens,

Hatta prensler, kraliçeler görmek için,

Sizlerin yardımına muhtaç değil miyiz? Can ellerimiz.

Ayna karşısında makyajımızı sizlerle,

Ayna karşısında zülfümüzü sizlerle,

Yine kostümümüzü de sizlerle,

Şekillendirmiyor muyuz? Can ellerimiz.

Her şeyi sizlerle yapar, ederiz.

Sizlerle hayır hasenata gideriz.

Sizlerle sayfalar dolusu günah işleriz,

Sonrada, sizlerin yardımı ile can ellerimiz.

Mevlamızın huzuruna gideriz.

_ Ey yüce mevlam sana açılan,

Bu aciz ve günahkar elleri boş çevirmedeyiz.

Yine sizlerle günahlarımızı bağışlarız can ellerimiz.

Mevlam duamızı kabul  ve ihsan eyleyince,

Sizleri dualarla yüzlerimize sürmez miyiz? 

Sizin tanrı huzurundan aldığınız rahmetle,

Şükrü, niyaz elleriz o, büyük, yüce Rab.

Öyle değil mi? Eller, eller  can ellerimiz.

İnsanı, insan edende sizlersiniz,

İnsanı vezir edende, rezil  edenlerde sizlersiniz,

Şah yapanda, padişah yapanda, sizlersiniz.

Şah’a tacını  giydirende sizlersiniz,

Şah’ın  başından tacını, alanda sizlersiniz  can ellerimiz.

Hem bizlere mutluluk verirsiniz. 

Hemde bizleri yerden yere vurursunuz.

Acılı anlarımızda, rakımızı duble duble içittiren,

Sigaramızı yudum yudum çekip içirttiren

Sizler değil misiniz? A! Can ellerimiz.

Bizim için canda, cananda sizlersiniz,

Canı verende alanda, hatta bağışlayanda sizlersiniz,

Toprağı, tırnak tırnak işleyip, sürende sizlersiniz.

Ürünü üretip, hasatını yapanda, bizlere bağışlayanda, can ellerimiz.

Semaya açılıp, dua edersiniz.

Toprağı karıştırıp ürün üretirsiniz.

Bu kadar meziyetlerinizin yanında

Birde silah kabzasından kavrarsınız.

Size can, kan taşıyan masum insana

Bir kurşun sıkarak, canından edersiniz, can ellerimiz.

Semaya açılıp dua etmediniz diye,

Bir damla bereket düşmedi toprağa

Açlıktan, kuraklıktan, kınağa geldi,

Sahibin olan insan evladı, sonunda can ellerimiz.

Kara sabanı toprağın bağrında,

Bir gergef gibi işlemediniz diye,

Yine açlık, sefalet geldi, başımıza bela,

Muhtaç olup, geldik kapınıza can ellerimiz.

Kıymetinizi biliriz, sizlere artık silah vermeyeceğiz.

Birinize zeytin dalı, birinize de güvercin

Mutluluk, barış ve özgürlük dolu günler için,

Yarınlara, sizlerle elele mutlu, neşeli gideceğiz.

Yarınlara, güvenle bakıp ilerleyeceğiz...

Sizlerle can ellerimiz... can ellerimiz...

1987 ÇANAKKALE', 'Duyguları, düşünceleri kalemle yazan, Duyguları, düşünceleri güllerle anlatan. Sevgiliyede gonca, gonca gülleri uzatan, Sizler değilsinizde,...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/can-ellerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalkavuklar', 'dalkavuklar-cahit-pehlivan-hiwus', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Divana çıkıp bende bir insanım desen

Çevremdekilerin hepsi “estağfurullah” diyorlar.

O halde bana niçin “hor” bakıyorsunuz desem.

Bizim ne haddimize bey ağabeyim billahi derler.

Divandaki dalkavuk dostlarımdır bunlar.

Bunlardan fazlasını beklemem hiçbir zaman

Onlar ağustos böceği gibi olan yaşantılarının,

Sözle, sazla, tadını çıkarmak istiyorlar, her an.

Atalarımız “bal yiyen baldan usanır” demişler hani,

Bize de öyle oldu. Bu dalkavuklardan bıktım şimdi.

İstemiyorum onlara ait olan ne estağfurullahlarını,

Ne de bir işime yaramayan ne haddimize bey ağabeyi.

Görmek, bilmek ve tanımak istiyorum artık diğerlerini,

Sormaktan da korkuyorum onlardaki gerçekleri,

Can dostumun birisi ağla gözyaşlarında bulursun dedi.

Gece gündüz onlarla geçen boş zamanlarıma,

Onların boş sözlerini, bir hiç uğruna dinlediğime,

Ağlıyorum onlara, intizarlarda buluna buluna,

Hemde en karanlık gecelerden, en aydınlık sabahlara...

15 MAYIS 1986 ÇANAKKALE', 'Divana çıkıp bende bir insanım desen Çevremdekilerin hepsi “estağfurullah” diyorlar. O halde bana niçin “hor” bakıyorsunuz desem. Bizim ne h...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dalkavuklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amaçsız Yaşamak', 'amacsiz-yasamak-cahit-pehlivan-14oh9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dünyaya niçin getirdiler beni? 

Sebepleri ne idi? Hizmetleri ne idi? 

Bilmiyorum. Niçin yaşama davet ettiler beni? 

Sanki kendileri bu yaşamdan, zevk mi alıyorlar ki? 

Geldim sizin olan bu dümensiz yere,

Belli değil; kim nerede, ne iş peşinde? 

Herkes bir şeyin kavgasını vermekte,

Anlamsız, anlamsız yaşamlarını sürdürmekte 

Büyük küçük bütün insanların amacı,

Gece gündüz on parmakları ile kazandıklarını,

Yine on parmakları ile savurmak mı? 

Kimse bilmiyor, bu işin getireceklerini,

Hepside günlük yaşıyor, sanıyorum.

Çünkü nerede akşam, orada sabah yaparak,

Yaşamak istediklerini görüyorum.

Ne gelecek günü, nede sonrasını düşünen yok,

Yalanla, dolanla hayatını idame ettiriyorlar,

Onların böylesine amaçsız yaşamaları ile ilgilenen de yok.

03 KASIM 1985 ÇANAKKALE', 'Dünyaya niçin getirdiler beni?  Sebepleri ne idi? Hizmetleri ne idi?  Bilmiyorum. Niçin yaşama davet ettiler beni?  Sanki kendileri bu yaşam...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/amacsiz-yasamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anaları Ağlatmayınız', 'analari-aglatmayiniz-cahit-pehlivan-4i2od', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kimler gelip geçti,

Şimdi bu kâbusun beraberinde getirdiği,

Karabasanlardan.

Her siyasetçimiz maşallah bir söz cambazı,

Yaydığı pis kokuları çektirmek için dahi,

Hiçbir zaman kullanmazlar davlumbazı,

Çünkü, bu şakşakçı millet ve onun yalakaları,

Sarıp sarmalarlar afakımızı,

Ne bir hesap sorulur, ne de bir söz söylenmez.

Varsa yoksa bu yalancı ve sahtekarların,

Yarattığı yalancı Dünya''yı bize sunarlar,

Alın size cennet, başka cennetlere benzemez,

Diyerek, bizi aldatıp avutuyorlar.

İstemiyorum. Direniyorum. Haykırıyorum.

Sizin yalanlarınıza inanmıyorum, diyorum.

Ama nafile, bu bilinçsiz, bu yalaka,

Bir o kadar da salaka güruhu olan bu insanlar da,

Şimdi beni susturup, onları dinliyorlar.

Ne diyeyim, siz her şeye müstahaksınız.

Ama bunların elinde bir gün mutlaka ağlayacaksınız.

Lütfen dikkat ediniz.

Karaman’ın koyunu geçince...,

Lütfen analarınızı ağlatmayınız.

MARDİN', 'Kimler gelip geçti, Şimdi bu kâbusun beraberinde getirdiği, Karabasanlardan. Her siyasetçimiz maşallah bir söz cambazı, Yaydığı pis kokuları...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/analari-aglatmayiniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elimizden Bu Gelir', 'elimizden-bu-gelir-i-brahim-necati-gunay-fgmsa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kader avladı bizi

Gören tavladı bizi

Elimizden bu gelir

Ömrümüzün sonunda

Yatarız yarin koynunda

Elimizden bu gelir

Su akar şırıl şırıl

Evlatlar pırıl pırıl

Elimizden bu gelir

Dünya devran dönecek

Bacamız hep tütecek

Elimizden bu gelir

Ateş topu vuracak

Alem bir gün son bulacak

Elimizden bu gelir

Diliniz hep tatlı olsun

Gönlünüz hep aşkla dolsun

Elimizden bu gelir

Kalem yazar dil söyler

Kader böyle gönül neyler

Elimizden bu gelir

(www.ultrailan.com)', 'Kader avladı bizi Gören tavladı bizi Elimizden bu gelir Ömrümüzün sonunda Yatarız yarin koynunda Elimizden bu gelir Su akar şırıl şırıl Evla...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/elimizden-bu-gelir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demekki Öyleymiş', 'demekki-oyleymis-cahit-pehlivan-j6dxw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İki insan bir araya geliyor.

Sonra o malum işi yapıyor.

Yine o malum süre geçiyor.

Ve... nur topu gibi bir çocuk doğuyor.

Büyütmek için, büyüklerimizde,

Sağımıza, solumuza çekinmeden ellerler de,

Sonra ne mi olur? Bu çocuk? 

Nurluğu geçer ve topluğu baki kalır.

Bunun üzerine Türk ve müslüman

Anne ve babanın çocuğu olan,

Bu insana bir sürü anlamsız yük yüklenir.

Haydi uşağım! (eşeğim)  bu yükü çek denir.

Tutar ipin ucundan çekeriz.

Çeke bildiğimiz yere kadar, götürürüz.

Arka fondan mehter marşı eşliğinde bir ses,

Vatan, millet, sakarya ünlemeleriyle,

Bu ülkeyi sevdirmeye çalışıyorlar bize,

Yok dostum, yok artık,

Maymuna gözünü açtırdık.

Yok öyle, ensesine vur lokmasını al,

Yok artık karşınızda derviş Celal,

Niye alıyorsunuz? Kime vereceksiniz? 

Bunu nereden ve nasıl kazandım bilir misiniz? 

Tarihte üç kıt’ada at koşturan ataların,

Torunları bizleriz demeyeceğiz.

Yok artık, atın topuk sesleri ile,

Raiting raporları düzenlemeyeceğiz.

Girdiğimiz her toplumda, her mecliste,

Eğri oturacağız belki, ama hep doğru söyleyeceğiz.

Ellerinde viski yudumlayan entellerin,

Bize söylediklerinin doğru olmadığını bileceğiz.

Onlara var gücümüzle GO HOME! Diyerek,

Bir an önce ülkeyi terk etmesini isteyeceğiz.

Damarlarımızdaki asil kan artık durmam diyor.

Bize gerçek diye anlatılanlar, masal gibi geliyor.

Haydi, ne duruyoruz? Elele vererek kenetlenelim.

Ve bizi biz yapan değerlere lütfen sahip çıkalım.

Enteline, magandasına, döneğine fırsat vermeyelim.

Naçiz vücutlarımızı bizlerde toprak yapalım.

Ama; Türkiye Cumhuriyeti’nin değerlerini,

Hiç ama hiç kimsenin tekeline bırakmayalım.

Bu değerleri ilelebet payidar kılalım.

Artık bir avuç ne idüğü belirsizlerin,

Nesebi bozuk, her fırsatta bize ihanet edenlerin,

Dersini verip; bir 9 eylül tarihi daha yazalım.

Bu acı gerçeklerle karşılaştıklarında yalvarırcasına,

Demek ki bu ülkenin değerleri böyle değilmiş,

Öteki Türkiye’nin değerleri, demek ki öyleymiş,

Dedirttirelim. 

Yeni 10 ncu yıl marşlarını besteleyelim.

“80 yılda 80 milyon genç yarattık her yaştan...” 

2002 KIRIKKALE', 'İki insan bir araya geliyor. Sonra o malum işi yapıyor. Yine o malum süre geçiyor. Ve... nur topu gibi bir çocuk doğuyor. Büyütmek için, büy...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/demekki-oyleymis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kayıp Kentin kayıp Çocukları', 'kayip-kentin-kayip-cocuklari-i-brahim-necati-gunay-8nitb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üç bir yanı denizlerle çevrili

Medeniyetlerin gözde merkezi

Bakınca kamaştırır gözleri

Gecenin ışıkları altında

Adeta farklı bir cennetin 

Saklı Kent’in

Taşına toprağına aldandı gönüller

Saraylarında açardı gencecik sümbüller

Bir başka öterdi bahçelerinde bülbüller

Şehri eşkiya ile doldu tirübinler

Cennet Kent’in 

Gündüzün ışıltısı ile yığılır betonlar

Gizemin ve sisin çağrıştırdığı patronlar

Güneşin doğduğu yerden seçilir kurbanlar

Avare insanlarla doldu meydanlar

Kayıp Kent’in

(www.ultrailan.com)', 'Üç bir yanı denizlerle çevrili Medeniyetlerin gözde merkezi Bakınca kamaştırır gözleri Gecenin ışıkları altında Adeta farklı bir cennetin  S...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Necati Günay']::text[], 8.5, '{"poet":"İbrahim Necati Günay","poet_slug":"i-brahim-necati-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kayip-kentin-kayip-cocuklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mümkün Değil', 'mumkun-degil-cahit-pehlivan-1lkpi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni görmek için çok uzaklardan geldim.

Gözümle, dilimle, elimle, kalbimle, her şeyimle,

Yalnızca, evet sevgilim yalnızca seni sevdim.

Ne senden başkasını sevmem, ne de ona yar olmam,

Mümkün değil...

Daha dün bana verdiğin resimlerin, şimdi masamda,

Görüyorum, bir başka zarafet ve güzellikler sultanımda,

Olmanı o kadar çok isterdim ki, şu an yanımda,

Senden başkasını ne karşımda, ne de yanı başımda istemem,

Mümkün değil...

Sen dalga dalga sevgi ve neşe yüklüsün bilirim.

Hem dünyada, hem mahşerde, bendeki bu sevgi ve aşkla,

Yalnızca evet sevgilim, yalnızca seni sevebilirim.

Hatta şakada olsa bana, başkasını da seversin diyorsun.

İki gözüm önüme aksın ki, inan senden başkasını sevmem,

Mümkün değil...

İSTANBUL', 'Seni görmek için çok uzaklardan geldim. Gözümle, dilimle, elimle, kalbimle, her şeyimle, Yalnızca, evet sevgilim yalnızca seni sevdim. Ne se...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/mumkun-degil-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Amcamdı', 'amcamdi-yasin-kurt-ubvfs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevmişti...

Uğrunda dilenmişti...

Son sözlerini söyleyemeden gitti

Amcamdı...

Ve cesetkende sevdalıydı...

Sevmişti....

Uğrunda dilenmişti...', 'Sevmişti... Uğrunda dilenmişti... Son sözlerini söyleyemeden gitti Amcamdı... Ve cesetkende sevdalıydı... Sevmişti.... Uğrunda dilenmişti......', ARRAY['Türk Edebiyatı','Şiir','Yasin Kurt']::text[], 8.5, '{"poet":"Yasin Kurt","poet_slug":"yasin-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/amcamdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandiliniz Kutlu Olsun', 'kandiliniz-kutlu-olsun-kadir-kaya-xv2ne', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Antoloji.Com'' daki gönül dostlarımızın  Miraç Kandilimizi kutlarım.Hayırlara vesile olmasını canı gönülden dua ederim.Hastalarımıza şifa,sıkıntıda olanlara rahatlık diler selam ve saygılarımı sunarım.', 'Antoloji.Com'' daki gönül dostlarımızın  Miraç Kandilimizi kutlarım.Hayırlara vesile olmasını canı gönülden dua ederim.Hastalarımıza şifa,sık...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/kandiliniz-kutlu-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen buna değersin', 'sen-buna-degersin-emre-saricicek-hmh63', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin göremiyeceğim kadar uzakta.

Sözlerin ise hala kulaklarımda.

Ben çok üzgünüm yokluğunda.

Düşlerimde hep sen varsın yanımda.

Yarınlara umutla bakan gözlerim, hep ağlamakta.

Yüreğim ise deli gibi çırpınmakta.

Yaşamla ölüm arasındaki ince çizgide, yürümekte.

Ama biliyorum, çıkıp geleceksin.

Gelmesende hep benim kalacaksın.

Çünkü bu aşk ölümsüz.

Ve sen buna değersin.', 'Gözlerin göremiyeceğim kadar uzakta. Sözlerin ise hala kulaklarımda. Ben çok üzgünüm yokluğunda. Düşlerimde hep sen varsın yanımda. Yarınlar...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-buna-degersin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yamalı Bir Aşktan Geriye Kalanlar', 'yamali-bir-asktan-geriye-kalanlar-humeyra-yilmaz-sshcw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'söndürüp bir kibrit kutusuna sakladım yangınlarımı 

ellerimde kurutulmuş yalnızlıklarımın tek heceli isyanı 

gözlerimde susuzluğumun nisan kokan şarkıları 

ve dudaklarımda senli şehri sensizliğe gömen kaderin bükülmüşlüğü kaldı

şafak rengini giyinmişti yine sabah

ve yolcusu kayıp bir yol düştü yatağıma ansızın

aklımda ölümün inadına savunmasız  inadına sarhoş karanlığı

yüreğimde ise yamalı bir aşkın iğne delikleri kaldı

kusur bulamadığım sessizlikte eridi güneşim

yağmayan yağmurlar şahidimdir ki seni sırılsıklam sevdim 

senden sonra öyle ağır yapraklar kopup gitti ki takvimlerden 

yakaladığım baharlardan geriye kuru yapraklar kaldı 

hiç kimseye dokunmadı acılarımın çırpınan kanadı 

en soğuk ve kırılgan savaşlardan payıma hasret düştü 

yitirdiğim benliğimde sen dimdik ilerlerken

bana yine bildiğim yollarda kaybolmak kaldı', 'söndürüp bir kibrit kutusuna sakladım yangınlarımı  ellerimde kurutulmuş yalnızlıklarımın tek heceli isyanı  gözlerimde susuzluğumun nisan k...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yamali-bir-asktan-geriye-kalanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Benim Doğum Günüm', 'bugun-benim-dogum-gunum-mehmet-yaldirgan-9jj5j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün benim doğum günüm,

Karanlık geçmişimi,

Dünlerime gömdüğüm,

Uyunmamış gecelerim var,

Sensiz geçen yıllarda,

Ayrılığı gördüğüm,

Bugün benim doğum günüm,

Gökyüzünde ay yarım,

Hayat yarım yaşadığım,

Bende kalan sen yarım,

Bugün benim doğum günüm,

Bir sancı var içimde,

Seni içinde yaşattığım,

Kırık dökük ve harap bir biçimde,

Bugün benim doğum günüm,

Ayrılıklar bitmeli,

Ya çözülmeli bu düğüm,

Ya da çekip gitmeli,

Bugün benim doğum günüm,

Hayatım yol alıyor,

Kederliyim ve üzgünüm,

Gönlüm aşka kanıyor.

Bugün benim doğum günüm,

Karanlık geçmişimi,

Dünlerime gömdüğüm,

Uyunmamış gecelerim var,

Sensiz geçen yıllarda,

Ayrılığı gördüğüm.

		27.08.2005

		 KAYSERİ', 'Bugün benim doğum günüm, Karanlık geçmişimi, Dünlerime gömdüğüm, Uyunmamış gecelerim var, Sensiz geçen yıllarda, Ayrılığı gördüğüm, Bugün be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaldırgan']::text[], 8.5, '{"poet":"Mehmet Yaldırgan","poet_slug":"mehmet-yaldirgan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bugun-benim-dogum-gunum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Misal', 'misal-emre-saricicek-j6z27', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir güneş misali; 

Hani güneş hergün doğar ya.

Bir yağmur misali; 

Arada sırada gözyaşı olur ya.

Bir şimşek misali; 

Parlayıp sönersin ya.

Denizler misali; 

Sevgin sonsuz olur ya.

Bir fırtına misali; 

Kavgalar hiç bitmez ya.

Gölge misali; 

Aşkın hep peşindedir ya.

Soğuk bir rüzgar misali; 

İçin ürperir ya.

Şaşkınlık misali; 

Hani elin ayağına dolaşır ya.

Ölümsüz bir sevgi misali; 

İşte buda bizimkisi...', 'Bir güneş misali;  Hani güneş hergün doğar ya. Bir yağmur misali;  Arada sırada gözyaşı olur ya. Bir şimşek misali;  Parlayıp sönersin ya. D...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/misal-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşık mıyım? (Aşık dedi)', 'asik-miyim-asik-dedi-cihan-kaya-xa9jy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşte gördüm düşü hayıra yordum

Kötü kabusları, koşturup yordum

Böyle garip hali sevene sordum

Aşık dedi, ''Uyumam ki ne bilem''

Kurşun gönle girdi yarin dilinden

Allar yükseliyor gönül ilinden

Al gelir mi dedim gözün selinden? 

Aşık dedi, ''Göremem ki ne bilem''

Bana nasip oldu öldüm yaşarken

Gizli alem gezdim diyar aşarken

Hepsine inandım size şaşarken

Aşık dedi, ''Ölemem ki ne bilem''

Garip hale düştüm aşığım sandım

Bilmeden bakıp da halime kandım

Neden küle döndüm sizinle yandım

Aşık dedi, ''Bilemem ki ne bilem''', 'Düşte gördüm düşü hayıra yordum Kötü kabusları, koşturup yordum Böyle garip hali sevene sordum Aşık dedi, ''Uyumam ki ne bilem'' Kurşun gönle ...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/asik-miyim-asik-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soruyorum', 'soruyorum-emre-saricicek-sd24g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüreğini yüreğime kattığım günden beri içime işledin.

Şimdi sensiz bir gün bile bana zulüm.

Hüküm giymiş mahkum gibi dört duvar arasında.

Düşünüyorum.

Korkularım var yenemediğim.

Sanki seni benden koparacaklarmış gibi.

Gözyaşsız içten içe ağlıyorum.

Gecelerde hüzün görüyorum.

Avunuyorum.

Bazen karanlık üzerime geliyor.

Işıl ışıl parlayan yıldızlar ümidim oluyor.

Beni bırakıp gidecekmi acaba bir gün diyorum.

Bir gün yapayalnız bırakacakmısın beni.

Soruyorum?', 'Yüreğini yüreğime kattığım günden beri içime işledin. Şimdi sensiz bir gün bile bana zulüm. Hüküm giymiş mahkum gibi dört duvar arasında. Dü...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/soruyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlat Bana Kendini.', 'anlat-bana-kendini-veysel-alkan-apyyo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anlat bana kendini, adınla başla söze.

Ne kadar da güzelsin,

Gelmez misin hiç göze? 

Gelmezsin imkansız,nazarlığın yüzlerce.

Gözledim bilki seni,

Aylarca,senelerce.

Neyin seni koruyan,kem gözlerden bakıştan? 

Yüzüme öyle bakma,

Soruşlarım meraktan.

Ben hep böyleyim işte,bir güzeli görünce.

Sorarım her şeyini,

Ta ki bıktırınca.

Kolay kolay vazgeçmem,bırakmam hiç peşini.

Ne zaman konuşursun,

O zaman kurtulursun.

Anlat bana kendini,nerde doğdun ne zaman? 

Parlamış mı gökyüzü,

Senin doğduğun o an? 

Bir ailen var mıdır,ölmüş mü anan baban? 

Benim gibi yalnız mısın,

Hiç yokmu ki akraban? 

Geceleri seyretmeyi sever misin yıldızları? 

Kalmadı mı hiç aklında,

Çocukluk anıları? 

Anlat bana kendini hiç konuşmaz mısın sen? 

Görmez misin çabamı,

Anlamadın mı beni sen? 

Çatlatacaksın beni,konuşta bir şey söyle.

Öğrenmek isterim seni,

Kendim gibi öylece.

Anlat bana kendini demekten ben yoruldum.

Ne olur bir şey söyle,

Çıldırmak üzereyim.

Susma artık konuşalım,duyayım şu sesini.

Ben önemli değilim,

Yitirdim değerimi.

Anlat bana kendini.

Beni sorma.

Seni anlat.', 'Anlat bana kendini, adınla başla söze. Ne kadar da güzelsin, Gelmez misin hiç göze?  Gelmezsin imkansız,nazarlığın yüzlerce. Gözledim bilki ...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/anlat-bana-kendini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adam Değilsin', 'adam-degilsin-halil-kesken-lrffl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne desem aynı masal, değmezsin bir kelama 

Bu son şiirim olsun, almam seni kaleme 

Şerefin beş paralık, rezilsin el aleme 

Bir selamıma bile, değen adam değilsin 

Senden hayır beklemem, gözün bürünmüş kana 

Mezar bile istemez, kıymışsan masum cana 

Ölüm sana da gelir, dönersin yaradana 

Yasin''e, Fatiha''ya, değen adam değilsin 

Giyotin’i olmuşsun, karanlık celladın sen

Sadakati, sevgiyi, kalbinden yolladın sen

Gün oldu bir bebeği, düşmanın belledin sen

Güzel bir aileye, değen adam değilsin

Türk evladı dediğin, Türk canına kıyar mı? 

Vampir olmayan insan, böyle kanla doyar mı? 

İslam; islam evine, söyle bomba koyar mı? 

Sen cehenneme bile, değen adam değilsin', 'Ne desem aynı masal, değmezsin bir kelama  Bu son şiirim olsun, almam seni kaleme  Şerefin beş paralık, rezilsin el aleme  Bir selamıma bile...', ARRAY['Türk Edebiyatı','Şiir','Halil Kesken']::text[], 8.5, '{"poet":"Halil Kesken","poet_slug":"halil-kesken","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/adam-degilsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz Güzelim, Hayalimsin', 'i-simsiz-guzelim-hayalimsin-volkan-yoruc-2iwx1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir kez daha gülümsemeni görebilseydim

Bilirmisin neleri feda ederdim? 

Bana bakıpta kısılan gözlerini ve dünya tatlısı gülümseyişini

Nasılda görmek isterdim bilirmisin? 

Şu anda gökte gezinen hilali de alırdık aramıza

Ve serpilmiş yıldızları da

Hepsini toplayıpta yakamozumuzda

Seninle, sadece seninle bu anı birkezcikte olsa paylaşmak uğruna neler vermezdim

Ah benim isimsiz güzelim

Sana duyduğum bu özlemi bilirmisin? 

Elini o hilalin altında tutmayı

O hilalin altında gözgöze bakışmayı

Kollarımızın arasında hayallere dalmayı

Koynuma dağılmış saçlarını okşamayı

Seninle, sadece seninle bu anı birkezcikte olsa paylaşmak uğruna neler vermezdim

Bilirmisin sen aslında hayalimsin

Ama sen bilmezsin

Benim isimsiz güzelim

Yüreğim, benliğim, ellerim

Nefesim, sözlerim, gözlerim

Ve isimsiz sevgim

Seninle uyusun, seninle uyansın

Seninle gülümsesin, seninle ağlasın

Ah benim isimsiz güzelim

Şimdi uykudasın, hilali göremezsin

Şimdi hülyalarında nerelerde, kimlerlesin? 

Oysa beni düşlerde görmeni nede isterdim

Bak ben hala pencerede hilalle ve seninleyim

Saat nerdeyse sabah 5 

Ve ben hala unutulmaz gülümseyişinle, hayalinleyim

Ah benim isimsiz güzelim, seni nasılda severim, bilirmisin?', 'Bir kez daha gülümsemeni görebilseydim Bilirmisin neleri feda ederdim?  Bana bakıpta kısılan gözlerini ve dünya tatlısı gülümseyişini Nasıld...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/isimsiz-guzelim-hayalimsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar Gülü', 'ruzgar-gulu-gulseren-onay-dx4ow', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Asılı kaldı 

Bulutlar gözlerimde.

Yürek denizimde 

Ne bir çırpıntı 

Nede dalgalanma var.

Eşliğinde şarkılar söyleyen 

Ağaçlar sustu.

Duruldu cilvesi yaprakların…

Soluksuz  kalmış 

Bir rüzgarsın artık,

Bense  dingin rüzgar gülü…

Sen esmedikçe,

Dönebilir miyim çevrende 

Delice pervane…

GÜLSEREN ONAY', 'Asılı kaldı  Bulutlar gözlerimde. Yürek denizimde  Ne bir çırpıntı  Nede dalgalanma var. Eşliğinde şarkılar söyleyen  Ağaçlar sustu. Duruldu...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/ruzgar-gulu-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avunurum', 'avunurum-volkan-yoruc-xduaw', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gördüğüm her çiçeği sen sanarım

Dokunamam, koklayamam

Solar sanarım, kopacak sanarım 

Uzaktan bakarda öyle avunurum

Özlerim

Hemde deliler gibi özlerim

Gördüğüm her suyu sen sanarım

Dokunamam, içemem

Kuruyacak sanarım, dökülücek sanarım

Öylece dalar, avunurum

Gördüğüm her hayali sen sanarım

Dokunamam lakin gözlerimle tutunurum

Gitme derim, ağlarım, unutamam

Öylesine herşeyi sen sanarda avunurum

Özlerim

Hemde deliler gibi özlerim

Ve bitmez bu özlem bilirim', 'Gördüğüm her çiçeği sen sanarım Dokunamam, koklayamam Solar sanarım, kopacak sanarım  Uzaktan bakarda öyle avunurum Özlerim Hemde deliler gi...', ARRAY['Türk Edebiyatı','Şiir','Volkan Yoruç']::text[], 8.5, '{"poet":"Volkan Yoruç","poet_slug":"volkan-yoruc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/avunurum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yurdagül', 'yurdagul-bolat-unsal-fhpiz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yüreğinde sevgi çiçekler açar,

Umudu şafağa eker Yurdagül.

Riyasız sözlerle gülücük saçar,

Dudağında sabır çeker Yurdagül.

Ağlasa görünmez gözünün yaşı,

Gurbette bağrına basıyor taşı,

Üzülse dost omzu arıyor başı,

Lahzadan yılları söker Yurdagül.

Kor düşmüş kalbine kadere kırgın,

Uykusuz geceler güneşe dargın

Ruhunda fırtına içinde yangın

Nar’ına ırmaklar döker Yurdagül.

Ahu’ya benziyor yolda sekişi,

Zalimi eritir bir ah çekişi,

Canlardan can alır nazlı bakışı,

Sineye ooy diye çöker Yurdagül…

                                 bolatunsal.com', 'Yüreğinde sevgi çiçekler açar, Umudu şafağa eker Yurdagül. Riyasız sözlerle gülücük saçar, Dudağında sabır çeker Yurdagül. Ağlasa görünmez g...', ARRAY['Türk Edebiyatı','Şiir','Bolat Ünsal']::text[], 8.5, '{"poet":"Bolat Ünsal","poet_slug":"bolat-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yurdagul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarım Kalan Sevda', 'yarim-kalan-sevda-emre-findik-n4rwb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yokutun hayatımda ben seni severken

Önce otobüs durağında gördüm seni

Sonra en yakın arkadaşımın yanında

Hayallerimi süslerken geceleri rüyalarımda

Aniden girdin hayatıma

İlk defa aşık oldum

Yemin ederek elini tuttum

Bırakırsam bu eli geri

Gelmesin başım beladan beri

Sonra gözlerimiz birleşti aynı noktada

Hançer gibi keskin

çiçekler gibi ince gözlerine daldım

Saatler boyunca

Gözlerine bakarken bile

Seni kaybetmekten korkuyordum

Bulmuşken kendi aynamı

Kırmaktan korkuyordum

Mutluyduk aylardır

Aylar sonra başladı kavgalar yavaş yavaş

Ateşimize su döküyordu sanki birileri

Hiç sebepsiz yereydi tartışmalar

Sonumuzu getiriyordu eski sevdalar

Veya 3. şahıslar

Hemen gel dedin bekliyorum seni,

Geldiğimde yoktun kandırdın beni

Sevmek kandırmak mı senin gibi

Yoksa gelmeyecek sevgiliyi beklemek mi benim gibi

Saatler sonra gelen mesajda saklıydı gelmemenin nedeni

Başkası var diyordun artık bekleme beni! ...

                                                                Emre Fındık', 'Sen yokutun hayatımda ben seni severken Önce otobüs durağında gördüm seni Sonra en yakın arkadaşımın yanında Hayallerimi süslerken geceleri ...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yarim-kalan-sevda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yorgun Demokrat', 'yorgun-demokrat-emre-findik-esry0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Unutmadım anne

Unutmadım verdiğim sözü

Unutamadım karşımda ağlamamak için kendini zor tutan

o iki gözü

Alışmadım anne

Alışmadım yokluğuna

Alışamadım her günün sensiz doğuşuna

Karışmadım anne

Karışmadım gecenin karanlığına

Karışamadım gidişindeki eksik yanına

Barışmadım anne

Barışamadım sessizlik içindeki çığlıkla

Yoruldum anne

Yoruldum faşistlerin kahpeliğinden

Kaçıyorum anne

Kaçıyorum artık gerçeklerden

Vuruyorlar anne

Vuruyorlar artık doğru söyleyeni

Gidiyorum anne

Gidiyorum yaşamak için ölüme

Bekle beni anne

Döneceğim bir gün ölsem bile:...........', 'Unutmadım anne Unutmadım verdiğim sözü Unutamadım karşımda ağlamamak için kendini zor tutan o iki gözü Alışmadım anne Alışmadım yokluğuna Al...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/yorgun-demokrat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen & Ben', 'sen-ben-emre-findik-kyquh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sen vardın beni anlayan

Artık sende yoksun

Bir sır vardı bilmediğim

Öğrendim yokluğunla

Bu gidişteki nispetin bana mı

Yoksa beni anlamayanlarımı

Sen de onlardan birisin artık

Gerçeklerden kaçan

Doğruyken yalan

Yanar iken sönen

Var iken yok olan SEN

Artık sende yoksun öylemi

Bakmayacaksın gözlerime

Tutmayacaksın ellerimi

Gülmeyeceksin

Ve ağlamayacaksın benimle

İki iken birdik biz saatler önce

Sen ve ben diye bir şey yoktu hani

Biz vardı ikimiz

Anlıyorum ki

Yemin ettiğimiz diller

Yazdığımız şiirler

Ve nice sözler boşa

Yolun açık olsun sevgili

SEN yoluna BEN yoluma

Umutsuz yarınlarda', 'Bir sen vardın beni anlayan Artık sende yoksun Bir sır vardı bilmediğim Öğrendim yokluğunla Bu gidişteki nispetin bana mı Yoksa beni anlamay...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-ben-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiyi Sakın Kurutma', 'sevgiyi-sakin-kurutma-halil-colak-v3lo6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dikensiz gül boşa arama

Gülü sevdiren dikendir ama

Aşkın gülü sevgidir ama

Goncada sevgiyi sakın kurutma

Halil Çolak 31.8.2005 Ankara', 'Dikensiz gül boşa arama Gülü sevdiren dikendir ama Aşkın gülü sevgidir ama Goncada sevgiyi sakın kurutma Halil Çolak 31.8.2005 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sevgiyi-sakin-kurutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüşü Yaralım', 'gulusu-yaralim-emre-findik-ivdnt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yalanmış meğer beni sevdiğin

Ölürüm sana dediğin

Ölümüne beklediğim

Sevgin yalanmış

Gece gündüz demeden

Aşkı-sevgiyi tatmadan

Beni bırakıp kaçmadan

Yaşadıklarımız yalanmış

Her şey geçti belki ama

Aşkım deyişin kulaklarımda

Resmin hala odamda

Gülüşün yaralı yüreğimde', 'Yalanmış meğer beni sevdiğin Ölürüm sana dediğin Ölümüne beklediğim Sevgin yalanmış Gece gündüz demeden Aşkı-sevgiyi tatmadan Beni bırakıp k...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gulusu-yaralim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz şiir', 'i-simsiz-siir-emre-findik-za8wo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kimi hasret çekecek

Kimi ölümüne sevecek

Dünya hali bu,

Belkide herkes sürünecek.

Kimseyi ölüp diriltmeyecek,

Kimseye torpil geçmeyecek,

Sevip,sevilmek hakkımız ama

Namusuna söz geçirmeyecek.

Kimi zaman güldürecek,

Kimi zaman düşündürecek,

Yarın ne olacağı,

Bu günden bilinmeyecek.

İşte bu anlattıklarım,

Süresi meçhul bilin,

HAYAT denilen oyun,

Yorum sizin buyurun.', 'Kimi hasret çekecek Kimi ölümüne sevecek Dünya hali bu, Belkide herkes sürünecek. Kimseyi ölüp diriltmeyecek, Kimseye torpil geçmeyecek, Sev...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/isimsiz-siir-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Altıbin dokuzyüz otuzbeş', 'altibin-dokuzyuz-otuzbes-emre-findik-h9n0o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bilmem on dokuz yıl

Kaç tane bir gece

Bildiğim bir şey var

Seni yaşadım gecelerce

Sen yokken hayatımda

Seninleydim ben bilmediğin şiirlerde

Hatta şiirlerdeki hecelerde

Dile kolay on dokuz yıl

Anılar kaldı gecelerde

Paylaşılmaz onlar

Ne gündüzle,ne seninle

Çünkü geceler yalnızlığımın kanıtı

Çünkü duygu gemisinin 

Hüzün adasındaki anları onlar

Çünkü yalnızlık Paylaşılmaz,

Paylaşılırsa yalnızlık olmaz.

Hani hatırlarmısın bir gece

Bir gece sensizken yine

Radyomun çalışmadığını

Teyp dinleyerek ağladığımı

Nereden bileceksin

Sen yoktun ki

NEYSE

Bu gece hesap yaptım

Bu gece sensiz 6935. gece

Sen anlayamazsın

Ne bu duyguyu

Nede YALNIZLIĞIMI! ! ! ! ! ! ! !', 'Bilmem on dokuz yıl Kaç tane bir gece Bildiğim bir şey var Seni yaşadım gecelerce Sen yokken hayatımda Seninleydim ben bilmediğin şiirlerde ...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/altibin-dokuzyuz-otuzbes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kandilin Mübarek Olsun Sevdiğimm', 'kandilin-mubarek-olsun-sevdigimm-esra-aksu-z2q5u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ellerini hiç tutamamanın verdiği hüzünle

keşke gözlerine baka baka söyleyebilseydim...



tutulacak elleri olmayan bi sevdaydı bizimkisi

kulaklarından tuttuk hep,sağırdı oysa.

ne yandan baksak melal 

ne yana baksak hicran kucakladı şairliğimizi.

kimin aklına gelirdi gözleri buğday tarlası küçücüğümm! 

kimin tütün kokan ellerinde yazılmıştı bizim hikayemiz? 

senin titremeyen kalbin mi...

benim uslanmayan çocuk yanım mı...

ya da sevdamıza göz koyan hain kurtların hikayesi mi bu? 

şimdi ılık rüzgarlar esiyor çamlar ardında

ruhumu yele vermişim

say ki senden bi parçayım 

say ki sıcacık tebessümüne müptelayım! 

kimin yazgısıydı ah''ını aldığımız

ve kimin yazgısına ah ettim bu gece? 

varlığına her gün değil balımm 

yokluğuna üç gün ağlayacağım 

ve seni artık bi başıma anacağım...

gidişin mübarek olsun sevdiğimm..

bi avuç gözyaşıyla uğurlar olsun sevdiğimm...

KANDİLİN MÜBAREK OLSUN  SEVDİĞİMM....', 'ellerini hiç tutamamanın verdiği hüzünle keşke gözlerine baka baka söyleyebilseydim... tutulacak elleri olmayan bi sevdaydı bizimkisi kulakl...', ARRAY['Türk Edebiyatı','Şiir','Esra Aksu']::text[], 8.5, '{"poet":"Esra Aksu","poet_slug":"esra-aksu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/kandilin-mubarek-olsun-sevdigimm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Palavra', 'palavra-emre-findik-w1jmu', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir köy varmış karşı limanda

O köyün bekçisi varmış zamanında

Milyarları varmış altın kasasında

Dolarları varmış köpeğinin tasmasında

Geceleri kazı yaparmış

Kimse görmeden köy ortasında

Görürlermiş aslında rüyalarında

Konuşurlarmış her gün köy muhtarıyla

Bir sır vereyim mi size! ! ! ! ! ! ! 

Bunların hepsi PLAVRA', 'Bir köy varmış karşı limanda O köyün bekçisi varmış zamanında Milyarları varmış altın kasasında Dolarları varmış köpeğinin tasmasında Gecele...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/palavra-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateşin', 'atesin-turk-oger-koc-6l4a8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ateşin

yakarken beni

kül olmakla

bitirmiyorki

savruluyorum

düştüğünde

toprağa

yangınlara

dönüyorum

2005', 'ateşin yakarken beni kül olmakla bitirmiyorki savruluyorum düştüğünde toprağa yangınlara dönüyorum 2005...', ARRAY['Türk Edebiyatı','Şiir','Türk Öğer Koç']::text[], 8.5, '{"poet":"Türk Öğer Koç","poet_slug":"turk-oger-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/atesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Gülüm', 'ben-gulum-nese-arsu-pta1g', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir güldüm hayatında

Kırmızı ve gonca.

Rengimi sevgi nehrinden

Goncalığımı yaşadığım ilkten,

Hayatı ise ne senden ne benden

İçimde yaşattığım sevgimden aldım.

Toprağımın ıslaklığı; nefesindi.

Işığa dönüşüm; sana yön verişimdi.

Ne dikenlerim olmalıydı aslında

Üzerimde olması gereken özelliğimde

Oysa; 

Yaprak ve dikenleri döküntülerden ibaret''çıplaktım''..

Ömrüm neye kadardı? 

Kaç mevsimliktim acaba? 

Bilemedim ve kendi kabulumle

Köklerimden koparılıp 

Seyredilmek üzere,vazolara yerleştirildim.

Koklanaraktan yerleştirildiğim yerden

Başımı tutamadım  büküldüm, süzüldüm.

Dibe düşmüş yapraklarımı selamlarcasına..', 'Bir güldüm hayatında Kırmızı ve gonca. Rengimi sevgi nehrinden Goncalığımı yaşadığım ilkten, Hayatı ise ne senden ne benden İçimde yaşattığı...', ARRAY['Türk Edebiyatı','Şiir','Neşe Arsu']::text[], 8.5, '{"poet":"Neşe Arsu","poet_slug":"nese-arsu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ben-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkularım var benim', 'korkularim-var-benim-yagiz-yuksel-4hz9o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'korkularım var benim

yüzleşirken korkulara kapıldığım..

güneşten korkuyorum..

sen benim güneşimken...

karanlıktan korkuyorum

sen uyurken..

ve bir daha sesim çıkmıyor

sabah olana dek..

sabahtan korkuyorum..

masanın üzerin de

sigara içen gölgem

seni düşünüyor..

ama beni bilmem..

korkuyor muyum..

bilmem...', 'korkularım var benim yüzleşirken korkulara kapıldığım.. güneşten korkuyorum.. sen benim güneşimken... karanlıktan korkuyorum sen uyurken.. v...', ARRAY['Türk Edebiyatı','Şiir','Yagiz Yüksel']::text[], 8.5, '{"poet":"Yagiz Yüksel","poet_slug":"yagiz-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkularim-var-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B.Kent''te İki Kişiydik', 'b-kent-te-i-ki-kisiydik-nail-yavuz-v4ett', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kent''te iki kişiydik o gece

aydınlıktı gökyüzü / aşk da öyleydi

eş zamanlı yangınlar başlamıştı

adı belliydi yaşananların

_____pusulasızdık_____

fazla sadeydik giysileri önemsemiyorduk

dudaklar öpülesi duruşlardaydı

şifresiz tetiği çekilmişti duyguların

etimizin tadını etimizden alıyorduk

_____engerekler bürünmüştük_____

ay düşmüştü tatlı kayıtsızlığımıza

iki alev çomağı ile yüzlerimizi dağlıyorduk

dizginlenemez bir duyumdu yaşamak

sevmeyi seviyorduk

_____sabahı bitirmiştik_____', 'kent''te iki kişiydik o gece aydınlıktı gökyüzü / aşk da öyleydi eş zamanlı yangınlar başlamıştı adı belliydi yaşananların _____pusulasızdık_...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/b-kent-te-iki-kisiydik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehtabında güneşin', 'mehtabinda-gunesin-emre-saricicek-hn7nu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlemin yüreğimi parçalarken,gözyaşım nehirleri taşırırken,

Ellerim ellerini ararken sana geleceğim mehtabında güneşin.

Hasret yüreğimi dağlasada,yollarım çok uzak olsada,

Dağlar önüme barikat kursada sana geleceğim mehtabında güneşin.

Hasreti bir yana bırakacağım,bir gül ile sana koşacağım,

Sana doyasıya sarılacağım,sana geleceğim mehtabında güneşin.

Yanından hiç ayrılmayacağım,ellerini asla bırakmayacağım,

Gözlerimi gözlerinden ayırmayacağım,sana geleceğim mehtabında güneşin.

Tüm sevgimi önüne sereceğim,istersen çiğne geç diyeceğim,

Özlemle o günü bekleyeceğim,seni seviyorum diyeceğim,

Mehtabında güneşin.', 'Özlemin yüreğimi parçalarken,gözyaşım nehirleri taşırırken, Ellerim ellerini ararken sana geleceğim mehtabında güneşin. Hasret yüreğimi dağl...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/mehtabinda-gunesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'B. Yedinci Gün', 'b-yedinci-gun-nail-yavuz-uk29o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öfke yansımasıyla zincirlenmiş sırları 

başka bir çağdan gelmiş ölçülü adımlar 

tarihsiz dönemlerin karanlık göçlerinde 

övgüsüz zamanların yıldızlarıymış 

şaşkın yüzlü mumyalar 

ölmek dediğimiz şey kesin ölümdür 

denizlerini kirletmiş korsan şarkıları 

_____ sonrasız zaman 

yaralamış suyun sevincini 

ve yedinci günün birlikteliğini 

yılan derisinde orman rengi desenler 

gece kelebeği kanatlarında 

________benekli pullar 

aşkları örgütleyen seher vakti 

dönüş yolunun anahtarı 

yapraklar gün batımının rengine dönüşmüş 

süzülen yarı karanlıkta/duyumsanan sessizlik 

___________ sus pus 

gökyüzü de yalancı/ görkemli yalnızlığı da 

kimim var kiminle paylaşayım yedinci günü 

Nail Yavuz İzmir, 24.04.2005', 'öfke yansımasıyla zincirlenmiş sırları  başka bir çağdan gelmiş ölçülü adımlar  tarihsiz dönemlerin karanlık göçlerinde  övgüsüz zamanların ...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/b-yedinci-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rastlamadım', 'rastlamadim-emre-saricicek-h6nh2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen yokken rastlamadım senin gibi birine.

Yeryüzünde ışığım olup kalbime girene.

Her rüyamı her hayallerimi süsleyene.

İnanki rastlamadım senin gibi birine.

Geceleri uyumayan beni hiç kırmayan.

Gönlüme umut veren beni yürekten seven.

Yokluğumda beni düşünen,asla terk etmeyen.

Senin gibisine rastlamadım ben hala.

Karanlık gecelerimi aydınlatan.

Yanağıma öpücükler konduran.

Gereğinden fazla olgun davranan.

Senin gibisine rastlayamam ben inan...', 'Sen yokken rastlamadım senin gibi birine. Yeryüzünde ışığım olup kalbime girene. Her rüyamı her hayallerimi süsleyene. İnanki rastlamadım se...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/rastlamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I am Sory', 'i-am-sory-emre-findik-3ujwo', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Eşkıya dünyanın 

Cesur insanları

Verdiğin mücadelenin

Aslı olmalı

Ağlamayla gülmenin

Sevmeyle ölmenin

Helalle haramın 

Doğruyla yalanın

Ayrımını yapmadan

Hayata hastir çekip

Gerçeklerde kaçıp

Meçhule gitmek midir yaşamak? 

Bir menekşe açmadan soluyorsa

Bir bebek doğmadan ölüyorsa

Sevenler kavuşamıyor

Hastalıklar çoğalıyorsa

Sonumu geldi cihanın yoksa

Kalmadı kimsede bir damla yürek

Yok artık kimse güvenecek

Ben ölünce kimler güvenecek

Yeni nesil bilmiyom ne edecek', 'Eşkıya dünyanın  Cesur insanları Verdiğin mücadelenin Aslı olmalı Ağlamayla gülmenin Sevmeyle ölmenin Helalle haramın  Doğruyla yalanın Ayrı...', ARRAY['Türk Edebiyatı','Şiir','Emre Fındık']::text[], 8.5, '{"poet":"Emre Fındık","poet_slug":"emre-findik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/i-am-sory-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne fayda', 'ne-fayda-emre-saricicek-9em1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece nokta koyduk bu ölümsüz aşka.

Herşeyi anlattın bana gözlerinde yaşla.

Haykırdın tüm benliğini bütün gece ağlayışla.

Vuramadım başımı taşlara,duvarlara.

Başkası varmış gönlünde belki bir zamanlar.

Ama unutmamışsın sevmişsin,ağlamışsın.

Ona karşı hep kendini suçlamışsın.

Onu sevmiş beni beni sevdiğini sanmışsın.

Arkadaş olmak yetmiş sana ilerisi ne fayda.

Zincirler vurun bana yazın son ayında...', 'Dün gece nokta koyduk bu ölümsüz aşka. Herşeyi anlattın bana gözlerinde yaşla. Haykırdın tüm benliğini bütün gece ağlayışla. Vuramadım başım...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-fayda-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen Köle Ol.. İstersen Yönet', 'i-stersen-kole-ol-i-stersen-yonet-guzin-eye-dundar-rzcfz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen ki o gözlerle 

........................neler görürsün

o gözleri yaratanın 

..........neler gördüğünü düşün...

Balçık  çamur derler 

aslın hamuru

toprak neden bekler

yağan yağmuru

bırak sınırlanmış

bencil guruhu

ruhu sevgi besler

unutma bunu

kavra  taksim eyle

istersen hükmet

istersen köle ol

İstersen yönet

bedene hakim ol

ruhunu keşfet

onun  varlığıdır

aslın vucudu..', 'Sen ki o gözlerle  ........................neler görürsün o gözleri yaratanın  ..........neler gördüğünü düşün... Balçık  çamur derler  aslı...', ARRAY['Türk Edebiyatı','Şiir','Güzin Eye Dündar']::text[], 8.5, '{"poet":"Güzin Eye Dündar","poet_slug":"guzin-eye-dundar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/istersen-kole-ol-istersen-yonet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anılar ve Düşler', 'anilar-ve-dusler-nail-yavuz-fxiob', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'suretler denizinde 

görüntülere çarptı gemilerimiz / başı boş 

ağır yara aldı bellek 

hüznünde battım gözlerinin 

düş ve gerçek karıştı birbirine 

ya da ben öyle sandım 

bir ışık yangını başladı saçlarında 

uzak bir ejderhanın nefesiyle tutuşan 

sözcüklerin pençeleri fırtına 

yazarken esen rüzgar 

soluğunla buluştu 

anılarımız az / konuşacaklarımız çoktu 

dört dudak arasındaydı düşler 

kırlangıç kanatları çırpındı gece boyu 

zorunlu izine çıkardım olmazı 

bana doğru dön 

sonsuzda buluşur paralel doğrular 

hangi depremde sarsılırsa sarsılsın 

kırılacak bir fay daha var 

ters akan ırmaklarında hayatın 

sesim gelir 

kendime göç eden uzaklardan 

bellekler sisli / sorgulanmamış 

geçmişten / geleceğe / anılar / düşler 

misafir olmamış yüzüme gülüşler 

feleğin çemberine çomak sokmayıp da 

_____ne yapacaktık 

Nail Yavuz, İZMİR 

30 Temmuz 2005', 'suretler denizinde  görüntülere çarptı gemilerimiz / başı boş  ağır yara aldı bellek  hüznünde battım gözlerinin  düş ve gerçek karıştı birb...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/anilar-ve-dusler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A.Şiir', 'a-siir-nail-yavuz-2co3a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kolu kanadı kırık umut 

kimsesiz sevgim 

seninle başlar şiirim 

nasıl biter bilinmez 

sevmekten başka işim olmamalı 

kağıda dökülür yüreğim 

kıyısına yanaştığım cennetinden kovuldum 

hangi aşksız yılıma yanayım 

sızlayan bir çağrının ardında 

alkış tutuldu yenilgime 

siyah bir çizgi ki / silik yazgıda 

şiirlerim suskun / kapılar sağır 

Nail Yavuz İzmir 27.04.2005', 'kolu kanadı kırık umut  kimsesiz sevgim  seninle başlar şiirim  nasıl biter bilinmez  sevmekten başka işim olmamalı  kağıda dökülür yüreğim ...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/a-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidenlerimize', 'gidenlerimize-nese-arsu-kqarh', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cesaretinde ol kaybın

Yitirilen bedene karşı

Sevgi pınarı gözlerini boşalt

Ardı sıra bakakalma sakın

Yaşanmış yitirilmiş kayıp bir hayata

Neler çekmiş bir hayata hoşçakal derken; 

Cesaretinde ol...

Sunulmuş saygının,sevgisinin üstüne

gönlünce hüznünde ol

Ne son görevimiz arkalarından bakmak

Ne de bedelini veremediğimiz emeklerinin..

Yıllarca dizlerinde olduk fakat

Bir günde bir saatte uğurlamak görevimiz.

Yüreğimizde; kabullenılmez bir veriş bu

Duyguları derinlerde yanan sancılara salmak bu..

Biz mi güçlüyüz? 

Biz mi yürekliyiz? 

Hangi sevgiyi unutup hangi güçle yüreklere gam vurup

Bir günde bir ömrü teslim ediyoruz ''toprağa''..

Cesaretinde ol kaybın

En değerler en canımız en kanımız gitmişse

Duasında ol

Metaneti de,

Sabrıda gelecektir peşinden..', 'Cesaretinde ol kaybın Yitirilen bedene karşı Sevgi pınarı gözlerini boşalt Ardı sıra bakakalma sakın Yaşanmış yitirilmiş kayıp bir hayata Ne...', ARRAY['Türk Edebiyatı','Şiir','Neşe Arsu']::text[], 8.5, '{"poet":"Neşe Arsu","poet_slug":"nese-arsu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/gidenlerimize-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'A. Sanat ve Sanal', 'a-sanat-ve-sanal-nail-yavuz-b9y5r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Birbirinin yollarında buluşan 

Kendi kalemlerimizin kalabalığı 

Satır aralarından dünyaya bakarak 

_______dizelerden tanıdığımız 

yakın bir dostu düşlemek / hiç görmediğimiz 

sözcüklerden kurduğumuz yapıt 

______oyuncak şiir 

ak kağıttır karaladığımız 

bir kar tanesinin üzerinde 

uçuk mavi su damlası 

bir kitabın özdeyişidir 

anılarla uzayıp giden sıralamalar 

yazgının derinliğidir sözün anlattığı 

atıverir kendini yeni bir imgenin kollarına 

evrenin dili / öncesiz ve sonrasız 

körlerin gözlerine görünen sezgi 

o ışıklı sisin ortasındaki 

kapıların önünde dolaşıyoruz/hiç aralayamadığımız 

işte yüreğim açıyorum göğsümü 

ben seni sevdim 

uzak aşkların uzak imgesi 

Nail Yavuz, İzmir Mayıs 2005', 'Birbirinin yollarında buluşan  Kendi kalemlerimizin kalabalığı  Satır aralarından dünyaya bakarak  _______dizelerden tanıdığımız  yakın bir ...', ARRAY['Türk Edebiyatı','Şiir','Nail Yavuz']::text[], 8.5, '{"poet":"Nail Yavuz","poet_slug":"nail-yavuz","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/a-sanat-ve-sanal-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidelim Mi', 'gidelim-mi-nese-arsu-orgir', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidelim mi diye başladığım cümlenin

Nereye sorusuna nasıl cevap vereceğim sensiz! 

Tek başıma çıkamadığım sevdanın yollarına,

Söylermisin hangi eli tutarak yürüyeceğim sevgisiz..

Gidelim mi deyişime 

Bir söz söyle istersen, yazacaklarıma 

Yada,bir yönver, yaşayamadıklarımıza! 

beni hep bekleten,koyarak gıderken unuttukların yok mu? 

Biliyorum gıdreken almadıkların var 

istersen geriye dön

Gideceğimiz bir yol yoksa

Sakın anlatma,konuşma.

Yeni bırakacaklarını bırakmaya gel

Gidelim mi deyişimi unut,

Sen yollarına devam et,

Benim de seni beklememi seyret..', 'Gidelim mi diye başladığım cümlenin Nereye sorusuna nasıl cevap vereceğim sensiz!  Tek başıma çıkamadığım sevdanın yollarına, Söylermisin ha...', ARRAY['Türk Edebiyatı','Şiir','Neşe Arsu']::text[], 8.5, '{"poet":"Neşe Arsu","poet_slug":"nese-arsu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gidelim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mehmedim', 'mehmedim-metin-topcu-vg24m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'MEHMEDİM

            Dağlara yürü Mehmet''im

            Dağlara,titresin.

            Sıradan biri değil

            Nebi madalyalısın...

İlahi emirdir bu,ta Altay’dan Bosna’ya,

İki adımda gittin öz yurttan Viyana’ya.

Bu ateş bin yüreğin,ciğerin ateşidir,

Kucak açıp yalvaran bir Ananın sesidir.

Doksan bin şehit verdik biz Allahuekber'' de,

Yüz binler, yüz binleri kurban ettik çöllerde! 

Böyle toprak var mıdır,sımsıkı kucaklanan,

Hiçbir vatan var mıdır,bağrında aslan yatan...

                   Dağlara yürü Mehmet''im 

                   Dağlara,titresin

                   Şehit kanıyla sulanmış

                   Bu toprak kükresin.

Kükresin de,tozu dumana katsın dumana,

Kör olsun gözler,harman vız gelir tırpana.

Örtüsüne aldanma hiyanet çamurudur o,

Anadolu’dur Ana,şehit deryasıdır O,

Güneşe balçık tutmaz, Anadolu’ya çamur,

İhanet örtüsüdür bu,yetim kanıyla hamur...

Mertliğin,asaletin, şevkatin eseridir,

Yeri gelir atılır kan çıbanı gibidir! ...

        

            Dağlara yürü Mehmet''im   

            Dağlara,titresin.

            Alçaklar,bin yazdığın 

            O destanı dinlesin...

Yara sardın, gül diktin, gittiğin her uzakta,

Düşmanların boğuldu,.kurduğu her tuzakta...

Göz yaşı sile sile gezdin tarih boyunca,

Hiçbir zülüm yapmadın yetmiş asır boyunca.

Kahpece kurşunlanan yavruların dili yok,

Gözyaşları okyanus olanların sesi yok! 

Maksadı anlaşılan bu caniler maşadır,

Kuduz sürülerine Rum ermeni paşadır.

Okulda öğretmenim,hocam bayrak çekiyor,

Her kapıda bir şehit tavaf için bekliyor! 

Bak oğlum! Bak Mehmet'' im Sakın kaşın kaldırma,

Unutur seni şehit gider gelmez yardıma! 

“Bir işten maksat neyse hüküm ona göredir” 

Peygamberin emrine uymak bizde töredir...

Anadolu’m yanıyor bekleme artık anı,

İndir demir yumruğu geldi artık zamanı...

    Metin TOPÇU', 'MEHMEDİM             Dağlara yürü Mehmet''im             Dağlara,titresin.             Sıradan biri değil             Nebi madalyalısın... İl...', ARRAY['Türk Edebiyatı','Şiir','Metin Topçu']::text[], 8.5, '{"poet":"Metin Topçu","poet_slug":"metin-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/mehmedim-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Herkesten Baş Gülüm...', 'sen-herkesten-bas-gulum-zulfikar-yapar-kaleli-4e1lb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Şurada niceler var,

Sensiz hayat yaş gülüm! 

Devler ve cüceler var,

Gönül senle hoş gülüm! 

Sensiz bahar yaz olmaz

Sensiz derdim az olmaz

Sen olmazsan naz olmaz

Sen herkesten baş gülüm! 

Aç olmak tok olmak var

Tek olmak çok olmak var

Var olmak yok olmak var

Sensiz sevda boş gülüm! 

Ne keder, ne gam ister

Mert, cesur adam ister

İnsanca nizam ister 

Sevgin bana iş gülüm! 

Şu yanda şer bakanlar

Şu yanda hor bakanlar

Şu yanda kör bakanlar

Sensiz günüm kış gülüm! 

Göz açmaya erinen

Kuzu  posta bürünen

Suret haktan görünen

Hissiz gözde yaş gülüm! 

30.8.2005', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Şurada niceler var, Sensiz hayat yaş gülüm!  Devler ve cüceler var, Gönül senle hoş gülüm...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-herkesten-bas-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Süleymaniye camii', 'suleymaniye-camii-elazigli-mustafa-kaya-2h2uk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'koşuyorum…

gökyüzüne  uzanan şehre.

ışık dolu şehir bu gece.

ilahi davetin huzurunda,

bir ulu mabete,

içimi delip geçen Süleymaniye

ve içinde cennetler saklı İstanbul a..

tezkiye oldum,

felah bulduğum saatlerdi

Süleymaniye de hakikat gözlerimi yaktı.

yalana durmuş  halimize

küf ve pas kokan hayatımıza

bu gecenin büyüsü iniyor..

beni esir alan günahlarımı döktüm

ince bir sızı gezinir şimdi

hayatım silinir tevbe kadar …

ve hayatlarımız tazelenir..

bir rüyadayım bilemezsin,

beni vazgeçiremezsin ey nefsim

beni bu geceden edemezsin..

                                                                  

                                                                         Mustafa kaya / süleyaniye camii

                                                                          www.mustafakaya.net

                                                                           01.09.2005', 'koşuyorum… gökyüzüne  uzanan şehre. ışık dolu şehir bu gece. ilahi davetin huzurunda, bir ulu mabete, içimi delip geçen Süleymaniye ve içind...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/suleymaniye-camii-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Resimdeki sen', 'resimdeki-sen-elazigli-mustafa-kaya-u43i8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'eğildim üzüntülerimle geceye

sırlarımla girdim..

yıldızlar darılmasın diye

gökyüzüne gülümsedim..

ve hayallerine girmek için

karşısına geçtim resminin

söğüt dalları seviyor seni

eğilmiş..

kaygılar uçuşurken bende

ne güzel gülüyorsun resminde …

çıkıyorum alıp resmini

bir taşın üzerinde Çengelköy de

düştüm bir düşe

açmıyorum ağzımı  seslere,

bir su damlası olup karışıyorum denize

hangi dalgalardı seni taşıyan uzaklara

ve genç bir kız yüzü gibi gülümseyen..

ruhuma dolan serinlik

ayna oldu,

derinliklerde sen sarıyorsun

seninle geçiyorum kendimden

 ve yangınlara düşüyor ay

mor-turuncu bir gece bakıyor, 

çırpınmalarıma,

şehir genzime kaçıyor .

binlerce çoğalıyorum

beni tutan denizde..

dişlediğim bir yosun kabuğu

uyandırmasa

sabahları bulacaktım 

mor düşüncelerimle

İstanbul kadar güzel Çengelköy de…

                                                                        O1.o9.2005 / Çengelköy

                                                                         Mustafa kaya

                                                                          www.ustafakaya.net', 'eğildim üzüntülerimle geceye sırlarımla girdim.. yıldızlar darılmasın diye gökyüzüne gülümsedim.. ve hayallerine girmek için karşısına geçti...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/resimdeki-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yazmak', 'yazmak-burhanettin-akdag-8uh6q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiir benim hayatım

Soluduğum hava gibi yazmak

Bazan...

Ayrı kaldığımda kalemimden

Acıkıyorum duyguya, sevgiye

Duygularımı yazmak...

Sıcak havada serinlik gibi

Ağrıyan yerime ilaç sanki

Boğuluyorum şiirden uzakta

Vefasızlık ve sevgisizlik çemberinde

Geriliyorum yay misali.

İşte böyle anlarda...

Sarılıyorum kalemime sımsıkı

Resitale başlıyor mavi mavi satırlar

Yağıyor gönlüme lapa lapa, usul usul

Seriliyor bembeyaz duygular, alabildiğince

Duyuyorum sükunetin yumuşak sesini 

Alışmışım ardı sıra dizmeye

Manaları, sevdaları, aşkları, hayatı

Konuşup dertleşerek kelimelerle.

İçime mor sümbüller sarkıyor

Tenime değiyor dizelerin

İpeksi dokunuşları ard arda

Herbiri sırabaşı dizilmiş

Canlı, kıpır kıpır karşımda

Gülüyor, kalbime sesleniyor harfler

Yıkanıyor ruhum akarsularında

Sanki yeni doğmuş bebeyim

Dingin, sakin, yarınlara umutlu

Çelik gibi sinirlerim

Yarınlardaki hayat kapışmalarına hazır.

Kendime geliyorum yazınca...

Satırları tekrar tekrar okuyor

Hayat dersinin ezberini yapıyorum

Bilmem hangi odadaki ekranın içinde

Yeniden doğuyorum her açılışla

Boy gösteriyor duygularım sıra sıra

Okundukça akıyor gönüllere

Hiç görmediğim dost kalplere

Belki hiç karşılaşmıyacağım 

Gönül aşıklarının 

O öpülesi yüreklerine.

Ne büyük bir mutluluk bu Allah''ım

Yazması zor

Anlatması zor

Anlaması kolay...

Nasıl yazmam beyaz sayfaya sıra sıra

Nasıl dizmem duygularımı öbek öbek

Nasıl vermem gülleri demet demet

Nasıl vazgeçerim nefes almaktan

Duygularıma güfteler yazmaktan...

Çünkü...

Şiir benim akciğerim,

Olmazsa olmazım.

Bitkisel hayata girerim,

Duygularımla sevişmezsem.

Yaşayamam

Öyle sadece bedende,

Ruhumla dans etmezsem.

Eğer yaşamaksa bunu adı

Ölürüm hergün yeniden

En ücra köşede, yapayalnız.

Yapamam,

Şiirsiz yaşayamam...

Ölürüm! ! ! 

(31.08.2005)', 'Şiir benim hayatım Soluduğum hava gibi yazmak Bazan... Ayrı kaldığımda kalemimden Acıkıyorum duyguya, sevgiye Duygularımı yazmak... Sıcak ha...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Akdağ']::text[], 8.5, '{"poet":"Burhanettin Akdağ","poet_slug":"burhanettin-akdag","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/yazmak-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sele Kapıldı Oda', 'sele-kapildi-oda-hatice-bediroglu-tou8e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merdiveni dayadı sabaha,

Nihayet zaman.

Çivilerini batırdı yatak,

Bedenime saatlerdir,

Mola vermeden.

Buluşmadı göz kapaklarım,

Hiç sevmedi birbirini.

Kara, kocaman bir örümcek,

Faydalandı bu durumdan.

Gelip yerleşti,

Kurdu ağını bir güzel,

Serseri mayınlar gibi,

Dolaşan düşüncelerime.

Oyuldu içim mağara gibi.

Canımın acısı,

Kudurdu... kudurdu...

Dayanamadı,

Çıkıp gitti gözlerimden.

Sele kapıldı oda,

Hücum etti ağzıma sular.

Çırpındım...çabaladım.

Tutunmak istedim,

Sen yoktun...

Boğuldum,

Yitip gittim.

www.haticebediroglu.net

-Aşkı Bulan Şiirler- Gündüz Kitabevi Aralık 2005', 'Merdiveni dayadı sabaha, Nihayet zaman. Çivilerini batırdı yatak, Bedenime saatlerdir, Mola vermeden. Buluşmadı göz kapaklarım, Hiç sevmedi ...', ARRAY['Türk Edebiyatı','Şiir','Hatice Bediroğlu']::text[], 8.5, '{"poet":"Hatice Bediroğlu","poet_slug":"hatice-bediroglu","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sele-kapildi-oda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eşitliği yakalamış ne mutlu!', 'esitligi-yakalamis-ne-mutlu-mikdat-bal-4g4g1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sis çöktü yurduma hem kara kara

Başımız dertlidir gönlümüz yara

Memuru işçisi fakir fukara

Eşitliği yakalamış ne mutlu! 

İşsizleri kimse hesaba koymaz

Bağırır çağırır, hiç kimse duymaz

Çalışan  çalışır midesi doymaz

İşi varmış çalışıyor ne mutlu! 

Herkes dönmüş yaşamanın derdine

Kimse bakmaz yiğitine mertine

Milli gelir ülkenin her ferdine

Sözde üç bin dolar olmuş ne mutlu! 

Mikdat Bal der ne söylesem kâr etmez

Bizi böyle yönetenler ar etmez

Değerleri bence bir dolar etmez

Ne mutlu Türk’üm diyene, ne mutlu

Gelecekten umutluyum umutlu', 'Sis çöktü yurduma hem kara kara Başımız dertlidir gönlümüz yara Memuru işçisi fakir fukara Eşitliği yakalamış ne mutlu!  İşsizleri kimse hes...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/esitligi-yakalamis-ne-mutlu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçekleri burnumdan soluyabilsem', 'cicekleri-burnumdan-soluyabilsem-ahmet-atac-f19nb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çiçekleri burnumdan soluyorum

Ruhumdan geçenleri okuyorum...

(26.08.2005  s.16:51)', 'Çiçekleri burnumdan soluyorum Ruhumdan geçenleri okuyorum... (26.08.2005  s.16:51)...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataç']::text[], 8.5, '{"poet":"Ahmet Ataç","poet_slug":"ahmet-atac","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/cicekleri-burnumdan-soluyabilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da yaşamı bir kolaylaştırabilsem', 'i-stanbul-da-yasami-bir-kolaylastirabilsem-ahmet-atac-3bwr5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İstanbul''da yaşamı bir kolaylaştırabilsem

Hazıra konarmıydım neler yapardım bilmem

                                                            (s.16:57) 

Göçüyor üzerimden beni mahkum eden esrar

Kendimi yokluyorum artık verebiliyorum karar

Sis perdesi ruhumdan kalkarken azar azar

Örselenmiş geçmişim geleceğimle bi(r)   karar

Ne yaparsam yapayım azıcıktır iradem

Tek başıma bir hiçim dua alayım madem

Arasam bulsam desem sürgünün yolu olurum

Aradan çıkartırsam beni Hüda''ya kavuşurum

Nereden bulacağım salih dua ehlini? 

Rüyalardan işaret alsam iyi mi? 

Açık bir kapı göster kurtar bu düşünceden

Denklemini çözdüğüm vadinin çemberinden.', 'İstanbul''da yaşamı bir kolaylaştırabilsem Hazıra konarmıydım neler yapardım bilmem                                                          ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataç']::text[], 8.5, '{"poet":"Ahmet Ataç","poet_slug":"ahmet-atac","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/istanbul-da-yasami-bir-kolaylastirabilsem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nur Yağdı...', 'nur-yagdi-hulya-arisan-f4x3j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gecem,

senin gününle

evlendi.

Gecemi aydınlattı.

Üzerimize 

NUR yağdı...

İstanbul 29 Ağustos 2006', 'Gecem, senin gününle evlendi. Gecemi aydınlattı. Üzerimize  NUR yağdı... İstanbul 29 Ağustos 2006...', ARRAY['Türk Edebiyatı','Şiir','Hülya Arısan']::text[], 8.5, '{"poet":"Hülya Arısan","poet_slug":"hulya-arisan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/nur-yagdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne''cip', 'ne-cip-ahmet-atac-m7rc7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '(dostum İbrahim Araboğlu''na) 

Ben cip''im cip

Sapsız ve küreksiz...

İlham aldığım Ne''

Esinlendiğim...cip', '(dostum İbrahim Araboğlu''na)  Ben cip''im cip Sapsız ve küreksiz... İlham aldığım Ne'' Esinlendiğim...cip...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataç']::text[], 8.5, '{"poet":"Ahmet Ataç","poet_slug":"ahmet-atac","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ne-cip-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aliye.', 'aliye-veysel-alkan-coouw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yüzün böyle güzelken,

Bu hüzün niye? 

Ömür elden gitmeden,

Gel benimle, gül Aliye.

Ellerimi sımsıkı tut,

Boş verelim biz maziye.

Gündüz yaşa,gece unut,

Kollarımda sen Aliye.

Az koşmadım, yorulmadım,

Olacaksın benim diye.

Sen varsın ya aramadım,

Senden güzel, yok Aliye.

Benden başka aşık varsa,

Dönerim ya, ben deliye.

Kader bizi ne yaparsa,

Kabullendim ben Aliye.

Beni anla bana hak ver,

Sensiz gidem ben nereye? 

Bana güven biraz şans ver,

Sadakati gör Aliye.

Kal yanımda, hiç ayrılma,

Dönmeyelim biz geriye.

Başka biri yok yanılma,

Beni,senin bil Aliye.', 'Yüzün böyle güzelken, Bu hüzün niye?  Ömür elden gitmeden, Gel benimle, gül Aliye. Ellerimi sımsıkı tut, Boş verelim biz maziye. Gündüz yaşa...', ARRAY['Türk Edebiyatı','Şiir','Veysel Alkan']::text[], 8.5, '{"poet":"Veysel Alkan","poet_slug":"veysel-alkan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/aliye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Makina Aşklar', 'makina-asklar-gulsum-cakir-ozumok-fn4s2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Korkuların en doğalıdır…

Olabileceklerden

Veee

Olamayacaklardan korkmak

Şevişmenin en olağanıdır…

Bedenin bedene

Terin tere karışması

Veee

Terle tenin birleşmesi

Sevmenin en  doyuranıdır…

Dokunabildiğin

Veeee

Dokunulabildiğin

Anlarda asılı kalmak,

Sımsıkı…

Acıların sonsuzluğudur…

İçinde ki teklik  “ken”

Dışında

Çok sandıkların “yokken”

Makine üzerinden

Açlık doyurmak

Hakarettir

Aşka

Desemdeeeee

İnanmayacaklar bana

Aşkı 

Tadamadan

Aşkı

Anlamadan

Aşkı

Yaşamadan

Yok olacak olan

Makine aşıkları

M… A…K…İ…N…A…

Korkuların en doğalıdır…

Olabileceklerden

Veee

Olamayacaklardan

Korkmak

Gülsüm Çakır Ozumok/Ankara/Çankaya/Or-an/Eylül 1/0325', 'Korkuların en doğalıdır… Olabileceklerden Veee Olamayacaklardan korkmak Şevişmenin en olağanıdır… Bedenin bedene Terin tere karışması Veee T...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/makina-asklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Babil! in Asma Bahçeleri', 'babil-in-asma-bahceleri-gulsum-cakir-ozumok-fkyz2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ketlemişim kendimi 

Yıllardır...

Babil’in asma bahçelerine 

Asmışım

Sarıp sarmalayıp 

Beni...

En gizillere, 

Kuytu kuyulara salmışım.

Kilitlemişim duygularımı

Kilidin anahtarını nerde unuttuğumu 

Bile...

Unutturmuşum bana

İmdiiii

Anımsamak imkansız sanarken

Anımsayıverdiğimi görmek

Yok saydıklarımı 

Yok sanarken

Ve

Onlar varken, 

A t ı l a m a m ı ş k e n

Var olduklarını bilirken

Bilmezlik olmadı, Babil’in asma bahçelerini

Asılı kalmışlık

Yok saymışlık

Kırdığını sandığın anahtar

Çok kısa zamanda alevlenenler 

Çok dan da kısa zamanda yok olurken

Bakakalmışlık

Salda salınma

Burka da kalma

Tüm ketlerimin dağılışını seyirde kilitlenmişlik 

Babil’in asma bahçelerinde

Üzüm salkımları gözlerimde, kitaplar

Gülsüm Çakır Ozumok/Ank./Çankaya/Or-an2005/Ağustos29/0215', 'Ketlemişim kendimi  Yıllardır... Babil’in asma bahçelerine  Asmışım Sarıp sarmalayıp  Beni... En gizillere,  Kuytu kuyulara salmışım. Kilitl...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/babil-in-asma-bahceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Belki...! ! !', 'belki-gulsum-cakir-ozumok-f6qbg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Belki ben 

Zayıf bir zamanımın, zayıf bir dilimindeyim

Belki sen çok iyisin 

Belki mutlu olmanın tam zamanıdır

Belki

Ben bunu gördüm

Belki

Sandığını sandığın şey

Sandığını sandığın şey değil

Belki 

Çocuksu

Belki

Masum

Belki

Bozulmamış

Belki

Bakir duygular

Belki…

Sandığını sandığın şey

Sandığını sandığın şeydir

Belki ben

Uçuk kaçık

Akıl ötesi çizgideyimdir, şimdilerde

İşte o yüzden

Her şey belki

Belki…! ! ! 

Gülsüm Çakır Ozumok/Ankara/Çankaya/Or-an/Ağustos 30/0450', 'Belki ben  Zayıf bir zamanımın, zayıf bir dilimindeyim Belki sen çok iyisin  Belki mutlu olmanın tam zamanıdır Belki Ben bunu gördüm Belki S...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/belki-86-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Barış', 'baris-gulseren-onay-26psg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Barış

Koydular ismini,

Barışık bir dünyaydı 

Düşledikleri.

Barışsever  büyüttüler 

Ve yine 

Barış için yapılan 

Savaşta  yitirdiler 

GÜLSEREN ONAY 

*Barışlar yitirilmesin. 1/Eylül Dünya barış günü kutlu olsun..', 'Barış Koydular ismini, Barışık bir dünyaydı  Düşledikleri. Barışsever  büyüttüler  Ve yine  Barış için yapılan  Savaşta  yitirdiler  GÜLSERE...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/baris-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşam', 'yasam-gulsum-cakir-ozumok-i5a6p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yaşamda

Bulmayı umut ettiklerimizi

Bulmayı umut etmekten

Korkarak kaldıkça

Asla 

Bulamayacak bizi

Bulmayı 

Umuudd  ettiklerimiz

Yaşamda

Yapacaklarımızı

Yapabilme şansımız

Olabilirse

Yaşam 

Daaa 

Yapabileceklerini

Görme şansına

Saplanır kalır 

Yaşamımız boyunca

Yaşam …

Dengemi bozma…! ! ! 

Beni sana düşman! ! ! 

Seni bana han eyleme.

Gülsüm Çakır Ozumok/Ankara/Çankaya/Or-an/ Ğustos30/ 0500', 'Yaşamda Bulmayı umut ettiklerimizi Bulmayı umut etmekten Korkarak kaldıkça Asla  Bulamayacak bizi Bulmayı  Umuudd  ettiklerimiz Yaşamda Yapa...', ARRAY['Türk Edebiyatı','Şiir','Gülsüm Çakır Ozumok']::text[], 8.5, '{"poet":"Gülsüm Çakır Ozumok","poet_slug":"gulsum-cakir-ozumok","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/yasam-75-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşığım Ben', 'asigim-ben-ahmet-atac-wwlou', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyuyorum,

korkunç karanlık sarmış her yanımı.

Korkuyorum,

ufak bir ışık aydınlatıyor odayı.

ve kapı açılıyor bir melek giriyor içeri

elinde şerbetle yaklaşıyor, uyatıyor beni.

beraberce onu içiyoruz, gülerek.

içimin yandığını hissediyorum, bilerek.

ve yakalamak istiyorum onu kaybolmuş.

arıyorum onu, yok, oda bomboşmuş.

yine karanlık...

kara bir el tutuyor sırtımdan, sallıyor beni.

kalbimi elleriyle parçalıyor, giriyor içeri.

çok acıyor yüreğim, dayanamıyorum.

adı karasevdaymış, bilemiyorum.

uyanıyorum.

kurtulamıyorum bu pençeden, yaralıyor beni.

kanıyor yaram dinmiyor yüreğimin seli.

görüyorum o gün meleğimi

bir sıcaklık sarıyor tüm bedenimi.

içim ılınıyor rahatlıyorum

ne idi bu anlamıyorum.

düşünüyorum! 

artık ben yokum, ikimiz varız.

meleğim ve ben birbirimize aşığız.

onsuz yokum ben, onsuz yaşayamam...

yaram iyileşiyor kurtulduğumu sanıyorum.

ve mutluluğun en güzelini, en iyisini

en tatlısını tadıyorum.

seviyorum birisini; 

artık aşığım ben...

   yaz veya bahar mevsimi 1988', 'Uyuyorum, korkunç karanlık sarmış her yanımı. Korkuyorum, ufak bir ışık aydınlatıyor odayı. ve kapı açılıyor bir melek giriyor içeri elinde ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ataç']::text[], 8.5, '{"poet":"Ahmet Ataç","poet_slug":"ahmet-atac","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/asigim-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgaların getirdiği', 'dalgalarin-getirdigi-elazigli-mustafa-kaya-7epbx', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'şarkılar bile hüzün geliyor.

ne tarafa koşsam,

denize koşsam,

üstelik sürekli dalgalar

ne kadar çoşkun olsa 

hüznümü gizleyemem.

yalnızlığıma geldi

durmadan dönüp uçan martılar.

buğulu gözlerini unutmadım.

şehrin her yanında rastladıkça..

daha çok ağlarım,

burada bu şehirde

masmavi güzelliğin içinde.

dalgaların getirdiği yalnızlıklar

içime işledikçe..

artık yoruluyorum

sensizlikten..

sensiz şehrin güzelliklerinden..

elimde değil yalnızlığım

şimdi sen ağlarsın

ağlama sevgilim..ağlama..! 

yoksa gülmez İstanbul

şimdi sen ağlarsan şarkılar susacak

ve bir dalga alıp beni

ve martılar tutup beni kaçıracak…

                                                                       31.09.2005 / Büyükada

                                                                        Mustafa kaya

                                                                         www.mustafakaya.net', 'şarkılar bile hüzün geliyor. ne tarafa koşsam, denize koşsam, üstelik sürekli dalgalar ne kadar çoşkun olsa  hüznümü gizleyemem. yalnızlığım...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/dalgalarin-getirdigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gontas İzleri: ''İkiz'' bir Çinek (Gontas ikizleri ve bir Çinek)', 'gontas-i-zleri-i-kiz-bir-cinek-gontas-ikizleri-ve-bir-cinek-akin-akca-bw7w8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '1.

Kardan çatılanmış evlerin açık yeşile dönen

örgüsü birleşiyor geceyle:biri ışıklı,

diğeri içeriden ışık sızdırmayan bu evlerden 

ve hemen karşılarında kardan bir tepecik; 

arka sırt kısmında, ışıldatan çam ağaçları -

yine açık yeşil ile, hemen altındaki tepeciği

- mütemadiyen ki usulcacık

! Harika bir tablo, karşı uzaklıkların göbeğinde –

yine, o uzak yeşilliklerin, o uzak karın …

Çok sade ama biri uyuyor ikizlerden. *

Diğeri kitap okuyor ya çevreyi gözlüyor.

Bu çevrede, geceleyin, apansız kurtlamalar

..çok oluyor doğayı eşelemeye çırpınanlar! 

Geçen an, sessizlikteydi …

DONANLAR YAZIN

2.a

Geceydi,

Işığı kapalı evden çıkan bazıları vardı! 

Kadınlar; yukarı, ufak tepeye hızlıca çıktı! ! 

Bir şeyler toplamaya çalışıyor gibiydiler yerden.

Cama üşüşmüş, geceyi süzüyordu

bazı “yeni yetme ruhlu-tüylüler”, sair kulübeden:

Bir şenlik olabilirdi, içeride ışık vardı.

Sabah olduğunda, karlar biraz erimişti.

Güneş en tepede belirdiğinde henüz. 

saat 10:30’du.

Erkeklerden, şu ufak tepeye çıkan bazıları; 

oracığa putlaşmış bazı tavırlar fark ettiğinde..

(Bitki gibiydi! bitki gibi şeylerdi!)    

..her zaman için üretilesi düşünceler

gönül terazisine danıştı:

Bu, olanlar neydi? ? 

ÇİÇEK VE SİNEK

2.b

Toza kapışmak mı seversin? 

Sinek, bir küçük çiçekli bitkiyi eşeleyerek; 

nektar peşinde ki, amacı 

tüpün sonundaki nektar havuzuna erişmek! ! 

Nektar peşinde olan böcek; 

Tüm dileği nektar göleti sonrasındaki,

az biraz rahat molalar almak:

 vücutlarında –

 bu bölme-uzvu-hörgüçlerinde polen ağartan, 

 yukarı tutup ışıtan; 

 bedenleri yatırmak çiçek boğumuna sıkı fıkı! ! 

Doğal seçilim! doğal seçilim! 

Çiçek tüpleri uzadı böyle, sevdi buna; 

artık sineklerde olması lazım bir gaga-leylek! 

Bu yüzden, seçildiysek? 

:Paldır küldür koşmaya başladı tüylüler,

ışığı sönük eve doğru,

bayır aşağı …

(Doğru sun: doğrusun, ancak doğru sun! !)    

Dışarıda, ufak tepecikte “putlaşmışlar’ın

eskizleri”ni içeride buldular, 

onların ruhlarını! ! 

Sonra bir ansiklopedi karıştırıp öğrendiler:

Nemestriniade ailesinden; 

Prosoeca ganglbaueri, bir sinek –

gelme dağlarından G. Afrika’nın

- Zaluziyanskya mikrosiphon’sa bir çiçek! ! 

Arayer düşgue geçişi …

(Sevgili! 

Bak, bu işler ince işler; 

çok emek var, çokk! ! 

Kırmızı gül dilersin, şaşmamalı çilek

çekmemene o şanlı dilek (! 

)    

DIŞ UZAYDA ÜST TÜNEL

3.a

Kırmızı gül dilersin, şaşmamalı çilek

çekmemene bir dilek

Hemencecik buz gibi cacık

yerine sapsade bir çinek *

Kocaman Jon Coffee geçiyor

gibi …

Ve diyor kendisi:

“Soyağacı,

kahve gibi söylenişi, değil mi? ”

(ha, onun yaşlı teyzeye üfürdüğü…)    

Daracık o verimli tüpten geçebilmesine

hiç şaşmamalı! 

Ağzından saçtığı lav tozlarını

tüpten toplamıştı –

vergeçişi, hayat seçişi …

Bir yanda çılgın müzik partileri,

diğerinde sessiz huşu seferleri:

Düşünür çiçek; 

“Çılgınca açtığınca kendini Gün,

güneş neden kararamaz ama? ”

3.b

Ner’de ki or’da hissettiğin:

asimetrik ki, oldukça doğasından; 

farklı parçalar tümlendiğinde, 

kusursuz simetrik.

Çok kesif meşeli bir kuzey ormanına 

düştü; 

karanlık gözükmesi bir tesadüf 

cinsinden …

Hep düşlediği tatil oluşu,

Nisan ayıyla burayı ziyaret edişinden.

Bir taş ev, odun geçişlerle

güçlendirilmiş ara ara:

Ne depremde yıkılır, ne anafor illa.

Nehir odasında ortasındaydı suların; 

yan tarafta sık ağaçlar raflarda 

belki sarkıtan kendini yapma çiçekler

ve bir şelale ufukta, büyükçe, bir koca! …

ardınca, bir güneş, daimi tepede …

Zaluzianskaya mikrosiphon; 

mikrop olmayan biri

siklotronlar içinde dolaşarak

CERN’de..

Bir ileri, bir geri ve denli yakın(-aksak)       ışığa…

Zulu kabilesinden kabilinden –

Oynayan tavşanlar tamtamlar eşliğinde

- Irina Slutskaya’vari.

Kuğutek, buz patencisi gibisin.

Bireysel bir karayip, ikircik.

Değil dışarıladığını sandıkların,

3. kişi, değil! 

:Gene sigara mı içiyorsun aşkile? 

(Lanet olsun sana, lanet bana; 

çünkü neden ama,

aereğiyle birlikte olmanın...

) 

Bağımlı kıyı (!) , denize …

kendine.

-

Açıklamalar:

1. bölüm; 

Sn. Reşide Sarıkavak’ın grubundaki resme bakarak 31 ağs ’05 günü başlamıştım, bir gün sonraya sarktı.

“Gontas” adı, resme verilmiş isimdi.

Resmi alarak “çinek” fikriyle karınca ve son bölümdeki duygu ve fikir geçişlerine bağlanınca, ortaya bu çıktı.

Sevgi ve saygılar

Düşgue: düşünce-duygu (türetme)       (ikisini birleştirince sanki düşünce duygudan ilhamlaşarak düş’leşti gibi. Ama sanırım tuhaf olmamalı.

Bu kelimenin geçtiği dize için; küçük italikle belirtmiştim word belgesinde.

Sinek ve çiçek için küçük kabilinden kaynakça:

Nemestrinidae ailesinden bu sinek türü (Prosoeca ganglbaueri)       Güney Afrika’nın Drakensberg dağlarındaki bu küçük çiçekli bitkiyi (Zaluzianskaya mikrosiphon)       ziyaret ediyor. Çiçek ve Sinek bir ortak evrim döngüsüne yakalanmış durumdalar. Bitki, tozlaşma için çiçek tüplerinden yararlanır; çünkü nektar peşinde olan böceklerin tüpün sonundaki nektar havuzuna erişmek için vücutlarını polen taşıyan çiçek bölümüne sıkıca bastırmaları gerekir. Ancak çiçek tüpleri uzadıkça doğal seçilim ağız parçaları daha uzun olan böcekleri tercih eder; bu tür sinekler, besin bulmada en verimli olanlarıdır. Sonuç, çiçek ve sinekte ilgili kısımların giderek uzamasıdır. Dahası, her tür ötekine bağımlı hale gelir ve bu özel değişime uğramamış organizmalar dışlanmış olur.

Bilim ve Teknik, Haziran 2005, s. 56 (“Çiçek ve Sinek” araştırmasına dergide giriliş yazısı)    

Çinek: sineksel çiçek (türetme)    

-

Irina Slutskaya: rus patinajcilar icin teknigi kotu demek cok zor, ama her performansinda yaptigi ufak bir hata genelde teknik acidan kusursuz bir performans sunmus olan michelle kwana kaybetmesine yol aciyor.. iki uc sicrayistan sonra kizaran yanaklari, ''sevimli genc kiz'' imaji yaratiyor.. ama bence o kizaran yanaklar heyecanli bir yapinin da gostergesi..

Siklotron:atom araştırmalarında, elektronların yüksek hızla döndürüldüğü aygıt.

CERN: avrupa nukleer arastirma organizasyonu 

cern in acilimida sole ki

conseil pour la recherche nucleaire

dunyanin en buyuk elementary particle arastirma merkezi 

isvicrede cenevrede bulunmakta

eksisozluk

-

Jon Coffee: “The Gren Mile” filmindeki iri kıyım saf görünümlü ama aşırı zeki zencinin karakter adı.', '1. Kardan çatılanmış evlerin açık yeşile dönen örgüsü birleşiyor geceyle:biri ışıklı, diğeri içeriden ışık sızdırmayan bu evlerden  ve hemen...', ARRAY['Türk Edebiyatı','Şiir','Akın Akça']::text[], 8.5, '{"poet":"Akın Akça","poet_slug":"akin-akca","theme":"Türk Şiiri","is_hero":false,"total_lines":153,"source_url":"https://www.antoloji.com/gontas-izleri-ikiz-bir-cinek-gontas-ikizleri-ve-bir-cinek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Güne Bir Mektup 6', 'her-gune-bir-mektup-6-mehmet-haluk-hisli-l6grb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '...

Güzellikler paylaşılmalı... ki renklensin ve parlaklığını muhafaza etsin... 

En karanlık ücra köşelerde dahi bir ışık bulmak,  gerekiyorsa yaratmak umudu ve gerçekleşecek hayalleri avuç içinde tutmak ve sunmak; mutluluğu arttırır düşüncesindeyim... 

Bu bir şiirle, bir sohbetle, bir göz yaşını paylaşmakla da olsa mutluluk yaratacaktır... 

Mesela yazışmamızın devamını arzulamanız beni sevindirdi, mutlu etti... Teşekkür ederim... 

Mutluluğun yıldız misali üzerinize yağmasını temenni ederim... 

Hoş kalın... Mutlu ve umutlu kalın... 

S…', '... Güzellikler paylaşılmalı... ki renklensin ve parlaklığını muhafaza etsin...  En karanlık ücra köşelerde dahi bir ışık bulmak,  gerekiyor...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/her-gune-bir-mektup-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Güne Bir Mektup 7', 'her-gune-bir-mektup-7-mehmet-haluk-hisli-cf4wb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '...

Güzellikler paylaşılmalı... ki renklensin ve parlaklığını muhafaza etsin... 

en karanlık ücra köselerde dahi bir ışık bulmak, gerekiyorsa yaratmak umudu ve gerçekleşecek hayalleri avuç içinde tutmak ve sunmak mutluluğu arttırır düşüncesindeyim... 

ELBETTE PAYLAŞILDIKÇA BÜYÜYEN, ÇOĞALANLARDAN SÖYLEDİKLERİNİZ...EKSİLENLERDEN DEĞİL... YİNE SİZE HAKLISINIZ DEMEMEK ELİMDE DEĞİL.... 

Bu bir şiirle, bir sohbetle, bir gözyaşını paylaşmakla da olsa mutluluk yaratacaktır.. 

ZORDUR GERÇİ SÖYLEDİKLERİNİZİ PAYLAŞMAK, AMA BİR O KADAR DA GÜZELDİR YAKALANABİLDİĞİNDE PAYLAŞILACAK KİŞİYİ... 

mesela yazışmamızın devamını arzulamanız beni sevindirdi, mutlu etti... teşekkür ederim... 

 :-))

mutluluğun yıldız misali üzerinize yağmasını temenni ederim... 

hoş kalın... mutlu ve umutlu kalın... 

S... 

AYNI DİLEKLERLE VE BİR ŞİİRLE ŞİMDİDEN YENİ YILINIZI KUTLUYORUM 

H... 



Hasretinden Prangalar Eskittim

Seni, anlatabilmek seni.

İyi çocuklara, kahramanlara.

Seni anlatabilmek seni,

Namussuza, halden bilmeze,

Kahpe yalana.

Ard- arda kaç zehmeri,

Kurt uyur, kuş uyur, zindan uyurdu.

Dışarda gürül- gürül akan bir dünya... 

Bir ben uyumadım,

Kaç leylim bahar,

Hasretinden prangalar eskittim.

Saçlarına kan gülleri takayım,

Bir o yana 

Bir bu yana...

Seni bağırabilsem seni,

Dipsiz kuyulara,

Akan yıldıza,

Bir kibrit çöpüne varana,

Okyanusun en ıssız dalgasına

Düşmüş bir kibrit çöpüne.

Yitirmiş tılsımını ilk sevmelerin,

Yitirmiş  öpücükleri,

Payı yok, apansız inen akşamlardan,

Bir kadeh, bir cigara, dalıp gidene,

Seni anlatabilsem seni...

Yokluğun, Cehennemin öbür adı dır

Üşüyorum, kapama gözlerini...

                      

                                   Ahmet Arif', '... Güzellikler paylaşılmalı... ki renklensin ve parlaklığını muhafaza etsin...  en karanlık ücra köselerde dahi bir ışık bulmak, gerekiyors...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Haluk Hisli']::text[], 8.5, '{"poet":"Mehmet Haluk Hisli","poet_slug":"mehmet-haluk-hisli","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/her-gune-bir-mektup-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teknolojinin Neresindeyiz/Komedi Serisi', 'teknolojinin-neresindeyiz-komedi-serisi-mehmet-akif-gulhan-xm378', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Her şey korku ile başladı

Yaşlanma korkusu

Treni kaçırma korkusu

Bunu nereden anlıyorsunuz

Çocuğunuz farklı düşünüyor

Farklı konuşuyor

Kullandığı teknoloji bile farklı

Biz çala kalem şiir öykü yazıyoruz

Bir elimizde kalem 

Bir elimizde silgi

Hem kalemi hem silgiyi 

hem de ömrümüzü tüketiyoruz

-Baba sana bir bilgisayar alalım

-Hani şu elektronik beyinlerden mi

-Hah hah ha baba elektronik beyin mi? 

-Gülme ulan piç kurusu,bizim zamanımız da öyle denirdi

-Bilgisayar baba,yani Pc

-Pisi ne ulan pisi pisi gibi kedi mi bu

-Yok baba personıl compütır yani

-Ne diyorsun oğlum

Dedim ya çocuğunla bile aynı lisanı konuşamıyorsunuz artık

Korku sardı beni,çağın gerisinde kalmak korkusu

Babam; Türkiyede ilk televizyonun imalatını gerçekleştirmiş duayen bir elektronikçi

Ben ise onunla beraber radyo,teyp ve role imalatları yapmış eski bir elektronikçi,

çok ağırıma gidiyor bu geri kalmışlık

İnceledim biraz bilgisayarı,hoşuma gitti

Yazıyı yaz beğenmediğin yer mi var geri gel sil

Satır arasına bir şey mi eklenecek,satır arasını aç bir hamlede araya gir yaz

Çok hoşuma gitti,karar verdim bir tane alacağım artık

Bu karar benim hayatımın dönüm noktasıymış meğer; 

ne bileyim ben başıma gelecekleri

-Oğlum bir bilgisayar alalım

-Yaşa baba alalım

-Nereden,nasıl,ne marka alacağız

-Kolay baba,şimdi kampanya var alırız

-Şu marka var,1500 $ 

-Yuh! O ne lan araba mı alıyoruz

-Bu marka var 1200 $

-Pahalı –alamayız-

-Öteki marka var 1000 $

-Eh o iyi galiba

-Yalınız onun rem’i biraz düşük

-Rem ne ulan

-Yani hızı 

-Olur mu ulan onca para ver,hızı düşük makine al,

ne yapayım ben akılsız bilgisayarı

Aklıma bir hikaye geldi rahmetli anneannem anlatırdı

Yaşı geçkince bir hanım varmış,hiç evlenmemiş

Komşusu bir gün sevinçle gelmiş

-Komşum gözün aydın sana bir kısmet var diye

kadın heyecanlanmış,bunca seneden sonra vuslata erecek ya

-Kim o komşu,demiş

-Falancaların falancası

-Ya

-Çok iyi bir adam

-Eee

-Çok ta zengin

-Oh

-Yalnız bir kusuru var

-Ne kusuru komşu

-Bir kaza geçirmiş

-Ya! vah vah,yani

-Söylemesi ayıptır,aleti

-Aaa ne olmuş kız aletine

-Bak komşu,akıllı,yakışıklı,zengin adam o kadar kusur olur artık,alet çalışmıyormuş,

kadıncağız hışımla ayağa kalkmış

-Bunca sene bekledim komşu kusura bakma demiş.-Aleti’de çalışır olsun

Bizim bilgisayarında her şeyi tam olsun değil mi? 

Bunca sene sonra cesaret edip almaya karar vermişiz

Yalınız bir problem var ben satın alma kusurluyum.

Bütün ev halkı ve akrabalar ve komşular 

ve dahi tanıdıkları ayağa kaldırdım

-Bilgisayar alacağım,dedim

Tüm dostlar teyakkuz modu’na geçti

-Eyvah yandık biz şimdi,diyorlar

Bundan seneler evvel araba almaya kalkmıştım.İki sene sürdü bir araba almam

En sonunda arkadaşım

-Yeter be arkadaş senin araba falan alacağın yok deyip kızmıştı

Hatta müşterek bir tanıdığımıza

-O,değil otomobil –eşek arabası bile alamaz-demiş

En sonunda parayı verdim,tanıdığı bir galeriden bir otomobil aldı geldi bana 

Bir müddet sonra,çalıştığım firmanın bilgisayarcıları geldi.İyi çocuklar

Benim için bu fırsat,aldım aldım yoksa ayazdayız yine

-Koçum bana bilgisayar lazım

-Hallederiz abi

-Bak, eve,kendime alacağım ha

-Kolay abi

-Kaça olacak? Hem ucuz hem her şeyi tam olacak ha

-Sana toplama yapalım abi

-Toplama ne lan? Kaportacı gibi,eski araba mı topluyorsun

-Korkma abi harika yaparız,

hem garantide veririz,bir şey olursa yenisini veririz

-Tamam ulan yapın bir tane

Fiyatta ödemede anlaştık.Bütün tanıdıklar kurtuldu bu dertten

Bilgisayarım geldi.Sevinçten havalara uçuyorum

Arkadaşlar kurdu bilgisayarı

Mutluyum,el yordamı birazda tarif ile yazı yazabiliyorum

Senelerce birikmiş işler var

Şiirler,hikayeler hepsini yazacağım

-Bilgisayarı almışsın abi

-Aldık şükür

-Ne marka

-Bilmem

-Ne yazıyor üstünde abi

-Falan yazıyor

-O monitörün markası abi

Toplama diyemiyorum.karizmayı çizdirmeyelim diye

Tam yazıyı yazmışım elektrik kesiliyor

Elektrik geldiğinde bir bakıyorum tüm yazdıklarım yok olmuş

Sarılıyorum telefona

-Koçum tüm yazılar gitti kafayı yiyeceğim

-Kayıt etmemiş miydin abi

-Yooo

-Kayıt edeceksin abi, ya da

-Ya da ne? 

-Sana sabit güç kaynağı vereceğiz

-O ne koçum

-Elektrik kesilse de bir müddet çalışır bilgisayarın,en azından kayıt edene kadar

-Ooo iyiymiş takalım

-İyisi var 600$ kullanılmışı var 400$ ama tavsiye etmem,

az güçlüsü var,çok güçlüsü var,şu markası var,bu markası var

-İstemiyorum kardeşim kalsın ben kayıta basarım

Artık ikide bir kayıta basıyorum,iki satır hop kayıt,iki satır hop kayıt

-Abi bunun televizyonu yok mu

-Yok

-Olur mu abi televizyonsuz

-Ne yapayım ulan televizyonu evde televizyon var

-Cine 5 i seyredersin

-Hadi ya,aganigi filmleri falan mı

-Ayıpsın abi,hem de şifreli maçları falan seyredersin

Sarılıyorum telefona

-Koçum buna niye tv takmadın

-Takarız abi

-Önce kapasiteyi büyüteceğiz 60 $

-Sonra

-Sonra tv kartı alacağız 80-100 $

-Sonra

-Birde krek program o bizden hediye

-Sonra

-Servis ücreti 40 $ o da sana oluru abi

-İstemem ulan tv mivi kalsın,feşın tv yi seyrederim daha iyi

-Abi bunun radyosu yok mu

-Yok ulan

Başıma geleceği biliyorum sormam bile

-Faks modemi yok mu

-Yok ulan posta güvercini kullanıyorum

-Resim basabiliyor musun

-Basacağım simdi sana –sopayı-

-Olur mu abi,kitabına resim koymayacak mısın

-Koyacağım

Doğru söylüyor öyle bir ihtiyacım var

Telefona sarılıyorum

-Koçum,resim falan nasıl olacak yani,kem küm

-Olur abi kolay

-Nasıl yani

-Önce sana bir s.ken er vereceğiz

-Allah belanı versin ulan o ne biçim laf

-Yanlış anladın abi yani scanner yani tarayıcı

-Öyle söylesene ulan hayvan; kırkaltı yaşından sonra tövbe tövbe

-100 $

-Lanet olsun getir

Eldeki fotoğrafları tarıyorum harika,

ama benim çekmem gerekfotoğraflar var ne yapacağız

-Koçum fotoğrafları ben çeksem nasıl olacak

-Kolay abi

-Sana göre kolay tabi oğlum,buldun benim gibi kaz’ı yol babam yol

-Önce sana bir fotoğraf makinesi vereceğiz

-Hah! bu defa yolamayacaksın beni,ben de bir tane var fotoğraf makinesi,emektar

-Olmaz abi dijital olacak,teknoloji uymaz

-Hay teknolojiniz hay medeniyetinizin

-Sonra sana bir port takacağız

-Başlama ulan yine, şimdi ben sana bir takarım

-İstersen abi sen bilirsin

Makine aldık –dijital,ucuzundan- 300 $, port’u da taktırdık münasip yerimize

Artık eksiğim yoktur herhalde derken

Bilgisayarım bir ağırlaştı sormayın

Bir dosya arıyorum

Bilgisayar tencere gibi ses çıkarıyor 

Hani tencere kaynarda kapağı tıkır tıkır vurur ya öyle

-Koçum bu bilgisayara bir şeyler oldu

-İnternet’e giriyor musun abi

-Ben anlamam çocuk giriyor galiba

-Tamam anlaşıldı,sana virüs bulaşmış abi

-Ne virüsü ulan,çok şükür sıhhatim iyi

-Öyle değil abi.sana solucan girmiş

-Ne Allah belanı versin o ne lan

-Korkma abi küçük bir şey

-İyi be! bir de utanmasan Anakonda girdi diyeceksin

Servis geldi baktı inceledi

-Abi solucan değilmiş 

-Çok şükür

-Yalnız bir şey söyleyeceğim kızma

-Tamam ulan kızmam

-Abi sana trojan girmiş

-O ne lan şerefsiz

-Sana truva atı girmiş abi

-Allah belanı vermesin e mi

Bir tane virüs önleyici program koydular

Bir tane solucan önleyici

Bir tane port kapayıcı

Virüsü biraz olsun önledik-ama-

Bilgisayar daha da ağırlaştı

Sebebini sordum

Virüs önleyici programlardan olurmuş

Çözümü var tabi

En son model hızlı bilgisayar almak

Fiyatını bile sormadım

-Oğlum ne oldu bu bilgisayara çalışmıyor

-Bilmiyorum baba

Ne yaptıysam çalıştıramadım,kaptığım gibi servise götürdüm

-Nesi var kardeşim bu meretin

-Elektrik gelmiyor

-Yani

-Arkada power saplay var o değişecek 20 $

Bu defa koz bende,vermeyeceğim o 20 $ ı

-İstemez ben saplayıveririm

Eski elektronikçiyim ya,ben yaparım elektriğini sigortasını

Kaptığım gibi eve götürüp açtım,hakikaten sigortası yanmış

Sigortayı söktüm,eski usul ince bir bakır telle sardım

Taktım yerine vira bismillah

Elektrik fişini takar takmaz bomba patlaması gibi bir ses- bir duman-

Bütün ev ayağa kalktı

Yine aldım servise götürdüm

-Nesi var bunun

-Abi bilgisayarı patlatmışsın

-Yani

-Hard disk gitmiş

-Hard disktir

-Si di sürücü kaput

-Has sidi-r

-Sadece kasa işe yarar tamamı değişecek

-? 

-1000 $

Evde oğlum ağlıyor ben bilgisayarımı isterim diye

Hanım’da bir haftadır benle konuşmuyor

Neyse bilgisayar kasasını kurtardık ya- 20 $ kardayım -

Yalınız bir sorun var, 980 $ nereden bulacağız

Mehmet Akif Gülhan  31.08.2005 Saat 13.03', 'Her şey korku ile başladı Yaşlanma korkusu Treni kaçırma korkusu Bunu nereden anlıyorsunuz Çocuğunuz farklı düşünüyor Farklı konuşuyor Kulla...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Gülhan']::text[], 8.5, '{"poet":"Mehmet Akif Gülhan","poet_slug":"mehmet-akif-gulhan","theme":"Türk Şiiri","is_hero":false,"total_lines":238,"source_url":"https://www.antoloji.com/teknolojinin-neresindeyiz-komedi-serisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
