INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyu yavrum nenni nenni', 'uyu-yavrum-nenni-nenni-celal-isildak-iq8c5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sefil yavrum hasta oldu

Yavrum memelerim doldu

Çift gezerdin tek kaldı

Uyu yavrum nenni nenni

	Doktorlar gelmiş dinliyor

	Yavru yatmış iniliyor

	Kimse halini bilmiyor

	Uyu yavrum nenni nenni

Doya doya sevmedim

Kıymetini bilmedim

Yavru halini sormadım

Uyu yavrum nenni nenni

	Bekir daha ne söyleyim

	Ben başına ne belayım

	Yavru seni neyleyim

	Uyu yavrum nenni nenni

Bekir IŞILDAK', 'Sefil yavrum hasta oldu Yavrum memelerim doldu Çift gezerdin tek kaldı Uyu yavrum nenni nenni 	Doktorlar gelmiş dinliyor 	Yavru yatmış inili...', ARRAY['Türk Edebiyatı','Şiir','Celal Işıldak']::text[], 8.5, '{"poet":"Celal Işıldak","poet_slug":"celal-isildak","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/uyu-yavrum-nenni-nenni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kal İki Dakika', 'kal-i-ki-dakika-i-lknur-cekici-79wip', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki dakika daha kal

Bak gözlerime, ak kalbime

Son kez sigara yak

Dumanları sevgime kat

Satır satır çoğal benimle

Tekrar alevlen yüreğimde

Gecelerce ben seninle

Yanarım inan bu sevgiyle

Sonra ekle dakikaları

Sensiz bırakma bu yılları

Yosun gözlerinden, akıtma acıları

Yaşatma yanlız sancıları

Affet, yitik zamanlarda bırakma

Veda ile yüreğimi kanatma

Hasretin koynuna da atma

Ne olur gitme,kal iki dakika', 'İki dakika daha kal Bak gözlerime, ak kalbime Son kez sigara yak Dumanları sevgime kat Satır satır çoğal benimle Tekrar alevlen yüreğimde Ge...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kal-iki-dakika-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
