INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin7', 'bin7-ese-ese-231lf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bilirsin ki aslında çok farketmez

ne olursa olsun yaşam eskitir

günler eskir sevişmeler eskir

bakışmalar gülüşler davranışlar

hem eskiyizdir hem de eskimekteyizdir

eskimek yenilenmemektir

eski tas eski hamam gibi

eskiyi ve eskinin geçmişini benimsemektir

sen beni yeni tut

ben seni

sen bunun için varsın

ben bunun için', 'bilirsin ki aslında çok farketmez ne olursa olsun yaşam eskitir günler eskir sevişmeler eskir bakışmalar gülüşler davranışlar hem eskiyizdir...', ARRAY['Türk Edebiyatı','Şiir','Ese Ese']::text[], 8.5, '{"poet":"Ese Ese","poet_slug":"ese-ese","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bin7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsandılar', 'i-nsandilar-alaaddin-kulcuoglu-twq6j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'küçük dünyalarında

yoğurdular hamurlarını 

umutlarıyla

ve sevgiyle katık ettiler

insandılar

ulaşılmayacak kadar uzak

ve inanılmaz sıcaktılar

iliklerine kadar cesur

iliklerine kadar korkaktılar

insandılar

yoklukların ortasında

merhametlerin ve acımasızlıkların mimarıydılar

her an dost ve düşmandılar

insandılar', 'küçük dünyalarında yoğurdular hamurlarını  umutlarıyla ve sevgiyle katık ettiler insandılar ulaşılmayacak kadar uzak ve inanılmaz sıcaktılar...', ARRAY['Türk Edebiyatı','Şiir','Alaaddin Külcüoğlu']::text[], 8.5, '{"poet":"Alaaddin Külcüoğlu","poet_slug":"alaaddin-kulcuoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/insandilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost Aradım', 'dost-aradim-atilla-gozukucuk-ee0py', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dost aradım nerde hani,

Bulamadım çok yer dolaştım,

Ölümlüdür bu dünya fani,

Dost aradım bulamadım.

Kadere karşı gelinmez,

Bugünü gördüm,dünü yazdım,

Yarın ne olur bilinmez,

Dost aradım bulamadım.

11/09/2005', 'Dost aradım nerde hani, Bulamadım çok yer dolaştım, Ölümlüdür bu dünya fani, Dost aradım bulamadım. Kadere karşı gelinmez, Bugünü gördüm,dün...', ARRAY['Türk Edebiyatı','Şiir','Atilla Gözüküçük']::text[], 8.5, '{"poet":"Atilla Gözüküçük","poet_slug":"atilla-gozukucuk","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dost-aradim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tomris Uyar için bir ağlama', 'tomris-uyar-icin-bir-aglama-mehmet-yasar-a-hb0pf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'öykünün anası! 

susarsan, öykü anısız kalır

kentin daracık sokaklarında kötü çocuklar

nasıl anlatır öykülerini zamanın uzağına

			

sustun, her yer karanlıktı

kentin gece gezen kızları toplandı Galata’ya

sen gibi karanfil, sen gibi diz boyu papatya

			

sustun otuzların kadını, sustuğun kentin adı bilinmez

uzaktır  yaşayana; sana yakın 

sen  o kentin çocuğusun, gözlerinde yıldızlar

			

sabahtın cıvıl cıvıl İstanbul sokaklarında

şimdi bir akşamüstü

			

bulut, teninin beyazlığından alırdı kederini

güneş seninle aydınlanırdı, yalnız sen

Turgutu ve Turgutu severdin

göğün sonsuz boşluğunda asılı mezarlık ziyaretin,

			

yalnız sen doya doya yaşama savaşında 

bu kadarcıktı hikayen

sustun, öykü öksüz kaldı.', 'öykünün anası!  susarsan, öykü anısız kalır kentin daracık sokaklarında kötü çocuklar nasıl anlatır öykülerini zamanın uzağına 			 sustun, h...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Yaşar A']::text[], 8.5, '{"poet":"Mehmet Yaşar A","poet_slug":"mehmet-yasar-a","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/tomris-uyar-icin-bir-aglama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Anlarsın', 'ne-anlarsin-fatma-caglayan-9sji6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne anlarsın 

