INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haiku Denemeleri 1', 'haiku-denemeleri-1-hanife-banu-kqp2n', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şimdi ben bir kapı önündeyim

sana açılmayan....', 'Şimdi ben bir kapı önündeyim sana açılmayan.......', ARRAY['Türk Edebiyatı','Şiir','Hanife Banu']::text[], 8.5, '{"poet":"Hanife Banu","poet_slug":"hanife-banu","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/haiku-denemeleri-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
