INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakarış', 'yakaris-fatih-arslan-vtz6n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hüzünlü bir gecenin yakarışı,

Vakit geçti ama,

Çıkıp dağlara haykırasım geliyor

Canım bağıra bağıra ağlamak çekiyor.

Gece üçe vurduğu an,

Bir adam karanlıkta yüreğiyle şiir yazıyor,

Aklına sevdiği düşüyor, uyuyamıyor,

Canı bağıra bağıra ağlamak çekiyor.

Birden kalkıyor yatağından terler içinde,

Sokakta volta atıyor,

Kimseler duymasın ama,

Canı bağıra bağıra nara atmak çekiyor.

Aslında bütün yaşadığı hayatı değilde sitemi andırıyor,

İki damla yaş düşüyor göz pınarından,sonra kesiliyor,

Yıllarca ağladığı burdan belli oluyor,

Canı sıkılıyor,Canı ölmek çekiyor

Bir haber yakıyor içini,ağır çekim resitalinde

Hayatı film gibi gözlerinin önünden geçiyor,

Parmağından ağır ağır bir yüzük düşüyor,

Canım bağıra bağıra ağlamak çekiyor.

Bir sen doğuyorsun pencereme,

Rüzgar ayrılığın şarkısı söylüyor,

Kalkıp muslıktan bir ''Sen'' içiyorum

Bakıyorum gökyüne, bıkıyorum

İşte o vakitler hep ağlıyorum.

Bir piyango çekiyorum,

Sonu hep sıfır, hep sıfır,

Yani etkisiz eleman,

Yani tek başına hiç bir işe yaramayan o uğursuz rakam,

Beni kaybedişlerin adamı yapıyor,

Canım bağıra bağıra ağlamak çekiyor.

Bir gül geçiyor elime,

Kahretsin, hep sevmiyor hep sevmiyor,

Fırlatıp atıyorum,bir silah dayıyorum

Kabuslar içinde uyandım yine,

Sensiz yaşamaktansa bu can 

Ölmek çekiyor...', 'Hüzünlü bir gecenin yakarışı, Vakit geçti ama, Çıkıp dağlara haykırasım geliyor Canım bağıra bağıra ağlamak çekiyor. Gece üçe vurduğu an, Bi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Arslan']::text[], 8.5, '{"poet":"Fatih Arslan","poet_slug":"fatih-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/yakaris-43-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 18/ Kadin ve erkekle ilgili', 'resaran-siir-ve-beyitsiler-18-kadin-ve-erkekle-ilgili-huseyin-avdic-q0f9x', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadınla Erkek Eşit Değildir

Kadınlar kızmasın, Allah onları zayıf yaratmıştır.

Hukuk dışında kadınla erkek hiç eşit olmamıştır.

******

Kadın Ve Erkek Birbirinin Tamamlayıcı

Kadın eksi''dir yaradılışça, erkek artı.

Eksi''dir amma, artının da varolma şartı.

******

Kadın Cinsel Obje Değildir

Kadın; aşktır, şehvettir, şefkâttir.

Onu yalnız şehvet gören, eşşektir! 

******

Kadın Erkekten Üstündür, Eğer...

Kadın erkekten üstündür, eğer Allah''a muti ve kulsa.

Erkek kadından alçaktır, eğer Rabb''a kulluğu olmazsa.

Berlin, Ağustos-Eylül 2005.', 'Kadınla Erkek Eşit Değildir Kadınlar kızmasın, Allah onları zayıf yaratmıştır. Hukuk dışında kadınla erkek hiç eşit olmamıştır. ****** Kadın...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-18-kadin-ve-erkekle-ilgili-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül bahceme hosgeldin BITANEM', 'gonul-bahceme-hosgeldin-bitanem-serpil-maglicoglu-n3rj0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sihirli sözler de varmis

Sihirli ellerin var oldugu gibi

Sihirli gözler de varmis

Sihirli ASK larin varligi gibi

Maskeler düsüyor yüzümden

Maskelerin tümü birer birer

Maskeler kurtarmazmis meger

Maske nin ardini da gören olunca

Duvarlar yikiliyor artik 

Duvarin icine örülmüs BEN siyriliyor 

Duvarlarimdi beni benden kaciran

Duvarlarimdi icimi SENDEN gizleyen

Gönül baglarim sere serpe yollarda

Gönlüm deki hüsranlar sözlerinle eriyor

Gönlümün dikenli telleri bir bir sökülüyor 

Gönlüm de yeniden bir bahce ekiliyor 

Gönül bahceme hosgeldin BITANEM

(Berlin 15.09.2005)', 'Sihirli sözler de varmis Sihirli ellerin var oldugu gibi Sihirli gözler de varmis Sihirli ASK larin varligi gibi Maskeler düsüyor yüzümden M...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gonul-bahceme-hosgeldin-bitanem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir Kokuyor bu gece', 'siir-kokuyor-bu-gece-fatih-arslan-17int', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şiir kokuyor bu gece,

Sanki geçen her dakika bir mısra,

Ve her mısra seni anlatıyor,

Yani sen yoksun diye mısralar ağlıyor,

Kıta kıta döküyorum seni kağıtlara,

Seni yazıyorum, gelen günü yazıyorum sabahlara,

Sen yoksun diye hasretlerde bu mürekkep,

Özlem yazıyor her hecesinde,

Kan çıkıyor, kan damlatıyor geceye,

Yani sen yoksun diye kalemlerde ağlıyor...', 'Şiir kokuyor bu gece, Sanki geçen her dakika bir mısra, Ve her mısra seni anlatıyor, Yani sen yoksun diye mısralar ağlıyor, Kıta kıta döküyo...', ARRAY['Türk Edebiyatı','Şiir','Fatih Arslan']::text[], 8.5, '{"poet":"Fatih Arslan","poet_slug":"fatih-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/siir-kokuyor-bu-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurulup', 'vurulup-eda-karatas-puzg9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen  gözlerimden  akan  nehir

yüreğimde  çağlayan  sevda

bedenimi  tutuşturan  ateş

gökyüzünde    uçuran bir  kuş

.... ve yeryüzünde  ezen aşksın 

sen  rüyam ,hayalim 

senj  sevdiğim,

nerede kimde  olursa olsun gözlerin, yüreğin

ben  sevmekteyim  seni hala  çoşkuyla

ne  uzaklıklara nedde  ayrılıklara  datyanmaz  yüreğim 

sen  yakınımda olsanda

tenimi  eskitirim  senin için

pırangalara  vurulup  dağlarım gözlerimi

senden  başkasını  sevmemesi  için 

cezam  neyse  cekerim

uğrunda  ölüm  olsa  gelirim

sen    sevdiğim 

dilimde  düğüm   yüreğimde     ölüm

bedenimde arzu ,  beynimde  soru 

sen   heyyyyy   sevdiğim

elimde  zehir  gözlerimde  ilaç 

sen  sevdiğim 

yüreğimin  aşkla  tutuşup yandığı nefesim,

dile  gelip  söylediği  iki  kelimesin..........', 'sen  gözlerimden  akan  nehir yüreğimde  çağlayan  sevda bedenimi  tutuşturan  ateş gökyüzünde    uçuran bir  kuş .... ve yeryüzünde  ezen a...', ARRAY['Türk Edebiyatı','Şiir','Eda Karataş']::text[], 8.5, '{"poet":"Eda Karataş","poet_slug":"eda-karatas","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vurulup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yildizlar damliyor odama', 'yildizlar-damliyor-odama-serpil-maglicoglu-h1y8z', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yildizlar damliyor odama

Binlerce kilit

Vurdugum dünyami

Aciyorum 

Canimin icini

Sevmeye ve sevilmeye hazir

Seni bekliyorum

Gönlümün kapilari 

Sana aciliyor

Yüzyillarin ardindan

Karanligin pesinden

Sessizligin icinden

Susamisligin arkasindan

SANA Canimin ici

Gönlüm gönlüne

Yüregim yüregine

Tenim tenine

Ruhum ruhuna

Demir atiyor

Yildizlar damliyor odama

Avuclarimin ici yaniyor 

Isik isik bir yoldayim 

Senin ruhundur  isildayan

karanligima sizan

Sizip ta beni benden alan 

Berlin 15.09.2005', 'Yildizlar damliyor odama Binlerce kilit Vurdugum dünyami Aciyorum  Canimin icini Sevmeye ve sevilmeye hazir Seni bekliyorum Gönlümün kapilar...', ARRAY['Türk Edebiyatı','Şiir','Serpil Maglicoglu']::text[], 8.5, '{"poet":"Serpil Maglicoglu","poet_slug":"serpil-maglicoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yildizlar-damliyor-odama-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vurun', 'vurun-durmus-karakus-hefm7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevgiye saygıyla eğilmek gerek

O kutsal duyguyu sevene sorun

Hiçbir haksızlığa dayanmaz yürek

Sevgiye ihanet edeni vurun.

İster ağa olsun isterse paşa

Bakmayın gözünden döktüğü yaşa

Öldürmek ALLAH''a mahsustur haşa

Sevgiye ihanet edeni vurun.

Böyle dönüyorsa dünyanın çarkı

Varmıdır insanın hayvandan farkı

Farketmez yaşının otuzu kırkı

Sevgiye ihanet edeni vurun

Sözümde ciddiyim gayet de sakin

Dürüstlük her yerde dünyaya hakim

Yaşamak herkezin hakkıdır lakin

Sevgiye ihanet edeni vurun.', 'Sevgiye saygıyla eğilmek gerek O kutsal duyguyu sevene sorun Hiçbir haksızlığa dayanmaz yürek Sevgiye ihanet edeni vurun. İster ağa olsun is...', ARRAY['Türk Edebiyatı','Şiir','Durmuş Karakuş']::text[], 8.5, '{"poet":"Durmuş Karakuş","poet_slug":"durmus-karakus","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/vurun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neden?', 'neden-cahit-pehlivan-q4c6g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ezilen hep benim,

Üzülen mi? 

Sorarım be kardeşim,

Tarif et bakalım kime uyuyor? 

Gördün değil mi? 

Elinde olmasa da, istemesen de,

Yine beni tarif ettin.

Neden? 

Göz yaşlarını kuru ekmeğe pastörize gibi süren,

Hiçbir şeye inat etmeyip, direnmeyen,

Yaşadığı tüm acı gerçeklerde, hep sukut eden,

Horlanıp, dışlanan ben oluyorum. Neden? 

Kardeş, ana, baba gibi kavramlar yabancı,

Dost, arkadaş, yar, yaren hepiside yalancı,

Erkeksen bul merhemini, haydi artık dinsin bu acı,

Yoksa dinden, imandan çıkaracaklar beni, neden? 

Şansmış, talihmiş zaten bunları bir fasılda geçtim de,

Şu ahlak kavramlarına acayip taktım son günlerde,

Dürüstlükmüş, hayır severmiş, iyilik edermişim de,

Haydi be oradan! Artık nefret ediyorum.

Bu kavramlardan...

Bu kavramları savunup taşımam için,

Yanımda bulundurmam için vahiy mi geldi? 

Cebrail’de tebligat mı iletti ki? 

Bütün bunlar, hep benden isteniyor neden? 

Neden? Neden? Yalnız ben ve benim gibiler,

Birilerinin sofralarında ucuz lokma oluyorlar,

Yada, kimilerinin dişinin dibinde, bir kırıntı.

Neden ha! Yaşamak istemiyorum o zaman,

Alın,  o zaman sizin olsun bunca yaşanan,

İstemiyorum artık, ne tek bir nefes, ne de bir bakış,

Ömür denen şey, sizin olsun,

İstememen artık onu, üstü kalsın,

Hemen tabutlu, teneşirli, bir düğün düzülsün. 

İmam da karar versin,

İkindi namazını müteakip mi olacak kalkış? 

Fazlada gecikmesin isterim, menzile varış,

Varsa başka çare, buyurun siz söyleyin,

Benim gibi milyonların, sessiz çığlığını dinleyin,

Ve söylenecek bir şeyimiz varsa, lütfen söyleyin.

Yoksa tabutum kalkmış omuzlara,

Bir daha da inmez yere,

Açılın kapılar, gidelim,

Tanrının dört ikliminde, 

En sıcak olan yerine,

Sizin anlayacağınız, Cehennemin dibine,

Birileri yaşamak istiyormuş, 

Yaşasın, yaşaya bildiğince,

Neden? Neden? Neden? 

Diye sormayın sizde, lütfen... 

Öyle bir günün arkasından ve gözyaşlarımla! ...

 Mardin', 'Ezilen hep benim, Üzülen mi?  Sorarım be kardeşim, Tarif et bakalım kime uyuyor?  Gördün değil mi?  Elinde olmasa da, istemesen de, Yine ben...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/neden-182-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaşamak Buysa', 'yasamak-buysa-cahit-pehlivan-8fpng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şu güzelim cennet dünyanın,

Yaşıyorum. Cennet bir yurdunda.

Bu cenneti, cehennem yapanlar varsa,

Yaşamaktan zevk alan olur mu? Orada,

Geçinim derdi başlar daha küçük yaşta,

Ekmek parası kazanmak için, yavrucaklarda.

Kimi boya kutusu ile dolaşır çarşılarda.

Kimisi de çekirdek, sakız satar insanlara,

Kimisi hamallık yapar, istasyonlarda,

Kimisi de, evden kaçıp, dolaşır pervasızca,

Bir dilim ekmek hakkı ödemek için,

Kimisi de çalışır, tozda, toprakta.

Şu güzelim cennet Dünyanın yurdunda,

Yaşayan insanlar olarak da,

Yaşam mücadelesi veriyoruz, daima,

Ezilerek, sömürülerek, vicdansızca ve acımasızca.

Keşan/Edirne', 'Şu güzelim cennet dünyanın, Yaşıyorum. Cennet bir yurdunda. Bu cenneti, cehennem yapanlar varsa, Yaşamaktan zevk alan olur mu? Orada, Geçini...', ARRAY['Türk Edebiyatı','Şiir','Cahit Pehlivan']::text[], 8.5, '{"poet":"Cahit Pehlivan","poet_slug":"cahit-pehlivan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/yasamak-buysa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman Yollara Düşsem', 'ne-zaman-yollara-dussem-akin-tekin-7mcwd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne zaman yollara düşsem,

Gözlerin geliyor aklıma! ..

Öfkeli bir ok gibi saplanıyor böğrüme acı! 

Sessiz kıyametler kopuyor içimde...

Bir şeyler olsa diyorum, kötü bir şeyler

Kaza yapsam mesela, kolum bacağım kırılsa,

Ya da hastalansam ölümüne,

Kötü bir şeyler olsa da,hafiflese acım...

Ne zaman düşsem yollara,

Peşimden geliyorsun...

Toplayıp bütün hüzünleri,

Sihirli bir pelerin gibi, örtüyorsun üstüme...

Ayçiçekleri geçiyor üzerimden,

Siyaha boyayıp yapraklarını, döküyorlar ellerime...

Kan oluyor ellerim! 

Gözlerimi kapıyorum, seni görmemek için...

İğneler batıyor gözlerime, binlerce sivri uç; 

felç olmuş aşkları hatırlatıyor bana, dayanılmaz...

Soluk bir gökyüzü altında uzarken yollar,

buğulu camlara adını yazıyorum...

Ve sen, gülümsüyorsun...

İşte yine başlıyor ayrılık...

Her gülümseyişinde, kendini yeniliyor acı...

Bir şarkı takılıyor dilime; 

Öyle sarhoş olsam ki

Sevdiğimi unutsam

Unutulmuyor oysa...

Bir bulutun peşine takılıp gitmişken gözlerim,

Uğur böceklerinin ateşli kanatlarında geliyor aşk...

Tam zamanıdır işte; 

Yanmalı! 

Kor olup yanmalı aşk için! 

Bir yanardağ gibi açılan yürek; 

Tutuşturmalı dünyayı! 

Heyhat; 

Her bir yaprağında bir damla gözyaşı gizli,

Bembeyaz güller döküyorsun yollarıma...

Buz kesiyor içim! 

Ve kar yağıyor! ..

Milyonlarca kelebeğin sırayla intihar etmesi gibi,

kar yağıyor…

Kaldırıp başımı gökyüzüne

umutsuzca haykırıyorum; 

Olmasın böyle, olmamalı; 

Yeniden yazılmalı bu aşkın sonu! 

Buna karşılık, tarih çeviriyor sayfasını...

Sonrası sessizlik…

Ateş ve su yalnızlığında,

kulakları sağır eden bir sessizlik…

Ne zaman yollara düşsem,

yalnız bir sokak lambası dışında,

bütün ışıklar sönüyor…

Ve hiç ara vermeden, durup dinlenmeden,

kar yağıyor...', 'Ne zaman yollara düşsem, Gözlerin geliyor aklıma! .. Öfkeli bir ok gibi saplanıyor böğrüme acı!  Sessiz kıyametler kopuyor içimde... Bir şey...', ARRAY['Türk Edebiyatı','Şiir','Akın Tekin']::text[], 8.5, '{"poet":"Akın Tekin","poet_slug":"akin-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ne-zaman-yollara-dussem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Taş Düştüğü Yerden Kalkar', 'tas-dustugu-yerden-kalkar-ali-ziya-camur-ktqgf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dehledik geceyi dağların sırtında yıldızlara basa basa

Nal seslerimizde söküverdi şafak, boy/l/adık ufukları

Bulvarlar şaşkın,  ovalar utanmıştı suskunluğundan

Sürüklemiştik rüzgârı doludizgin utkunun harmanına

Ödenemez borçların kan deryasına bastı geçti  bir Evren

İzi kaldı  zakkum kokulu; gölgesi  düştü yıldızlı doruklara

Islak türkülere  sardık çiçek tozağını kırlarımızın

Acıya alıştı sessizlik,  çağlayanlar  ıslıkladı bilincimizi

Solan  yiğitliğiydi hayatın, kendisi değil asla

Yangınlara mıhlanmış  çisenti,  geremez çarmıha beklentileri...

Uçarı suların ödediği bedele saklıdır  umutlarımız,

Değmeden anısı bitmemiş düşlerin kanayan aynasına.

Şimdi gölgesini arayan raylarca tuzlu yorgunluktayız

Susturulduğumuz ıslıkta  kilitlenmiş  kalmışız paramparça

Rengi bir, sofrası bir  farklı kimliklerde paslaşıp duruyoruz

Yarılmış söylemleri tenis topunca bir atıp  bir tutuyoruz

Dumansız yaşamların coşkulu izleriyle dağlanmış acılarda.

Zaman havuzunda halkalanan dalgalar,  dalgalanan halkalar,

Ya solgun unutkanlıkların  boyut  atlaması  gibi yayılır 

Ya....  düşlerimizi astığımız duvarlarda çözülür bu kırağı.

Gün gelir  fırlar, sisin kucağına saklı kırık anılar

Ödediklerimiz sayılır en sivri özlemlerin  borcuna

Günlerin kızardığı uçurumlardan uçururuz atlarımızı

Taşar,  eylem eylem dağıtır  köpükleri, kuşatılmış dalgalar....', 'Dehledik geceyi dağların sırtında yıldızlara basa basa Nal seslerimizde söküverdi şafak, boy/l/adık ufukları Bulvarlar şaşkın,  ovalar utanm...', ARRAY['Türk Edebiyatı','Şiir','Ali Ziya Çamur']::text[], 8.5, '{"poet":"Ali Ziya Çamur","poet_slug":"ali-ziya-camur","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tas-dustugu-yerden-kalkar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Gözlerim Ah', 'ah-gozlerim-ah-osman-karaduman-83xff', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ah ah,

Yine akşam oldu, güneş battı

Bir gün daha bitti

Ömrümden bir gün daha gitti

Aslında ne geçen günedir sitemler

Nede yalnız kalan yüreğime

Sadece gücendim ben 

Seni görmeyen şu gözlerime

Ne diye bakarlar ki saate

Ne diye parlarlar günün güzelliğinde

Ve ne diye ağlarlar ki ardından

Nede olsa görmedi güzelliğini

Sadece baktı öylesine maviliğine

Yaşadı hasretini

Ve,

Dünya gözüyle görmedi, göremedi

Şu gözlerim yine seni...

11.06.2003 - SARIGERME', 'Ah ah, Yine akşam oldu, güneş battı Bir gün daha bitti Ömrümden bir gün daha gitti Aslında ne geçen günedir sitemler Nede yalnız kalan yüreğ...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ah-gozlerim-ah-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur damlası', 'yagmur-damlasi-osman-gultekin-3a4x8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Her yere düşen yağmur damlasına bir mana vermeye çalışırdım ve hiçbir zaman bulamazdım..

Hatırlıyormusun her yağmur yağdığında ıslanmak isterdim ama hep sen engel olurdun...

ve şimdi sen yoksunhep ıslanmayı arzuladığım yağmur var dışarda bardaktan boşalırcasına yağıyordu beni çağırıyordu sanki yere düşen yağmur damlaları...

şimdi bana kim engel olacak ıslanmamak için 

bardaktan boşalırcısana yağan yağmurmu? yoksa hasta olma korkusumu ikiside değil.Sen yoksun ve engel olacak hiçkimse de yok şimdi senin yokluğunda ıslanıyorum...

İşte buldum yağmur damlalarının anlamını her yere düşen damla seni seviyoru diye fısıldıyor tıpkı benim senin kulağına fısıldadığım gibi ve sen yoksun iliklerime kadar ıslanıyorum senin yokluğunda...

Her yağmur dindiğinde ondan sonra içimde kopan fırtınalar başlardı gözlerim dolar ve ağlardım işte buda benim yağmurumdu..

Hep derdin sana ağlamak yakışmaz diye işte ağlıyorum yokluğun yakışsada yakışmasada ağlıyorum içimde kopan fırtınalarla birlikte ve sen yoksun...

Şimdi hangi mazeret seni benden koparacak hangi yağmur damlaları seni sevmiyorum dediğindemi yoksa içimde kopan fırtınlar dinincemi veya gözlerimden akan yaşlar dinincemi senden kopacağım hiçbiri değil...

sen yoksun ve senin yokluğunda yağan her yağmur seni andırıyor bana sen yoksun...

kalbim karanlıklar içinde zincir vurulmuş ışııda sensin anahtarıda...şimdi seni bekliyorum....

ve bir gece daha geçiyor yağmurlu senin yokluğunda', 'Her yere düşen yağmur damlasına bir mana vermeye çalışırdım ve hiçbir zaman bulamazdım.. Hatırlıyormusun her yağmur yağdığında ıslanmak iste...', ARRAY['Türk Edebiyatı','Şiir','Osman Gültekin']::text[], 8.5, '{"poet":"Osman Gültekin","poet_slug":"osman-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yagmur-damlasi-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün', 'bugun-osman-karaduman-kfso3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Mevsimlerden yazdı sen gittiğinde

Güneş gibi yaktı yüreğimi hasretin

Yaşanmıyor buralarda sen olmayınca

Seninle geçen günleri ararım bugün

Öyle kolay mıydı bırakıp gitmek

Hiç düşünmedin mi ardındakini

Gözleri yaşlı bıraktın beni

Güldüğüm günleri ararım bugün

Gelirsin diye umutluyum ben

Gelmesen de kırılmam üzülme sen

Nasılsa sevmişim seni yürekten

Geleceğin günleri beklerim bugün...

11.06.2003 - SARIGERME', 'Mevsimlerden yazdı sen gittiğinde Güneş gibi yaktı yüreğimi hasretin Yaşanmıyor buralarda sen olmayınca Seninle geçen günleri ararım bugün Ö...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bugun-70-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sevgiliye', 'eski-sevgiliye-osman-karaduman-t7d59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Elimde resmin var sensizliğin ilacı

Seni düşünüyorum gözlerim yaşlı

Katlanmak zor geliyor sensizlik zor

İnanmıyorsan sende yüreğine bir sor

Sanki seninle hala beraberiz

El ele birlikte yine sahildeyiz

Veda etmeden gittin dönmeni bekliyorum

Gelmeyecek olsan da gönlümü avutuyorum

İnsan sevince kolay unutamıyor

Laf olsun diye değil inan yüreğim yanıyor

İlgine sevgine muhtacım gözlerim seni arıyor

Yüreğim yansa da ellerim üşüyor

Eskisi gibi değil gülüm bu deli seni daha çok seviyor...

03.03.2003 - DALAMAN', 'Elimde resmin var sensizliğin ilacı Seni düşünüyorum gözlerim yaşlı Katlanmak zor geliyor sensizlik zor İnanmıyorsan sende yüreğine bir sor ...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eski-sevgiliye-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz İnsanlar İçin', 'biz-i-nsanlar-i-cin-nalan-kahraman-x0y5g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'İnsanlar; 

Doğarlar,

Büyürler,

Yaşamak için mücadele ederler.

Bazen gülerek,

Bazen ağlayarak,

Bazen de isyan ederek:

Ah,ah niçin doğrum,

Neden buradayım,

Nereye gidiyorum? 

Ah ulan ahh…

Her şeye rağmen yaşamaya değer be….

Biz insanlar böyleyiz; 

Bazen sevecen,

Bazen nankör,

Bazen güler,

Bazen kan kusarız.

Yinede yaşamak güzel deriz.

Sizde mutlu yarınlarda

Gönlünüzce yaşayın,

Sevin,sevilin,

Gülün,güldürün,

Ara sıra da..

Ağlayın,ağlatın ki

Yaşamın cilveleri de nasibini alsın; 

Nasıl olsa her şey biz insanlar için.', 'İnsanlar;  Doğarlar, Büyürler, Yaşamak için mücadele ederler. Bazen gülerek, Bazen ağlayarak, Bazen de isyan ederek: Ah,ah niçin doğrum, Ned...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/biz-insanlar-icin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Sende Gizliyim', 'ben-sende-gizliyim-osman-karaduman-vbjlk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hasretim sanadır meleğim

Sıcacık nefesinedir özlemim

Gözlerindedir yüreğim

Ben sende gizliyim

Gün seninle başlamalı

Her şey sende bulunmalı

Ay seninle doğmalı

Yaşam sende gizlenmeli

Sen vermelisin yeşile rengini

Ve sen olmalısın hayatın anlamı

Aşk seninle yaşanmalı

Sevgi sende gizlenmeli

Ve sende son bulmalı ömür

Senin yanında terk etmeli ruhum bedenimi

Gitmeliyim belki seni öpmeden

Ve aşkım sende gizlenmeli...

24.05.2003 - SARIGERME', 'Hasretim sanadır meleğim Sıcacık nefesinedir özlemim Gözlerindedir yüreğim Ben sende gizliyim Gün seninle başlamalı Her şey sende bulunmalı ...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/ben-sende-gizliyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-mehmet-koc-82mn1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bir bulut olsam 

seni yüklensem 

renk renk 

boğum boğum 

ve seni yağsam 

kıraç topraklar üstüne 

can olsan, canan olsan 

doğa olsam 

seni giyinsem 

yeşilin envai çeşidinde 

ve can versem her mahlukata 

sen olsam 

seni olsam 

sende olsam 

seni sen gibi sende yaşasam 

iki göz aralığında 

ben sende silinsem', 'bir bulut olsam  seni yüklensem  renk renk  boğum boğum  ve seni yağsam  kıraç topraklar üstüne  can olsan, canan olsan  doğa olsam  seni gi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Koç']::text[], 8.5, '{"poet":"Mehmet Koç","poet_slug":"mehmet-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sen-634-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Biraz Anlasaydın...', 'beni-biraz-anlasaydin-mustafa-murat-aydogdu-eh3s0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni biraz anlasaydın,

Peşinden koşmazdım bu kadar

Seninle dolmazdı her anım

Bu denli sevemezdim seni

Beni biraz anlasaydın,

Aşkına hasret nöbetleri tutamazdım her gece

Çalıştığın yerin önünden geçmezdim durmadan

Belki görebilirim diye

Beni biraz anlasaydın,

Hemen karşılık verseydin duygularıma

Kıymetini bilemezdim o zaman.

Sevgini kazanmışlığın verdiği huzurla

Sana daha çok bağlanmam gerekirken

Gün gün uzaklaşırdım senden

Beni biraz anlasaydın,

Yıldızlara bakmazdım her gece

En uzak yıldıza; senmisin diye

Bakabilseydim istediğim kadar yüzüne

İstediğimde dokunsaydım ellerine

Hatta uyuyabilseydim dizlerinde

Beni biraz anlasaydın,

Yağmurlu havalarda aptal aptal dolaşıp

Sırılsıklam olmazdım galiba! 

Fener maçlarını da kaçırmazdım

Çünkü daha önemli olurdu fener,senden

Beni biraz anlasaydın,

Gözlerim dolmazdı seni düşünürken

Kalbim böyle çarpmazdı her görüşümde

Görüş gününü bekleyen mahkumlar gibi

İçimde bin hasret,bin ümitle

Bekleyemezdim seni.

Bana birkez sarılsaydın,

Anlamı kalmazdı sarılışların

Neden diye merak etmezdim

Beni görünce çatılıyor kaşların

Nerede yanlış yaptım demezdim

En doğru olanı yapmışım gibi

Hatalarımdan soyutlardım kendimi

Beni biraz anlasaydın,

Dünyalar benim olurdu

Dünyalarımda ne kadar çiçek varsa; senin

Sonra yetmezdi sana sevgim

Daha fazlasını beklerdin benden,

Oysa tüm güzelliklerimi sana vermiştim

Sonra beni terkederdin

Dünya çiçeksiz,ben sensiz; 

Biterdim! 

Beni biraz anlasaydın,

Asla yazamazdım bu sözleri

İyi ki anlamadın,

İyi ki sevdim seni...', 'Beni biraz anlasaydın, Peşinden koşmazdım bu kadar Seninle dolmazdı her anım Bu denli sevemezdim seni Beni biraz anlasaydın, Aşkına hasret n...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Murat Aydoğdu']::text[], 8.5, '{"poet":"Mustafa Murat Aydoğdu","poet_slug":"mustafa-murat-aydogdu","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/beni-biraz-anlasaydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-osman-karaduman-9vdo3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Özlemekti belki de seni sevmek

Haykırmak sanırdım oysa ben

Nasılsa anlamıyorsun aşkımı

Duymuyorsun yalvarışlarımı

Yaşamak saymıyorum yaşadıklarımı

Sensiz geçen her an ölüme bir adım 

Benim için hayat senden ibaret

Yaşamak seninle olmak

Ölümse sensizliğin son durağı bence

Ne yapalım bu otobüste geldi sona

Duracak birazdan ve ben ineceğim

Ama sen bilmeyeceksin

Son durağın sen

Senin ise ben olduğumu

Ve ben ölüp gideceğim...

08.05.2003 – SARIGERME', 'Özlemekti belki de seni sevmek Haykırmak sanırdım oysa ben Nasılsa anlamıyorsun aşkımı Duymuyorsun yalvarışlarımı Yaşamak saymıyorum yaşadık...', ARRAY['Türk Edebiyatı','Şiir','Osman Karaduman']::text[], 8.5, '{"poet":"Osman Karaduman","poet_slug":"osman-karaduman","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sensizken-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vahşi Batının Mazisi...', 'vahsi-batinin-mazisi-mehmet-demir-atmali-bwn71', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '-Soru: ESANS niçin icad edildi? 

-Cevap: Bizans Çocukları''nda yıkanma kültürü olmadığı için, Fransa''nın kurucusu Fransuva suya düşerek, kazara ömründe bir defa yıkanmış. Vücudundaki pis kokuları gideremeyen Doktorları, ESANS denen kokuları icad etmişler. Bu nedenle ESANS MERKEZİ denince hemen akla Fransa gelir...

-Soru: Yüksek Topuklu Ayakkabı niçin icad edildi? 

-Cevap: Avrupalı Bizans çocuklarında Tuvalet Kültürü yoktu. Çok büyükçe pisledikleri için, pislikleri kıçlarına bulaşırmış... Bu soruna çözüm olarak, Yüksek Topuklu Ayakkabı icad edilmiş, kıçlarını yerden yükseltmeyi becerebilmişler...

Bizler de Topuklu Ayakkabıyı moda olarak giyiyoruz.

-Soru: Diş Fırçası deyince Bizans''ın aklına ne gelir? 

-Cevap: Bir ırmak kenarında konaklayan Osmanlı Askerleri''ni izleyerek, komutanlarına rapor veren Bizans Askerleri; Osmanlı Askeri''nin Misvak ile dişlerini temizlediklerini görünce anlam verememişlerdi.

-Osmanlı Askerleri''nin, Bizans Askerleri''ni daha iyi ısırabilmeleri için dişlerini bileledikleri(keskinleştirdikleri)   ni komutanlarına rapor etmişlerdi... Komutan da ''dikkatli olun'' diyerek tembihte bulunmuştu.

17.9.2005', '-Soru: ESANS niçin icad edildi?  -Cevap: Bizans Çocukları''nda yıkanma kültürü olmadığı için, Fransa''nın kurucusu Fransuva suya düşerek, kaza...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/vahsi-batinin-mazisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kuzgunun Pandomiması', 'kuzgunun-pandomimasi-i-mdat-demir-ghlec', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'çala kamçı bizar durur yeleleri kar

ölüm çekirdeği diğer yarısı hayatın

omuzlarında keman telleri uçuşur

gözleri merdiven yorgunu kanar

uzaklardan kim sorar mahşere kaç atlı var

yanıp söner kelimeleri

kesik heceler de abak düzenler

gökyüzü abanoz hep kalır

polen rengi saçları kaçgöç niçinler

beyninde mermerden anlamlar

bir dize hangi sözle gelir

soğuk sorular mı yakar şarabın yüzünü

yoksa elim bir şiir mi

yine kelimeler

ve şehir şiirde inficar

aşk mı

tuzlu ten adası

ve başkası

orada sancılar intihar işaretçileri

mezar kazıcıları

debbağlar sahtiyan

dağ ve kuzgun

bu kadar

bir fotoğraf açık edecek yanağındaki gizleri

eşik altında

asabi gülüşleri

fırlatmak ise bir çocuğu annesinden

bazen anlam aramamalı

sadece esnemeli belimizdeki can

esriten

uzaklarda

bir yerlerde

bir yaprağın gölgesinde

ruhunu kanatarak

sahipsin bir şeylere

oysa ''olmak'' başkadır

bir ocağın başında ateşi seyreden

sözcükler kelebekler

ve plesenta...

omzunda kesikler ölümün çekirdeği…', 'çala kamçı bizar durur yeleleri kar ölüm çekirdeği diğer yarısı hayatın omuzlarında keman telleri uçuşur gözleri merdiven yorgunu kanar uzak...', ARRAY['Türk Edebiyatı','Şiir','İmdat Demir']::text[], 8.5, '{"poet":"İmdat Demir","poet_slug":"i-mdat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/kuzgunun-pandomimasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu', 'bu-i-mdat-demir-wqkli', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'balerinlerle niçin yaşamak zorundayız

onları öldürelim:

elim

kırıldı ve

kalem kadım dostum

ve şiir

iki dudak arası ıslak öpücük

ve kanlı çocuk

şarkının Es 

durağı

Rüzgar

Sahi

Gökyüzünde ne var', 'balerinlerle niçin yaşamak zorundayız onları öldürelim: elim kırıldı ve kalem kadım dostum ve şiir iki dudak arası ıslak öpücük ve kanlı çoc...', ARRAY['Türk Edebiyatı','Şiir','İmdat Demir']::text[], 8.5, '{"poet":"İmdat Demir","poet_slug":"i-mdat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretin Kanıma Girdi Girecek', 'hasretin-kanima-girdi-girecek-abdullah-arkadas-tnpe5', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'adımın önünde adın yazılı

resmimin yanında resmin basılı

sabrım sabıkalı,sevdam azılı

hasretin kanıma girdi girecek', 'adımın önünde adın yazılı resmimin yanında resmin basılı sabrım sabıkalı,sevdam azılı hasretin kanıma girdi girecek...', ARRAY['Türk Edebiyatı','Şiir','Abdullah & Arkadaş']::text[], 8.5, '{"poet":"Abdullah & Arkadaş","poet_slug":"abdullah-arkadas","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasretin-kanima-girdi-girecek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntılar I', 'kirintilar-i-ruhsel-bariscimen-c7905', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bayat bir ekmeği alıp dilimlediginde ufalanıp dökülür ya hani; işte bu günlerde yüregimde aynen öyle kırıntılarla dolu....Yoksa kırıklar mı? 

Ben de tam çözemedim ya...Yürek bayatlar mı diyorum...

Düsünüyorum! ... Bayatliyan biseyler var, var da yürek değil...ask galiba...

Bayatladikça aşk ufalanip parça parça dökülüyor...Bende topladim kırıkları kuslara yem ediyorum....Uçup gelmediler mi sana? 

Tembihliydiler oysa; özlemis, sana çok kırgin diyeceklerdi...', 'Bayat bir ekmeği alıp dilimlediginde ufalanıp dökülür ya hani; işte bu günlerde yüregimde aynen öyle kırıntılarla dolu....Yoksa kırıklar mı?...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kirintilar-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Telafer Muzaffer', 'telafer-muzaffer-oguz-duzgun-3e295', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Telafer...

Gözlerime fer! 

Telafer..

Mümin bir nefer! 

Telafer...

Zaferdir zafer! 

Telafer...

İslam`a miğfer

Telafer..

Türk`e atmosfer

Telafer...

Olmaz telef er

Telafer...

Dâim muzaffer

Telafer...', 'Telafer... Gözlerime fer!  Telafer.. Mümin bir nefer!  Telafer... Zaferdir zafer!  Telafer... İslam`a miğfer Telafer.. Türk`e atmosfer Telaf...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Düzgün']::text[], 8.5, '{"poet":"Oğuz Düzgün","poet_slug":"oguz-duzgun","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/telafer-muzaffer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kızıma Maniler', 'kizima-maniler-erdogan-ergin-y0uqr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '--kızıma

yıl biter, ay biter

çekilirse gün biter

damarımda damla damla kan

ömrümden ömür biter

çekildi çileler

elinde fileler

kapıda 

bebeğim bekler

--kızımdan

bir gelir, bir gider

biri babam der

aklar saçına çabuk düştü

evde sensiz gün mü biter?', '--kızıma yıl biter, ay biter çekilirse gün biter damarımda damla damla kan ömrümden ömür biter çekildi çileler elinde fileler kapıda  bebeği...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kizima-maniler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntılar II', 'kirintilar-ii-ruhsel-bariscimen-y116h', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şurda arka cebimde taa çocukluğumdan kalma kırıntılar var...

Kimi arkadaslarımdan, kimi annemden arta kalanlar..Allahtan arka cebimde de unutu veriyorum...

Sahile her çıktıgımda aniden annanem yanımda bitiveriyor...birlikte  hiç konuşmadan arka cebimdekileri balıklara atıyoruz...Bitmiyorlar bir türlü, el attıkça artıyor sanki...

Keske cebim delik olsaydı da saça döküle bitirseydim..zamanın sanki bonus etkisi var...tasidikça artıyor kırıntılarım...', 'Şurda arka cebimde taa çocukluğumdan kalma kırıntılar var... Kimi arkadaslarımdan, kimi annemden arta kalanlar..Allahtan arka cebimde de unu...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kirintilar-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bundan Kurtulamazsın', 'bundan-kurtulamazsin-yilmaz-helimergin-ofmda', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tenin donup titreyip te ruhun senden uzarken; 

Öyle yoğun duygu ki aman desen kaçamazsın.

Nurun senden irkilip te yerden göğe uçarken; 

Yaman yorgun olursun, bundan fazla olamazsın.

Şüphe dolup ürperirken,  belki son kez bakarken! 

Aklın durur işlemez, hiçbir yere varamazsın.

Bir el ve su bekler iken,  “medet ya Râbb” umarken; 

Çoktan gelir almaya seni ondan çalamazsın.

Canı siper eyleyip te inat edip yaşarken; 

Son bir nefes çekince asla geri alamazsın.

Hem ten hem rûh terleyip te deniz gibi taşarken; 

El kol açıp yalvarıp ey can bundan kaçamazsın! 

 	17.09.2003 20:00:00', 'Tenin donup titreyip te ruhun senden uzarken;  Öyle yoğun duygu ki aman desen kaçamazsın. Nurun senden irkilip te yerden göğe uçarken;  Yama...', ARRAY['Türk Edebiyatı','Şiir','Yılmaz Helimergin']::text[], 8.5, '{"poet":"Yılmaz Helimergin","poet_slug":"yilmaz-helimergin","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bundan-kurtulamazsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırıntılar III', 'kirintilar-iii-ruhsel-bariscimen-nndho', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Boyumca çocuklarım; hala akşam olup babalarının korne sesini duyduklarında oleeey babam geldi derler...

Ben çocukken babamın arabasının korne sesini duyunca oyun arkadaslarıma hosçakalın demeden eve kosar tuvalete saklanıp kapısını kilitlerdim...taa ki terim soguyup yüzümün kırmızılığı normale dönene kadar...

Benim yüzümden ablamin dayak yemesine dayanamazdım...ama çocukluk işte oyundan da geri kalmaz koşar, oynar, terlerdim...ablam da yalvarmama dayanamaz izin verirdi sokağa çıkmama...

Çocuklar; koşar, terler, düşer, dizleride yara olur kanar...hepsi geçer gider...

Yeter ki yüreğine cam misali kırıntılar birikmesin...', 'Boyumca çocuklarım; hala akşam olup babalarının korne sesini duyduklarında oleeey babam geldi derler... Ben çocukken babamın arabasının korn...', ARRAY['Türk Edebiyatı','Şiir','Ruhsel Barışçimen']::text[], 8.5, '{"poet":"Ruhsel Barışçimen","poet_slug":"ruhsel-bariscimen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kirintilar-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Yanım Kadıköy Bir Yanım Harem', 'bir-yanim-kadikoy-bir-yanim-harem-erol-buker-8hbic', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevdanı hapsettim bu akşam

yüreğimin  en ıssız köşesine.

soluk bir eylül akşamı

oturmuşum  vapur iskelesine

başımın üstünde çığlık çığlığa martılar

hani utanmasam 

inan ağlarım bu akşam. 

Ayışığı gir sende şu bulutların arasına

ne olur hatırım için bir süre kaybolsan

bir süre aydınlatmasan gecemi

hani gözyaşlarımı bir saklasam

inan ağlarım bu aksam.

Bu akşam herkes benimle

Geçmişim, hayalin,özlemin

yosun rengi gözlerin 

tanıdık tüm hüzünlerim.

vapurlar gelip gidiyor yorgun ve sessiz

gençliğimin yaşlı  vapurları

birde  konuşabilseler

Kimbilir neler neler vardır anlatacakları.

dalgalar vuruyor kıyıya

hüzünlü bir şarkının nağmeleri gibi

bütün gece adını ezberlediler

zavallı mutsuz dalgalar

birde beni anlasalar.

Sevdanı hapsettim bu akşam

yüreğimin en ıssız köşesine.

oturmuşum  vapur iskelesine

bir yanım kadıköy bir yanımda  harem

çok efkarlıyım bugün ben birtanem.

bu akşam martılar gibi cığlık cığlığa

vapurlar gibi yorgun ve sessiz

dalgalar kadar mutsuz

vede yıldızlar kadar yalnızım.

hani varya kendimden utanmasam

inan ağlarım bu akşam.', 'Sevdanı hapsettim bu akşam yüreğimin  en ıssız köşesine. soluk bir eylül akşamı oturmuşum  vapur iskelesine başımın üstünde çığlık çığlığa m...', ARRAY['Türk Edebiyatı','Şiir','Erol Büker']::text[], 8.5, '{"poet":"Erol Büker","poet_slug":"erol-buker","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-yanim-kadikoy-bir-yanimda-harem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin', 'gidisin-sair-faik-o21lr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İlkin öncelikli olması gerekiyordu

imlasının bozulmaması açısından

ama sen üçyüzaltmış derece dönüyordun

kar gibi yağıyordu bebekleri gözünün

üzerime doğru

veya

yanlış 

üşüyordum

ilkin öncelikli olması gerekiyordu

açık bir yerde öpüşmenin utancı gibi

buruk bir gülümsemeyle

gidişin...', 'İlkin öncelikli olması gerekiyordu imlasının bozulmaması açısından ama sen üçyüzaltmış derece dönüyordun kar gibi yağıyordu bebekleri gözünü...', ARRAY['Türk Edebiyatı','Şiir','Şair Faik']::text[], 8.5, '{"poet":"Şair Faik","poet_slug":"sair-faik","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gidisin-46-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baykuş', 'baykus-sair-faik-ew989', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'er gecelere ışık sızdıran kanunsuz

ılık ılık akıtıyorsun başını 

gövdeme

oysa ben 

dişi bir kelime istemiştim tanrıdan

uğursuz bir düşünce değil...', 'er gecelere ışık sızdıran kanunsuz ılık ılık akıtıyorsun başını  gövdeme oysa ben  dişi bir kelime istemiştim tanrıdan uğursuz bir düşünce d...', ARRAY['Türk Edebiyatı','Şiir','Şair Faik']::text[], 8.5, '{"poet":"Şair Faik","poet_slug":"sair-faik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/baykus-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-sair-faik-31kqj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir delik açılmış kayıkta

uzaktan balinaya benzetmiş kayığı

su fışkırtıyor

bu yüzden batacak yakında

bu yüzden başka bir balıkla tanışacak 

balina...', 'bir delik açılmış kayıkta uzaktan balinaya benzetmiş kayığı su fışkırtıyor bu yüzden batacak yakında bu yüzden başka bir balıkla tanışacak  ...', ARRAY['Türk Edebiyatı','Şiir','Şair Faik']::text[], 8.5, '{"poet":"Şair Faik","poet_slug":"sair-faik","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yabanci-53-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayaldeki seni', 'hayaldeki-seni-ugur-aydin-2-xst0j', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözün sağolsun görmüyormuş ki resmimi 

dilin sağ olsun anmıyormuş ki ismimi 

elin sağ olsun tumaz olmuş ellerimi 

kalbin sağ olsun sevmiş başka birisini 

gönlün sağ olsun çoktan unutmuşsun beni 

başın sağ olsun öldürdün hayaldeki seni', 'gözün sağolsun görmüyormuş ki resmimi  dilin sağ olsun anmıyormuş ki ismimi  elin sağ olsun tumaz olmuş ellerimi  kalbin sağ olsun sevmiş ba...', ARRAY['Türk Edebiyatı','Şiir','Uğur Aydin 2']::text[], 8.5, '{"poet":"Uğur Aydin 2","poet_slug":"ugur-aydin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hayaldeki-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hamlet''i Gördüm (Deneme)', 'hamlet-i-gordum-deneme-aydin-demirkan-aw42a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Antik tiyatronun yer yer çatlamış beton kakmalarında, tozlu ama tarih kokan havasında tek başıma izliyordum oyunu, tarih tekerrür ediyordu. 

Hain bıçağın sivri ucu sırtından bedenine saplandığında ölüm merhaba demişti Hamlet''e. Hareketini kısıtlayan kanlı bıçak yer etmişken sırtında, son çabasıyla geriye dönerek brütüse söylenen iki kelime ise çıkılan sınırsız yolculuk öncesi titretiyordu bedenimi...

Sen de mi Brütüs...

Zaman ve mekan farklıydı.

Fakat bana da uğramıştı ölüm. Yere boylu boyunca uzanmış gördüm kendimi ruhum göğe yükselirken. Karnıma kadar çektiğim dizlerim ve dizlerimin arasına sıkıştırdığım ellerimle anne karnındaki embriyonun şekillenmiş haliydim. Zaman ve mekan yoktu artık...

Ben Hamlet''i gördüm düşümde, Hamlet''in düşlerini gördüm.

Ve Brütüs''ü gördüm...

Hamlet öldü.

Brütüs öldürdü...

Ben öldüm.

Ve dirildim... Merhaba hayat...', 'Antik tiyatronun yer yer çatlamış beton kakmalarında, tozlu ama tarih kokan havasında tek başıma izliyordum oyunu, tarih tekerrür ediyordu. ...', ARRAY['Türk Edebiyatı','Şiir','Aydın Demirkan']::text[], 8.5, '{"poet":"Aydın Demirkan","poet_slug":"aydin-demirkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hamlet-i-gordum-deneme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyu', 'uyu-sair-faik-g0aiq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'uyu

daha çok vaktimiz var 

doymak için

gün ışısın gideceğim

yer bulamıyorum koca yatakta

seni uyandıracak

temiz bir yer

kaç saatimiz var sevişmeye doymak için? 

öyle güzel bir çocuksun ki

gözkapaklarını öpmeli uyanmadan

habersizken daha çok hissetmeli

kirpiklerinin beyaz sıcaklığını

şimdi uyan güzel kızım

vakit epey erken olmalı

baksana gün ışıdı...', 'uyu daha çok vaktimiz var  doymak için gün ışısın gideceğim yer bulamıyorum koca yatakta seni uyandıracak temiz bir yer kaç saatimiz var sev...', ARRAY['Türk Edebiyatı','Şiir','Şair Faik']::text[], 8.5, '{"poet":"Şair Faik","poet_slug":"sair-faik","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uyu-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Su Hasreti', 'su-hasreti-yagmur-damlasi-yress', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Zavallı kuyu, ay ışığına hasret 

Güneş bilmez neylesin 

Kaç taş atılır bağrına sabret 

Yağmurlarla su gelsin 

Dolarsa yüzünü yıkasın 

Ay dedenin küçük torunu 

Olmadı yıldızlardan kaydırsın 

Bereketini bolluğunu 

Buhar olup kokusu 

Semanın ruhuna otursun 

Başak versin boyu posu 

Aç çocukları doyursun 

Ya Sonra inatla sen 

Sonra adımlarına küsen 

Dağınık yatak saçlı adamın 

Göğsünde uyanacaksın 

Her aşk acı getirir ya peşinden 

Ardından öylece bakacaksın 

Yine gece olacak yine sabah 

Sen uyuduklarınla uyanacaksın 

Dilinde son sözün eyvah 

Doymayacaksın hayata 

Bir türlü dolamayacaksın 

İnsana aldanacak suya 

Kanamayacaksın 

Yüreğinde kalacaksın hep 

Bundan sebep 

Yağmurun damlasının.', 'Zavallı kuyu, ay ışığına hasret  Güneş bilmez neylesin  Kaç taş atılır bağrına sabret  Yağmurlarla su gelsin  Dolarsa yüzünü yıkasın  Ay ded...', ARRAY['Türk Edebiyatı','Şiir','Yağmur Damlası']::text[], 8.5, '{"poet":"Yağmur Damlası","poet_slug":"yagmur-damlasi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/su-hasreti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Düş tü Seni Sevmek', 'bir-dus-tu-seni-sevmek-i-lknur-er-l40aj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir düş tü seni sevmek

Dağ başında bir lale idin

Gönlümde

Tektin

Erişilmezdin

Dalgalanırdım her adınmında

Gözlerine değdiğinde gözlerim

Sil baştan yaratılırdım

Tepeden Tırnağa

Ürkekti duruşların

Sanki her an kanatlanacakmışta

Bu diyarlardan göçecek gibi

Göçebe aşkı idin kalbimin

Bir düştü seni sevmek

Hiç yaklaşamadan

Hep yanımdaymış gibi

Sevmek', 'Bir düş tü seni sevmek Dağ başında bir lale idin Gönlümde Tektin Erişilmezdin Dalgalanırdım her adınmında Gözlerine değdiğinde gözlerim Sil ...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bir-dus-tu-seni-sevmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstersen', 'i-stersen-i-lknur-er-w222f', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalbimde

Bir köşk yaptım sana

İpeklerle işledim nakış nakış

En güzel çiçekleri yerleştirdim içine

Kuş tüyü yastıklarla donattım

Aşk ile bezedim her yanını

Birde kilit vurdum üzerine

Bir tek anahtarı var 

Oda sende

İstersen şimdi kapıyı aç gir

Sonsuza kadar orada kal

İstersen anahtarı boynuma as git

Sonsuza kadar bensiz kal

Anahtarı açıp içeriye girme cesaretini gösteren sevdiğime sevgi ile.', 'Kalbimde Bir köşk yaptım sana İpeklerle işledim nakış nakış En güzel çiçekleri yerleştirdim içine Kuş tüyü yastıklarla donattım Aşk ile beze...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/istersen-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay ışığı akşamlarda deli oluyordum', 'ay-isigi-aksamlarda-deli-oluyordum-gencay-coskun-xytmx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gecenin ortasında lamba gibi duruyordu ay.

Kaçıp da saklanacak her hangi bir sığınağı da yoktu garibin. 

Geceler hüküm salmak zordur aslında, 

Canım ay güneşten aldığı oncacık ışığını dağıtıyordu üstümüze.

Sessiz kimsesiz yakamozların deryasında

Deniz kenarında olmak lazımdı şimdi aslında 

Durdum düşündüm ‘kim tutuyordu beni’ dedim içimden

Diğer bir ses muhtemelen bana ait değildi 

‘Yürü yakamozlara’ dedi.

Güldüm kendi kendime

Yalnızlıktan monologlar uyduruyordum

Ya da ay ışığı akşamlarda sesler duyuyordum. 

Deliyim damarlarımdaki son damlaya kadar 

Yürüdüm yakamozlara doğru 

Gene güldüm kendime 

Düşündüm de kaç zamandır içten gülmüyordum

Bugün biraz dışıma taştı tek başıma 

Gecenin ortasında deniz kenarında oturdum

Doldurma kayaların üstünde 

Harbiden ortalık sessizdi

Uzaktan birkaç ses duyuluyordu

Onlarda belli belirsizdi 

Kendini en çok dinlediğin yerler 

Sessizlik duvarlarının üstüne örüldüğü yerlerdi

Yakamozlar denizin üstünde nasılda oynaşıyorlardı

Ne çok korkardım denizden 

Ölümü hatırlatırdı hep 

Bugünse ölümüne sevdalı meçhul asker gibi

Ay ışığı akşamlarda yakamoz yakalamaya çalışıyordum.

Gene gülüyordum kendime 

Damarlarımdaki deli kanın etkisi çok fenaydı 

Sessizlik ve yalnızlıkta fena çarpıyordu beni.

Ne kadar çarpsa da haklıydı 

Deli kanlı olmak sonu olmayan bir ayrıcalıktı. 

Dalıp dalıp gidiyordum yakamozların dansında 

Geçmişe geleceğe olamadığım ve olmak istediğim her yere

Hayal kurmak dilemek istemek dua etmek parayla değildi 

‘Yağar mı şimdi sevgili yağmur’ dedim

Gene o ses ‘Deli misin ay ışığı akşamlarda yağmur yağar mı’ dedi

Kıllandım bir kere sesten birazda ürktüm 

Gene güldüm kendime 

Bugüne kadar hiç gülmediğim kadar.

‘Evet deliyim, görürsün bak yağar yağmurum’ dedim.

Sonra ne mi oldu ses güldü ben güldüm 

Güle güle bir geceyi ortaladım tam ortasında

Yüreğimden vuruldum. 

Nerelerde kaybolmuştum ki 

Sıkılıp dünyadan bir ucuna saklanmıştım

Saklamıştım kendimi 

Ay ışığı akşamlarda yakamozları özlemiştim 

Ses te sustu bende sustum 

Bir boşluktu düşüncelerimi baştan sona silmeye çalışan 

Ama ancak tozunu aldı 

Gene gülümsedim 

Ses gene suskundu 

Bulutlarım gelmişti 

Her nerelerdeyse

Çığlık çığlığa bir şeyleri anlatıyordu 

Bu sessizlikte hiçbir şey duyulmuyordu

Elime bir taş aldım 

Kaldırıp atasım geldi yakamozlara 

Kıyamadım sonra taşa sen yıllarca uğraş kıyılara çıkacam diye

Kaldır at denizin ortasına 

Biraz haksızlık gibi geldi 

Aldığım yere usulca koydum 

Sanki sevenleri ayırırmışım gibi geldi

Ürperdim 

Birden ses ‘Sen doğrusun. Al sana yağmurun ’ dedi

Ay ışığı akşamın ilk yağmurunun damlası sağ yanağıma düştü

Sol yanağımdaki damla ise benden geldi 

Gece ağladı ben ağladım,

Ben ağladım gece ağladı,

Yanlıkta şehir sadece seyretti 

Tüm olan biteni bilmeden 

Ay ışığı akşamlarda deli oluyordum

Gece ağladı ben ağladım,

Ben ağladım gece ağladı,

Yüreğimin garibanlığında

Çok lüks yaşıyordum aslında 

Şükürlerden bir kolyeyi Yaratanıma

Yağmurları yüreğime verdim.

Gece ağladı ben ağladım,

Ben ağladım gece ağladı,

Sonra kalktım geldiğim kıyıdan

Gittim içimin en ücra vilayetine

Hiç tanıyanım olmasın istedim 

Çokta gülmedim gündüzlerde 

Yalan olanların dışında

İçimden hep ağladım yanaklarımı ıslatmadan. 

Ay ışığı akşamlarda deli oldum.

Galiba tas tamam deli kanlı oldum.', 'Gecenin ortasında lamba gibi duruyordu ay. Kaçıp da saklanacak her hangi bir sığınağı da yoktu garibin.  Geceler hüküm salmak zordur aslında...', ARRAY['Türk Edebiyatı','Şiir','Gencay Coşkun']::text[], 8.5, '{"poet":"Gencay Coşkun","poet_slug":"gencay-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/ay-isigi-aksamlarda-deli-oluyordum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türk Genci (I)', 'turk-genci-i-cihan-kaya-nxz4b', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaraya tuz ekip dert biçeriz biz

Susar da kanarız söz içeriz biz

Durdurup zamanı dem içeriz biz

Alemlere değer Türk Genci''yiz biz

Dayanıp gerçege hiç düşmeyiz biz

Toprak çıkarınca yer eşmeyiz biz

Doğrular yolunca tez şaşmayız biz

Alemlere değer Türk Genci''yiz biz

Yalan dolan dolsa tek asılız biz

Üzülmüş umuda hep fasılız biz

Bırak el-alemi biz nasılız biz? 

Alemlere değer Türk Genci''yiz biz', 'Yaraya tuz ekip dert biçeriz biz Susar da kanarız söz içeriz biz Durdurup zamanı dem içeriz biz Alemlere değer Türk Genci''yiz biz Dayanıp ge...', ARRAY['Türk Edebiyatı','Şiir','Cihan Kaya']::text[], 8.5, '{"poet":"Cihan Kaya","poet_slug":"cihan-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turk-genci-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-yavuz-bayram-caliskan-rddw3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey hüzün al başını git 

Ben Çin seddini bile dolanırım

Surlarını mancınıklarım İstanbul''un 

Boğazımda düğümlenir boğazda yediğimiz ekmek

Kalırsın benimle yeniden

Çekemem, git ne olur git 

Seni Allah''ımdan dileyemem', 'Ey hüzün al başını git  Ben Çin seddini bile dolanırım Surlarını mancınıklarım İstanbul''un  Boğazımda düğümlenir boğazda yediğimiz ekmek Kal...', ARRAY['Türk Edebiyatı','Şiir','Yavuz Bayram Çalışkan']::text[], 8.5, '{"poet":"Yavuz Bayram Çalışkan","poet_slug":"yavuz-bayram-caliskan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/huzun-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umursamaz Aşk', 'umursamaz-ask-ugur-oguz-sahin-22fu3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Canımı acıttı hep

Aşkın güllerindeki dikeni

Niçin nasıl sorgulandım

Açtılar bıkmadan eski defterleri

Nadas gönüllerinde haram geceleri

Umut sevginin göleti

Gözlerde kesilir aşkın bileti

Umursamaz aşk memleketi milleti

Riya onursuzluk sabırdır gönül serveti', 'Canımı acıttı hep Aşkın güllerindeki dikeni Niçin nasıl sorgulandım Açtılar bıkmadan eski defterleri Nadas gönüllerinde haram geceleri Umut ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Oğuz Şahin']::text[], 8.5, '{"poet":"Uğur Oğuz Şahin","poet_slug":"ugur-oguz-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/umursamaz-ask-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne Bilirsin?', 'sen-ne-bilirsin-ufuk-bayraktar-wqzkl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''senin anan, 

        baban, 

              kardeşin, 

                  bebeğin değildir ölen,

doktor

sen ne bilirsin yürek yangınını! ''

senin kadar üzülmez doktor,

çabası boşa gitmiş

kurtaramadığı hastasının öldüğünü

nasıl söyleyecektir? 

kelimeler nasıl tane tane

nasıl kesik kesik...

ahh! 

sen bilir misin? ? ? 

şimdi değilse birazdan gülecek yüzün,

yemek saati geldiğinde oturacaksın masaya; 

biz taziyeleri kabul ederken belki sen piknikte olacaksın...

çünkü yoktur doktorların anası,

     babası, 

              kardeşi, 

                         bebeği

bilmezler onlar içi nasıl titrer insanın

ölümü her gün tanırlar ama 

bilmezler acısını...

yoktur onların babaanneleri,

bir başka meslektaşına emanet edip

kendi işindedir...

akşam aradığında artık olmadığını söylemezler ona! 

sen ne bilirsin ufuk! 

her ölüm yıkmasa da 

sarsar seni...

yıpranmış bedenin dayanacak mı bir gün

          anan

                  baban

daha kötüsü kardeşin öldüğünde?', '''senin anan,          baban,                kardeşin,                    bebeğin değildir ölen, doktor sen ne bilirsin yürek yangınını! '' se...', ARRAY['Türk Edebiyatı','Şiir','Ufuk Bayraktar']::text[], 8.5, '{"poet":"Ufuk Bayraktar","poet_slug":"ufuk-bayraktar","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sen-ne-bilirsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmedin', 'bilmedin-kazim-tinaz-bodkm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevdin desem,hiç sevmedin.

Sevda nedir, hiç bilmedin.

Muhtaç idi bir kalp sana,

Gördün desem, hiç görmedin.

Yağdı karlar, kar üstüne,

Geçti yazlar, yaz üstüne,

Doldu topraklar üstüme,

Gördün desem, hiç görmedin.

Can faniydi vade doldu,

Ne sen, ne de aşkın soldu,

Ne olduysa bana oldu.

Bildin desem, hiç bilmedin.', 'Sevdin desem,hiç sevmedin. Sevda nedir, hiç bilmedin. Muhtaç idi bir kalp sana, Gördün desem, hiç görmedin. Yağdı karlar, kar üstüne, Geçti ...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilmedin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyemedim', 'diyemedim-kazim-tinaz-fgcw0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tok kalmadım, hep yarı aç,

Bir lokma ekmeğe muhtaç.

Sevda, sılada tek ilaç.

Diyemedim, diyemedim.

Sarardı gül benzim, soldum.

Mezara kimsesiz kondum.

Gurbette toprağın oldum.

Diyemedim, diyemedim.

Hasretlik vurdu gözümü,

Gurbetlik aldı özümü,

Kalanlara son sözümü,

Diyemedim, diyemedim.', 'Tok kalmadım, hep yarı aç, Bir lokma ekmeğe muhtaç. Sevda, sılada tek ilaç. Diyemedim, diyemedim. Sarardı gül benzim, soldum. Mezara kimsesi...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/diyemedim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bedel', 'bedel-gulseren-onay-wlmzp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Evet 

Diyerek başlanır mı

Aşka? 

Verilen sözler mi

Büyütür aşkı? 

Aşık

İstemeden 

Hedef olmaz mı 

Eros’un okunun 

Kan kızılı ucuna 

Yürek yara alır 

Cevap artık 

Ne evet

Nede hayırdır..

Sağaltmak için, 

Yara

Yıkanmalı

Afrodit’in yıkandığı 

Sularda..

İstemsizdir aşk

Yanıt aramayan sorulardır

Beklentisizdir 

Ve 

Ulaşılmazlık 

Bedelidir büyük aşkın..

17/09/2005 Gülseren Onay …', 'Evet  Diyerek başlanır mı Aşka?  Verilen sözler mi Büyütür aşkı?  Aşık İstemeden  Hedef olmaz mı  Eros’un okunun  Kan kızılı ucuna  Yürek ya...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bedel-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Gül', 'beyaz-gul-mehmet-omer-cg9s7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçine  göm kentleri

yalnızlığı duyulsun

kırık düşlerin

umut umut aç

sabah karanlığında

çiğ damlası gözlerime.

dikenler

gülleri ağlatamaz', 'İçine  göm kentleri yalnızlığı duyulsun kırık düşlerin umut umut aç sabah karanlığında çiğ damlası gözlerime. dikenler gülleri ağlatamaz...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ömer']::text[], 8.5, '{"poet":"Mehmet Ömer","poet_slug":"mehmet-omer","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/beyaz-gul-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Huri Gözler', 'huri-gozler-aliye-onur-39g3l', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkları harlar ruhların içtenliği,

Şevkle doldurur coşar yürekleri...

Sessizce derler paylaşır bilinmezi,

Sevdaya tutulur dalar gözleri... 

Aşk şerbeti buluşturur sözleri, 

Gönüller hazda ihya eder dilleri, 

Canlar hicranda yanar yürekleri,

Meçhulde kesişir bahar gözleri...

Yaşandıkça alevlenip kavurur ateşi,

Latife şevklenip taşar sevgileri...  

Saatleri alıp giden dillerde düşleri,

Aşktır parıldatıp ışıldatan gözleri...

Şirin bekler ferhat’ı özünde şehvetli, 

Canlar fısıldar yarene aşkı gizemli...

Gönülde umutlar aklın sebat denizi,

Derinden yakar sevdanın huri gözleri...', 'Aşkları harlar ruhların içtenliği, Şevkle doldurur coşar yürekleri... Sessizce derler paylaşır bilinmezi, Sevdaya tutulur dalar gözleri...  ...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huri-gozler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşçakalsın Sevenlerim', 'hoscakalsin-sevenlerim-kazim-tinaz-vuyl2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne dün kaldı, ne bugünüm,

Geçti ömrüm, doldu günüm.

Hoşçakalsın sevenlerim,

Diyemedim çok üzgünüm.

Uzak kaldım anam uzak,

Kader kurdu bana tuzak,

Ördüğün o yeşil kazak,

Saramadı çok üzgünüm.

Silemedim gözlerini,

Deremedim güllerini,

O mübarek ellerini,

Öpemedim çok üzgünüm.

Gurbet dağladı gözümü,

Yaradan aldı özümü,

Son kez anam, nur yüzünü,

Göremedim çok üzgünüm.', 'Ne dün kaldı, ne bugünüm, Geçti ömrüm, doldu günüm. Hoşçakalsın sevenlerim, Diyemedim çok üzgünüm. Uzak kaldım anam uzak, Kader kurdu bana t...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hoscakalsin-sevenlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşüdüm', 'usudum-aliye-onur-2goit', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Günün son deminde; 

Tutuluncaya med-cezire, 

Dalgalarla karaya yol aldım… 

Kamerin ışıltısında, 

Bulutlara sarıldım sessizce... 

Çiselediler iç çekişlerle; 

Boşlukta kaldı nemli ellerim… 

Kandilleri yoldaş bildim; 

Kayarken meçhule, 

Dileklerin eşliğinde 

Buğulu çöllere düşüverdim… 

Buselerle sahralarda gölleştim… 

Rüzgarın kanadında gezindim, 

Gözlerden gönüllere süzüldüm, 

Dillerden akıllara yürüdüm 

Tutunamadım 

Üşüdüm…', 'Günün son deminde;  Tutuluncaya med-cezire,  Dalgalarla karaya yol aldım…  Kamerin ışıltısında,  Bulutlara sarıldım sessizce...  Çiselediler...', ARRAY['Türk Edebiyatı','Şiir','Aliye Onur']::text[], 8.5, '{"poet":"Aliye Onur","poet_slug":"aliye-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/usudum-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Görmeden', 'gun-gormeden-kazim-tinaz-3cg6n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çok çileler çektim Tanrım,

Daha otuza ermeden.

O güzele nasıl kandım,

Eriyorum gün görmeden.

Çıkmaz olaydı karşıma,

Acımadı genç yaşıma,

Doldu miad tek başıma,

Gidiyorum gün görmeden.

Ecel gelmiş can almaya,

Gücüm varmaz durdurmaya,

Bu dünyadan, o dünyaya,

Göçüyorum gün görmeden.', 'Çok çileler çektim Tanrım, Daha otuza ermeden. O güzele nasıl kandım, Eriyorum gün görmeden. Çıkmaz olaydı karşıma, Acımadı genç yaşıma, Dol...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gun-gormeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karınca Gibi', 'karinca-gibi-mehmet-bicik-420wo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir sevdâ uğruna,

Karınca gibi çalıştım…

Bu yolda kimlerle,

Nelerle karşılaştım…

Özendim büyük yazarlara,

Benzemek istedim Sezar’lara,

Her gün giderek mezarlara,

Mezarıma alıştım…

Düşünmek için özgürce,

Söylemek için mertçe,

Yaşamak için Türk’çe,

İslâm’a yanaştım…

17 Ekim 1994, Kumkapı', 'Bir sevdâ uğruna, Karınca gibi çalıştım… Bu yolda kimlerle, Nelerle karşılaştım… Özendim büyük yazarlara, Benzemek istedim Sezar’lara, Her g...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/karinca-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Veli De Bir, Deli de!', 'veli-de-bir-deli-de-zulfikar-yapar-kaleli-jbk2f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'font face=''Comic Sans MS'' color=''black'' size=''0,5''

Eda kıvrak, naz ince   

Şehir de bir, köy de bir! 

Ecel donu giyince

Paşa da bir, bey de bir! 

İnsanlar kısım kısım

Derdim var isim isim

Bitecek mi bu mevsim? 

Aman da bir, oy da bir! 

Parsellenmişse yürek

Ona hürriyet gerek

Ne umut var, ne erek

Kazançta bir, zay da bir! 

Yazık değil mi yazık? 

Heybede yoksa azık…

Kalbinde sicili bozuk

Bayan da bir, bay da bir! 

Yiğit benzer volkana

Lüzum görmez kalkana

Pusulasız yelkene

Liman da bir; koy da bir! 

Akıl ki ermiyorsa,

Kalp karar vermiyorsa

Göz iyi görmüyorsa

Yıldız da bir, ay da bir! 

Lisan, lisan değilse

Lütf-ü asan değilse

İnsan, insan değilse

İnançta bir, soy da bir! 

Konuştuğu dil haram

Hükümdara olmaz ram

Deliye her gün bayram

Düğünde bir; toy da bir! 

Dostlar karardı ayım

Biliniz ki hastayım

Artık özge yastayım

Zarar da bir; fayda bir!', 'font face=''Comic Sans MS'' color=''black'' size=''0,5'' Eda kıvrak, naz ince    Şehir de bir, köy de bir!  Ecel donu giyince Paşa da bir, bey de ...', ARRAY['Türk Edebiyatı','Şiir','Zülfikar Yapar Kaleli']::text[], 8.5, '{"poet":"Zülfikar Yapar Kaleli","poet_slug":"zulfikar-yapar-kaleli","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/veli-de-bir-deli-de-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kanayış', 'kanayis-melih-coskun-wumr6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Cam kırıkları üzerinde dolaştım yıllar yılı 

İzim kaldı kanlı ayaklarımla bastığım 

Bütün topraklarında yurdumun. 

Duydum gencecik bir yaşamı sona erdiren merminin 

Namluya sürülürken çıkarttığı 

O çelik kokan çığlığını 

Düşen her tetikte

Kanadı umudu kavuşmanın 

Yuvasından fırlayan her boş kovanda

Can verdi

Merhameti insan kalan yanımın.

Başka acılara bastım 

Toprağının her karışında 

Kan revan içindeki ayaklarımla. 

Kızıl akan derelerde yıkadım yüzümü 

Ekmeksiz, aşsız evlerde sabahladım. 

Şimdi isyan olup 

Fırlatsam sesimi sonsuzluğa 

Neye faydam olur 

Kendi vicdanımı kurtarmaktan başka. 

Oysa her çığlığımda 

Bir can katabilmek isterdim 

Susuz bırakılmış her karış toprağıma.

Bir cana daha öğretebilmek 

Bölüşmeyi sofrasında tuzu, ekmeği

Direnebileyi yeri geldiğinde 

Hakkını almak için 

Sevgiden ve ekmekten yana… 

Cam kırıkları üzerinde dolaştım yıllar yılı 

Sızladı ayaklarım 

Kan revan içinde yürüdüğüm 

Her karış toprağında yurdumun

Gördüm bir hayalin alnının ortasından vuruluşunu 

Toprakta boylu boyunca uzanırken 

İnsanlığımız……………………..! 

2005', 'Cam kırıkları üzerinde dolaştım yıllar yılı  İzim kaldı kanlı ayaklarımla bastığım  Bütün topraklarında yurdumun.  Duydum gencecik bir yaşam...', ARRAY['Türk Edebiyatı','Şiir','Melih Coşkun']::text[], 8.5, '{"poet":"Melih Coşkun","poet_slug":"melih-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/kanayis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugün Güneş..', 'bugun-gunes-vedat-okkar-7bdf8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün güneş bir başka doğdu yüreğime 

Al beni de götür gittiğin yere 

Doğudan doğmanın, Batıdan batmanın standartları içinde, 

Yaşıyoruz bu dünyanın Kuzeyiyle, Güneyiyle. 

Bir elimde gül demeti, ötekinde dikenleri 

Güllerde hayat gibi. 

Tutmasını bilmedinmi gülleri,dikenleri biryerlerimize mi girmeli? 

Yoksa kesmelimi o dikenleri? 

Bence kesmemeli o dikenleri. 

Hayatın dikenleri nasıl kesilebilir ki? 

En güzeli tutmayı öğrenmeli rengarenk gülleri. 

Bende bu hayatın bir gülüyüm, 

Dikenlerimde olacak tabiki. 

Seni güzelliğinle, idealinle geleceğinle kabullendim, 

Acımasız yarınları dindirdim, mutlu günler getirdim, 

Seni sen olduğun için sevdim 

Beni sevecek insan dikenlerimide kabul edebilmeli. 

Sen benim HAYAT''ımın AŞK''ısın. 

Mutluluğumsun, baç tacımsın. 

Benim herşeyim sende 

Seninkide (BENDE) 

Gel birtanem naz etme 

Mutluluğa uçalım seninle sonsuz geleceğe 

Kanatlarımız dokunsun birbirine uçarken biz gökyüzünde 

Gökyüzünün maviliklerinde her gece, bir öpücük kondur yüreğime 

GECE,MAVİ,ÖPÜCÜK SESSİZCE....  (VeDoHaM)', 'Bugün güneş bir başka doğdu yüreğime  Al beni de götür gittiğin yere  Doğudan doğmanın, Batıdan batmanın standartları içinde,  Yaşıyoruz bu ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bugun-gunes-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülsün Yüzün', 'gulsun-yuzun-vedat-okkar-oc4a4', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir başka şimdi yüreğim, 

Bir başka sevdaya akmakta, 

Gözlerimde perdeler varcasına, 

Kör bakıyorum dünyaya. 

Aramızda 12 saat olsada 

Ben hazırım bu sevdaya. 

Beni düşün ve 

Bir şiir yaz bu gece. 

Umut olsun içinde 

geleceğe dair. 

Kavuşmak olsun, 

Ve... 

Mutlu gülüşler olsun 

dizelerinde 

Sonra bu gülüşleri 

Takın yüzüne 

Beni gördükçe 

Gözyaşlarını sakla 

Hüzünlerini göm, 

sonsuz çukurlara. 

Kalbinde yer aç 

Yeni mutluluklara. 

Gel, tut ellerimi, yavaş yavaş tut! 

Dünyayı, zamanı, herşeyi unut... 

Hiçbir şey söyleme, hiçbir şey sorma, 

Yıldızları sustur, geceyi unut; 

Bana güven, 

Beni düşün, 

Bitsin hüzün, 

Sana gülmek çok yakışıyor 

Ve bundan sonra hep Gülsün yüzün.', 'Bir başka şimdi yüreğim,  Bir başka sevdaya akmakta,  Gözlerimde perdeler varcasına,  Kör bakıyorum dünyaya.  Aramızda 12 saat olsada  Ben h...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/gulsun-yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cemre Gibi', 'cemre-gibi-kazim-tinaz-cblvz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Severken terk edilsem, inan güzelim, 

Hasretin olur benim, ölüm nedenim. 

Hiç mi yüreğin yanmaz, ağlamazmısın? 

Cemre gibi toprağa düşse bedenim. 

Yığılıp bir kenarda düşünmez misin? 

Maziyi hatırlayıp, dövünmez misin? 

Bir demet çiçekle de görünmez misin? 

Cemre gibi toprağa düşse bedenim. 

Ağlar, sevgilim ağlar, sen de ağlarsın, 

Yanarsın yaptığına, yürek dağlarsın, 

Ot bitmiş o mezara, birgün uğrarsın, 

Cemre gibi toprağa düşse bedenim.', 'Severken terk edilsem, inan güzelim,  Hasretin olur benim, ölüm nedenim.  Hiç mi yüreğin yanmaz, ağlamazmısın?  Cemre gibi toprağa düşse bed...', ARRAY['Türk Edebiyatı','Şiir','Kazım Tınaz']::text[], 8.5, '{"poet":"Kazım Tınaz","poet_slug":"kazim-tinaz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cemre-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-vedat-okkar-m7yym', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'S evgilim deyip kitlemiştim kalbime 

E llerimi verdim tutup öpesin diye 

N asılda inanmışım senin mahsum yüzüne 

İ stesende asla inanmam sözlerine 

S enden tek bir şey isterdim bana verseydin eğer 

E n çok istediğim kalbin bana dünyaya değer 

V adettiğim kalbimi yalvarırım kabul et 

İ stemessen yanıma gelme uzaktan gül yeter 

Y alnız sendin benim dünyada tek dileğim 

O lmaz olsun senin gibi acı veren sevgilim 

R abbim ne olur yanına al ben böyle yaşayamam 

U mutsuzca yaşayıp maziye karışamam 

M azideki sevgilimi ölesemde unutamam...', 'S evgilim deyip kitlemiştim kalbime  E llerimi verdim tutup öpesin diye  N asılda inanmışım senin mahsum yüzüne  İ stesende asla inanmam söz...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/seni-seviyorum-286-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya', 'ruya-vedat-okkar-6e229', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu gece rüyamda seni gördüm bebeğim, 

Anlatılması imkansızdı güzelliğinin, 

Bir deniz vardı mavi ve sakin 

Kumsalındaydık biz hayatım gerçeğim. 

Rüyamda bir balık zıpladı denizin içinde 

O balığın gülüşü senin güzel yüzünde 

Sabah kalktım balık benim yüreğimde 

Aynaya baktım gülüşünde yüzümde. 

Oturuyoduk sahilde el ele 

Sensin bu sevgime tek çare 

O balık götürecek beni yarime 

Güleceğiz birlikte senelerce. 

Gel bu deniz, bu mavilik bizim olsun 

Kumsalı da herzaman sevgimizle dolsun 

Yaşatalım bu sevgiyi hep varolsun 

O balıkta nikahımızın şahidi olsun.', 'Bu gece rüyamda seni gördüm bebeğim,  Anlatılması imkansızdı güzelliğinin,  Bir deniz vardı mavi ve sakin  Kumsalındaydık biz hayatım gerçeğ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruya-199-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıldızlı Bir Gece', 'yildizli-bir-gece-vedat-okkar-qji9a', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Y ıldızlı bir geceydi rüyamda seni gördüm 

I ssızlığım içinde yanlız kendimi buldum 

L uzumsuz bie sebebten sürekli kafamı yordum 

D ünyada kalmıştım yapayanlız tek başıma 

I lık eser rüzgarlar konuştuğum en zor anda 

Z aten belliydi bu aşkın sonuda 

L akin dedim bulamaz onu benim kadar seveni 

I ssız bir çöl misali yanlız kalınca aramasın hiç beni 

B ırakıp gitsin bitsin artık bu çile 

İ şte bak söylüyorum dönme sakın geriye 

R esminide al götür fırsatım olmasın seni düşünmeye 

G it istediğin anda seni tutup ağlamıyacağım 

E ğer pişman olup dönersen sen beni bulamıyacaksın 

C anın isterse git belki mutluluğu bulursun 

E llemeyin zavallıyı bırakın hayalleriyle avunsun...', 'Y ıldızlı bir geceydi rüyamda seni gördüm  I ssızlığım içinde yanlız kendimi buldum  L uzumsuz bie sebebten sürekli kafamı yordum  D ünyada ...', ARRAY['Türk Edebiyatı','Şiir','Vedat Okkar']::text[], 8.5, '{"poet":"Vedat Okkar","poet_slug":"vedat-okkar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/yildizli-bir-gece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eminönü...', 'eminonu-ali-baksi-hld9l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Oy sürme kaşlı yarim

Kime bu içlenmen? 

Gözlerin gözlerime inat! 

Saklanmış dizelerinde

Bende saklanma cık içimden

Ben sende kaldım dar kaldırımlı sokak

Loş lamba merdiven basamakları

Çıktım kapına ecelsiz 

Sen yoksun! ! 

Siyah adam beyazı seçti

Kaplunbuğa beni geçti

Oy masum yüzlü yarim

Anlaya’bilirmi’sin halimden 

Yüreğim yangın yeri durulmuyor

Atıyorum kendimi emin önü

Biri ileri biri geri

Ya sev yada gene sev beni

Çıkmaz bu sokak’tan aşkın

Bitmez bu göz yaşı sensiz’ken

Söyleyemem sevdiğimi  yaşanmadan

Anlatamam martılardan başkasına seni

Bir ileri bir geri varıyorum emin önü

Seninle ikinciyi seviyorum eminönünde…', 'Oy sürme kaşlı yarim Kime bu içlenmen?  Gözlerin gözlerime inat!  Saklanmış dizelerinde Bende saklanma cık içimden Ben sende kaldım dar kald...', ARRAY['Türk Edebiyatı','Şiir','Ali Baksı']::text[], 8.5, '{"poet":"Ali Baksı","poet_slug":"ali-baksi","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/eminonu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ada', 'ada-emine-deniz-lnu0z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Göç mevsimidir şimdi,yol uzun 

Çığlıklar bastırır kanatlardaki hakikati 

Kaybolmuş bir adayı aramak 

Ve 

Yeşil bir dal olmak,bir nefes soluklanmak 

Denizler dolusu mavi ol 

Kuşlar dolusu kanat 

Sığınacak bir adadan ibarettir 

...kainat 

Göçmek 

Varlığın kuytusunda aramak yokluğu 

Milyonlarca kuş içinde 

Çokluğu 

Geceler dolusu yıldız ol 

Şarkılar dolusu hüzün 

Aynada gördüğün kadar mutludur yüzün. 

Gitmek 

Yürümeden,bir kanat çırpışı kadar kısa 

Yeniden yeşeren küçük bir ada 

Uzanıp huzura ermek yeniden 

Mutluluk denilen rüyaya dalmak 

Şarkılar söylemek kuşlara inat 

Ve 

Yeşil bir dal olmak 

Eski sokakta 

Varsa 

Kendine ait bir ADA...', 'Göç mevsimidir şimdi,yol uzun  Çığlıklar bastırır kanatlardaki hakikati  Kaybolmuş bir adayı aramak  Ve  Yeşil bir dal olmak,bir nefes soluk...', ARRAY['Türk Edebiyatı','Şiir','Emine Deniz']::text[], 8.5, '{"poet":"Emine Deniz","poet_slug":"emine-deniz","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/ada-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gurbet Ellerde Bayram Sabahı', 'bu-gurbet-ellerde-bayram-sabahi-mikdat-bal-fu053', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ağlarım ağlarım gözlerim şişer 

Bu gurbet ellerde bayram sabahı 

Memleketim yurdum aklıma düşer 

Bu gurbet ellerde bayram sabahı 

Ne anne ne baba yolları gözler 

Ne kalem muktedir ne kafi sözler 

Gurbetçi sılayı, soyunu özler 

Bu gurbet ellerde bayram sabahı 

Anneler hazırlar baklava börek

Bayram var bayrama hazırlık gerek

Öyle bir hasret ki dayanmaz yürek

Bu gurbet ellerde bayram sabahı

En mübarek günde, hasret çekeriz 

İki büklüm olup boyun bükeriz 

Ateş sönsün diye yaşlar dökeriz 

Bu gurbet ellerde bayram sabahı 

Gurbet elde gurbetçiler buluşur 

Vatan hasretiyle keder bölüşür 

Bayrama hürmeten söyler gülüşür 

Bu gurbet ellerde bayram sabahı 

Mikdat der gurbette bayramlar böyle 

Hasretiz, uzağız burda her şeyle 

İrtibat kesilmiş vatanla köyle 

Bu gurbet ellerde bayram sabahı', 'Ağlarım ağlarım gözlerim şişer  Bu gurbet ellerde bayram sabahı  Memleketim yurdum aklıma düşer  Bu gurbet ellerde bayram sabahı  Ne anne ne...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bu-gurbet-ellerde-bayram-sabahi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şarkılar-04', 'sarkilar-04-kemal-tahir-ozcan-jg7gs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tatmadım yıllar varki, sevmeyi sevilmeyi.

Çok oldu unutalı, gülmeyi sevinmeyi.

Özledim aynalarda, gülen bir yüz görmeyi.

Çok oldu unutalı, gülmeyi sevinmeyi.', 'Tatmadım yıllar varki, sevmeyi sevilmeyi. Çok oldu unutalı, gülmeyi sevinmeyi. Özledim aynalarda, gülen bir yüz görmeyi. Çok oldu unutalı, g...', ARRAY['Türk Edebiyatı','Şiir','Kemal Tahir Özcan']::text[], 8.5, '{"poet":"Kemal Tahir Özcan","poet_slug":"kemal-tahir-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sarkilar-04-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onu Kaybetmeden', 'onu-kaybetmeden-emre-saricicek-x147z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir şarkı dinledim, sen geldin aklıma.

Aşk türküsüydü dinlediğim.

İşte o''an aklıma öyle bir söz geldiki.

Şiir oldu yazdı kalemim.

Bülbül dala konupta susarmı.

Şarkılar söylemezmi saatlerce.

O''da benim gibi mutsuz olmalı ki,

Hergün mutluluk şarkıları söyleyen kuş,

Biranda sustu.

İşte o an aklıma bir söz geldiki,

Şiir oldu yazdı kalemim.

O gün sadece şiir yazmakla uğraştım.

Sabaha kadar hiç bıkmadan, sıkılmadan.

Bu şiiri okudum, dinlediğim türkü''de bana eşlik etti.

Ve tüğlerim ürperdi bütün gece.

En güzel yazımla defterime geçtim.

Dostlarımada en güzel sesimle okuyacağım.

Yeterki tüm sevgimizi paylaşalım.

Ve herşeyin değerini bilelim.

Onu kaybetmeden...', 'Bir şarkı dinledim, sen geldin aklıma. Aşk türküsüydü dinlediğim. İşte o''an aklıma öyle bir söz geldiki. Şiir oldu yazdı kalemim. Bülbül dal...', ARRAY['Türk Edebiyatı','Şiir','Emre Sarıçiçek']::text[], 8.5, '{"poet":"Emre Sarıçiçek","poet_slug":"emre-saricicek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/onu-kaybetmeden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sitem', 'sitem-feride-senturk-m3m0y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün bir başka gönlüm, dağıldım iki gözüm,

Hüznün karanlığında, kayboldu gülen yüzüm.

Ölümü yudumlarken, yiten aşkıma sözüm,	

Ömrün günbatımında, senden yana öksüzüm.', 'Bugün bir başka gönlüm, dağıldım iki gözüm, Hüznün karanlığında, kayboldu gülen yüzüm. Ölümü yudumlarken, yiten aşkıma sözüm,	 Ömrün günbatı...', ARRAY['Türk Edebiyatı','Şiir','Feride Şentürk']::text[], 8.5, '{"poet":"Feride Şentürk","poet_slug":"feride-senturk","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sitem-181-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kartaneleri', 'kartaneleri-yusuf-i-mamoglu-21gpv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kim demiş, 

kartanesinin gölgesinde 

yazılamaz şiir, 

kim demiş, 

kartaneleri yalnız 

değildir, 

ve kim demiş, 

kar soğuyu altında 

gözlerinin ısıtmayacağını... 

kim demişse halt etmiş 

bilememiş, düşünememiş, 

şimdilerde; yüreğe 

gölgesi vururken tanelerin, 

şiirlerde yazılırdı 

bakışlarında eriyen, 

yalnızlığı örten 

kartanelerine... 

sen soğuk nedir bilirmisin? 

gecenin ayazında, 

soğuktan öte, 

ay ışığında, 

sadece sensizlikde... 

kartanelerinde... 

y.i', 'kim demiş,  kartanesinin gölgesinde  yazılamaz şiir,  kim demiş,  kartaneleri yalnız  değildir,  ve kim demiş,  kar soğuyu altında  gözlerin...', ARRAY['Türk Edebiyatı','Şiir','Yusuf İmamoğlu']::text[], 8.5, '{"poet":"Yusuf İmamoğlu","poet_slug":"yusuf-i-mamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kartaneleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün beslemek', 'huzun-beslemek-yusuf-i-mamoglu-ucn1l', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'kartanesi hüzünler beslemek vardıya, 

hani uçurum yamaçlarından öteye, 

kıyısında kumsalın, kum tanesinde, 

kartanesi hüzünler saklamak vardıya! 

havada sadece süzülen 

ve inceden inceye biriken... 

çığlardan uzak korkusunda yaşamadan... 

kartanesi sevdalar beslemek değil, 

kartanesi hüzünler olsun isterdim. 

dokunup sıcaklığında sevdanın 

eriterek hüzünleri... 

y.i', 'kartanesi hüzünler beslemek vardıya,  hani uçurum yamaçlarından öteye,  kıyısında kumsalın, kum tanesinde,  kartanesi hüzünler saklamak vard...', ARRAY['Türk Edebiyatı','Şiir','Yusuf İmamoğlu']::text[], 8.5, '{"poet":"Yusuf İmamoğlu","poet_slug":"yusuf-i-mamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/huzun-beslemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sabah Erken Uyandım Anne!', 'bu-sabah-erken-uyandim-anne-humeyra-yilmaz-6m56a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bu sabah erken uyandım anne! 

Dikenleri nasır tutmuş güz gülleri kokuyordu dışarıda 

Güneş kadar soğuktu odam anne

Soğuktu sol yanımda kıvrılıp yatan yalnızlığım

Duvarlar yine konuşmuyordu benimle

Bu sabahta ağladım

Ve şehir yine ıslandı anne 

Bu sabah erken uyandım anne! 

Hasret kızılı gök bile daha kalkmadan sıcacık yatağından

Sancılarım saplandıkça bedenime 

Avuntu şurupları içtim aç karnıma

Geçmedi be anne

Sende biliyorsun yalandan ölmez insan ama

Geçmedi işte...! 

Çikolata rengi ve acı kahve tadında bir sabah

Saat çok erken anne

Gözlerimden sığıntı hüzünler akıyor uyku yerine

Uykularımı kaçıran 

Kaçıncı süslü intihar bu boğazıma bağladığım

Sabret dedin diye bekliyorum 

Yoksa çoktan ölmüştüm anne

Belik belik ör kadersizliğimi 

Umut rengi kurdeleyle bağla hayata

Sana benzeyen yanlarıma yanma için için 

Ben seni de seviyorum acıyı da 

Böyle ağladığıma bakma anne

Ellerimde çoban türküleri kanarken

İki satır daha yaklaştı aşk toprağa

Ve düştü düşecek kurtar anne

Gücüm tükendi

Babam duymasın ama 

Üşüyorum 

Hem de çok 

Çok üşüyorum anne

Kurda kuzu teslim edercesine

Benim de aklım yüreğime emanet

Ne yapsam susmuyor içimdeki bu sessizlik anne

Üzüldüğümü kimse bilmesin 

Sakın kimseye söyleme 

Bu bir rüyaysa sen uyandır beni anne 

Değilse 

En sevdiğim yalanı söyle

Söyle de uyuyayım 

Ama yarın daha  da erken uyandır beni anne...!', 'Bu sabah erken uyandım anne!  Dikenleri nasır tutmuş güz gülleri kokuyordu dışarıda  Güneş kadar soğuktu odam anne Soğuktu sol yanımda kıvrı...', ARRAY['Türk Edebiyatı','Şiir','Hümeyra Yılmaz']::text[], 8.5, '{"poet":"Hümeyra Yılmaz","poet_slug":"humeyra-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bu-sabah-erken-uyandim-anne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeydin?', 'neredeydin-yusuf-i-mamoglu-29sgq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gece neden gelmedin? 

neden duymadım sesini? 

neden dokunmadın yanağıma

dudaklarınla,

neden hissettirmedin nefesini? 

bu gece neredeydin? 

neden saklandın bir bulutun

arkasına tüm gece? 

ve neden geceyi yalnız yaşattın? 

buda bir oyunmuydu

yaşamayı öğretirken bana? 

neden sustun! 

ve bana nefret ettiğim

nedenleri, niyeleri, sorgulattın...

bu gece ''neden'' yoktun...

y.i', 'bu gece neden gelmedin?  neden duymadım sesini?  neden dokunmadın yanağıma dudaklarınla, neden hissettirmedin nefesini?  bu gece neredeydin?...', ARRAY['Türk Edebiyatı','Şiir','Yusuf İmamoğlu']::text[], 8.5, '{"poet":"Yusuf İmamoğlu","poet_slug":"yusuf-i-mamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/neredeydin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yitik kelimeler', 'yitik-kelimeler-yusuf-i-mamoglu-xjd34', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'biz demek bu sevdanın

en yitik kelimesi

bıkmadan, usanmadan beklemenin

kaçınılmaz sonu.

yarına yarın ekleyip

sonsuzluğu düşünmenin, 

herhangi bir sana yakınken umudu

biz demek gökyüzü

sen ''ay'' ken,

ben yeryüzünde seni izlerken,

sana yakın hissetmek belkide.

belkide yakınlığını hissetmek umursuzca,

gülümsemende korkmadan kaybolmak.

biz demek, henüz sen ve ben varken

sadece

sabaha karşı görülen düş

biz demek...

y.i', 'biz demek bu sevdanın en yitik kelimesi bıkmadan, usanmadan beklemenin kaçınılmaz sonu. yarına yarın ekleyip sonsuzluğu düşünmenin,  herhang...', ARRAY['Türk Edebiyatı','Şiir','Yusuf İmamoğlu']::text[], 8.5, '{"poet":"Yusuf İmamoğlu","poet_slug":"yusuf-i-mamoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yitik-kelimeler-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boyacı Çocuk', 'boyaci-cocuk-haluk-serdar-xqplw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vanda bahardan kalma bir kış günü

Yarı ayaz yarı güneşli bu günde

Gözüm takılıp kalıyor

Kaldığım odanın penceresinde

Asılı duran bir hüzün sanki.

nefesiyle parmaklarını ısıtmaya çalışan

Oniki onüç yaşlarında bir  çocuk

Omzunda kendi ağırlığınca bir boya sandığı.

Üzerinde yokluktan bir mont

Belki dolaştığ hep aynı kaldıımlar

Çevresinde hep aynı umarsızlar

Ama yinede her şeye ve herkese inat

Gözlerinde o cevval bakışlar.



20 şubat 1996  Van', 'Vanda bahardan kalma bir kış günü Yarı ayaz yarı güneşli bu günde Gözüm takılıp kalıyor Kaldığım odanın penceresinde Asılı duran bir hüzün s...', ARRAY['Türk Edebiyatı','Şiir','Haluk Serdar']::text[], 8.5, '{"poet":"Haluk Serdar","poet_slug":"haluk-serdar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/boyaci-cocuk-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunda', 'yoklugunda-ali-i-hsan-erdogan-f6yl6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Baharda gül dalıydım 

Rüzgarlar esti yüreğimde 

Koparamadılar can vardı damarlarımda 

Sonra sonbahar 

Kurudum, dalımda gül kalmadı 

Kan kalmadı bedenimde 

Ve yalnızlığa yenik düştüm 

Ezberledim senin yokluğunda 

Ağlamayı ve umutlanmayı 

Sen olmadan seni düşünmeyi 

Ve haykırarak uyanmayı 

Duygularımın sel olduğu günler 

Sana olan yağmurlarımın yüzünden 

Bir gecede ölmeyi 

Bin gecede dirilmeyi öğrendim 

Sana olan rüzgarlarımın yüzünden 

Kendimi sorgulayamadım bile 

İstemekle belki kavuşurum sanmıştım 

Lakin olmadı 

Şehirde kuşlar da kalmadı 

Artık bıktım, bu yaşamda sıktı 

Ya seninle ya da sensiz 

Gelsin artık bu ömrün sonu 

Bu yerden seni götürmeliyim 

Ya da ellere yenik ve yalnız gideceğim 

Ali İhsan Erdoğan', 'Baharda gül dalıydım  Rüzgarlar esti yüreğimde  Koparamadılar can vardı damarlarımda  Sonra sonbahar  Kurudum, dalımda gül kalmadı  Kan kalm...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Erdoğan']::text[], 8.5, '{"poet":"Ali İhsan Erdoğan","poet_slug":"ali-i-hsan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yoklugunda-39-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elveda diyemediğimiz şehir', 'elveda-diyemedigimiz-sehir-ali-i-hsan-erdogan-uu5b7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Elveda diyemedik bu şehrin sokaklarına

Bir sene daha geçirdik bu diyarda

Her şey karın tokluğuna

Hayatta kalmak uğruna

Ekmek uğruna 

Sevgi uğruna

Sevdiklerimiz uğruna

Yaşamla mücadele aşkına

Bir senenin değil, her saniyenin önemi vardı

Yalnız anlayana ve inanana

Bu şehrin kaldırımlarını bizler aşındırdık

Yürüdüğümüz adımlarla

Yaptığımız kavgalarla

Yaşadığımız aşklarla

Bizler kazıdık odalarımızın duvarlarına

Vatan, millet aşkını

Allah, Muhammet aşkını

Gurbette geçen zamanı

Bizler vurduk kafalarımızı duvarlara

Bir bunalım akşamında

Sabaha karşı bir hiç uğruna

Bizler yazdık ve yaşadık bu şehirde

Yalnız anlayana ve inanana

Hayallerimizde aynı özlem ve tutku vardı

Bu gurbet zamanında hep yalnızlık duygusu

Ve bir sıkıntı

Yine bunalıma giriyorum

Niçin; sevmek veya sevilmek aşkı galiba

Bizler düşündük zamanı çizen bu yolda

Gelecekte neler yaşayacağımızı 

Neler yaşatacağımızı

Hepimizin bir gönül sıkıntısı vardı

Bir yar ve onunla sevda

Yaşayacağımız aşklar uğruna

Bizim gönlümüzde yeri olurdu

Ölüme kadar birlikte bu dünyada

Fikrimizi hiç değiştirmedik

Kişiliğimizden ödün vermedik

Şeklimizle oynaşmadık

Alışkanlıklarımızdan vazgeçmedik

Hiçbir zaman taviz vermedik

Çünkü bir gün gideceğiz bu şehirden

İşte o zaman yar varsa yanımızda

Alıp götürürüz kendi toprağımıza

Arkamızda kimseyi bırakmayız bu yolda 

Sevdik, sevildik değişmezsek bu zamanda…

                                                    ALİ İHSAN ERDOĞAN', 'Elveda diyemedik bu şehrin sokaklarına Bir sene daha geçirdik bu diyarda Her şey karın tokluğuna Hayatta kalmak uğruna Ekmek uğruna  Sevgi u...', ARRAY['Türk Edebiyatı','Şiir','Ali İhsan Erdoğan']::text[], 8.5, '{"poet":"Ali İhsan Erdoğan","poet_slug":"ali-i-hsan-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/elveda-diyemedigimiz-sehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beraat kandili', 'beraat-kandili-elazigli-mustafa-kaya-y4w15', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hiç bir gece söylenmemiş

doğruların

kırılmış bir ayna gibi 

günahların

parça parça itirafı

var

yeni bir bedene kavuşmak 

gibi.

eyy ulu mabed..! 

sar ilahi nefesinle beni..

kayıp bir mehtaplı geceyi

aramak

ve esrarlı bir geceyi 

kuşanmak

yeşil mavi bir kandili

yaşamak varmış..

yıldızlar kadar uzak 

yıldızlar kadar yakın

kendi ruhumun yolcusuyum 

ve 

şehrin bilinmezlerini

yeniden yeniden yaşıyorum...

ne yana dönsem melekler

mü''minleri taşıyor.

bir suçlu gibi köşelerde

ağını germiş günahlarım

dökülür bu gece..

ve

sabahı bulan

tevbe istiğfarlarım

hayatımı tazeler bu

beraat gecesinde...

                                mustafa kaya

                                18.09.2005 / süleymaniye

www.mustafakaya.net', 'hiç bir gece söylenmemiş doğruların kırılmış bir ayna gibi  günahların parça parça itirafı var yeni bir bedene kavuşmak  gibi. eyy ulu mabed...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/beraat-kandili-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kına', 'kina-elazigli-mustafa-kaya-0aupa', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'kaldırmıştım gençliğimi

dinlediklerimi

ve aşkı vurmuştum zincire

si l''amour existe encore

çalıyor bir yerde

bir dilek gibi ezberlemiştim

biliyorum dönemem

bıraktığım yıllara

hiçbir elin değmediği...

ve içimde kırılmış bir ayna

hep kar yağışı var

hep ağlatan acılar yıllarca

eğer aşk yaşamaya değer olsaydı

sen dışında kalmazdın...

dilim dilim edilmişim

kanlı bir denize düşmüşüm

yıllarca dinlediğim şarkılar

kavuşturmadı seni bana

ben hep üşümüşüm...üşümüşüm...

uyandım bugün

kınalı saçlarınla

döndüm gençliğime

ve gökyüzünü farkettim

bu resimdeki gülüşünle

içimi açan kına şehir kadar

güzel yapmış yüzünü de..

mustafa kaya / kavacık

18.09.2005

www.mustafakaya.net', 'kaldırmıştım gençliğimi dinlediklerimi ve aşkı vurmuştum zincire si l''amour existe encore çalıyor bir yerde bir dilek gibi ezberlemiştim bil...', ARRAY['Türk Edebiyatı','Şiir','Elazığlı Mustafa Kaya']::text[], 8.5, '{"poet":"Elazığlı Mustafa Kaya","poet_slug":"elazigli-mustafa-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/kina-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başka Aynı', 'baska-ayni-sair-faik-inqu7', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynı akşam.

        Başka bir adam.

        İnsan da var.

        Biraz kırgın ya da kırılgan veya kırık.

        Masumiyet.

        Cinayet cinnet cehennem.

        Kadın ortada yok.

        Sağım solum önüm arkam.

        Sığır sağır sıyır.

        Seks.

        Başka bir akşam.

        Aynı kadın ayrı orta.

        İnsan da çok.



        Biraz açık ya da çıplak veya örtünmemiş.

        Kötülük.

        Sevgi sevda sevi.

        Adam ortada var.

        Bir iki üç dört.

        Çal çırp çek.

        Ölüm.

        Başka aynı.      Aynı başka.', 'Aynı akşam.         Başka bir adam.         İnsan da var.         Biraz kırgın ya da kırılgan veya kırık.         Masumiyet.         Cinayet...', ARRAY['Türk Edebiyatı','Şiir','Şair Faik']::text[], 8.5, '{"poet":"Şair Faik","poet_slug":"sair-faik","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/baska-ayni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykudan Kalktım', 'uykudan-kalktim-mikdat-bal-pee31', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Uykudan kalktım gece

Başladım hece hece

Ne saz var ne kemence

Kalemdir tercümanım

Ne rüyada ne düşte

Çalışırım zor işte

Akşam eve dönüşte

Kesiliyor dermanım

Meskenim kira ile

Her şeyi para ile

Tartıyla tara ile

Ne bağ var ne harmanım

Yazarım dura dura

Bizler sahibiz nura

Gavur dini gavura

Eksilmiyor imanım

Tattım islam şerbeti

Mekan ettim gurbeti

Çekiyorum hasreti

Doğduğuma pişmanım

Gurbette olmaz sefam 

Bitmiyor benim çefam

Ağrıdan zonklar kafam

Dertlerden elamanım

Eloğluna hor oldum

Yarı yarı kör oldum

Yandım yandım kor oldum

Çıkmaz oldu dumanım

Burda neler çekerim

Dile gelsin dertlerim

Hayli yazmak isterim

Uzun olsun romanım

Hasret en büyük sancı

Ne yolcuyum ne hancı

Burda derler yabancı

Türkiye de Almanım

Adım çıktı üstada

Çok görmeyin Mikdat''a

Eğer ettiysem hata 

Affınızı umanım', 'Uykudan kalktım gece Başladım hece hece Ne saz var ne kemence Kalemdir tercümanım Ne rüyada ne düşte Çalışırım zor işte Akşam eve dönüşte Ke...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/uykudan-kalktim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne zaman', 'ne-zaman-mikdat-bal-rq057', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Müslümanlar her gün zulüm görmekte

Açlıktan soğuktan çoğu ölmekte

Artık bütün dünya görüp bilmekte

Ne zaman farkına varacaksın sen

Bol keseden atma,kahramanlıktan

Ne kaldı sen söyle müslümanlıktan

Artık ne beklenir şu insanlıktan

Ne zaman kafanı yoracaksın sen

Ortadoğu her gün bulanır kana

Emperyalist güçler kıyarlar cana

Öldün mü,kaldın mı ne oldu sana

Ne zaman kendine soracaksın sen

Adım Mikdat Baldır içim kan ağlar

Gözüm iki çeşme durmadan çağlar

Kendinize gelin ey ölü sağlar

Ne zaman ayakta duracaksın sen', 'Müslümanlar her gün zulüm görmekte Açlıktan soğuktan çoğu ölmekte Artık bütün dünya görüp bilmekte Ne zaman farkına varacaksın sen Bol kesed...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ne-zaman-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'a-İlgİn Kadar Bİlgİn Olur', 'a-i-lgi-n-kadar-bi-lgi-n-olur-mikdat-bal-vi7ft', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir dostum var Hollanda’da lisan bilmez yol bilmez 

Kendine has görüşü var sağı bilmez sol bilmez 

Elli yıldır öğrenmedi Hollanda lisanını 

Komşularını tanımaz, sevmedi insanını 

Okuması yazması yok hiç okula gitmedi

İsteseydi öğrenirdi ancak heves etmedi

Bilir para kıymetini sayar milyara kadar 

Lisanı da öğrenirdi sevseydi para kadar 

Öğretelim her dedikçe, der ki kafam çalışmaz 

Buna inandığı için artık bir şey alışmaz 

Bir gün baktım anlatıyor saatlerce bir konu 

Dedim ona be kardeşim nerden öğrendin bunu 

Dedi anam mektup yazdı dün kızıma okuttum 

Mektuptan öğrenmiş oldum onu aklımda tuttum

On beş sayfa ezberledi tek bir kere dinlemiş 

O kafası çalışmayan her haberi anlamış 

İlgin kadar bilgin olur fazla söze lüzum yok 

Mikdadî der cahilliğe bundan başka çözüm yok

Ozan Mikdadî', 'Bir dostum var Hollanda’da lisan bilmez yol bilmez  Kendine has görüşü var sağı bilmez sol bilmez  Elli yıldır öğrenmedi Hollanda lisanını  ...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/a-ilgin-kadar-bilgin-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şucu bucu', 'sucu-bucu-mikdat-bal-1v259', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Apaçık kardeşiz yoktur şifremiz

Aynı yöne döner bizim ipremiz

Birdir kitabımız,birdir kıblemiz

Şucu bucu diye ayırmak nedir? 

Yerleşik bu millet yedi bölgeye

Hepimiz mensubuz tek bir ülkeye

Mümkün mü toplanmak aynı ilkeye

Şucu bucu diye ayırmak nedir? 

Herkes birbirine tahammul etsin

İstediği yoldan çizgiden gitsin

Artık çok uzadı bu kavga bitsin

Şucu bucu diye ayırmak nedir? 

Mikdat der birliğe çağrı yapanlar

En başta onlardır yoldan sapanlar

Vatan bir,millet bir ey inananlar

Şucu bucu diye ayırmak nedir', 'Apaçık kardeşiz yoktur şifremiz Aynı yöne döner bizim ipremiz Birdir kitabımız,birdir kıblemiz Şucu bucu diye ayırmak nedir?  Yerleşik bu mi...', ARRAY['Türk Edebiyatı','Şiir','Mikdat Bal']::text[], 8.5, '{"poet":"Mikdat Bal","poet_slug":"mikdat-bal","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sucu-bucu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zamanın Kızları', 'zamanin-kizlari-okan-tuncer-gmdek', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dalga geçip duruyorlar

garip garip soruyorlar

her gün sevgili buluyorlar

zamanın kızları

benim güvenim kalmadı

kafam hiç sarmadı

şimdiki kızlar dalgacı

zamanın kızları

gelmiyorlar sohbete

hasret kaldım muhabbete

dalıyorlar çete

zamanın kızları

kızlar böyle olurmu

size talih konarmı

bu peygamber yolumu

zamanın kızları

bi gidişle evde kalırsınız

hep böyle gidecek sanırsınız

nede çok aldanırsınız

zamanın kızları', 'dalga geçip duruyorlar garip garip soruyorlar her gün sevgili buluyorlar zamanın kızları benim güvenim kalmadı kafam hiç sarmadı şimdiki kız...', ARRAY['Türk Edebiyatı','Şiir','Okan Tuncer']::text[], 8.5, '{"poet":"Okan Tuncer","poet_slug":"okan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/zamanin-kizlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskil Hatırası', 'eskil-hatirasi-okan-tuncer-50gs9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hatıralarda kalan bir pazar akşamı

Eskilin tek parkının ortadaki kamelyası

kamelyada bir masa

masada bir tabak

tabakta sana ait dogum günü pastası

kadehlerimizde velinin birası

dudaklarımızda baglılık yeminleri

gözlerimizde yakalanma kaygısı; 

Eskil küçük yer

herkes birbirini tanır

birine görünüpte hava atmak gibi bir niyetimizde yok zaten

hala heyecanlandırır beni dudaklarının tadı

şimdi anılarda kalan

seninle son gecemin Eskil hatırası

kamelyada kilitli kaldı ettiğin yeminlerin

gittin..şimdi yoksun..

böylemi bitecekti aşkımızın rüyası

herkese kavun yedirdin

banada kelek

hey gidi gözünü sevdiğimin dünyası', 'hatıralarda kalan bir pazar akşamı Eskilin tek parkının ortadaki kamelyası kamelyada bir masa masada bir tabak tabakta sana ait dogum günü p...', ARRAY['Türk Edebiyatı','Şiir','Okan Tuncer']::text[], 8.5, '{"poet":"Okan Tuncer","poet_slug":"okan-tuncer","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/eskil-hatirasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '-İkinci El-', 'i-kinci-el-elif-gulay-z8lch', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önceden,

Geleceğe dair umutlarım vardı benim; 

fesleğen kokulu yaz akşamlarında

Bir kırlangıcın kanadına sarılı.

İçimde yanan volkanlar vardı; 

Dokunulmamış,saf ve temiz,

Bir çocuğun gözbebeklerinde.

Hayallerim vardı umarsız,

Ve sen vardın yalansız; 

Bir sonda bulmuştum seni,

Başlangıcım olmuştun.

Ellerin vardı sıcacık,

Koruyup sahiplenen kolların vardı,

Ve gözlerin vardı kendimin aynası.

Önceden; 

Ağlamazdım batan güne,

Yarınlara üzülmezdim hiç ve

Acımazdım geçmişe.

Rengarenk çiçeklerim vardı gönül bahçamde; 

Sen baktıkça yeşeren,

Seninle hayat bulan,

Gülüşünle çoğalan..

Önceden; 

''Önceden'' demezdim hiç.

Hep ilerisi vardı,

Güzel günler vardı yaşanacak

Ve hep sen vardın hep var olacak.

Ve şimdi...

Gittin.

Bir enkaz bıraktın geride,dokunulmamış.

Bir çocuk oyuncağını kaybetti,

Bir anne yavrusunu,

Ve ben seni kaybettim

Sendeki beni kaybettim

Bizi kaybettim.

Baharda yeşeren ağacın,

Uyanan doğanın,

Bir anlamı yok sensiz.

Şarkılar,kuş sesleri beyhude,

Gülüşmeler yalan

Kurmaca sevişmeler,sahte! 

Mutluluk bir ütopya..

Bir yalnızlık var yakamı bırakmayan,

Korkular üzerime üşüştü.

Ne söylesem nafile.

Elimde aşkın vardı,kıymetli,

Üzerine titrediğim

Sen gittin ya

Kahretsin! 

O da ikinci ele düştü..', 'Önceden, Geleceğe dair umutlarım vardı benim;  fesleğen kokulu yaz akşamlarında Bir kırlangıcın kanadına sarılı. İçimde yanan volkanlar vard...', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/ikinci-el-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne&Baba', 'anne-baba-elif-gulay-0wnvp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu ev dedikleri,

Bir beton yığını sadece.

Adı ''yuva'' oluveriyor,

İçine siz gelince..', 'Bu ev dedikleri, Bir beton yığını sadece. Adı ''yuva'' oluveriyor, İçine siz gelince.....', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anne-baba-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Aşkın', 'senin-askin-elif-gulay-rxp5a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Anladım ki; 

Bir salkım üzümdeymiş hayat,

Kapının çalınışındaymış mutluluk

Ve kaçınılmazmış yalnızlık.

Hayallerdeymiş büyük aşklar

Tavan arasına atılmış

Bir köşede tozlu ve eski

Bir eşya kalbim sanki; 

Unutulmuş,kırılmış,tamir bekleyen,

Sıcak bir insan eli isteyen.

Ama o günler öyle uzak ki..

Ve anladım ki,

Bir gülün dikeniymiş onu erişilmez kılan,

Tıpkı senin aşkın gibi..', 'Anladım ki;  Bir salkım üzümdeymiş hayat, Kapının çalınışındaymış mutluluk Ve kaçınılmazmış yalnızlık. Hayallerdeymiş büyük aşklar Tavan ara...', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/senin-askin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yönetmen', 'yonetmen-elif-gulay-sz8sr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çocukken oynadığım parklar,

Bindiğim bisiklet,

Ve yediğim şeker kamışları

Hepsi ama hepsi figuran senaryoma dahil..

Başrol oyuncusu ben''im

Senaryoyu önceden okumadım

Ve bu filmi kendim seçmedim! 

Rolümü kimseye veremem,

İstesem de çekip gidemem,

Diğer oyuncuları seçemem

Filmin bittiği günü bile bilemem.

Yönetmenin seçimi,onun tercihi

Ne kadar haykırsam nafile,

Ona söz geçiremem..', 'Çocukken oynadığım parklar, Bindiğim bisiklet, Ve yediğim şeker kamışları Hepsi ama hepsi figuran senaryoma dahil.. Başrol oyuncusu ben''im S...', ARRAY['Türk Edebiyatı','Şiir','Elif Gülay']::text[], 8.5, '{"poet":"Elif Gülay","poet_slug":"elif-gulay","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yonetmen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskişehirdeyim', 'eskisehirdeyim-sahin-erturk-ng86d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Belki diye bu şehire geldim

Senin için Eskişehirdeyim

Sıcak sular,Adaları gezdim

Kebapçıya,köpteçiye sordum

Yer yarıldı,içinemi girdin

Buradada yoksun,yoksun işte

(Dün...Eskişehirde) 

(178.09.2005-Yeni)', 'Belki diye bu şehire geldim Senin için Eskişehirdeyim Sıcak sular,Adaları gezdim Kebapçıya,köpteçiye sordum Yer yarıldı,içinemi girdin Burad...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/eskisehirdeyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburum', 'mecburum-sahin-erturk-5y93m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kanıma sen karıştın

İstesemde atamam

