INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ahh Ayrılık', 'ahh-ayrilik-i-lknur-er-x2fa6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ahhh….Ayrılık

Yinemi ben

Ne kadar çok seviyorsun beni

Korkuyorum ki

Banada kendini sevdireceksin', 'Ahhh….Ayrılık Yinemi ben Ne kadar çok seviyorsun beni Korkuyorum ki Banada kendini sevdireceksin...', ARRAY['Türk Edebiyatı','Şiir','İlknur Er']::text[], 8.5, '{"poet":"İlknur Er","poet_slug":"i-lknur-er","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ahh-ayrilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-gulcin-derin-md8yj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Anladım ki bir rüya,

Bir düştü gördüklerim...

Herşey bu kısa zamanda bitmemeliydi,

Aşk yaşanmadan gitti uzaklara...

Şimdi esen bir meltem ol,

Es uzaklardan sarıl boynuma,

Al beni koynuna öp, okşa.

Daha ne istiyosun? 

Seninim işte, tek senin...', 'Anladım ki bir rüya, Bir düştü gördüklerim... Herşey bu kısa zamanda bitmemeliydi, Aşk yaşanmadan gitti uzaklara... Şimdi esen bir meltem ol...', ARRAY['Türk Edebiyatı','Şiir','Gülçin Derin']::text[], 8.5, '{"poet":"Gülçin Derin","poet_slug":"gulcin-derin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sitem-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül Gelince', 'eylul-gelince-zeki-ergin-w32wb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kuşlar

kışlaklarına kanat çırpar

sarı hüzün sonbahar geldi

dingin eylül

yorgun eylül

sevdalar 

yüreklerde kanat çırpar

hayın kabuslar düşlerimi böler

delik deşik olur uykularım

eylül gelince

dolar gözlerim

bir seni

bir de yağmurları beklerim

_erenköy 14eyl05

_dağlara ver sırtını yt:haz09', 'kuşlar kışlaklarına kanat çırpar sarı hüzün sonbahar geldi dingin eylül yorgun eylül sevdalar  yüreklerde kanat çırpar hayın kabuslar düşler...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/eylul-gelince-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Krizantem', 'beyaz-krizantem-tarik-erkutlu-fkmpb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'İçimdeki sen sus artık! 

Söyleme onu hala sevdiğimi,

Kudurur bir eylül günü deniz, 

Köpürürken  köpek dişli dalgalar,

Vurur Marmara da sandallara… 

Sarhoş olsam da ben seni unutamam…. 

Neylersin; 

Çıman saplı yüreğime, mercanlar gibi karmaşığım, 

Bir süngeri sökermiş gibi göğsümden beni yaralama… 

Yüzyıl geçse de aradan ben sana aşığım… 

İçimdeki sen  dur artık yapma yeter… 

Haykırma kulaklarıma sevdanın utancını

Bir yakutun yanında yalın ayaktım ben…

Kararırken gece pusluydu hava 

Ve onunla yatakta daha da çıplaktım ben..

Umudum olsanda sen sana karşı koyamam.

Bilmezsin;

Seni her düşlediğimde kalbimin  nasıl durduğunu, 

Gökte uçan balonmuşcasına uzaklaşıp kaybolduğumu..

Bir defa  daha çıksan karşıma bu defa benim olurdun sen.. 

Ne olurdu benimle bıraksan çocukluğumu  

Neylersin,  ama bilmezsin;

Yitip giden boşlukların zamanın  acısını

Saçlarımın ne kadar kırlaştığını, hayatın ne kadar zorlaştığını

Beni terk ettiğin gün bir köşede seninle ölmüşüm ben…

ÖLÜM’ün  daha da bağlamış bizi…

Ne zaman seni düşlesem önce gülüyorum, 

Sonrası  sinir krizleri….

Efendim! duyamadım,  Sende mi seviyorsun? 

Apak toprağına uzanıp  öpmek isterim seni…. 

 İyi uykular ….*beyaz krizantem*. 

Tarık Erkutlu – Üsküdar 20.09.2005 

(Beyaz Krizantem çiçeği:  Sadakat)', 'İçimdeki sen sus artık!  Söyleme onu hala sevdiğimi, Kudurur bir eylül günü deniz,  Köpürürken  köpek dişli dalgalar, Vurur Marmara da sanda...', ARRAY['Türk Edebiyatı','Şiir','Tarık Erkutlu']::text[], 8.5, '{"poet":"Tarık Erkutlu","poet_slug":"tarik-erkutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/beyaz-krizantem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Aşka Attığı Tokatla Soldu Gün', 'ayriligin-aska-attigi-tokatla-soldu-gun-atilla-guler-zrjvx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sessizliklere gömülen bir tokat gibi yalnızlığın 

…yalnızlığım 

…yalnızlığımız 

ıslak gözlerimde silinmeyen bir yüz 

dilimde eskimeyen bir isim 

azgın bir gecenin 

kahpe şehvetine yenik düştü 

sıradanlığın saydam büyüsünde 

uyku mahmuru aşk 

ya/sakladım aşkı 

ya/saklandım 

ayrılıklarda büyüdü aşk 

büyüdükçe yıktı kalelerini kahramanın 

…daha dün gibi 

hayatın kralı bendim 

düşlerim/vezirlerim 

…daha dün gibi 

… 

salyangoz kaçışlara mahkum yalnızlıkta vurgun yedim…yaralı 

yasak aşkların kıvrandıran zehri damarlarımda 

gökler seriliverdi ayaklarımın altına 

bir kez daha kanadı yaram 

sızı(n)  birikti yüreğimde 

gözlerine değsin vurgun yediğim saatlerin okları 

...kör/se gözler...görmez 

bir pamuk şekeri gecesinde 

ıslatsın yüzümü yangını sevdanın 

bir öpücük kondursun 

saçlarına mevsimlerin 

sana çağlasın sevgi çiçeği...buram buram 

çocuk şenlensin yüreğimde/yüreğinde 

beni bekle 

…bekle 

ya/sakladı aşk beni 

ya/saklandın sen 

bekle/gün bitmesin', 'sessizliklere gömülen bir tokat gibi yalnızlığın  …yalnızlığım  …yalnızlığımız  ıslak gözlerimde silinmeyen bir yüz  dilimde eskimeyen bir i...', ARRAY['Türk Edebiyatı','Şiir','Atilla Güler']::text[], 8.5, '{"poet":"Atilla Güler","poet_slug":"atilla-guler","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/ayriligin-aska-attigi-tokatla-soldu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gün', 'bu-gun-salim-erben-njf0q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerim yine semada

Havada bulut yok

Geç doğacak ayda

Bir yıldız görünür 

Koyu karanlık dağlarda

Hani derler ya 

Bahtı kara

İşte o benim galiba

Ne sevenler arar

Nede sevilenler

Hele esinle esra var ya

Gözükmezler hayal dünyamda

Aramıza dağlar kondu

Ulaşılmaz

Hani demiştim ya

Sevenler gelsin buraya

Ne gelen oldu

Ne selam gönderen

Yine ben oldum

Zalımlara boyun büken', 'Gözlerim yine semada Havada bulut yok Geç doğacak ayda Bir yıldız görünür  Koyu karanlık dağlarda Hani derler ya  Bahtı kara İşte o benim ga...', ARRAY['Türk Edebiyatı','Şiir','Salim Erben']::text[], 8.5, '{"poet":"Salim Erben","poet_slug":"salim-erben","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bu-gun-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ara', 'bir-ara-ertugrul-sakar-a9h8a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir

Binbir soru

Koru tut

Yakar koru

Kara

Karabağ

Ankara

Anka

Ara

Ara sıra

Bir ara

Birden ara

Ar

Arsıza

Hırsıza

Bir artık

Gül nare

Düştü güle

Bu yola bir

Düş ara', 'Bir Binbir soru Koru tut Yakar koru Kara Karabağ Ankara Anka Ara Ara sıra Bir ara Birden ara Ar Arsıza Hırsıza Bir artık Gül nare Düştü güle...', ARRAY['Türk Edebiyatı','Şiir','Ertuğrul Şakar']::text[], 8.5, '{"poet":"Ertuğrul Şakar","poet_slug":"ertugrul-sakar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bir-ara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkürname (1)', 'tesekkurname-1-abdullah-atay-bd6q9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu alemi kurana

Yol gösteren kur’ana

Hak için can verene

Teşekkürüm var benim...

Beni doğuran cana

Damarda asil kana

Yaşadığım her an’a

Teşekkürüm var benim...

Sallandığım beşiğe

Sütle dolu kaşığa

Can seven hak aşığa

Teşekkürüm var benim...

Bilgi veren okula

Çağdaş olan akıla

Hak’kı bilen her kula

Teşekkürüm var benim...

Her gün doğan güneşe

Gönüldeki ateşe

Eşe,dosta,kardeşe

Teşekkürüm var benim...

Gönlümdeki konağa

Yarda ki al yanağa

Nimet sunan çanağa

Teşekkürüm var benim...', 'Bu alemi kurana Yol gösteren kur’ana Hak için can verene Teşekkürüm var benim... Beni doğuran cana Damarda asil kana Yaşadığım her an’a Teşe...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Atay']::text[], 8.5, '{"poet":"Abdullah Atay","poet_slug":"abdullah-atay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/tesekkurname-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anladım', 'anladim-tekin-koc-zjq0z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerin gözlerimin içine baktığında

Ellerin ellerimi ttuğunda

Dudakların dudaklarıma dokunduğunda

Beni Sevdiğini anladım', 'Gözlerin gözlerimin içine baktığında Ellerin ellerimi ttuğunda Dudakların dudaklarıma dokunduğunda Beni Sevdiğini anladım...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anladim-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kara Gözlüm', 'kara-gozlum-tekin-koc-2j506', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben Değilmiyidim 

Kara Gözlerine

Destanlar yazan

Ben Değilmiyidim 

Kara Gözlerine

Sevdalı

Ben Değilmiyidim 

Kara Gözlerine bakınca dünyayı unutan', 'Ben Değilmiyidim  Kara Gözlerine Destanlar yazan Ben Değilmiyidim  Kara Gözlerine Sevdalı Ben Değilmiyidim  Kara Gözlerine bakınca dünyayı u...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kara-gozlum-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşcakal', 'hoscakal-tekin-koc-acuwj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sana veda ediyorum

Yolumuz buraya kadar

Sen geriye 

Bense dönüşü olmayan bir yola

Hasretlik başlıyor hayatımızda 

Beni sakın düşünme 

Bu yola geldim bir kere

Senin temiz sevgine hoşcakal sevgilim', 'Sana veda ediyorum Yolumuz buraya kadar Sen geriye  Bense dönüşü olmayan bir yola Hasretlik başlıyor hayatımızda  Beni sakın düşünme  Bu yol...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hoscakal-67-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avun', 'avun-sahin-erturk-ty0bv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Avun dostum sende avun

Yalanlarla,masallarla

Şiirlerle,şölenlerle

Ödüllerle sende avun

Avun dostum sende avun

Le Fontenden masalları

Kırk yaşında dinliyorsun

Kandırıldın bilmiyorsun

Onurunu kırıyorlar

Senle dalga geçiyorlar

Ardından bak gülüyorlar

Avun dostum sende avun

Kitap açıp okumazlar

Şiir onlar için PAZAR

Uyak,durak aramazlar

TİLKİ gibi kurnaz onlar

İsteyen herkese dağıt

Ödül dediğin bir kağıt

Bastır,çoğalt şair avut

Avun dostum sende avun

Onlar işin kaymağında

Bir parmak bal dudağında

Yalan dostum sende yalan

Yalanlarla,masallarla

Avun dostum sende avun

(22.09.2005-Yeni)', 'Avun dostum sende avun Yalanlarla,masallarla Şiirlerle,şölenlerle Ödüllerle sende avun Avun dostum sende avun Le Fontenden masalları Kırk ya...', ARRAY['Türk Edebiyatı','Şiir','Şahin Ertürk']::text[], 8.5, '{"poet":"Şahin Ertürk","poet_slug":"sahin-erturk","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/avun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kan Damlıyor Tarihten', 'kan-damliyor-tarihten-necmi-unsal-m5e5d', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kan damlıyor tarihten, sahneler kirli.

Tüm savaşların omzunda zalimler tepinir.

Işık perdeli, despot gölgeler kibirli.

Barış kovboyu (!)  çocuk katliyle yetinir.

Bir toz bulutu kalkar tarih raflarından.

Ciğerlerini tıkar taze dimağların.

Fitnenin adamları nifak saflarından.

Doldurulmuş fişekler kurbanı ağların.

30 Temmuz 2004 Cuma, Danimarka-Køge 22.34 *7+6', 'Kan damlıyor tarihten, sahneler kirli. Tüm savaşların omzunda zalimler tepinir. Işık perdeli, despot gölgeler kibirli. Barış kovboyu (!)  ço...', ARRAY['Türk Edebiyatı','Şiir','Necmi Ünsal']::text[], 8.5, '{"poet":"Necmi Ünsal","poet_slug":"necmi-unsal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/kan-damliyor-tarihten-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dayanamıyorum', 'dayanamiyorum-tekin-koc-ct9jg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Artık sabah olmuyor

Geceler bitmiyor

Geceler değilmiydi

Seni benden ayıran

Artık sabah olmasını istiyorum

Olmayan her sabah 

Beni karanlığa sürüklüyor

Yok oluyorum artık

Bu ızdıraba, yokluğuna 

Dayanamıyorum', 'Artık sabah olmuyor Geceler bitmiyor Geceler değilmiydi Seni benden ayıran Artık sabah olmasını istiyorum Olmayan her sabah  Beni karanlığa ...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/dayanamiyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şaşarım Gayri', 'sasarim-gayri-murat-demir-1l0jw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmeyi severim bakmam türüne

Sevmeyen sevmesin demem sürüne

Yalnız, bir deryaya körü körüne

Dalana şaşarım dalana gayri

Zevk, eğlence derken sesin tonuna

Hayat şiirinin uyup fonuna

Ar, edep, namusta yolun sonuna

Kalana şaşarım kalana gayri

Sakınıp her zaman fikri saklıdan

Elleri havada hep şak şaklıdan

Şu fani dünyada hakkı haklıdan

Çalana şaşarım çalana gayri

Derim, kötülüğü bir kenara at

Üzülmem, olsamda duyulmayan hat

Fakat, şerşeytandan gidip nasihat

Alana şaşarım alana gayri

Enginlerden engin olsamda dağ ben

Ne değişir sanki kalsamda sağ ben

Yurdumun içinde açlara rağmen

Talana şaşarım talana gayri

Doydukça acıkan olmuş reçine

Söz geçmiyor artık elin piçine

Baktıkça söylenen gözün içine

Yalana şaşarım yalana gayri

Garip ucuz diye yerken kepeği

Haydutlar soyarken butün ülkeyi

Yoksulun üstüne iti köpeği

Salana şaşarım salana gayri!', 'Sevmeyi severim bakmam türüne Sevmeyen sevmesin demem sürüne Yalnız, bir deryaya körü körüne Dalana şaşarım dalana gayri Zevk, eğlence derke...', ARRAY['Türk Edebiyatı','Şiir','Murat Demir']::text[], 8.5, '{"poet":"Murat Demir","poet_slug":"murat-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sasarim-gayri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahpe Dünya', 'kahpe-dunya-abdullah-acar-7fy1j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kaç yiğidi ram ettin arzuna

Söyle bana be kahpe dünya

Kaç güzelin geçtin ırzına

Söyle bana be kahpe dünya

Kimler ölmedi ki senin uğrunda

Kimlerin benzi solmadı yolunda

Sıra bana mı geldi sonunda

Söyle bana be kahpe dünya

Yürürken kırıtır, sallanırsın

Alı yeşili giyer, pullanırsın

Daha yetmedi mi, ne avlanırsın

Söyle bana be kahpe dünya

Sende aradığını bulan mı var

Kime yar oldun sonuna kadar

Söyle bana, ederin ne kadar

Söyle bana be kahpe dünya

Üçgünlüksün, üçgünlük bir düş

Gözlerim açılınca bitecek bir rüya

Daha uzun konukluğu kim görmüş

Söyle bana be kahpe dünya

(20/09/2005- Ankara)', 'Kaç yiğidi ram ettin arzuna Söyle bana be kahpe dünya Kaç güzelin geçtin ırzına Söyle bana be kahpe dünya Kimler ölmedi ki senin uğrunda Kim...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kahpe-dunya-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Yağsaydı Böyle Olmazdı', 'yagmur-yagsaydi-boyle-olmazdi-abdullah-acar-kfdln', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yağmur yağsaydı

Senin yüreğin kavrulmaz

Benim çiçeklerim solmazdı

Yağmur yağsaydı

Böyle olmazdı

(21/09/2005- Ankara)', 'Yağmur yağsaydı Senin yüreğin kavrulmaz Benim çiçeklerim solmazdı Yağmur yağsaydı Böyle olmazdı (21/09/2005- Ankara)...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Acar']::text[], 8.5, '{"poet":"Abdullah Acar","poet_slug":"abdullah-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/yagmur-yagsaydi-boyle-olmazdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne geldim, Ne de Giderim…', 'ne-geldim-ne-de-giderim-muammer-celik-igkiu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'vaz geçecek gitmelerimiz mi kaldı, sanıyorsun

hiç bir zaman gelemedik halbu ki, biliyorsun...

kapıları aralarsın, gireyim içine diye, sessiz

bazen yüzüme kapatırsın ki, o denli pervasız

kapında avunduğum günlerin sayısı belirsiz

gelmedim ki, gidişlerim olsun o denli hayasız

gidecek değilim ki, bir geleceğim olsun, sensiz! ...

BirDeli

22.09.2005', 'vaz geçecek gitmelerimiz mi kaldı, sanıyorsun hiç bir zaman gelemedik halbu ki, biliyorsun... kapıları aralarsın, gireyim içine diye, sessiz...', ARRAY['Türk Edebiyatı','Şiir','Muammer Çelik']::text[], 8.5, '{"poet":"Muammer Çelik","poet_slug":"muammer-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ne-geldim-ne-de-giderim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülleri Vermesinler...', 'gulleri-vermesinler-i-brahim-ethem-bingul-qlbgh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırla o geceyi

Sonbahar ağlıyordu sokaklara

Bir sen, bir ben

Bir de ayak seslerimiz sokakta...

O çok sevdiğim şarkıyı mırıldanıyorum:

'' Benzemez kimse sana''

''Tavrına hayran olayım mı? ...''

Daha sıkı tutuyordum ellerini usulca...

Ve sustuk bir anda

Gelen vardı yanımıza

Uzun saçlarını taramış geriye, boyluca

Belli ki acı çekmiş bir amca

Gözleri kanlı, ağlamış

Durdu tam karşımızda...

Bir gül çıkarttı ceketinin içinden

Uzattı bana ve dedi:

'' Al bunu ver yanındakine''

'' Bekledi boşuna bu gül senelerce''

'' Gitmek için değecek sevgiliye''

'' Demek kısmetmiş sizin sevginize''

'' Söyleyin seviyorum diyen herkese''

''Gülleri vermesinler değmez gönüllere''

www.iebingül.com', 'Hatırla o geceyi Sonbahar ağlıyordu sokaklara Bir sen, bir ben Bir de ayak seslerimiz sokakta... O çok sevdiğim şarkıyı mırıldanıyorum: '' Be...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Ethem Bingül']::text[], 8.5, '{"poet":"İbrahim Ethem Bingül","poet_slug":"i-brahim-ethem-bingul","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulleri-vermesinler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-celal-topo-g4l7b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerin bakışlarımın son limanı olsun

  Bırak ta demir atıp yıllarca kalayım

  Yüreğin sevdamın son durağı olsun

  Bırak ta başka bir yer aramayayım...

  Islanayım gözyaşınla sırılsıklam

  Uyuyayım ömrümce düşler içinde

  Uyandırma kirpiklerinle dokunupta

  Bırak ta yıllarca gözlerinde uyuyayım....

  Ellerine dokunayım bütün hislerimle

  Bırak ma tut ellerimden ne olur tut

  İtme bu ölüm dolu yalnızlığıma itme

  Bırak ta dizlerinde ömrümce ağlayayım.....



                                                                 

                                                                                     

                                                                             Antalya', 'Gözlerin bakışlarımın son limanı olsun   Bırak ta demir atıp yıllarca kalayım   Yüreğin sevdamın son durağı olsun   Bırak ta başka bir yer a...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gozlerin-183-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet-I', 'i-hanet-i-muharrem-cetinkaya-l7985', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ne kanatlı bir kuştur iblis

Ne de bir sürüngen,

Ne de toprakta yetişir.

İçimizdedir şeytan; 

Bazen bir nefes,

Bir lokma ekmek,

Bir fısıltı,

Bazen bir ses

Bir uğultu,

İçimizdedir şeytan…

Genlerimizde midir nedir? 

Nerden gelir,

Nereye gider? 

Kim döker mürekkebi,

Niye bu çamur,

Kim yapar? 

Ya da kim yaptırır? 

Bembeyaz sayfalara bu kara lekeyi? 

Bilinmez! 

Ve

Ne kanadı vardır ihanetin,

Ne de pazardan alınır..

İhanet şeytanın çocuğu,

O’ndan hamile kalınır,

Biz doğururuz

Ağrısız,

Sancısız…

Dostlar  çeker  ağrıyı-sızıyı.

Çocuk bizim çocuğumuz,

Kimliksiz! ...', 'Ne kanatlı bir kuştur iblis Ne de bir sürüngen, Ne de toprakta yetişir. İçimizdedir şeytan;  Bazen bir nefes, Bir lokma ekmek, Bir fısıltı, ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ihanet-i-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SeN', 'sen-muharrem-cetinkaya-sce36', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bin bir çiçekle bezenmiş

bir gülistansın,

bir çiçeğinde bin arı

bin çiçek tozu 

bir arında

bin derde deva var

bir çiçek tozun-da…', 'bin bir çiçekle bezenmiş bir gülistansın, bir çiçeğinde bin arı bin çiçek tozu  bir arında bin derde deva var bir çiçek tozun-da…...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/sen-638-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Gece...', 'dun-gece-muharrem-cetinkaya-kovwd', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dün geceyi bi-hatırlasana; 

Kuş olduk

Uçtuk

Uçsuz bucaksız gökyüzünde

Ben diyeyim kartal

Sen de atmaca

Kanat çırptık 

Sonunda

Ağzımızla kuş tuttuk…

Sırtımızda taş taşıdık,

Başı-kabak,

Yalın-ayak,

Dilimiz-damağımız kurudu,

Topuklarımız çatladı,

Nasır oldu ellerimiz,

Denizi doldurduk…

Dilimizin bağı çözüldü,

Dik yokuşlardan tırmadığımız dağların

Vadilerinde yankılarını dinlediğimiz

Türküleri söylerken,

Bilirsin 

Ben dünden yorgunum; 

Düşlerim zirvede,

Zirvede seni düşlerim,

Bilirsin,

Ben dünden vurgunum…', 'Dün geceyi bi-hatırlasana;  Kuş olduk Uçtuk Uçsuz bucaksız gökyüzünde Ben diyeyim kartal Sen de atmaca Kanat çırptık  Sonunda Ağzımızla kuş ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/dun-gece-69-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yangını Sen Yaktın', 'bu-yangini-sen-yaktin-murat-oz2-9rvnz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir yangındır korlanan

Bu yangını sen yaktın

Ben çıra,sen kıvılcım

Asırlardır sen yaktın.

Unuttum sanma ben seni

Hep yüreğimdeydin

Geceler artık hep hicran bana

Gönüller virane 

Yıldızlar olmuş suratin

Hayalimdin sen benim

Bir yangın misali,

Bu yangını sen yaktın.

Söğüt yaprağı şahit,

Eğik, buğuk esen serin rüzgar,

Goncaya öten garip bülbül,

Suya hasret kurumuş toprak,

Yağan, eylül yağmurları şahit,

Üsküdardaki gökkuşağı,

Kibrit kutusundaki yanlızlık,

Kıyılarda savrulan dalgalar,

Simitlere uçuşan martılar şahit,

Kol kola girmiş yanlızlıklar,

Aşka dem vuran sazlar,

Sana maumur mahmur bakan bu yeşil gözler,

ŞAHİT

Bu yangını sen yaktın', 'Bir yangındır korlanan Bu yangını sen yaktın Ben çıra,sen kıvılcım Asırlardır sen yaktın. Unuttum sanma ben seni Hep yüreğimdeydin Geceler a...', ARRAY['Türk Edebiyatı','Şiir','Murat Öz2']::text[], 8.5, '{"poet":"Murat Öz2","poet_slug":"murat-oz2","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/bu-yangini-sen-yaktin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Maziden Bir Kesit', 'maziden-bir-kesit-enver-herguler-95qsw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gücüm yetse de takvimden o günü

Hani güneşin doğar doğmaz battığı

Dünyamın karanlıklara gömüldüğü

Sıcacık yuvamın Hiroşima''da imişcesine

Yok olup toz zerreciklerine dönüştüğü

İşte o günü silebilsem...

Baş döndürücü bir süratle ilerleyen

Her şeyi yakıp yıkan, ezip yok eden

Zamanın önüne bir set çekip

Ters işlemesini sağlayabilsem! 

Yelkovanı ellerimle orada:

İşte bak tam orada

Mazimin bir kesitinde

Mutluluğumun ta zirvesine

Fazla değil, fazla değil sadece

Bir kaç saniye tutabilsem...', 'Gücüm yetse de takvimden o günü Hani güneşin doğar doğmaz battığı Dünyamın karanlıklara gömüldüğü Sıcacık yuvamın Hiroşima''da imişcesine Yok...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/maziden-bir-kesit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gününü Bekleyen şiirlere Dizeler', 'gununu-bekleyen-siirlere-dizeler-i-brahim-kibris-rs33s', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '...

GÜNÜNÜ BEKLEYEN ŞİİRLERE DİZELER

Dağ başlarında bir çocuk

Tükrüğüyle sulandırır

Esmer kayaların temrelerini

Parmaklarına çalar 

Yanaklarına çalar

Kuzularına çalar

Ve dünyası kına1ıya döner 

Rüyaları ayıpsız

Sürüleriyle kardeş bir çocuğun

	******

Ve belki de

Geceye yatmasaydı gündüzler 

Hiçbir bürokrat

Traş olmayacaktı

******

Anlık sevgilere adanmış

Bir çelenk gülü ilk kez böylesine üzüldü

 Ve İzzet Babaları

Bu sabah yaşamın kıyıcığından 

Sessizce uzaklaştı

	******

Dere boyunda çingeneler ki 

Eşyaları at arabasını doldurmaz

Neşeleri kamyonlara sığmaz

Sarıp sarmaladıkları yaşamlarıyla 

Bir gün orda bir gün burda 

******

Ve neden kadınlar

Gece yarılarında ya da

 Karanlıklarda kurtulurlar

	Çokluk sancılarından

Yoksa geceyle de mi sevişir

	Sözleşir kadınlar

	******

Duyarlılıkları bile yapay

Kent türkülerine inat

Bir köy türküsü içtenliğiyle sevmek

 Şu güzelim dünyayı

V e Acı/payamdan_

''Ballı incirlere'' dek

Bedrettin misali bölüşmek

Barışı ve kavgayı

''Barışı özlüyorsak

Acırım kavgasız  geçen günlerimize

 *******

Türküler ki

Gözlerin yumulduğu yerden

Vurur insanı ansızın

Ve yürekten elen bir buyrukla

Bir sarkaç gibi oynatır

Duyguya kesmiş delikanlı başları', '... GÜNÜNÜ BEKLEYEN ŞİİRLERE DİZELER Dağ başlarında bir çocuk Tükrüğüyle sulandırır Esmer kayaların temrelerini Parmaklarına çalar  Yanaklar...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kıbrıs']::text[], 8.5, '{"poet":"İbrahim Kıbrıs","poet_slug":"i-brahim-kibris","theme":"Türk Şiiri","is_hero":false,"total_lines":53,"source_url":"https://www.antoloji.com/gununu-bekleyen-siirlere-dizeler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölköy''de Yoğyrt Çiçekleriİ Açarken IV', 'golkoy-de-yogyrt-ciceklerii-acarken-iv-i-brahim-kibris-7g69j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'GÖLKÖY''DE YOĞURT ÇİÇEKLERİ AÇARKEN IV

Bu gece ''Türkmen Düğünü'' oynanacak 

V e ben ne zamandır

Ne gecenin sessizliğini

Bu denli coşkulu

Ne de kuşların ezgilerini

Bu denli erken dinlememiştim

Öğrencilerimin ilk düğünü

Benim ikinci düğünüm olacak bu...', 'GÖLKÖY''DE YOĞURT ÇİÇEKLERİ AÇARKEN IV Bu gece ''Türkmen Düğünü'' oynanacak  V e ben ne zamandır Ne gecenin sessizliğini Bu denli coşkulu Ne de...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Kıbrıs']::text[], 8.5, '{"poet":"İbrahim Kıbrıs","poet_slug":"i-brahim-kibris","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/golkoy-de-yogyrt-ciceklerii-acarken-iv-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehit Anasına Madalya', 'sehit-anasina-madalya-enver-herguler-56voj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dim dik duran omuzlarıma bir nazar atın

Rütbeleri görürsünüz

Sığmadı ki tamamı

Bir çoğu daha yüreğimde saklı...

Bağrımdan kopan parçanın yerine 

Eklenen toz kondurmadığım madalya

Her gün göz yaşlarımla yıkandığındandır ki

Pırıl pırıl...', 'Dim dik duran omuzlarıma bir nazar atın Rütbeleri görürsünüz Sığmadı ki tamamı Bir çoğu daha yüreğimde saklı... Bağrımdan kopan parçanın yer...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sehit-anasina-madalya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gel Bana Sor', 'sen-gel-bana-sor-sadik-altinkaynak-8ps4w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen Gel Bana Sor

Uğradığım zulüm arşa dayandı

Yalnız beden değil ruhum da yandı

Desen can bu zulme nasıl dayandı

Susuyorum amma sen gel bana sor

Zulüm yürek yakan amansız bir kor

Köşkten üç kez çevrildim bu bir rekor

Bunca hakarete dayanmak çok zor

Ben dayandım amma sen gel bana sor

Bunca feryada ses gelir kayadan

Uygun bir cevap gelmez Çankaya’dan

Sessizliğim korku değil hayadan

Susuyorum amma sen gel bana sor

Unutarak tarafsızlık andını

Kanun koymuş keyfi zulmün adını

Anlamak mümkün değil inadını

Gülüyorum amma sen gel bana sor

Diyeceksin kardeş bu nasıl susmak

Merde yakışmaz ki köşede pusmak

Küfür sayılır zulme razı olmak

Susuyorum amma sen gel bana sor

Elbet bir gün Ulu Divan kurulur

Koyunun hakkı koçtan sorulur

Faniden isteyen boşa yorulur

Biliyorum amma sen gel bana sor

			Sadık ALTINKAYNAK

                                          EYLÜL-2005', 'Sen Gel Bana Sor Uğradığım zulüm arşa dayandı Yalnız beden değil ruhum da yandı Desen can bu zulme nasıl dayandı Susuyorum amma sen gel bana...', ARRAY['Türk Edebiyatı','Şiir','Sadık Altınkaynak']::text[], 8.5, '{"poet":"Sadık Altınkaynak","poet_slug":"sadik-altinkaynak","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sen-gel-bana-sor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şairliğe Özenen Genç...', 'sairlige-ozenen-genc-recep-tuna-kxbrv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şairliğe özenen genç,

Bir sigara daha yakar gecenin karanlığı ile başbaşa.

Yatağına uzanmıştır,

Uyuyan sevgilisinin ruhunun yanına...

Birden öldürmek ister kendini,

Kırdığı kalpler adına...

Vakit gece,

Sevgili çok uzaklarda...', 'Şairliğe özenen genç, Bir sigara daha yakar gecenin karanlığı ile başbaşa. Yatağına uzanmıştır, Uyuyan sevgilisinin ruhunun yanına... Birden...', ARRAY['Türk Edebiyatı','Şiir','Recep Tuna']::text[], 8.5, '{"poet":"Recep Tuna","poet_slug":"recep-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sairlige-ozenen-genc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-i-sa-tekin-dpb3u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biraz karamsarlık

Bir de yanlızlık 

Özlem  ve umudumla

Derin düşüncelere dalıyorum

Nedeni bilinmeyen bir boşluktayım sanki

Doksan dokuz kapı ardından

Bir özlem bir de umut

Üç adımlık volta

İçten çekilen ah

O''da umut vermiyor

Tek tesellim

Üç beş satır,elem,keder

Sen orada yalnız

Ben burada hasret çekerken 

Tutsak bülbül misali

Kafesime çekilmiş

Gelecek yarınlarda 

Seni düşünüyorum

Özlemim ve umudumla baş başa', 'Biraz karamsarlık Bir de yanlızlık  Özlem  ve umudumla Derin düşüncelere dalıyorum Nedeni bilinmeyen bir boşluktayım sanki Doksan dokuz kapı...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/umut-206-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgam (Sensizlik)', 'kavgam-sensizlik-ali-gencay-h7250', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kalksam ayağa, başımda esen asi gençlik

Otursam, altımda devran binlerce senelik

Acı ve keder bir ömür, mutluluk gündelik

Öldürdüğüm zaman, her geceye bir çentik

Anamın muskası mı göğsümde şerre üzerlik

Nafile, duyduklarımdan yüreğim delik deşik

Terk etmez keşkeler, her sorgum teneşirlik 

Uykulara dizili düşler, anlık gülümsemelik

Buzdan ellerim, sanırım sonum kangrenlik

Kes sevdamı şah damarından, aşk bitmişlik 

Acıyarak bakma bana, bende yaşam yitik! 

Gecelere verdim sırlarımı, katilim sensizlik', 'Kalksam ayağa, başımda esen asi gençlik Otursam, altımda devran binlerce senelik Acı ve keder bir ömür, mutluluk gündelik Öldürdüğüm zaman, ...', ARRAY['Türk Edebiyatı','Şiir','Ali Gençay']::text[], 8.5, '{"poet":"Ali Gençay","poet_slug":"ali-gencay","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kavgam-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkür', 'tesekkur-recep-tuna-8o1xd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimi üşüten bir yalnızlıkla baş başa kalmışım

Arada sıcaklığın vuruyor içime.

Gitmem gerekiyor bu şehirden

Ama seni düşündükçe vazgeçiyorum,

Senden başka,

Hayatıma anlam katan herşeyden...

Bir sen kalıyosun orada,

Ta uzaklarda.

Gölgen vuruyor odama,duvarıma...

Aydınlanıyorum hiç olmadığı kadar

Teşekkür ediyorum varlığın için,

Seni bana verdiği içim Tanrı''ya....', 'İçimi üşüten bir yalnızlıkla baş başa kalmışım Arada sıcaklığın vuruyor içime. Gitmem gerekiyor bu şehirden Ama seni düşündükçe vazgeçiyorum...', ARRAY['Türk Edebiyatı','Şiir','Recep Tuna']::text[], 8.5, '{"poet":"Recep Tuna","poet_slug":"recep-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tesekkur-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Sensizlik*', 'sensizlik-enver-herguler-cyz87', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yarı boş kadehime sensizliği eklesem

Sarhoşluktan daha da beter olurum sersem

Abartı olmaz inan ilk göz ağrımsın desem

Sensizlik nice bilsen eyledi beni sersem.

Kendini sınayıp da döneceğini bilsem

Geçeceğin yollara gül yaprakları sersem

Sevgimden eksilen yok emin olurdun gelsen

Sensizlik nice bilsen eyledi beni sersem.', 'Yarı boş kadehime sensizliği eklesem Sarhoşluktan daha da beter olurum sersem Abartı olmaz inan ilk göz ağrımsın desem Sensizlik nice bilsen...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensizlik-204-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Yaşamak mı', 'bu-yasamak-mi-celal-topo-p0wbt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akşam olunca karanlığa bürünürüm

  Aynalarda hep hayal meyal görünürüm

  Varla yok arasında geçiyor şu ömrüm

  Yaşamak mı diyorsunuz bu yaşamak mı...

  Bir elimde kadeh diğerinde siğara

  Gözleri doluyor masamdaki bardağa

  Yudumlayarak içiyorum ağlaya ağlaya

  Yaşamak mı diyorsunuz bu yaşamakmı...

  Mutluluğa varamadım uzaktan baktım

  Güle hasret gönlümü dikenle avuttum

  Ağlamak duygusunu ayrılıkla tattım

  Yaşamak mı diyorsunuz bu yaşamak mı...

                                                             

                                                                          ANTALYA', 'Akşam olunca karanlığa bürünürüm   Aynalarda hep hayal meyal görünürüm   Varla yok arasında geçiyor şu ömrüm   Yaşamak mı diyorsunuz bu yaşa...', ARRAY['Türk Edebiyatı','Şiir','Celal Topo']::text[], 8.5, '{"poet":"Celal Topo","poet_slug":"celal-topo","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bu-yasamak-mi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsünce Sana', 'kusunce-sana-sezgin-cetin-3uobw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küsünce sana çiçekler küsüyor

Yeşil dağlar kıraç, mavi sular siyah

Zehir zemberek bir karanlık oluyor 

Sesimi yankılandırmıyor duvarlar 

Kulaklarım kara delik 

Ellerim ayak oluyor yürürken

Ve Gözlerim körebe oynuyor

Küsünce sana 

Sahipsiz ellerin izi kalıyor yüzümde

Dostlar selam vermiyor sana anlatamıyorum

Sende anlamıyorsun 

Darağacına gidip geliyor kafam 

Sehpa olmuyor kimse ama hiç kimse

Sende olmuyorsun

Yağmur bile üstümde kuruyor 

Islatmıyor…

Kötülüklerini bile saklıyor insanlar 

Sessizlikleri ile vuruyorlar bana

Sen bakıyorsun 

Sen de vuruyorsun sessizliğinle 

Sen de vuruyorsun bana

Sana küsünce…', 'Küsünce sana çiçekler küsüyor Yeşil dağlar kıraç, mavi sular siyah Zehir zemberek bir karanlık oluyor  Sesimi yankılandırmıyor duvarlar  Kul...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kusunce-sana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Peri!', 'gitme-peri-recep-tuna-4wm0v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gitme sırası sana mı geldi,Peri? 

Hep yanımda kalacaktın hani,

Hiç gitmeyecektin...

Noldu sana anlatsana,

Nedir sebebi bu vazgeçişin? 

Gitme Peri! 

Bir ölüm de sen katma ruhuma,

Bırakma beni içimdeki bu savaşla tek başıma.

Çıkma içimden,

Doldur hücrelerimi

Ki girmesin kötülükler içeri.

Sen gidersen ben biterim peri! 

Ben bitersem şiir kalmaz geriye.

Kim bitirecek sonra üç noktalı cümleleri? 

Seni seviyorum peri! 

Kal ve bana anlam kat,

Eskisi gibi...', 'Gitme sırası sana mı geldi,Peri?  Hep yanımda kalacaktın hani, Hiç gitmeyecektin... Noldu sana anlatsana, Nedir sebebi bu vazgeçişin?  Gitme...', ARRAY['Türk Edebiyatı','Şiir','Recep Tuna']::text[], 8.5, '{"poet":"Recep Tuna","poet_slug":"recep-tuna","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/gitme-peri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak Diyarların Koynunda', 'uzak-diyarlarin-koynunda-sezgin-cetin-inovz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Çoktandır kuru bir dal gibiyim, şiirsiz

Doğaçlama türküleri bozuk artık kaldırımların

Zanaatsiz bir insancasına 

Damarları kurumuş, yobaz bulut kümelerinin 

Hava almak için birkaç kedi çıkmış yazlıklara

Soğuk esintilerin ters düz ettiği uykular,

Garip, çilekeş azap dolu yalnızlıklar

Buruşturulmuş birkaç kokulu yaprak, 

Birde kapalı,oymalı bir kalp kalmış

Dizelere… Masa başında

Susamışlığa sarmaşıklar sarılmış

Ben sarmaşıklara sen dilime dolanmışsın

Aynı yolda uzak yürümüşüz, ışıklar kapalı

Duman ciğerimizi değil gönlümüzü bürümüş

Nemli ellerine yün eldiven vermişler

Gözüne bakmak ne cüret yanında yürümeye vurulmuşum

Gece benden uzak diyarların koynunda

Kupkuru soğuk bir döşek

Birde dilime sarı leke cigaram

Neyime yetmemiş

Gece benden uzak diyarların koynunda 

Uyumuşsundur güzelim gözlerini öpemem artık', 'Çoktandır kuru bir dal gibiyim, şiirsiz Doğaçlama türküleri bozuk artık kaldırımların Zanaatsiz bir insancasına  Damarları kurumuş, yobaz bu...', ARRAY['Türk Edebiyatı','Şiir','Sezgin Çetin']::text[], 8.5, '{"poet":"Sezgin Çetin","poet_slug":"sezgin-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uzak-diyarlarin-koynunda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyan', 'i-syan-gokhan-saluk-bb06x', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok yalnız bir gecenin sabahında 

Birçok şeylere kızıp, isyan ettim

Bir sigara yakmak istedim

Hava çok soğuktu

Onu bile yapamadım

Yapılacak çok şey vardı oysa

Ben yapamaz mıydım bazı şeyleri

Mesela hayata kahredip küfür etmeyi

Kızdığım şeylerin üstüne yürümeyi 

Fakat onu bile yapamadım

Halbuki bu dünya benim değil miydi', 'Çok yalnız bir gecenin sabahında  Birçok şeylere kızıp, isyan ettim Bir sigara yakmak istedim Hava çok soğuktu Onu bile yapamadım Yapılacak ...', ARRAY['Türk Edebiyatı','Şiir','Gökhan Saluk']::text[], 8.5, '{"poet":"Gökhan Saluk","poet_slug":"gokhan-saluk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/isyan-106-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi ve Çiçek', 'sevgi-ve-cicek-nursen-buluc-stjzn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Masada bir çiçek

Ne vazosu var,ne suyu

Uzun sürmeyecek belli

Çiçegin ömrü

Sabırla bekledi bir eli

Ömrüne anlam katacak

Tükenirken hayatı

Sevgiyle onu saracak

Açılırdı, canlanırdı yapragı

Bir bardak su bulsa

Fazla birşey istemezdi

Bu suda sevgi olsa

Artık zamanı dolmuştu

Yapragı kurumuştu

Bir çiçegin ömrüde

Sevgisiz son buldu', 'Masada bir çiçek Ne vazosu var,ne suyu Uzun sürmeyecek belli Çiçegin ömrü Sabırla bekledi bir eli Ömrüne anlam katacak Tükenirken hayatı Sev...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sevgi-ve-cicek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Bekleyiş', 'bos-bekleyis-faik-genc-3ehyr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dolu dolu geçen hayatı özlüyorum

Pencerede kapıdaki bekleyişi

Gelemeyeceğim demişti ama belki gelir diye

Bekleyişin doluluğunu özlüyorum

Gözlerim uzağa çakılı birer çizgi

Tenim nemli soğuk bir bıçak

Ellerim titreyen birer yaprak

Kalbim çırpınan bir kelebek

O dolu yalnızlığı özlüyorum şimdi işte...

Eylül 2005', 'Dolu dolu geçen hayatı özlüyorum Pencerede kapıdaki bekleyişi Gelemeyeceğim demişti ama belki gelir diye Bekleyişin doluluğunu özlüyorum Göz...', ARRAY['Türk Edebiyatı','Şiir','Faik Genç']::text[], 8.5, '{"poet":"Faik Genç","poet_slug":"faik-genc","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bos-bekleyis-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilinmezlige', 'bilinmezlige-nursen-buluc-xxjls', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sürüklenir ruhum bilinmezliğe

Uzaklara çook uzaklara

Kaçmak yok buradan

Alkışlanmasakta ayakta

Hayat süprizlerle dolu

Akşamların,sabahtır  sonu

Tek başımıza olsakta olmasakta

Bedenim taşımaz gibi bu yükü

İnsanım mecburum çekerim

Nasıl olacagını sonumun

Bilsemde,bilmesemde', 'Sürüklenir ruhum bilinmezliğe Uzaklara çook uzaklara Kaçmak yok buradan Alkışlanmasakta ayakta Hayat süprizlerle dolu Akşamların,sabahtır  s...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bilinmezlige-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üç Cumhurbaşkanından İnciler...', 'uc-cumhurbaskanindan-i-nciler-mehmet-demir-atmali-oymvm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Soru: 11 Eylül sabahı terörü durdurdunuz,rüşveti de durdurabilirdiniz? 

-''Rüşvet iki kişi arasında olan bir şeydir. Alan razı, veren razı''

Kenan EVREN	

-Soru: 1978''de İhtilal yapsaydınız, 3000 kişi ölmeyecekti? 

-''Biz ihtilalin olgunlaşmasını bekledik''

Kenan EVREN

-''Netekim''

Kenan EVREN

-Soru: Memura zam yapmayı düşünmüyormusunuz? 

-''Benim memurum işini bilir''

-''Ben zengin adamı severim''

-''Benim zamanımda zengin olmayan ahmaktır''

-''Seçimden önce zam yapacak kadar enayimiyim? ''

Turgut ÖZAL

-''Dün dündür, bu gün bugündür''

-''Yürümekle yollar aşınmaz''

-''Demokrasilerde çare tükenmez''

-''Vardı da vermedik mi? ''

-''Vamı bunun başka izahı? ''

-''Binaen aleyh''

Süleyman DEMİREL

22.9.2005', '-Soru: 11 Eylül sabahı terörü durdurdunuz,rüşveti de durdurabilirdiniz?  -''Rüşvet iki kişi arasında olan bir şeydir. Alan razı, veren razı'' ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Demir Atmalı']::text[], 8.5, '{"poet":"Mehmet Demir Atmalı","poet_slug":"mehmet-demir-atmali","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/uc-cumhurbaskanindan-inciler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aradığım Adam...', 'aradigim-adam-nurdane-diken-qni5j', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir adam arıyorum. 

Gözleri yeşil, saçları simsiyah olacak. 

Denizden uzak düştüğüm zaman 

Gözleri yosunları, 

Saçları simsiyah geceleri hatırlatacak. 

Bir adam arıyorum. 

Tunç rengini güneşten, 

Gözleri gökyüzünü anlatacak. 

Bir adam arıyorum, hürriyete aşık, 

Uzun müddet hürriyeti aradığı halde, 

Onu yine kendi içinde bulacak.....

Nurdane Diken', 'Bir adam arıyorum.  Gözleri yeşil, saçları simsiyah olacak.  Denizden uzak düştüğüm zaman  Gözleri yosunları,  Saçları simsiyah geceleri hat...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/aradigim-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Teşekkür', 'tesekkur-nursen-buluc-czota', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevincime ortak oldu o gün tabiat

Gökyüzü benim için sanki başka güzel

Islattı topragı,güneş yakmadan ısıttı

Toprak mis gibi kokusuyla eşlik etti

Agaçlar, çiçekler kelebekler

Hepsi farklı ritimde dans etti

Deniz dalgasıyla karışan,rüzgarın sesi

Duyuruyordu sanki heryana,bu sevincimi

Yıldız ve ayda katıldı gece sevincime

Bir başka parlattılar gökyüzünü o gece

Teşekkür ediyorum rabbim

Bana kızımı verdiğin için

Teşekkür ediyorum 16 nisan 1988 de

Tabiatı sevincime  ortak ettiğin için', 'Sevincime ortak oldu o gün tabiat Gökyüzü benim için sanki başka güzel Islattı topragı,güneş yakmadan ısıttı Toprak mis gibi kokusuyla eşlik...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/tesekkur-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ateş....', 'ates-nurdane-diken-hppbv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaprak olurum, eğer ağaç isen. 

Ben senin gül''ün olurum,har isen. 

Kar olurum, güneş ışığı isen. 

Eriyeyim gölün olayım diye.. 

Sen cehennemde bulunuyor isen, 

Ölürüm senle birleşeyim diye. 

Durmadan ateş olarak yanardım, 

Senle külli''yen bir olayım, diye........', 'Yaprak olurum, eğer ağaç isen.  Ben senin gül''ün olurum,har isen.  Kar olurum, güneş ışığı isen.  Eriyeyim gölün olayım diye..  Sen cehennem...', ARRAY['Türk Edebiyatı','Şiir','Nurdane Diken']::text[], 8.5, '{"poet":"Nurdane Diken","poet_slug":"nurdane-diken","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ates-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meyhane', 'meyhane-enver-herguler-tsvj1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gün boyu, günler boyu dertler birikir,

Devredileceği sanılır  ki 

Akşamları oraya gidilir

Derde mey eklenir...

Fazladan tek attırır

Boğuk sesli nağmeler bam teline vurunca.

Duvarlarda yankılanır

Hüzün ve kahkaha karışımı bir uğultu.

Dert ortağı yakılan sigara dahi unutulur

Küle dönüşür..

Loş ışık altında raks eder duman ve mey kokusu.

Kadeh derde destek verir

Mecal kalmaz, el dahi kalkamaz

Bir tek daha istenince.

Üstüne üstüne gelir, yol gösterir

Yalpa yapan duvarlar.

Dışarda kalan zaman kavramı seni bekler

Meyhaneye devrettiğimi sandığım dertler

Hiç eksiksiz peşim sıra gelir ve yarınınkilere

Eklenir...

Bir gün 

Ve elbet bir gün,

Tüm dertlerin devredileceği

O an beklenir ve gelir...', 'Gün boyu, günler boyu dertler birikir, Devredileceği sanılır  ki  Akşamları oraya gidilir Derde mey eklenir... Fazladan tek attırır Boğuk se...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/meyhane-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kurşun', 'kor-kursun-i-lknur-cekici-tesik', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kör bir kurşun gibi geldin

Yüreğime saplandın

Amaçsızdın öylece geldin

Ve ben bile bile sevdim

Sızlatacaktın biliyordum

Kanatacaktın acıtacaktın yüreğimi

Dayanamadığımda ise

Söküp alacaklardı seni

İstemesem de alacaklardı

Çünkü sen kör kurşun

Ve ben örselenmiş

Ve ben zaten bitmiş haldeyken

Her an ölümü yaşarken

Dayanamazdım acına

Yorgun yılların yükü omuzumda

Kör karanlıktayken hala

Evet alışamadım acılara

İzin veriyorum sana

Seni söküp almalarına

İhanetin izlerini soluyamam sayfalarca

Elveda aşkım sana', 'Kör bir kurşun gibi geldin Yüreğime saplandın Amaçsızdın öylece geldin Ve ben bile bile sevdim Sızlatacaktın biliyordum Kanatacaktın acıtaca...', ARRAY['Türk Edebiyatı','Şiir','İlknur Çekici']::text[], 8.5, '{"poet":"İlknur Çekici","poet_slug":"i-lknur-cekici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/kor-kursun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hak', 'hak-ali-yildiz-yofcg', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben ki vuslata dalarım her şafakta

Titreyen ruhlarla buluşur,

Ey olması gereken addediliş

Ey yıkılası isyan

Ve dilimde sen, göğsümde

Böğüresi bir çığlık gibi adın

Düşüncemde...', 'Ben ki vuslata dalarım her şafakta Titreyen ruhlarla buluşur, Ey olması gereken addediliş Ey yıkılası isyan Ve dilimde sen, göğsümde Böğüres...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/hak-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ali-yildiz-8db2u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece kusmak zamanıdır herşeyi

Bebekdilli yarınlardan vazgeçmek

Bu gece ona en yakın olmaktır 

Ve zamanıdır

Ve hissetmektir acizliği

Damarlarda ilerlemektir

Diken diken titremek

Yalnız yürümektir...', 'Bu gece kusmak zamanıdır herşeyi Bebekdilli yarınlardan vazgeçmek Bu gece ona en yakın olmaktır  Ve zamanıdır Ve hissetmektir acizliği Damar...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-gece-151-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aklımdaki Sen', 'aklimdaki-sen-ali-yildiz-zp789', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Umut ki ne umut

Hepsinin kalbinde uyuyan bir insanlık

Cahillik ve kavga,inat

Ve uyandırılamayan bir rüya

Düşünüyorum

Milyonlarca kişiden,aklımdaki sen

Ne güzel! 

Biliyorum,

Herkes parmak ucunda

Cep delik,kuyruk

Güzel hayallere ise devam

''''Düştük mapus damlarına''''

''''Ruhumun senden ilahi,şudur ancak emeli''''

Ve yüzünü bile unuttuğum

Aklımdaki sen...', 'Umut ki ne umut Hepsinin kalbinde uyuyan bir insanlık Cahillik ve kavga,inat Ve uyandırılamayan bir rüya Düşünüyorum Milyonlarca kişiden,akl...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/aklimdaki-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül', 'gonul-enver-herguler-ctaq0', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Od misali, acı vardır kem sözde

Yankısı kor olur akar gönüle.

Dil yumuşak, yanlış kelem edende,

Kalp kırılır birkaç parçaya hem de.

Pişmanlık yaşanır lâkin çoğu kez,

Netice alınamaz tamirinde.', 'Od misali, acı vardır kem sözde Yankısı kor olur akar gönüle. Dil yumuşak, yanlış kelem edende, Kalp kırılır birkaç parçaya hem de. Pişmanlı...', ARRAY['Türk Edebiyatı','Şiir','Enver Hergüler']::text[], 8.5, '{"poet":"Enver Hergüler","poet_slug":"enver-herguler","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gonul-117-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eylül''de...', 'eylul-de-reside-coskun-tsdvt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen hiç sarılarak dalamadın uykulara benle.. 

Gök gürültüsünün bir çığlık olduğu,ıslak eylül gecelerinde.. 

Ve sen hiç göremedin eylül sabahlarında, 

Turuncu bir güne açılan kömür gözlerimi benim.. 

Ellerimin üstünde ellerin açamadı pencereleri, 

Ve içimize dolamadı,eylül toprağının kokusu... 

Sensiz bensiz; öksüz doğan güneş, 

Aydınlatamadı sarı eylül öğlelerini... 

Ve bu öğlelerde sen hiç göremedin, 

Beni terk eden eylül leyleklerinin,üstümdeki gölgelerini... 

Ve sen hiç yetişemedin, 

Yalnızlığın beni esir aldığı,lacivert eylül akşamüstlerine...', 'Sen hiç sarılarak dalamadın uykulara benle..  Gök gürültüsünün bir çığlık olduğu,ıslak eylül gecelerinde..  Ve sen hiç göremedin eylül sabah...', ARRAY['Türk Edebiyatı','Şiir','Reşide Coşkun']::text[], 8.5, '{"poet":"Reşide Coşkun","poet_slug":"reside-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eylul-de-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Körfez', 'korfez-ali-yildiz-ik4m6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Karşıdaki evler

İnsan gibi

Gözlerimi kapasam

Yine ordalar

Aramızda martılar, gemiler

Karşıdaki evler

İnsan gibi

Hepsi bana bakıyor

Ah bu ben

Ah bu mesafeler...', 'Karşıdaki evler İnsan gibi Gözlerimi kapasam Yine ordalar Aramızda martılar, gemiler Karşıdaki evler İnsan gibi Hepsi bana bakıyor Ah bu ben...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/korfez-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-ali-olcars-qol33', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben ne çile çekmiş, nede rahat etmiş biri.

Ben yaşamı belirsiz, gömülmüş diri diri.

Yaşıyorum Hayalden bir yıkık barakada.

Bir ben varım birde gölgem, virane duvarda.

Uyku gözlerimde diken, kapandıkça batan.

Kalkıyorum çiviyle süslenmiş yatağımdan.

Bana en güzel yatak olacak tahta atım.

alıp beni hayalden gerçeğe adım adım.', 'Ben ne çile çekmiş, nede rahat etmiş biri. Ben yaşamı belirsiz, gömülmüş diri diri. Yaşıyorum Hayalden bir yıkık barakada. Bir ben varım bir...', ARRAY['Türk Edebiyatı','Şiir','Ali Olcars']::text[], 8.5, '{"poet":"Ali Olcars","poet_slug":"ali-olcars","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ben-200-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kölesin', 'kolesin-halil-colak-qvo4z', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Telafer kan ağlarken nasıl gülersin

Niçin Müslüman’ım ses çıkarmıyorsun 

Yoksa sende mi? Amerika’ya kölesin

Halil Çolak 22.9.2005 Ankara', 'Telafer kan ağlarken nasıl gülersin Niçin Müslüman’ım ses çıkarmıyorsun  Yoksa sende mi? Amerika’ya kölesin Halil Çolak 22.9.2005 Ankara...', ARRAY['Türk Edebiyatı','Şiir','Halil Çolak']::text[], 8.5, '{"poet":"Halil Çolak","poet_slug":"halil-colak","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kolesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaç Gece?', 'kac-gece-ali-yildiz-slnku', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir ben bilirim

Uykusuzlukta muhabbeti,sükut

Bir köşeye itilmişliği,bir ben

Birde..

Hak,bilinesi hukuk

Ve ölesi içim

Kaç gecedir, kaç gece? 

Sabahlara merdiven dayamayı 

Bir ben bilirim

Birde,

Okunası mektuplar,bozulası köstekli

İçim bir tuhaf ki...', 'Bir ben bilirim Uykusuzlukta muhabbeti,sükut Bir köşeye itilmişliği,bir ben Birde.. Hak,bilinesi hukuk Ve ölesi içim Kaç gecedir, kaç gece? ...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kac-gece-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Git-me!', 'git-me-reside-coskun-pruf7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Git! İstersen... 

Durmam önünde,kesmem yollarını, 

Hiç bağ olmam ayaklarına, 

Ya da diken olup batmam ellerine... 

Bir kuş gibi uç, 

Bir kelebek kadar hafif ol, 

Birde üstüme basıp geçme giderken... 

Bir ricam olacak senden! 

Giderken beni olmasa da,kokumu da al yanına, 

Kim bilir; olur ya özlersin belki.. 

Ama sen yine de, 

Bir gülde,bir yaseminde,bir karanfilde bul beni, 

Bilirim seversin çiçekleri.... 

Bir ricam olacak senden! 

Gel! yine de gitme sen, 

Bazen bir bağ olsamda ayağına, 

Ya da bir diken olup batsamda parmağına, 

Bir kafes olsamda altından, 

Sen yine de yanımda ol,yaşayarak kokla beni... 

Bir özlem olmayayım sende, 

Sevmedim bu adı, 

Sevinç olayım ben sende....', 'Git! İstersen...  Durmam önünde,kesmem yollarını,  Hiç bağ olmam ayaklarına,  Ya da diken olup batmam ellerine...  Bir kuş gibi uç,  Bir kel...', ARRAY['Türk Edebiyatı','Şiir','Reşide Coşkun']::text[], 8.5, '{"poet":"Reşide Coşkun","poet_slug":"reside-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/git-me-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı Olmayan Giz', 'sakli-olmayan-giz-bedir-nazir-e5byb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Aşk bahçesinin tomurcuk gülleri 

Açmışsa bana gönül pencereleri 

Görmek ve anmak kalmışsa yalnız bana

Alemin aslında gün yüzündeki gizlerini

Giz, giz saklı olmayan giz

Gizliymiş gibi görünen giz

Apaçık ortada, yalnız bakmak gerek

Bakmaktan kasıt, özümsemek

Bektaşi, Mevlana, Yunus bakar; Dinsiz bakar

Bakmaktan bakmaya ne fark var

Yoksa insandan insana ne fark var

Hepimiz etten kemikteniz

Bir sıkımlık can içindeyiz

Ebedi değil hayat bir gün öleceğiz', 'Aşk bahçesinin tomurcuk gülleri  Açmışsa bana gönül pencereleri  Görmek ve anmak kalmışsa yalnız bana Alemin aslında gün yüzündeki gizlerini...', ARRAY['Türk Edebiyatı','Şiir','Bedir Nazır']::text[], 8.5, '{"poet":"Bedir Nazır","poet_slug":"bedir-nazir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sakli-olmayan-giz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet-II', 'i-hanet-ii-muharrem-cetinkaya-v0wj7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dün seni gördüm

Yine biriyle,

Yıllar sonra.

Hiç değişmemişsin; 

Gözlerin yine yabancı,

Bakışlarında ihanet,

Dilin katil,

Dudakların yalancı şahit! 

Ve 

Kim-bilir,

Kaç gönülü gömdün  toprağa

Bu arada,

Kaç cinayetin oldu görmeyeli,

Faili mechül! ...', 'Dün seni gördüm Yine biriyle, Yıllar sonra. Hiç değişmemişsin;  Gözlerin yine yabancı, Bakışlarında ihanet, Dilin katil, Dudakların yalancı ...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ihanet-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anam', 'anam-ali-yildiz-dub6k', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yok! 

Bir dokunuş değil bu

Peki ne? 

Tarifi yok, anlatamam..

Sıkıntıyla yoğrulmuş, hüzünle

Gebe,yavrusuna aç

Gün görmemiş anam

Dil bilmez, konuşur gözler

Tarifi yok sana anlatamam

Anlatılmaz! 

Söz bilmez yanar yüreciği

Anam, benim anam

Bir dokunuş değil bu

Peki ne? 

Karşılıksız olan tek şey herhalde...', 'Yok!  Bir dokunuş değil bu Peki ne?  Tarifi yok, anlatamam.. Sıkıntıyla yoğrulmuş, hüzünle Gebe,yavrusuna aç Gün görmemiş anam Dil bilmez, k...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/anam-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanet-III', 'i-hanet-iii-muharrem-cetinkaya-8f1mv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her yıl açar ayva,yaz gelir,

Dut ağacında dut,

İğde iğdesini sunar,

Kıskanmaz armudunu,armut…

İhaneti yoktur güllerin,

Vefasızın bağında açar! 

Bir dilim ekmek versen,

Hatırlar seni yıllar geçse,

İhaneti yoktur,kapıdaki itin,

Böyle bir sadakat insanda yok! 

Sırtına yükselen onca yükü,

Götürmem demez,

Üstelik bir de binersin üstüne.

Aç-susuz bıraksan da bekler kapıda,

_çoğu insanda var

Eşekte bile ihanet yok! 

Doğa bize sunar bütün varını,

Keseriz,yok ederiz ormanı

Düşünmeyiz yarını.

Bilse insanın ihanetini

Acaba,

Arı toplar mı balını? 

Biz insanlar ne yaparız bilemem,

Vefa uğruna.

Yapamadıklarımızı saysam yetiremem,

Cefa uğruna…

İhaneti biz yarattık,

Üstelikte,

Heveslere taparız.

İnsanız dedik ya; 

Bizim işimizdir………!', 'Her yıl açar ayva,yaz gelir, Dut ağacında dut, İğde iğdesini sunar, Kıskanmaz armudunu,armut… İhaneti yoktur güllerin, Vefasızın bağında aça...', ARRAY['Türk Edebiyatı','Şiir','Muharrem Çetinkaya']::text[], 8.5, '{"poet":"Muharrem Çetinkaya","poet_slug":"muharrem-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ihanet-iii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dönerse Dünya Dönsün Ben Dönemem Aşktan', 'donerse-dunya-donsun-ben-donemem-asktan-kamil-soylemez-jj7xo', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kahramanı sen olan bir roman

Sayfalarını okşuyorum,başından

Belkide sabrımı sınıyor zaman

Kendi kendimi avutuyorum

Yakıyorken sevdan aldırmadan

Yazıp,çiziyorum sana destan

Yapraklarımı dağıtan rüzgar

Sen sevdamın esintisi can

Akılsız bir baştı bana bıraktığın

Dönüpte bir bak arkana

Saç sakal karışmış bir adam

Duruyor geçerken içimizden zaman

Gölgemden geçiyorum sabahlara

Aynalarda arıyorum yana,yana

Seni arıyorum gezdiğimiz yerde

Göz düşürerek yerlerde

Bir narin yürüyorsun ki içime

Bir peri edası gözlerimde

Bense  aşkı sektiriyorum içimde

Belki derin mavilerden alırım

Sevdanı bir nefeslik çekimde diye

Islatıyorum sonra istanbul sokaklarını

Köprüleri sırtlanıyorum adımlarımda

Sen aşkını sırtlandığım

Özleminle yandığım günden beri

Gözleri derin mavi yer,gök semahta

Döne dursun dünya 

Ben dönemem bu sevdadan bir daha', 'Kahramanı sen olan bir roman Sayfalarını okşuyorum,başından Belkide sabrımı sınıyor zaman Kendi kendimi avutuyorum Yakıyorken sevdan aldırma...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/donerse-dunya-donsun-ben-donemem-asktan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönlüm', 'gonlum-bedir-nazir-5ystw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dört yanımda dört apartman

Dördü de dört taraftan sardılar etrafımı

Bense istemezdim böyle olmasını 

Erken açıp solan çiçekler gibi gönlümün solmasını

Zira sevgi pınarında yıkandı gönlüm 

Gönülsüzlere gönül bağladı gönül gözüm', 'Dört yanımda dört apartman Dördü de dört taraftan sardılar etrafımı Bense istemezdim böyle olmasını  Erken açıp solan çiçekler gibi gönlümün...', ARRAY['Türk Edebiyatı','Şiir','Bedir Nazır']::text[], 8.5, '{"poet":"Bedir Nazır","poet_slug":"bedir-nazir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gonlum-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-nursen-buluc-z4ck0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zİyan olmuş sensiz geçen günlerim

Elimde olsa hep yanında olurdum

Dogdugun andan beri senin

Hayat,bende seninle varoldu

Hatırlamıyorum önceleri

Tek dilegim var rabbimden

Nasip etsin bana seninle bir ömür

Aynı çatı altında,acı tatlı günleri', 'Zİyan olmuş sensiz geçen günlerim Elimde olsa hep yanında olurdum Dogdugun andan beri senin Hayat,bende seninle varoldu Hatırlamıyorum öncel...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dilek-101-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Penceremde', 'penceremde-ali-yildiz-fzwjq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karşılıklı fenerler

Yanıp sönmekte

Sanki birer mors alfabesi

Sanki senden gelen bir haber

Dinliyorum  görerek

Çözüyorum onları...', 'Karşılıklı fenerler Yanıp sönmekte Sanki birer mors alfabesi Sanki senden gelen bir haber Dinliyorum  görerek Çözüyorum onları......', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/penceremde-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şimdi Tövbe Zamanı', 'simdi-tovbe-zamani-mehmet-sait-akkus-hapcm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dünya malın neylersin

Söyle bana ne söylersin

Kazandığın bu servetin

Hesabını sen vereceksin

Kimler kaldı bak eskilerden

Geri dönmedi gidenlerden

Onlarada kalmadı zaten

Çekip gittiler yerlerinden

İbreti vardır mezarlığın

Varmı senin hazırlığın

Hadi hazırlan gidiyoruz

Cebinde varmı azıklığın

Dünya sonsuz değildir

Sanma sahibsiz değildir

İnsan oğlu gafil olur

Dünyaya hep meyillidir

Ne eylersin saltanatı

Yaptırdığın bunca katı

Her şey geride kalacak

Gideceğin yer mezar katı

Her şey boş her şey yalan

Senden geriye kalan

Sanmaki baki kalacak

Belkide olmuştur talan

Bak geriye ne anladın

Hep böyle olacak sandın

Elde kalan bir şey varmı

Yazık şeytana kaldın

Bu dünyayı yaratan bir

Geceyi karartan bir

Şimdi tövbe zamanı

Hayırları arttıran bir

Düşün hazırlığın varmı

Seni kurtaracak kadarmı

Her zaman ileriyi düşün

Hayırın şerrini sararmı

Anla artık dostum anla

Sabahtan kalk ezanla

Farzlarını hep eda et

Günlüğünü aç kur anla

Şimdi tövebe zamanı

Toprağa vereceksin canı

Tövbeler kabul olunur

Sakın kaçırma bu anı

İnan duan kabul olur

Allah katında kabul görür

Yeri göğü yaratana

Kabul etmek kolay olur', 'Dünya malın neylersin Söyle bana ne söylersin Kazandığın bu servetin Hesabını sen vereceksin Kimler kaldı bak eskilerden Geri dönmedi gidenl...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sait Akkuş']::text[], 8.5, '{"poet":"Mehmet Sait Akkuş","poet_slug":"mehmet-sait-akkus","theme":"Türk Şiiri","is_hero":false,"total_lines":48,"source_url":"https://www.antoloji.com/simdi-tovbe-zamani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömür Borcu', 'omur-borcu-arif-onbasioglu-mv034', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Merhaba baba,

zaman pazarından

ömür getirdim sana.

Ucuza mı kapattım bilmiyorum 

ama,

altın gümüşe yeğ tutulmaz mı 

baba? 

Kardeşimin,

“hani baba, o kırmızı araba” (İbrahim Sadri''den) 

feryadına aldırma.

Bize çelik çomak da 

yakışıyor nasılsa,

sek sek taşımız kırılmadı ya.

Sen,

ömrünü yaşamaya bak

baba.

Korkma.

Yakınım,

şah damarından daha.

Hakkını helal et,

elveda baba.

Borcumu ödemeye 

gidiyorum 

zaman pazarındaki

tüccara', 'Merhaba baba, zaman pazarından ömür getirdim sana. Ucuza mı kapattım bilmiyorum  ama, altın gümüşe yeğ tutulmaz mı  baba?  Kardeşimin, “hani...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/omur-borcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnançlı ol', 'i-nancli-ol-nursen-buluc-gftx8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'cesaretli ol

Sakın korkma hayattan

Emin ol

Yardım edecek sana yaratan

Yıldırmasın seni

Karşına çıkan engeller

Lazım olunca

Gelecek yardımına melekler

Amacın olsun

Yaşamda  herzaman

Nasip olacak 

İstediklerin gelecek o zaman', 'cesaretli ol Sakın korkma hayattan Emin ol Yardım edecek sana yaratan Yıldırmasın seni Karşına çıkan engeller Lazım olunca Gelecek yardımına...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/inancli-ol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku', 'korku-bedir-nazir-mdn0o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bildiğimi bildiğim bir yerde

Bildiğimi bilmiyorum diye diye

Gerçek sevginin bir nebzesine eş değer olmadığını

Geç olsun anladım içimde kanayan yaranın acısını

Karanlıktan korkardım bir vakitler 

Aslında hep karanlıklar içindeydim

Peki neydi bu korkunun sebebi

Saklı olandan, görünmeyenden korkmak 

Korkular içindeki en derin korku

İlerledi yaş erdi kemale

Korkusuzluk korkusu indi bedenime

Sardı sarmaladı tenimi

Korkular içindeki korkusuzluk korkusu

Korkuyorum, korkuyorum diye diye

Korkmayı öğrendim

Gerçek korkulacak beşerin ta kendisiymiş bunu bildim', 'Bildiğimi bildiğim bir yerde Bildiğimi bilmiyorum diye diye Gerçek sevginin bir nebzesine eş değer olmadığını Geç olsun anladım içimde kanay...', ARRAY['Türk Edebiyatı','Şiir','Bedir Nazır']::text[], 8.5, '{"poet":"Bedir Nazır","poet_slug":"bedir-nazir","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/korku-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artvin', 'artvin-ali-yildiz-wgzzy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Şimdi burda olacaktın

Şuan arka bahçedeyim

Daha yeni yeşillenen ayva ağacını altında

Daha yeni boylanan paptyaların üstünde

O yemyeşil çayırda, güneş banyosu yapıyorum

Sıcaklık iliklerimde

Yanda, bizim kara kız

Az ilerde babaannem, çapada

Ve bacak bacağa kuşları dinliyorum

Komşunun kuzuları çirkin mi çirkin

Asıl manzarayı görmelisin

Karşıdaki dağlar yüce mi yüce

Uçlarındaki karlar zifiri beyaz

Ve şahinler dansta

Dedim ya burda olacaktın...', 'Şimdi burda olacaktın Şuan arka bahçedeyim Daha yeni yeşillenen ayva ağacını altında Daha yeni boylanan paptyaların üstünde O yemyeşil çayır...', ARRAY['Türk Edebiyatı','Şiir','Ali Yıldız']::text[], 8.5, '{"poet":"Ali Yıldız","poet_slug":"ali-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/artvin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek inanılan değer', 'tek-inanilan-deger-hatice-kelleli-0so8t', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşey yalanmış şu koskoca dünyada

Senden başka doğru kalmamış meğer

Sahtelikler yerini almış hayatta

Bir sen kalmışsın tek inanılan değer

Bilmez hiçkimse bendeki seni 

Anlatamam nedense aşk-ı servetini

Yüreğimdeki ilahi güç birliğini

Kalbimde saklarım güzel sevgini

Herkesin kalbinde, canının içindesin

Sen eşsiz benzersiz tek nağmesin

Herkesin dilinde hep gönüllerdesin

Erişilmez kudretinle yalnız sen teksin

Ahri cennetinde nice güzelliklerinle

Kalplerde var olan yüce sevginle

Yarattığın bu can daima seninle

Doğruya yönelt bizi merhametinle

Aldığımız her nefes adın anıyor

Dünyadaki herşey emrinle yürüyor

Hayat akışı sayende oluyor

Bu cihan yalnız seni tanıyor', 'Herşey yalanmış şu koskoca dünyada Senden başka doğru kalmamış meğer Sahtelikler yerini almış hayatta Bir sen kalmışsın tek inanılan değer B...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kelleli']::text[], 8.5, '{"poet":"Hatice Kelleli","poet_slug":"hatice-kelleli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tek-inanilan-deger-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '*Hayat*', 'hayat-servet-suner-5n276', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karlı dağlar ardında bir hayat varmış,

Hayaller yatağına sığmayan nehri andırırmış,

Cennetmiş sanki dünyası,

Umutlandıkça duyguları şahlanırmış.

Yollarda kırkbeşlerde varmış,

Kenarlarda ki tarlalar gözyaşlarıyla sulanmış.

İşte sırf bu yüzden verimli topraklar çorak,

Ömür ormanı kurak kalmış.

Ve O u-mutlu hayat karlı dağlar ardında bırakımlaş.

SERVET SUNER 

----------------------------------------', 'Karlı dağlar ardında bir hayat varmış, Hayaller yatağına sığmayan nehri andırırmış, Cennetmiş sanki dünyası, Umutlandıkça duyguları şahlanır...', ARRAY['Türk Edebiyatı','Şiir','Servet Suner']::text[], 8.5, '{"poet":"Servet Suner","poet_slug":"servet-suner","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayat-246-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış Evvelinde Sensizlik', 'kis-evvelinde-sensizlik-arif-onbasioglu-w0z1w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yalnızım kuyu dibinde,

         mecnun halimden, kime ne

	

Sensizliği ekledim yalnızlığıma

Hani geçen zamanlar 

kuru bir incir vermiştin ya

bana

yaramadı bir bestele

kaldırdım karanlığımın en köşesine

“karanlık”; dört duvar, 

kiremitler dizeli üzerine

bilirsin ya

“Ak Hüseyin Değirmeni”  beride

“Sırât Yokuşu Çıkmazı” nın tepesinde

dört duvar, 

kiremitler kırılıyor üzerinde

birkaç kırgın kiremit,

icabet ediyor feryadın davetine

bir de 

kiremitsizliği ekledim sensizliğe

uzun kış evvelinde

bî çare

kiremitsizlik mahkûmiyetine

kalınan sensizliğe

ne çare', 'Yalnızım kuyu dibinde,          mecnun halimden, kime ne 	 Sensizliği ekledim yalnızlığıma Hani geçen zamanlar  kuru bir incir vermiştin ya ...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/kis-evvelinde-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gamzelerine Yazılmış Bir Destan-4(Efsaneler Sonlara Gebe)', 'gamzelerine-yazilmis-bir-destan-4-efsaneler-sonlara-gebe-haluk-cenk-batur-e6cb4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kapattın sana açılan bütün kapılarımı

Zafer bayraklarını kalelerin burcuna diktin

Dünyanın hayli zifiri karanlıklarını

Hiç acımadan kader diye cebrettin

Çok zor artık kaybolan mananın yeniden hayat bulması

Biz yinede gamzelerinin hayaliyle yaşar avunuruz

Artık çok zor bu davanın savunulması

Belki bir gün bir zaman bir yer bir mekan gamzelerin ve ben buluşuruz.

Acımdan ağlayıp ta intizar etmem hiçbir zaman

Aşkından gümbür gümbür şiirler yazdıran kadın

Ne olur bir bak intihar etmeden zaman

Alnımda olmasa da lehv-i mahfuzda adın.

Bu son seslenişimi sakın ola yakarıştan sayma

Üslubum ah-u vah etmek değildir benim

Boşa uğraşıpta geleceğe dair planlar kurma

Çoktan yakardım denizleri seninle uyuşsaydı tenim.

Unutmak makamında olmasa da avutmaktayım kendimi şu aralar

Evden işe işten eve öylece geziyorum

Aklımın hep kaygan köşesinde kaygan sorular

Ben neyim kime memurum nereye gidiyorum? 

Divane ettim kendimi anonim bestelere

Kapattım güftelerimi kilitsiz zindanlara.

Unuttum ne varsa,sövdüğüm gecelere

Uymuyor bu hasret üniter yapıma.

Masallarda bahsedilen; Vuslata eremeyenlerin efsanesidir

Sen masalları beynime nakşeden kalemsin.

Leyla’sına kavuşamayan Mecnun’un ta kendisidir

Şiirler benim haykırışım,sen efsanemsin.

Aman canım bu ayrılıkta bizden olsun! 

Mecnun’u Leyla’yı hortlatmaya gerek yok.

Gamzelerine ihanet eden Nemrut’a yoldaş olsun! 

Ferhat’ı Şirin’i anmaya gerek yok.

Zerafet kokan aşkların başlangıcı gibiydi bizimkisi

Vuslata perdeydi her gün her gece.

Her şairin,her şiirin bir dipnotu,ilintisi

Neden efsaneler sonlara gebe? 

2005', 'Kapattın sana açılan bütün kapılarımı Zafer bayraklarını kalelerin burcuna diktin Dünyanın hayli zifiri karanlıklarını Hiç acımadan kader di...', ARRAY['Türk Edebiyatı','Şiir','Haluk Cenk Batur']::text[], 8.5, '{"poet":"Haluk Cenk Batur","poet_slug":"haluk-cenk-batur","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gamzelerine-yazilmis-bir-destan-4-efsaneler-sonlara-gebe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temsil-i Veda', 'temsil-i-veda-arif-onbasioglu-ok8hq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem kaç bahar geçti

serzenişte gözlerin,

kırık dökük teneşir

ah ölümdür sözlerin

bir tomurcuk gül idin,

döndürdün beni bülbüle

muhtaç ettin kendine, 

aşk-ı bahtiyar ellerin

bilirim, kaç baharı

teslim ettin kadere

Azrail, od harladı

başladı, son silsile

gül, ölüm oldu bülbüle

bülbül gülün teninde

kırıldı, dikenli dalları

bülbül, veda etti güle', 'Bilmem kaç bahar geçti serzenişte gözlerin, kırık dökük teneşir ah ölümdür sözlerin bir tomurcuk gül idin, döndürdün beni bülbüle muhtaç ett...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/temsil-i-veda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aç ellerini', 'ac-ellerini-hatice-kelleli-x9xtw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aç bu gece ellerini mevlaya 

Meylediver rabbinin adını defalarca

Aç kalbinin bir parçasınıda olsa 

Seslen seni yaradana

Bir defa, bin defa

Az ya da çok fazla

Bir kelime, bir söz,bir dua

Sevdiklerin için, kendin için,

Söyle istediklerin için

Kır  yüreğindeki kalın zincirleri

Menfaatsiz bir kelimede sen söyle

Seni yaradana', 'Aç bu gece ellerini mevlaya  Meylediver rabbinin adını defalarca Aç kalbinin bir parçasınıda olsa  Seslen seni yaradana Bir defa, bin defa A...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kelleli']::text[], 8.5, '{"poet":"Hatice Kelleli","poet_slug":"hatice-kelleli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ac-ellerini-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gölgeler de Sever', 'golgeler-de-sever-arif-onbasioglu-jb17w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi yanın aşk,

         ben, hangi yanınım”

Önce yumdun,

günah sinmemiş gözlerini.

Yaş on yedi...

Açıklıyor,

bana dair tedirginliğini.

Beyaz teninde

bir namus inceliği

Siyah gözlerim,

çöker mi beyaza

kara bulut gibi? 

Korkuyorsun

ve korkuyorum

Kalın perde üzerine

Düşüyorsun, tül misali.

Odam daha da kararıyor.

Dört duvar; mum dibi

Arıyorum

o korkak 

ve ürkek gölgemi

benden iyi bilen beni

Öyle ki

gölgem arkasından sunuyorum,

sana kendimi

Mecnun, bir idi

şimdi oldu iki

Ben, gölge mi

gölge, ben mi

Işık hangi tarafta ki?', 'Hangi yanın aşk,          ben, hangi yanınım” Önce yumdun, günah sinmemiş gözlerini. Yaş on yedi... Açıklıyor, bana dair tedirginliğini. Bey...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/golgeler-de-sever-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kutsiyet Adına Dans', 'kutsiyet-adina-dans-arif-onbasioglu-gta66', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bayan! ! ! 

   Güzel   bir  dansla  neden  kutsamıyoruz  bu  geceyi,

                                yoksa  tapılacak  şey  kalmadı  mı,

                               kutsiyeti  kalmadı  mı  yoksa  sevdaların? 

   Üzerimize  çöken  o  beyaz  bulutlar   artık  nerede,

                               yoksa  masumiyet  kalmadı  mı? 

   Suretimizdeki  karanlık  neden...? 

                               Yoksa  kara  bulutlar  mı? 

   Zamanın  aleyhimize  işliyor  olması,  ne  kadar  kötü

   bayan  değil  mi? 

   O  kutsiyeti  yaşayabilmek  için,  eğirdiğimiz  pamuk  ipliği

   bile,  bize  güven  vermiyor  artık.

Acizane,

endişe  içinde...

                    Arıyoruz  ölümü,  kaderimizin  her köşesinde                                    

                    ve  her  defasında  umutsuzluk  ile  yüz  yüze

Takdiriniz, 

                    sizin  takdiriniz  bayan! ! ! 

İsterseniz  oturun  şöyle,

İsterseniz  bütün  halet-i  ruhiyemizle 

 tapıyormuşçasına dans  edelim,

bu  karanlık   surette', 'Bayan! ! !     Güzel   bir  dansla  neden  kutsamıyoruz  bu  geceyi,                                 yoksa  tapılacak  şey  kalmadı  mı,    ...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kutsiyet-adina-dans-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizlik ve Bir Ölü', 'sessizlik-ve-bir-olu-arif-onbasioglu-3ze2d', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sessiz bir gidişti onunkisi

Benimle olan anıları da zaten sessizlikti

Bu sessiz anılar,

sessiz bir hayatın içinde,

bu sessiz hayat,

sessiz anılar halinde 

zaman zamanı takip ediyor

Güneş doğudan doğuyor,

batıdan batıyor...

Ertesi gün oluyor,

Gündüz yine Gece’ye sırnaşıyordu.

                             Ve o, sessiz...

Zaman’ın oğlu Gündüz’ün,

yerini kardeşi Gece’ye bırakırken

yeryüzüne çöken sessizlik gibi.

                            Ne bir ses var ne sis

                           ne siz ne biz

                          yalnız o var, yine sessiz.

Öylesine sessiz ki,

bazen sıkılmıyor değildim.

Sorularıma cevabı sessizlikti.

Bir harekette bile bulunmuyordu

                        

                               Tıpkı ölü sükûneti...

Anlamalıydım,

daha sonra öğrendim

                                            Meğerse Ö-LÜY-MÜŞ', 'Sessiz bir gidişti onunkisi Benimle olan anıları da zaten sessizlikti Bu sessiz anılar, sessiz bir hayatın içinde, bu sessiz hayat, sessiz a...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sessizlik-ve-bir-olu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebepsiz! ...', 'sebepsiz-reside-coskun-1phuk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uykusuz geçen gecelerin sebebi sensin..

Sebebi sensin uyanmak istemediğim rüyaların..

Geç doğan sabahların da sebebi sensin..

Sebebi sensin yalnızlığın üstüne binen yalnızlığın...

Mutluyken bir rüzgarın yüzüme esmesiyle gelen hüznün de sebebi sensin..

Gökyüzünde uçan güvercinin kaybolmasıyla yine mahkum oluşumunda sebebi sensin..

Bir uçurtmanın düşmesinin,bir balonun elden kaçmasının da sebebi sensin..

Isıtmayan güneşin,üşütmeyen karın,ıslatmayan yağmurun da sebebi sensin...

                                                                                            (11/09/2005) ist', 'Uykusuz geçen gecelerin sebebi sensin.. Sebebi sensin uyanmak istemediğim rüyaların.. Geç doğan sabahların da sebebi sensin.. Sebebi sensin ...', ARRAY['Türk Edebiyatı','Şiir','Reşide Coşkun']::text[], 8.5, '{"poet":"Reşide Coşkun","poet_slug":"reside-coskun","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sebepsiz-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Duyguları', 'guz-duygulari-dursun-elmas-apcgx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yine esmede güz rüzgârları

Kasavette bütün yaratık...

Sıkıca tutunmakta direniyor hayata

Son demlerini yaşayan yaprak...

İrkilirim yaprak çırpınışlarında,

Ürküsünü yaşarım soğuk yüzlü ölümün...

Gurbet elemleri sarar içimi,

Kucaklar bedenimi,ıslak nemli duygular...

Gözlerim önünde canlanır bir bir,

Güz gibi soluk,benzi kaçık sevdalar...

Yine esmede güz rüzgârları

Sevdalı yüreklere gam yüklemekte.

Güz gülleri misali

Hayat sürüp gitmekte...

Yürüyorum yağmur altlarında kaygısız,

Etraflara bakıyorum umutsuz ve amaçsız...

Hasret sancıları yakarken yüreğimi,

Hülyâlara dalıyorum çaresiz ve patavatsız...

Yine esmede güz rüzgârları

Gönlünde hapisli göz yaşlarım:

Rüzgârın saçlarının...

Ve hüzün çökmüş yüreğine:

Gözleri buğulu bulutların...

Hıçkırıkları dökülüyor gökyüzünün

Yanağımda busedir; göz yaşları yağmurun...', 'Yine esmede güz rüzgârları Kasavette bütün yaratık... Sıkıca tutunmakta direniyor hayata Son demlerini yaşayan yaprak... İrkilirim yaprak çı...', ARRAY['Türk Edebiyatı','Şiir','Dursun Elmas']::text[], 8.5, '{"poet":"Dursun Elmas","poet_slug":"dursun-elmas","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/guz-duygulari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '“BEN” den İzler', 'ben-den-i-zler-arif-onbasioglu-fkjbz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gizlenir, bir adam

gözlerin şavkında

hezarfenler uçuşur,

o mahçup saçlarında

kırıldı kırılacak

haritaların,

yol iz nedir bilinmez,

bilinmeyeni

gösterecek diye,

hezarfenler beklenmez

gideceksen kendine

bir “ben” e sor, yine kendine

gizlenen bir adamdan 

medet ummamak niye? 

O adam ki gizlenir, 

seni senden iyi bilir', 'Gizlenir, bir adam gözlerin şavkında hezarfenler uçuşur, o mahçup saçlarında kırıldı kırılacak haritaların, yol iz nedir bilinmez, bilinmeye...', ARRAY['Türk Edebiyatı','Şiir','Arif Onbaşıoğlu']::text[], 8.5, '{"poet":"Arif Onbaşıoğlu","poet_slug":"arif-onbasioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ben-den-izler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vur bir daha sende yittim', 'vur-bir-daha-sende-yittim-serkan-madak-h07wk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Beni dosta düşman ettin

Yemin ettin yine gittin

Ben dünyamı feda ettim

Vur bir daha sende yittim

Ele köle bana naz''dın

Izdırabı bana yazdın

Hani sözdü neden kızdın

Çok sevdim diyemi çizdin

İmkansızı deniyorum

Bin gönülü deriyorum

Yine sana dönüyorum

Acıtsanda seviyorum

Gamsızlığa vuruyorum

İçin için eriyorum

Bir kez daha soruyorum

Bitti deme ölüyorum

Şavaşalım bir kez daha

Yalvarırım biraz çaba

Olmaz ise vur bir daha

Her sevgi gider ALLAH''a', 'Beni dosta düşman ettin Yemin ettin yine gittin Ben dünyamı feda ettim Vur bir daha sende yittim Ele köle bana naz''dın Izdırabı bana yazdın ...', ARRAY['Türk Edebiyatı','Şiir','Serkan Madak']::text[], 8.5, '{"poet":"Serkan Madak","poet_slug":"serkan-madak","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/vur-bir-daha-sende-yittim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak kokusu', 'toprak-kokusu-hatice-kelleli-dkon7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ömrün her safhasında yaşamın her anında seninle

Sonsuz kadar büyük, canımdan değerlisin gözümde

Yüreğimde, içimdesin  her zaman seninleyim

Toprağında buldum hayatı

Toprağında buldum bu canı

Çünkü toprak kokusu var sende

Elvan çeşitli kokular arasından,

Sıyrılıp farkettiren kendini

En benimsediğim en çekici

Vazgeçemediğim tek koku

Toprak kokusu var sende

Yüreğinde içininde içinde

Buram buram tüten

Tüm benliğimi içine çeken

Cana can katan

Canı candan alan

Benliğimin her köşesinde yankılanan

Toprak kokusu var sende

İliğime işleyen

Toprak kokusu var sende

Sımsıcak içtenliğinin,gözkorkutan soğukluğunda

Cana can katan, canı candan alan

Doyuran, bıktırmayan

Toprak kokusu var sende

Tüm benliğinde

Yüreğinin gizeminde

Fırtınalı bakışlarının sessizliğinde

Birde içimi titreten gözlerinde

Toprak kokusu var sende

Muhtaçlıktan keyfaldığım

Sevmekten korkmadığım

Toprak kokusu var sende

Beni sana bağlayan özünde', 'Ömrün her safhasında yaşamın her anında seninle Sonsuz kadar büyük, canımdan değerlisin gözümde Yüreğimde, içimdesin  her zaman seninleyim T...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kelleli']::text[], 8.5, '{"poet":"Hatice Kelleli","poet_slug":"hatice-kelleli","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/toprak-kokusu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik nedir bilir misin', 'caresizlik-nedir-bilir-misin-meram-yalinizoglu-jprzf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çaresizlik nedir bilir misdin? 

Oksijeninin azaldığını hissetmek,

Yavaş yavaş değil; 

Hızla oksijen çemberinin daraldığını hissetmek? 

Yolunun bir uçurumda değil,

Sonu olmayan bir boşlukta bittiğini görmek.

Çığlık atmak isteyip

Sesini çıkaramamak? 

Kana kana su içmek istemek,

Ama suyun bir yudumda biteceğini görmek? 

Güneşin söndüğünü görmek,İçinde birşeylerin,

Tırnaklarını batırıp gezindiğini hissetmek? ? 

Çaresizlik nedir bilir misin? 

Nerden bileceksin,

Sen hiç sensiz kalmadın ki,

Benim sana aşık olduğum gibi

Hiç aşık olmadın ki...', 'Çaresizlik nedir bilir misdin?  Oksijeninin azaldığını hissetmek, Yavaş yavaş değil;  Hızla oksijen çemberinin daraldığını hissetmek?  Yolun...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/caresizlik-nedir-bilir-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayata Dair', 'hayata-dair-mevlut-battaloglu-oxbbi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hayat dediğin budur işte,

bir gelinin saçını

beyaz duvak içinde

bir sarıya 

bir maviye boyarsın

biraz pembe düşünür

üste siyah çalarsın

dönüp eflatunu unuttum dersin

sonra silip yeni baştan çizersin

ve bu resmi hiç bitiremezsin.', 'hayat dediğin budur işte, bir gelinin saçını beyaz duvak içinde bir sarıya  bir maviye boyarsın biraz pembe düşünür üste siyah çalarsın dönü...', ARRAY['Türk Edebiyatı','Şiir','Mevlüt Battaloğlu']::text[], 8.5, '{"poet":"Mevlüt Battaloğlu","poet_slug":"mevlut-battaloglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hayata-dair-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yiğidim', 'yigidim-kadir-kaya-bd5e5', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşk uğruna yandık ateşte,közde,

Kalplerde sevgimiz gülümser yüzde,

Muhabbetin balı bir tatlı sözde,

El eli öperken mutlu Yiğidim.

Sadelik, tevazu nişandır bizde,

Can kuşu bekliyor duruşu, nazda,

İnanan gönüller baharda, yazda,

Tertemiz yüreği kutlu  Yiğidim.', 'Aşk uğruna yandık ateşte,közde, Kalplerde sevgimiz gülümser yüzde, Muhabbetin balı bir tatlı sözde, El eli öperken mutlu Yiğidim. Sadelik, t...', ARRAY['Türk Edebiyatı','Şiir','Kadir Kaya']::text[], 8.5, '{"poet":"Kadir Kaya","poet_slug":"kadir-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ismini-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eğer', 'eger-meram-yalinizoglu-4toyg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Eğer; 

Yokluğunda içim yanıyorsa

Eğer; 

Özlemin kalbimi parçalıyorsa

Eğer; 

Yokluğun boğazımda bir düğüm,

Gözlerimde yaş oluyorsa

Eğer; 

Hasretin beni uykusuz gecelere itiyorsa

Ben kendimi bilirim.

Seni seviyorum

Sana aşık oldum demektir...', 'Eğer;  Yokluğunda içim yanıyorsa Eğer;  Özlemin kalbimi parçalıyorsa Eğer;  Yokluğun boğazımda bir düğüm, Gözlerimde yaş oluyorsa Eğer;  Has...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eger-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdam dört dağ içinde', 'sevdam-dort-dag-icinde-i-sa-tekin-p9lsc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zaman zaman içinde

Geçiyor devran içinde. 

Devran böyle gitmez 

Sevdam dört dağ içinde

Sabır kahır içinde

 Kahır bitecek mahpus içinde

 Bu türkü daha çok söylenecek

Sevdam dört dağ içinde 

İsa Tekin', 'Zaman zaman içinde Geçiyor devran içinde.  Devran böyle gitmez  Sevdam dört dağ içinde Sabır kahır içinde  Kahır bitecek mahpus içinde  Bu t...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevdam-dort-dag-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Acı Sensizlik', 'aci-sensizlik-meram-yalinizoglu-k824u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşamda her akşamki gibi

Başımı yastığa koyduğumda

Yaşıyorum sana özlemimi

İki kat.

Bu akşamda her akşamki gibi

Yastığa koyduğum an başımı

Uykum değil,

Yaş değil,

Sensizliğin ağlamaklı sesi,

Sensizliğin dayanılmaz acısı,

Özlemin akıyor gözlerimden.

Ezan sesleriyle beraber hıçkırıklarım,

Aheste aheste çöker içime

Acı sensizlik...', 'Bu akşamda her akşamki gibi Başımı yastığa koyduğumda Yaşıyorum sana özlemimi İki kat. Bu akşamda her akşamki gibi Yastığa koyduğum an başım...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/aci-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reşaranî Şiir ve Beyitsiler 23', 'resaran-siir-ve-beyitsiler-23-huseyin-avdic-rl57w', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Dua, Allah''la Konuşma Vasıtasıdır

Allah''ın insanlarla konuşmasıdır, mukaddes Kitaplar.

İnsanlar da O''nunla, dua ve ibadetle konuşsunlar.

******

Yanlız Kavlî Dua Kâr Etmez

Dua dinin esasıdır, Allah''a dua ediniz.

Fakat, tarlayı ekmeden hiç ürün beklemeyiniz.

******

Kazancın, Allah''ın Vergisine Bağlıdır

''Ben tarlayı ektikten sonra, duaya ne gerek vardır'' deme.

Yağmur vermezse Allah, nerden olsun sana, ürün elde etme? 

******

Değerli Olmak İsteyen, Dualı Olmalı

''Dua edin, cevap vereyim'' demiştir, Allah.

''Duanız olmazsa, yoktur değeriniz'' vallah! 

******

Allahsızlar, Duasız Kazanır

Allah, Allah-sızlara da verir, hiç bir dua etmeden.

Nasipleri yoktur ama onların, âhret ücretinden.

******

Duanın Asıl Karşılığı Âhirette

İnançsızlar, fiilî dualarının karşılığını alırlar bu dünyada.

İnançlılar da, sözlü dualarının karşılığını bulurlar öte yerde.

Berlin, Eylül 2005.', 'Dua, Allah''la Konuşma Vasıtasıdır Allah''ın insanlarla konuşmasıdır, mukaddes Kitaplar. İnsanlar da O''nunla, dua ve ibadetle konuşsunlar. ***...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Avdic']::text[], 8.5, '{"poet":"Hüseyin Avdic","poet_slug":"huseyin-avdic","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/resarani-siir-ve-beyitsiler-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukluğa Özlem', 'cocukluga-ozlem-korel-okay-ekuj7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir çocuk olsaydım,

Şöyle uzun sarı saçlı küçücük,

Gam keder nedir bilmeseydim! 

Koşup düşen, ağlayan gülen

Sevgide sadece şefkati bilen

Bir bebek olsaydım eğer.

Param olmuş, olmamış

Derdim yok ki deva bulsun

Sigara yerine elimde emzik

Yalnızlığım oyuncaklar arasında yoğrulsun.

Kış mı gelmiş paltom mu yok,

Elbet biri alacak bana

Oyuncaklarımdan başka derdim yok

Bozulsa da al derim babama.

Kinim yok, tasam yok

Ne yiyeceğim diye düşünmem akşama

Bu günler gidecekmiş onu da bilemem

Kaygısızca girerim yatağıma

Onun parası çokmuş, oldukça mutlu

Kıskanmam bulduğumla avunurum

Kötülük beklemem ki hiç kimseden

Dertle kederle değil oyunlarla yorulurum.

Büyüsem derim,babam gibi olsam

Bir sigara alırım elime

Emzik oyuncak yerine

Para hırsı büyümeye başlar

Alev alev içimde.

Derim işte o zaman

Hiç büyümesem

Hep çocuk kalsam, hep gülsem

Kader başıma çöreklenmeden 

Büyüklüğün ne olduğunu

Bir bilebilsem! 

Ama, nafile,

Ne yapsamda ne etsem

Çarkın içine girip başlayacağım dönmeye

Ve dualar fışkıracak dudaklarımdan

Tanrım bir an önce ölebilsem diye.

                            19.03.1981 

                            Korel Okay', 'Bir çocuk olsaydım, Şöyle uzun sarı saçlı küçücük, Gam keder nedir bilmeseydim!  Koşup düşen, ağlayan gülen Sevgide sadece şefkati bilen Bir...', ARRAY['Türk Edebiyatı','Şiir','Korel Okay']::text[], 8.5, '{"poet":"Korel Okay","poet_slug":"korel-okay","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cocukluga-ozlem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yaşıyorum', 'sana-yasiyorum-serkan-madak-6wfd1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sabahı olmuyor sensiz Başkentin

Sensiz kimsesizim sensiz dul,yetim

Sevdası olmayan bu adi kentin

Umudu olalım bitsin hasretim

Beklerim zamansa tek eziyetin

Sana geçen her an bil ibadetim

Biraz ümitlendir göster niyetin

Sana yaşıyorum kendime bittim', 'Sabahı olmuyor sensiz Başkentin Sensiz kimsesizim sensiz dul,yetim Sevdası olmayan bu adi kentin Umudu olalım bitsin hasretim Beklerim zaman...', ARRAY['Türk Edebiyatı','Şiir','Serkan Madak']::text[], 8.5, '{"poet":"Serkan Madak","poet_slug":"serkan-madak","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sana-yasiyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kır Çiçeği', 'kir-cicegi-asya-yildiz-opvtk', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tutundum, 

Yakasına yapışıp toprağın

Kara bağrına 

Köklerimle saldırdım,

İncecik bedenimi bağladım 

Yerküreye...

Savrulup durdum binlerce yıl, 

Öyle acizim ki..

Öyle yalın, öyle çıplak, 

Öyle kendimim işte.

Tohumlarım savrulup durdu 

Yerküreye...

Güneş gitti, rengim soldu; 

Tükendi suyum, yetemedim, kurudum.

Paylaşmaya geldi yasımı bulutlar,

Koşuştu eteğime iki kara böcek.

Hüzünse al sana hüzün arkadaş! 

Sonbahar katili değil ömrümün; 

Çoktan verdim ben canımı

Yerküreye...

Ayazdı toprağın üstü, 

Korkuturdu; 

Oysa usul bir bekleyiş vardı altında. 

Elleri başında, dizleri karnına çekik 

Gün sayar mahkum, gözleri devrik.

Mevsimler geçer, karalar bağlama; 

Tutunup toprağın anaç bağrına, 

Kökleri salmalı gidebildiğince.

Narin bedenin tanımalı şimdi

Yerküreyi...', 'Tutundum,  Yakasına yapışıp toprağın Kara bağrına  Köklerimle saldırdım, İncecik bedenimi bağladım  Yerküreye... Savrulup durdum binlerce yı...', ARRAY['Türk Edebiyatı','Şiir','Asya Yıldız']::text[], 8.5, '{"poet":"Asya Yıldız","poet_slug":"asya-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kir-cicegi-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canım Kızıma Öğütler', 'canim-kizima-ogutler-meram-yalinizoglu-6tk82', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Biz insanlar işte böyleyiz 

Egomuzun kurbanı olur 

Senin gibi masumlar 

Senin gibi günahsızlar getiririz dünyaya 

Öyle bir dünya ki bu dünya 

Değil yeni bir masuma 

Kendimize bile zor katlanıyoruz 

Ama egomuza yenik düşüyoruz. 

Sonra; 

O da yetmezmiş gibi 

Nasıl sorgusuz sualsiz 

Getirdiysek dünyaya 

Olsun bizim istediğimiz gibi 

Bizim gibi düşünüp bizim gibi ağla isteriz 

Kendimiz için isteyip yapamadığımızı 

Sen yap isteriz. 

Ağladığımızda ağla gülüğümüzde gül isteriz. 

Fark etmeyiz en büyük hatayı yapıp 

Seni en çok incitenin kendimiz olduğunu. 

Düşünemeyiz kızım 

Farklısın bizden 

Amaçların farklı zevklerin farklı 

Kabul etmeyiz sana özel bir hayatı 

Korkularımız sanırız ki senin korkuların 

Sevinçlerin bizim sevinçlerimiz. 

Bilmeyiz senin korkularının bizim baskılarımız olduğunu 

Biliriz de kabul etmeyiz. 

Hayat hem çok kısa kızım 

Hem de bi o kadar uzun 

Hayat hem mükemmel bitanem 

Hem cehennemden beter. 

Yanacaktır seninde canın 

Düşecektir damlalar gözlerinden 

Düştüğünde kanayacaktır dizin 

Beklide kalkmana kimse yardım etmeyecektir 

Beklide itecekler seni bir uçuruma 

Tepe taklak düşeceksin o yardan 

Canın acıyacaktır kızım 

Riyakar, nankörler etrafını sarmalayacak 

Anlam veremiyceksin bu adiliklere 

Yüreğin kabaracak 

Sarılmak isteyeceksin 

Can yeleğin delik olacak beklide 

Sırtını yasladığında 

Bakacaksın ki arkanda nebir dağ var ne bir kaya 

Koca bi boşluktan düşmüşün arkaya 

Saçından tel düşse yanar yanar da içimiz 

Anlatamayız bunu 

Düşen her damla yaş 

Yüreğimizde dolar kan 

Bebeğim; 

Açtın gözlerini şu fani dünyaya 

Acısı, tatlısı, gamı, kederi 

Alabildiğine çok hayata. 

Kızım; 

Hayat çok zor 

Yaşamak çok zor. 

Ağlatmasınlar seni izin verme, 

Ezdirme kendini, incinme, 

Eğme kimseye başını, 

Yürü hep emin adımlarla ileri 

Güzel iyi mutlu yarınlara 

Mutlu ol kızım 

Canım, ciğerim, yaşama sebebim, 

Güzel günler hep senin olsun, 

İçin hep neşeyle dolsun, 

Yüzünde gülücük eksik olmasın, 

Zulümden, acıdan kederden uzak 

Endişesiz sıkıntısız bir hayat senin olsun. 

Mutluluk senin gülmek senin 

Allah seninle olsun... 

Ne zaman yüreğin yanar, 

Ne zaman dizin kanar 

Ne zaman seni biri boşluğa iter 

Ne zaman sarılacak bir yelek arar 

Ne zaman yaslanacak bir yer istersen 

Ben orda 

Yanında 

Arkanda 

Başında 

Kalbinde 

İçinde 

Yüreğinde 

Sana sımsıkı sarılıp 

Tüm zorluklara göğüs germene yardımcı olacam. 

SENİ ÇOK SEVİYORUM KIZIM....İYİ Kİ VARSIN....', 'Biz insanlar işte böyleyiz  Egomuzun kurbanı olur  Senin gibi masumlar  Senin gibi günahsızlar getiririz dünyaya  Öyle bir dünya ki bu dünya...', ARRAY['Türk Edebiyatı','Şiir','Meram Yalınızoğlu']::text[], 8.5, '{"poet":"Meram Yalınızoğlu","poet_slug":"meram-yalinizoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":86,"source_url":"https://www.antoloji.com/canim-kizima-ogutler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben Seni Hiç Sevmedim Ki', 'ben-seni-hic-sevmedim-ki-kamil-soylemez-1ig0w', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben seni hiç sevmedim ki

Sadece görünce elim,ayağım karıştı

Sokaklar,caddeler yozlaştı

Tabelalar konuşmaz

Anlatmaz,oludu istanbul''u

Erol çakır öğretmenevi kayıptı

Ben kayıptım,istanbul kayıp

Sadece sen vardın yanımda

Aklımda fikrimde sen

O kadar güzeldin ki

Bakmalara kıyamadım

Doyamadım yanı başındalığıma

Ve ayrıldığımda 

İstanbul sokakları karanlıktı

Bense aydınlıktım sevdanla

Sabah olmadı o gece bana

Uyku dargındı,yastık dargın

Yatak azgın bir kısraktı

Sırtından durmadan beni atan

Sen geziniyordun ben gezinmelerimde

Her baktığım yerde sen vardın

Daha fazlan içimde

Sımsıcaktın buzlar faydasız

En azgın fırtınalar yararsızdı

Söndürülecek bir yangın vardı

Ta o ilk gördüğüm tuzla karargahından

Tüm atış talimlerinde hedef bendim

Hiçte düşlemediğim güzeliğinden

Sımsıcak sözlerinden etkilenen

Yangın yeriydim sana en derininden

Ve sen ayrılıp,giderken ben yağıyordum

Yalvarıp,seni getirmesini istediğim bulutlardan

Caddeleri ben ıslatıyordum yanaklarımda

Evet ben seni hiç sevmedim ki', 'Ben seni hiç sevmedim ki Sadece görünce elim,ayağım karıştı Sokaklar,caddeler yozlaştı Tabelalar konuşmaz Anlatmaz,oludu istanbul''u Erol çak...', ARRAY['Türk Edebiyatı','Şiir','Kamil Söylemez']::text[], 8.5, '{"poet":"Kamil Söylemez","poet_slug":"kamil-soylemez","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/ben-seni-hic-sevmedim-ki-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredesin Anam', 'neredesin-anam-i-sa-tekin-ltw1a', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anam ah anam

Gecem karanlık

Bedenim sancıyor

Her yanımı ihanet sarmış

Neredesin ah anam! 

Hastayım dardayım

İlacım yok takatsızım

Vurgun yedim, yüreğim yaralı

Dicle''den bir tas su ver

Neredesin ah anam

Geceler uzun

Kabuslar bitmiyor

Yüreğim yaralanıyor

Rüyalarımda da yoksun

Neredesin ah anam! 

Hücrem karanlık

Her yanım yosun kokuyor 

Bir tutam sevgini gönder

Karanfil koksun hücrem

Neredesin ah anam!', 'Anam ah anam Gecem karanlık Bedenim sancıyor Her yanımı ihanet sarmış Neredesin ah anam!  Hastayım dardayım İlacım yok takatsızım Vurgun yed...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/neredesin-anam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-ali-olcars-8sbtb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Çakılıp durur beynime çivi çivi hasret.

Durdurur benliğinde zamanı, ah yüreğim.

Yakıyorken ruhumu ateş, içimde nefret.

Toz pembe rüyalarımı gönlümden silerim.

Silinirde resmi zihinlerde anıların.

Dökülüverir yaprakları sevdamın tek tek.

Ben sayarken günleri arasında acının.

Boynuma dolar ağını sinsi örümcek.

küflü yataklara serilir zifri karanlık.

İliklerime işler duvardaki rutubet.

Aynada bakıpta gördüğüm zanlı idamlık.

Ruhum gerilir içten içe besler husumet.

Buhar buhar yükselir gözbebeklerimden nem.

Dalıveririm en kuytularına gecenin.

Bilinmez bir acıdır vurur enseme her dem.

Dolanırım içinde bilinmez bilmecenin.

Kulağımda zemheri gecenin uğultusu.

Anafor oluşur ruhumun derinliğinde.

Kaplar ve sarar cismimi aynanın buğusu.

Med-cezirler oluşur derbeder bedenimde.

Çekilirken korkular en izbe köşelere.

Umutlar yüklerim hayalimin zulasına.

Kabuslar çöksede birden en mahrem düşlere.

Salarım mutluluğu sevdamın kucağına.', 'Çakılıp durur beynime çivi çivi hasret. Durdurur benliğinde zamanı, ah yüreğim. Yakıyorken ruhumu ateş, içimde nefret. Toz pembe rüyalarımı ...', ARRAY['Türk Edebiyatı','Şiir','Ali Olcars']::text[], 8.5, '{"poet":"Ali Olcars","poet_slug":"ali-olcars","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hasret-274-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Açık kapı', 'acik-kapi-ali-olcars-kcmej', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zorlama boşuna kapalı kapıyı tık tık...

Bak rahmanın kapısı ardına kadar açık.

Senin varlığın değilmiki bir avuç balçık.

Girip bu rahmet kapısından insan ol ve çık.', 'Zorlama boşuna kapalı kapıyı tık tık... Bak rahmanın kapısı ardına kadar açık. Senin varlığın değilmiki bir avuç balçık. Girip bu rahmet kap...', ARRAY['Türk Edebiyatı','Şiir','Ali Olcars']::text[], 8.5, '{"poet":"Ali Olcars","poet_slug":"ali-olcars","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/acik-kapi-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Reçete', 'recete-ali-olcars-eci0c', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne acı bir ilaç bu hekimin tavsiyesi.

Beynimde zıp zıplayan cinlerin vesvesesi.

Diyorlarki sensin sen dünyanın efendisi.

Bana büyük hediye olmak onun kölesi.

Salsam umutlarımı gök kubbe delinecek.

Yer yarılıp içine sanki beni çekecek.

Bir dünya istiyorum arınmış necasetten.

Bir dünya istiyorum ruhu çıkmış cesetten.

Öyle saf öyle temiz öylesine pak olsun.

İçim onun nuruyla dolsun dolsun yoğrulsun.

Başka birşey istemem ne aş, ne ana, ne yar.

Onsuz bana bu diyar dibi olmayan mezar

Ben alemi süzgeçten geçirip süzen mercek.

Bir alem ki içimde beni sokan örümcek.

Bir nesil arıyorum bu dünyadan geçici.

bir nesil arıyorum o dünyadan haberci.', 'Ne acı bir ilaç bu hekimin tavsiyesi. Beynimde zıp zıplayan cinlerin vesvesesi. Diyorlarki sensin sen dünyanın efendisi. Bana büyük hediye o...', ARRAY['Türk Edebiyatı','Şiir','Ali Olcars']::text[], 8.5, '{"poet":"Ali Olcars","poet_slug":"ali-olcars","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/recete-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanoğlu...', 'i-nsanoglu-ali-olcars-0bc3c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hey gidi insanoğlu dedikleri varlık hey...

Dört mevsimi yaşıyor içinde herbir birey.

Önce doğup tomurcuk tomurcuk açılıyor.

Sonra fidan olup etrafına bakınıyor.

Geliştikçe gövde kimse kesemez sanıyor.

Kök salınca oduncunun yolunu gözlüyor.', 'Hey gidi insanoğlu dedikleri varlık hey... Dört mevsimi yaşıyor içinde herbir birey. Önce doğup tomurcuk tomurcuk açılıyor. Sonra fidan olup...', ARRAY['Türk Edebiyatı','Şiir','Ali Olcars']::text[], 8.5, '{"poet":"Ali Olcars","poet_slug":"ali-olcars","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/insanoglu-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İhanete Yenilme sakın', 'i-hanete-yenilme-sakin-i-sa-tekin-1148q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İstesende istemesen de

Bu umursamaz 

Ve acımasız insanlığın

İhaneti kahır eder

Güzellik dolu yüreğini

İstesende istemesende

Bu kuralsız dünya 

Çevremi kuşatan çiyanlar

Zehirlemek ister

Umut dolu yüreğimi

Sakın yüreğin daralmasın

Sabır ile yoğur

Umudu güzelliği

Umursamazlığa, acımasızlığa, ihanete yenilme sakın', 'İstesende istemesen de Bu umursamaz  Ve acımasız insanlığın İhaneti kahır eder Güzellik dolu yüreğini İstesende istemesende Bu kuralsız düny...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ihanete-yenilme-sakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoksun ya ondan', 'yoksun-ya-ondan-orhan-kutlu-vvjer', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yoksun ne zaman baksam seni bana getiren yollarda

 Bir garip duygu sarar her yanımı

 Bir kedi tırmalar sanki mide çeperlerimi.

 Kaşlarım çatılır kendiliğinden. 

Dişlerim sıkılır farkında olmadan.

Sebebi yoksun ya ondan.

Ne içtiğim suda tat var,

 Ne de yediğim lokmada. 

Sadece bekleyişin getirdiği gerginlik

Ve sensizlik var her yanımda. 

Ve sana gidemeyişimin çaresizliği. 

Şarkılar bile birazcık teselli vermiyorlar inan. 

Aksine daha çok hisettiriyorlar sensizliği. 

Sebebi sen yoksun ya ondan.

Bugün Pazar. 

Üstelik kandil diyorlar. 

Hiç bir şeyin farkında değilim.

Kendimi kaybettim herkes şurada burada iken. 

Zaman mı beni 

Ben mi zamanı öldürüyorum bilmiyorum. 

Bildiğim tek şey var yavaş yavaş kayboluyorum 

Kalabalıklar içinde.

 Sebebi sen yoksun ya ondan.

Bir merhabanın 

Bir selamın 

Bir canım demenin 

Bu kadar güzel, 

Bu kadar umut verici,

Bu kadar hayata bağlayıcı olduğunu bilemezdim. 

O kadar muhtaçmışım meğer bir tek kelimeye.

 Bu kadar zavallı isem eğer 

Ve yılgın bir şekilde harap olmuşsa gönlüm. 

Sebebi sen yoksun ya ondan.



Bir ambulans geçiyor yoldan. 

Acı çığlıkları bastıramıyor içimdeki sesleri. 

İçindeki hastanın bile derdini düşünecek, 

Ona acıyacak duygu kalmamış kalbimde. 

Bütün duygularım seninle,

Sensizliğinle paramparça.

Sebebi sen yoksun ya ondan.

Kelimeler de kayboluyor beynimden ağır aksak. 

Düşüncelerimi toparlayıp ta 

Yazmak istediklerimi yazamamak 

Çaresizliğimi gösteriyor yalnızlığımın aynasında. 

Sen olmayınca her şey kayboluyor nedense.. 

Neden sana bağlanıyor her şey. 

Neden bütün yollar sana çıkıyor. 

Biliyorum.

Sebebi sen yoksun ya ondan.

İşte öylesine neşesiz,

Durgun ve biçareyim.

Yüzüm asık.

Bilmiyorum ne kadar sürer bu   ayrılık.

Bu yalnızlık, 

Bu kahroluş. 

Lakin bütün olumsuzluklara karşı bir umut var içimde. 

Asırlardır seni bekleyen ruhuma geldiğin gibi 

Yine geleceksin biliyorum.

Yoktun geldin beni buldun.

Yine geleceksin

Merhaba canım, 

Nasılsın diyeceksin. 

Geleceksin biliyorum.

Sebebi sen yoksun da ondan 

.', 'Yoksun ne zaman baksam seni bana getiren yollarda  Bir garip duygu sarar her yanımı  Bir kedi tırmalar sanki mide çeperlerimi.  Kaşlarım çat...', ARRAY['Türk Edebiyatı','Şiir','Orhan Kutlu']::text[], 8.5, '{"poet":"Orhan Kutlu","poet_slug":"orhan-kutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":65,"source_url":"https://www.antoloji.com/yoksun-ya-ondan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vasiyet', 'vasiyet-necip-fazil-kisakurek-lmzkd', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Son gün olmasın dostum,çelengim,top arabam; 

Alıp beni götürsün, tam dört inanmış adam...', 'Son gün olmasın dostum,çelengim,top arabam;  Alıp beni götürsün, tam dört inanmış adam......', ARRAY['Türk Edebiyatı','Şiir','Necip Fazıl Kısakürek']::text[], 8.5, '{"poet":"Necip Fazıl Kısakürek","poet_slug":"necip-fazil-kisakurek","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/vasiyet-41-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeridir', 'yeridir-abdurrahman-tepe-2s0i9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İnsanlıktan yoksun bazı insana

İnsan değil hayvan desem yeridir

Aşk ile yoğrulmuş ehl-i gufrana

Alemlere sultan desem yeridir

Can canana canı kurban etmez mi

Dost gözüyle bakar seyran etmez mi

Ataşına yanıp giryan etmez mi

Buna huri gılman desem yeridir

Pak insanın asıllık var kanında

Kimisinin bir eda var şanında

Mert oğlu mert yazılıdır anlında

Buna kutb-u cihan desem yeridir

Bencil adam ecir sevap eylemez

Hayın insan hayır kelam söylemez

Gel irfana desen asla gelemez

İşte buna şeytan desem yeridir

Kamil insan tartar söyler sözünü

İnsanlığa vakf eylemiş özünü

Aşıklar endamla çalar sazını

SAMİHİ’ye ozan desem yeridir', 'İnsanlıktan yoksun bazı insana İnsan değil hayvan desem yeridir Aşk ile yoğrulmuş ehl-i gufrana Alemlere sultan desem yeridir Can canana can...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yeridir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çil Bir Dünya', 'cil-bir-dunya-koray-feyiz-x4poh', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sahil kasabalarını seviyorum en çok da yüzünün,

Şafaktan önce bir görkemle parıldarken yıldızlar, 

Bu çam ağacının yanarken kozalakları ıslak yeşil,

Her şey yalın mantıksal yaşamak gibi içimde bak 

Gemiler uluyor,martılar haykırıyor,saatler taşıyor. 

Sahil kasabalarını seviyorum en çok da yüzünün,

Diyorum dönmek belki de dönmemektir biraz ama 

Nasıl başlar yolculuğu akrebin,nasıl esner ırmak,

Nasıl işler ağaç ve nasıl doğrulanır terazisi kalbin 

Vermek için bana bu sevgiyi en baştan korkusuzca. 

Sahil kasabalarını seviyorum en çok da yüzünün,

Gitgide daha da koyulaşıyor sis kınımdaki isyan

Bir kama boşalıyor çelik renginde bu sabah deniz

Kara bir ulumadır evet o iniltisidir asla yenilmez

Bir su yığınının,koyu bir mürekkep gibi parlayan. 

Sahil kasabalarını seviyorum en çok da yüzünün,

Çilini,çilim bildim,çilini kırkbeş yaş şiirim sanki

Ağlamaklı begonyadır çilin hayatın sarı saksısında. 

Tırnaklarını yiyen bir çocuk dalgınlığındayım şimdi

Dertli çal kemancım,ben,çil bir aşk’ım,çil bir dünya.', 'Sahil kasabalarını seviyorum en çok da yüzünün, Şafaktan önce bir görkemle parıldarken yıldızlar,  Bu çam ağacının yanarken kozalakları ısla...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/cil-bir-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Suçlu', 'suclu-sinan-karakas-ikq36', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hata yapmayan  kim var içimizde 

Suçlayınca atarız suçu size

Kırılır mı dostluklar bir hiç için 

Çocuklar güler bizim halimize 

Suçlu benim desem katılır mısınız

Suç samur kürkü olsa alır mısınız 

Bu günler bir daha gelmez bilirim

Bu günleri bir gün anar mısınız

Çiğnerim gururu ayak altında 

Dik dururum kendi ayaklarımda

Bu yollar dikenli bunu bilirim

Yarış var insanlığa giden yolda 

Aptal diyecekler bu duygulara 

Bir çift sözüm vardır gerçek dostlara 

Dün geldik bugün yolcuyuz hedefe

Neleri bıraktık hatıralara', 'Hata yapmayan  kim var içimizde  Suçlayınca atarız suçu size Kırılır mı dostluklar bir hiç için  Çocuklar güler bizim halimize  Suçlu benim ...', ARRAY['Türk Edebiyatı','Şiir','Sinan Karakaş']::text[], 8.5, '{"poet":"Sinan Karakaş","poet_slug":"sinan-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/suclu-25-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzüldüğümü Bilmenizi İsterim', 'uzuldugumu-bilmenizi-i-sterim-koray-feyiz-98kr6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'üzüldüğümü bilmenizi isterim,böyle diyorum

ben de bakın kendi kendime,seviniz beni diye.

sevsin diye,bu yara,yaram:içimdeki suflör; 

bıçak ol,kes; bu acıyı,bu yaradan,kopar,al

sessizlik uysaldır,bir ağaç gölgesi,bir bağ evi.

sevsin diye,ürküttüğü kuşlar yağmurun,orda

seviniz beni diye,elinin sıcaklığının durduğu oda,

yalnızlığın sılasına uyandığım terlik sesi:kor! 

yolunu şaşırmış bir su için,sesim için,bir akor; 

bir çizik bırak,sensiz söylediğim eski bir şarkıya.

bıçak ol kes; bu acıyı,bu yaradan,kopar,al

utanıyorum,yaşadıklarımdan kalmasın bir köpek.

üzüldüğümü bilmenizi isterim,kürsüden indim,

ne varsa konuştuğum,sizin için konuştum,cebren,

ben de bakın kendi kendime,seviniz beni diye.', 'üzüldüğümü bilmenizi isterim,böyle diyorum ben de bakın kendi kendime,seviniz beni diye. sevsin diye,bu yara,yaram:içimdeki suflör;  bıçak o...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/uzuldugumu-bilmenizi-isterim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Canım', 'gel-canim-abdurrahman-tepe-dr16q', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Adem’den bu yana sevgiyle nefret

Sen nefrete bulaşmadan gel canım

Habil’den izzet var Kabil’de zillet

Sen zillete dalaşmadan gel canım

Böylece sürecek hak ile batıl

İlim irfan kervanına gel katıl

Geriye bakmadan ileri atıl

Sen minnete karışmadan gel canım

Alimle otursan alim olursun

Zalimi seversen zalim olursun

İster dalih ister salim olursun

Sen illete girişmeden gel canım

Karanlığa küfredene bir mum yak

Yanlışlara değil sen doğruya bak

O zaman tecelli eder yüce hak

Sen zulmete ilişmeden gel canım

Bir çibanı deşmek onu azdırır

Arıya ilişmek yekten kızdırır

Kader SAMİHİ’ye neler yazdırır

Sen gaflette buluşmadan gel canım', 'Adem’den bu yana sevgiyle nefret Sen nefrete bulaşmadan gel canım Habil’den izzet var Kabil’de zillet Sen zillete dalaşmadan gel canım Böyle...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahman Tepe']::text[], 8.5, '{"poet":"Abdurrahman Tepe","poet_slug":"abdurrahman-tepe","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gel-canim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Katil', 'katil-hatice-kelleli-lcv4t', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kan çeker, elbet döner gelirsin şehrime

Siyaha bürünmüş yastan, kan akan caddelerden

Bir de benden çekine çekine

Usulca girersin semtime

Susmak bilmez ağıtlardan,

Saçlarına dökülen yaşlardan

Kaçar adımlarla girersin mahalleme

Koşarsın koşabildiğince

Sokulup sokağıma yürürsün adım adım

Kanter içindeki tüm çevikliğinle

İlerlersin bana doğru yüzsüzce

Tam herşey bitti derken; 

Rüzgar uğultusu acımı çınlatır kulağına

Sonbahar yaprakları, yaptıklarını vurur suratına

Akan yaşlarımı yağmur anlatır sana

Tüm ışıklar söner kalırsın karanlıkta

Binbir panikle,çekine çekine geleceksin evime

Son bir hediye bulacaksın benim yerime

Merakla açmanı bekleyen son bir hediye

Önce anlam veremediğin bir avuç toprak

Sonra da sana bırakabileceğim

O donmuş elleri bulur korkarsın apansızca

Sana bıraktığım eller...

Yalnızca seni saran tüm sıcaklığını sana veren

Seni okşayan ellerim...

Önce korkar çekilirsin kenara

Ama bilirim merak eder dayanamaz dokunursun yavaşça

Seni ısıtan ellerin 

Artık sana vereceği son bir donukluk çıkar karşına

Sana vereceği son bir donukluk

Aşkımın sıcaklığını ezip geçen,

Beni bir kalemde unutan sen,

Artık unutamayacağın bir donuklukla 

Benimle yaşamak zorunda kaldın

Bilirim hazmedemezsin sen bunu

Haykırırsın etrafa haksızlık bu diye

Birde son bir mektup çarpar gözüne 

Açtığında sarsılacağın son bir not bulursun

İçinde sana bu hediyeyi anlatan

Son bir not...

Sana bu eller sensiz kalamaz dediğimi

Sana ait olduğunu anlatan 

Son bir mektup

Koşar ararsın beni sorarsın beni

Söylerler sana sen gittiğinde öldüğümü

Sensizliğe tahammül edemediğimi

Artık zaman seninle akmakta

Pişmanlık acısı seni yakmakta

Vicdanın  seni boğmakta

Artık mezara gömdüğün bir ceset

Birde katil makamı sahibisin 

Son sözüm sana bu acı sende hiç dinmesin', 'Kan çeker, elbet döner gelirsin şehrime Siyaha bürünmüş yastan, kan akan caddelerden Bir de benden çekine çekine Usulca girersin semtime Sus...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kelleli']::text[], 8.5, '{"poet":"Hatice Kelleli","poet_slug":"hatice-kelleli","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/katil-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Evlerde', 'ayni-evlerde-koray-feyiz-w7gwf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aynı evlerde,o bakışı yitirme

Sevilmek için,içgüdülerine güven.

Yalnızlık,ruhun kuruduğu bir bahçe

Orda,kokusu yok,yetişen çiçeklerin.

Aynı evlerde,o gülüşü eskitme

Beğenilmek için,esirgediklerine hayıflan.

Aşk,kalbin parçalandığı bir iskele

Orda,yolcusu yok,biriken gemilerin.

Aynı evlerde,biz ölü ve gömülüyüz

Sözcüklerimiz olmayacak,ölüler konuşamaz.

Ayrılık,derinin çürüdüğü bir libas

Orda,bedeni yok,biçilen kefenlerin.', 'Aynı evlerde,o bakışı yitirme Sevilmek için,içgüdülerine güven. Yalnızlık,ruhun kuruduğu bir bahçe Orda,kokusu yok,yetişen çiçeklerin. Aynı ...', ARRAY['Türk Edebiyatı','Şiir','Koray Feyiz']::text[], 8.5, '{"poet":"Koray Feyiz","poet_slug":"koray-feyiz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayni-evlerde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarim olsun', 'yarim-olsun-cengiz-kapusuz-9a38d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben bir Anadolu erkeğiyim

Toprak kokan bir yarim olsun,

Al fistanlı mor gömlek

El ele dağ bayır gezsek.

Bir yarim olsun,

Kınalı elleri, yanakları al al,

Gözleri güneş baksın,

Dudakları bal…

Bir yarim olsun; 

Olmasa da bunlar,

Benimle olsun,

Benden bahtiyar…..

Cengiz KAPUSUZ  22,09,2005', 'Ben bir Anadolu erkeğiyim Toprak kokan bir yarim olsun, Al fistanlı mor gömlek El ele dağ bayır gezsek. Bir yarim olsun, Kınalı elleri, yana...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Kapusuz']::text[], 8.5, '{"poet":"Cengiz Kapusuz","poet_slug":"cengiz-kapusuz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yarim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolayı neydi bu hayatın', 'kolayi-neydi-bu-hayatin-hatice-kelleli-0tf3b', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kolayı ne bu dünyanın

Hayatın içinde mi,toprağın içinde mi gömülü olmak

Aşkın denizinde mi, yalnızlığın pençesinde mi boğulmak

Kolaylığı neydi bu yaşamın

İnananıp koyuvermek mi, kendini korkup saklanmak mı

Güvenip anlatmak mı, içine atıp kahrolmak mı

Kolayı neydi...

Fedakarlık yapıp uğraşmakmı sonuna kadar

Ortalığı karıştırıp saklanmak mı bir kenara

İçin kan ağlarken gülebilmek mi

Sahtekar olup ağlar görünmek mi

Kolayı neydi...

Saplamak mı hançeri düşünmeden

Sabredip didinmek mi

Herşeye boyun eğip pusmak mı

Yoksa dimdik savaşmak mı sonuna kadar

Kolay olan neydi bu hayatta

Bırakıp gitmek mi herşeyi

Terkedilip beklemek mi

Çaba harcayıp uğraşmak mı

Aldırışsız olup umursamamakmı herşeyi

Kolayı neydi bu dünyanın

Yaşamak mı,ölmek mi

Ölmeden gömülmek mi toprağa

Kör olmak mı görmek mi

Görüp bilmemek mi

Bildiğin halde düşünmemek mi

Düşünerek yitirmek mi aklını

Umursamayıp yitirmekmi insanlığını

Hiç kolayı yok mu bu dünyanın 

Kolayı neydi bu yaşamın

Neydi...', 'Kolayı ne bu dünyanın Hayatın içinde mi,toprağın içinde mi gömülü olmak Aşkın denizinde mi, yalnızlığın pençesinde mi boğulmak Kolaylığı ney...', ARRAY['Türk Edebiyatı','Şiir','Hatice Kelleli']::text[], 8.5, '{"poet":"Hatice Kelleli","poet_slug":"hatice-kelleli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kolayi-neydi-bu-hayatin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-ali-emek-c2kff', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Soğuk bir rüzgar esiyor

Kemiklerime kadar işliyor yalnızlığı.

Dişlerim parçalarcasına çarpıyor birbirlerine

Ağlıyor rüzgar.

Yaşlar dökülüyor gözünden, gökyüzünden,

Kafası bulanık, düşünemiyor,

Dumanlı mı dumanlı

Siyah bulutlarla dolu.

Haykırıyor yalnızlığını yeryüzüne

Bir tufan olup kopuyor yalnızlığı

Anlamıyor hiç kimse, korkuyorlar.

Nasıl masallarda ağlıyorsa bir dev

O da ağlıyor.

Bütün gücüyle gürlüyor

Yıkıyor önüne her geleni

Tanımıyor hiçbir şeyi

Tanımıyor o da artık kendini,

Kendini kaybediyor 

Unuttu gitti serin serin

Esen yaz meltemlerini.

Harcadı neyi varsa 

Elinde kalan ne varsa

Yalnızlığı dışında

Öfkesini, hüznünü,

Yalanlarını, kahrını, pişmanlığını...

Sonra yavaş yavaş bitti

Önce soluğu kesildi

Sonra gözyaşları

Buldu kendini gökyüzünde

Dağıldı siyah bulutlar

Derin mavilik çıktı ortaya

Öldü rüzgar

Geriye ise 

Acı, hüzün, gözyaşı idi bıraktığı', 'Soğuk bir rüzgar esiyor Kemiklerime kadar işliyor yalnızlığı. Dişlerim parçalarcasına çarpıyor birbirlerine Ağlıyor rüzgar. Yaşlar dökülüyor...', ARRAY['Türk Edebiyatı','Şiir','Ali Emek']::text[], 8.5, '{"poet":"Ali Emek","poet_slug":"ali-emek","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/firtina-50-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnız “Zaman-Hayat”', 'yalniz-zaman-hayat-ali-emek-ecwp7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'I-Zaman

Hızla geçiyor günler,

Durmuyor saatler,

Yetmiyor gücüm

Durup düşünmeye.

Hatırlamıyorum en son ne zaman

Temizledim evimi,

Sıcak bir yemek yaptım tüp bitmeden,

Ne zaman şöyle bir baktım aynada kendime.

Hah... evimde hiç aynam olmadı ki benim.

Hızla geçiyor günler,

Durmuyor zaman.

Korkuyorum yalnızlıktan,

Yalnız kalmaktan.

Üşüyorum.

Serin bir rüzgar esiyor,

İçime işliyor soğuk

Yok kimse sarılacak yanımda.

Ben yalnız, yürek yalnız.

Hala korkuyorum düşünemedikçe,

Yalnızım işte...

II-Hayat

Hayatı arıyorum,

Bu dünyada,

	Bu şehirde,

		Bu odada,

			Ta içimde...

Derin bir fırt sigaramdan,

Bir yudumda üstüne bira

Kapattım gözlerimi

Dalmak istiyorum düşüncelere...

YOK! 

Yalnızlık kapatmış bütün yollarımı.

Sağda, solda, önümde, arkamda...

Hep yalnızlık.

Neden? Niçin? 

Soramıyorum bu soruyu kendime,

Zaten bi cevabım yok ki,

Yalnızlık içinde arıyorum hayatı.

Cevapsız sorular ardından,

Kaybolmuş bir akşam,

Yine karışıyor yalnızlığımın içine.', 'I-Zaman Hızla geçiyor günler, Durmuyor saatler, Yetmiyor gücüm Durup düşünmeye. Hatırlamıyorum en son ne zaman Temizledim evimi, Sıcak bir y...', ARRAY['Türk Edebiyatı','Şiir','Ali Emek']::text[], 8.5, '{"poet":"Ali Emek","poet_slug":"ali-emek","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yalniz-zaman-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asıl Olan', 'asil-olan-ali-emek-3yf01', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sevda ki, bir mihenk taşı,

Hayatın içinde, yaşam içinde,

Kavganın içinde, emek içinde,

Peki ya ben nerde?', 'Sevda ki, bir mihenk taşı, Hayatın içinde, yaşam içinde, Kavganın içinde, emek içinde, Peki ya ben nerde?...', ARRAY['Türk Edebiyatı','Şiir','Ali Emek']::text[], 8.5, '{"poet":"Ali Emek","poet_slug":"ali-emek","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/asil-olan-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağınık Şiir', 'daginik-siir-oguzkan-bolukbasi-fbqie', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuğun sorduğu sorulara verilemeyen cevaplarda saklıyım ben

Dünyaya leyleklerin getirdiğine inancımı yitirdiğim güne kadar çocuktum

/“Niyeydi sana meylim? ” şaşırdığımı anlattığımda 

güldüklerinde anladım ters olan bir şeyler var/

Her sorduğum soruya verilen yanıtların yalan olabileceği kuşkusudur

Kafama sığdırmaya çalıştığım bunca kitaplar

/Ki onların da yalanlarını yakaladığımda

Ömrümün kısalığını fark ettim bilmek için her şeyi,/

Bilmeyi bu kadar meraklı bir arzu ile istememin sebebi aşktır desem komik gelebilir

Ama aşk hayata bağlanmanın ipini sarmış beline salınıp durur ortalıkta

Ben bu kalabalıkta yolumu nasıl bulurdum sana tutunmasaydım

/İşte aşkın gerçeğe götürmesi hikayesi böylece başladı/

Ben tüm anılarımı bir şarkıya sararım

Yani yaşadıklarım şarkılarla sarmaş dolaş 

Kimse bilmez geçmişin gerçek olduğunu

Geleceğinse hayal

Şimdiki zaman yok desem

/Yangın, 

Yanmamış evlerde konuşulmaz/

O halde öğrenmek istediğin her şey orada duruyor

Yaşanmışlıklarda…

O dokunulmaz sandığın her noktana değip geçen zaman

İfşaatta bulunur 

Ve yakalanmaz

Cevapları arıyorum

Yanlışı

Yanılgısı olmayan cevaplar

Zor olanın ne olduğunu anladım

Beni doğru cevaplara götürecek doğru soruları bulmalıyım evvela

/Var sandığım çok şeyin olmadığını öğreniyorum

Ya ben de yoksam/

Ben yoksam 

Bana ne benden

Senden, sizlerden

Ve evrenden

Ama

Bilmeyi bu kadar meraklı bir arzu ile istememin sebebi aşktır desem komik gelebilir', 'Bir çocuğun sorduğu sorulara verilemeyen cevaplarda saklıyım ben Dünyaya leyleklerin getirdiğine inancımı yitirdiğim güne kadar çocuktum /“N...', ARRAY['Türk Edebiyatı','Şiir','Oğuzkan Bölükbaşı']::text[], 8.5, '{"poet":"Oğuzkan Bölükbaşı","poet_slug":"oguzkan-bolukbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/daginik-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anne', 'anne-ali-emek-yv3sq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir küçük çocuk,

Ağlamaklı kocaman gözleri.

Hüznün bütün renkleri yüzünde,

Eski bir parka, üstünde.

Dikkatlice bakıyor etrafa,

Zamanı durdurmak istercesine.

Ağlıyor.

Bilmiyor ne yapması gerektiğini

Daha önce hiç yalnız kalmamıştı ki

Yanında hep annesi

Babasını hiç tanımadı

“abim” diyemedi, “abla” demedi hiç

Bir saat önce de, terk etti annesi.

Koşamadı hiç yemyeşil çayırlarda,

Bildiği bir nemli bodrum kat,

Ve soğuk kaldırımlardı.

Hep yağmur vardı yaşamında

Güneşi bilmedi kitaplarda dahi.

Bir annesinin gülüşü,

Bir kokusu.

Başladı yine yağmur

Çocuk ıslak, kaldırımda

Boynu öne eğik

Karışıyor gözyaşları tuzlu suya

İstediği tek şey,

Dökülüyor dudaklarından,

Bir kelime, 

Derinden,

Kimseye duyurmadan sessizce:

anne..', 'Bir küçük çocuk, Ağlamaklı kocaman gözleri. Hüznün bütün renkleri yüzünde, Eski bir parka, üstünde. Dikkatlice bakıyor etrafa, Zamanı durdur...', ARRAY['Türk Edebiyatı','Şiir','Ali Emek']::text[], 8.5, '{"poet":"Ali Emek","poet_slug":"ali-emek","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/anne-168-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin', 'gidisin-huseyin-kantar-aklpp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ağlıyorsun çaresizce,

unutulmuş yeminler geliyor aklına,

susuyorsun,

kurumuş bir dalın son yaprağı aralıyor perdenin arasını,

gün yüzüne vuruyor,

çekip gidişini.....', 'ağlıyorsun çaresizce, unutulmuş yeminler geliyor aklına, susuyorsun, kurumuş bir dalın son yaprağı aralıyor perdenin arasını, gün yüzüne vur...', ARRAY['Türk Edebiyatı','Şiir','Hüseyin Kantar']::text[], 8.5, '{"poet":"Hüseyin Kantar","poet_slug":"huseyin-kantar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gidisin-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özlenen', 'ozlenen-i-smail-sahin-tta0q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni yırtık bir kağıtta, 

açıklanıp da anlatılmamış gizemlerde bıraktım. 

Bana küfürler ettim, dövdüm. 

Beni günlerce aç bırakıp, 

buruşturup kaldırım kenarında çamura attım. 

Artık bir korkağım... 

Senden yeterince korkmadığım için,

şimdi korkularımı güçlendi; 

Kuyruğunu sıkıştırıp kaçan bir köpek gibi 

kaçıyorum zaaflar yaratacak sevgilerden.

Hayat bir koridordur sevgilim 

kristal heykellerle doldurduğumuz. 

Düşürmeden, 

kimseleri kırmadan  geçmek lazım gelen. 

Tüm heykellerimi kırdım.

Kimsesizim 

ama istediğim gibi koşabiliyorum hayatta. 

Beni de o heykellerle beraber kırdım. 

Ben de umrumda değil artık.

İnsan; kaybedecek birşeyi olmayınca 

daha güçlü duruyor insanların karşısında.

Kendimi ikiye ayırdım 

güçsüz olanı dövdüm.

O yanım hala seni arar. 

Karşıdan karşıya geçerken 

belini arar ellerim 

sanki sen geçirirdin beni karşıya. 

Tuzlu makarnalar ister canım 

ve ocakta beklemeden kahve yapıyorum diye azarlanmak. 

Lokanta, markette ya da bir mağazada 

rezil olmak istiyorum yine. 

Paytak yürüyüşünü, 

kaba kelimelerini özlüyorum. 

O cahil, ilkel ruhunu, 

senin aptal çocukluğunu özlüyorum.

Sürekli sırt çantanı taşırdın, 

almak isterdim; 

sen bana kıyamazdın 

ben de sana. 

Yürürken uzanılacak omuzlar arar kollarım, 

ölmek için sallanıyorlar.

Sensizken yenilirdim hep okeyde, 

sen bilmezdin zaten 

ama seninle hiç yenilmezdik. 

Sana “bana güven” mi demek istiyordum bilmem.

Ayaklarını alırdım avuçlarıma

 –çorapların kirli olsa dahi- 

sarardım o küçücük ayaklarını. 

Seni gözüm kapalı 

sadece o ince uzun ayak parmaklarından dahi tanırım. 

Odam yine sen koksun ister canım. 

Odamı hep sen geleceksin diye 

temiz, düzenli tutardım. 

Her şiirimi sen okuyacaksın diye yapıştırırdım duvarlara. 

Yine ayaklarımın koktuğunu söylemesini, 

bağrılmasını istiyorum.

Ama beni senden başka kimse azarlayamaz ki! 

Mideni abur-cuburla doldurmanı, 

yemekler yiyip de doymamanı 

yine de diyetinden bahsetmeni arıyorum.

İkimizde acı çekerdik. 

Sen yolu bilmezdin, 

ben bilirdim ama gidemezdim. 

Ki gidebilsem sen hiç olmazdın.

Dediğim gibi, 

beni yırtık bir kağıtta, 

açıklanıp da anlatılmamış bir gizemde bıraktım. 

Küfrettim, dövdüm, kovdum 

beni aşkıyla beraber.

Şimdi güçlüyüm. 

İnandığım tüm felsefi kuramlar gibi. 

Şimdi daha da güçlüyüm 

seninle beraber kimseleri sevmediğim için.', 'Beni yırtık bir kağıtta,  açıklanıp da anlatılmamış gizemlerde bıraktım.  Bana küfürler ettim, dövdüm.  Beni günlerce aç bırakıp,  buruşturu...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":73,"source_url":"https://www.antoloji.com/ozlenen-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüyorum', 'oluyorum-nalan-kahraman-ewvvz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Saat kaç biliyor musun? 

Gecenin bir yarısı.

Gündüzüm yetmezmiş gibi

Gecede benimlesin

Hayallerimde olduğun gibi

Rüyalarımda da……

Kokunla,

Yatağımdaki sıcaklığınla….

İşte …

Gece odamda,yatağımda

Gündüz arabamda 

Masamdaki yemekte

Bardağımdaki suda

Hep seni görüp,seni kokluyorum.

Sigara,sigara diyorum

Günde üç paket…

Her dumanda senin hayalin beliriyor

Dumanlar yok olsa da

Hayalin bir türlü gitmiyor

Saat gecenin bir yarısı

Uyumak istiyorum sen,

Oturmak,düşünmek istiyorum sen,

İçmek istiyorum,kadehimde yine sen.

Bir gün yirmi dört saat 

Ve ben

Günün yirmi dört saati

Seni düşünüyorum,

Seni kokluyorum,

Seni içiyorum,

Seni istiyor,

Seni düşünüyorum,

Ve….

Hep seni bekliyorum.

Saat gecenin bir yarısı

Ben yine seninleyim

Sana yazıyorum,

Sana susuyorum,

Hava eksi beş derece

Odam boş bomboş,

Ellerim buz tutmuş,

Yatağım ise az önce ısındı,

Hayalin yanı başıma ilişince,

Kanımda ellerimde ısınmaya başladı.

Hayalin artık dokunuyor bana,

Senin gibi karşıma oturup

Alay etmiyor

Gülmüyor bana.

Bak artık sabah oluyor,

Güneş yavaş, yavaş kendini gösteriyor,

İnsanlar güneşe göre hareket ediyor.

Benim güneşimde,ayımda sensin.

Seninle doğduğum bu dünya da

Senin hayalinle

Yavaş,yavaş ölüyorum………', 'Saat kaç biliyor musun?  Gecenin bir yarısı. Gündüzüm yetmezmiş gibi Gecede benimlesin Hayallerimde olduğun gibi Rüyalarımda da…… Kokunla, Y...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kahraman']::text[], 8.5, '{"poet":"Nalan Kahraman","poet_slug":"nalan-kahraman","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/oluyorum-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnkİlap', 'i-nki-lap-mehme-arslan-4jxrr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'aradı

nasılsın dedi

''eksik'' diyemedim

keyfin nasıl dedi

''yarım'' diyemedim

telefonu kapattı

telefonu elinde tutan

depremde yıkılmış bi bina enkazıydı

böyle olmamalıyım

o beni her aradığında

yeni baştan yıkılmamalıyım

çekilmeliyim kuytu bi köşeye

köpek misali yaramı

yalaya yalaya sağaltmalıyım

22/09/2005

* köpekleşmek', 'aradı nasılsın dedi ''eksik'' diyemedim keyfin nasıl dedi ''yarım'' diyemedim telefonu kapattı telefonu elinde tutan depremde yıkılmış bi bina e...', ARRAY['Türk Edebiyatı','Şiir','Mehme Arslan']::text[], 8.5, '{"poet":"Mehme Arslan","poet_slug":"mehme-arslan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/inkilap-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İmza', 'bir-i-mza-tekin-koc-m1yep', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ben senin sevdanın yorgunuyum

Ve hala yaşadığımız gecelerin esiri

Kurtulamadım bu yorgunluktan 

Bitmedi mahkumluğum 

Hayatım senin eserin

Altında ise sadece bir imza yerin

At artık imzayı git burdan sevgilim', 'Ben senin sevdanın yorgunuyum Ve hala yaşadığımız gecelerin esiri Kurtulamadım bu yorgunluktan  Bitmedi mahkumluğum  Hayatım senin eserin Al...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-imza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman Yok', 'zaman-yok-nursen-buluc-0hvbg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sen bana dost ol

Ben sana destek

Beraber atalım dertleri

Tek tek

Biliyorsun vakitte geç

Fazla zaman yok

Başlamak gerek

Sevgi ve dürüstlükle', 'Sen bana dost ol Ben sana destek Beraber atalım dertleri Tek tek Biliyorsun vakitte geç Fazla zaman yok Başlamak gerek Sevgi ve dürüstlükle...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/zaman-yok-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir Sana', 'bu-siir-sana-i-smail-sahin-tw69j', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni sevdiği gibi

gönül başkasına da yanar

ama başka birisi

sevemez seni benim kadar

anlattımdı ya:

dağları deldiren yar değildi

Ferhat'' ın yüreğine eridi dağlar

Kays aşka mecnun bir yiğitti

sevgi bizde değil bende yaşar

sandın ki yıkıldım ayaklarında

aldanma,

yel kayadan sadece toz alabilir *

gönül bir başkasına da yanar

ama başka birisi

sevemez seni benim kadar

* Bir halk deyişi', 'seni sevdiği gibi gönül başkasına da yanar ama başka birisi sevemez seni benim kadar anlattımdı ya: dağları deldiren yar değildi Ferhat'' ın ...', ARRAY['Türk Edebiyatı','Şiir','İsmail Şahin']::text[], 8.5, '{"poet":"İsmail Şahin","poet_slug":"i-smail-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-siir-sana-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özledim', 'ozledim-tekin-koc-tstgz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sesini özledim

Konuştukça içimi rahatlatan

Ben seni özledim

Yanımdayken bütün dertlerimi unutturan

Gözlerini Özledim

Bir bakışınla içimde fırtınalar kopartan

Saçlarını özledim

Dokunduğumda içimi titreten

Ellerini özledim

Dokunduğumda ayaklarımı yerden kesen

Ama en çok

Ben senin sevgini özledim', 'Sesini özledim Konuştukça içimi rahatlatan Ben seni özledim Yanımdayken bütün dertlerimi unutturan Gözlerini Özledim Bir bakışınla içimde fı...', ARRAY['Türk Edebiyatı','Şiir','Tekin Koç']::text[], 8.5, '{"poet":"Tekin Koç","poet_slug":"tekin-koc","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ozledim-121-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YıLaNLı KaDıN', 'yilanli-kadin-mine-ozdemirtas-lvwo8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Git yoluna yılanlı kadın...! 

Düne kadar sadece aynalardaydın

Ezmedim başını diye mi şımardın...? 

Bu ne cüret...? 

ne oldu da

çatalıma,

kaşığıma

dilimin ucuna

bulandın...? 

bir anda

yatağıma,

yorganıma

saçlarıma

düşlerime

dadandın...? 

yoksa...? 

etin

kanın

canın

bir tutam da aklın

var mı saydın...? 

keşke.. bir bilene soraydın.

kim çeldi akılsızlığını

kime kandın...? 

seninle hiç işim olmaz

aynı yoldan geçemeyiz

aynı sudan içemeyiz

sen beni kendin mi sandın...? 

yazık

Bu defa

fena

aldandın...! 

22/09/2005 

(Bu şiir kadınlık genlerimize kodlanmış vırvırcı,dırdırcı,kaprisli,çekilmez ve baş edilemez cadılık yönümüze'' Bir meydan okumadır'''': =))', 'Git yoluna yılanlı kadın...!  Düne kadar sadece aynalardaydın Ezmedim başını diye mi şımardın...?  Bu ne cüret...?  ne oldu da çatalıma, kaş...', ARRAY['Türk Edebiyatı','Şiir','Mine Özdemirtaş']::text[], 8.5, '{"poet":"Mine Özdemirtaş","poet_slug":"mine-ozdemirtas","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/yilanli-kadin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Ne Kadar Bendesin', 'sen-ne-kadar-bendesin-filiz-turan-vuvhy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel desem sana bir gün

Ardına bakmadan çıkar gelir misin

Tut ellerimden gidelim desem

Bilinmez diyarlara benimle gelir misin

Sev desem sana bir gün

Hiç düşünmeden sever misin

Al bu yürek senin olsun desem

Sevgimle dolu yüreğimi ister misin

Ey yar söyler misin

Sen ne kadar bendesin? 

sana seslensem  bir gün 

Kaf dağının ardından sesimi duyar mısın

Uzatsam ellerimi çok uzaklardan

Uzanıp ellerimi sende tutar mısın

Geleceğim desem sana bir gün

Bir ömür beni  bekler misin

Hiç karşılıksız delice

Benim sevdiğim gibi sever misin

Ey yar söyler misin

Sen ne kadar bendesin? 

22  eylül 2005', 'Gel desem sana bir gün Ardına bakmadan çıkar gelir misin Tut ellerimden gidelim desem Bilinmez diyarlara benimle gelir misin Sev desem sana ...', ARRAY['Türk Edebiyatı','Şiir','Filiz Turan']::text[], 8.5, '{"poet":"Filiz Turan","poet_slug":"filiz-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-ne-kadar-bendesin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Damga', 'damga-mehmet-bicik-rkff0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çıktı yola,

Bir seyyâh-ı fakîr…

Gezdi yıllarca

Diyar diyar…

Anadolu ellerinde

Bulamadı tutunacak yer…

Erzurum’a uğradı,

Oynadı Dadaşlar’la bar…

Aydın’da halay çeker,

Efeler, zeybekler…

Horon’un başındadır,

Karadeniz’de uşaklar…

Eğribel,

Aşılmaz kar…

Antep’te dâne dâne,

Şirinnar…

Urfa Dağları''nda

Gezer ceylânlar…

Konya içinde 

Neleri saklar…

Meram’ı, Meram yapan,

Bahçeler, bağlar…

Unutulur mu hiç,

Yunuslar, Mevlânâlar…

Tokat yollarında

Takıldı ayağıma taşlar…

Ordu’nun dereleri

Hep yukarı akar…

Giresun uşakları,

Aksu’da keyif çatar…

Elazığlı gençler,

Çayda çıra oynar…

Muş’a gidenler,

Geriye dönmezler…

Ecdâdımız, Anadolu’ya,

Damgamızı vurmuşlar…

Dünya geçse karşımıza

Bizi buradan atamazlar…

Heveslenen alçaklar,

Sonunda avucunu yalar…

8 Nisan 1997, Ş. Karahisar', 'Çıktı yola, Bir seyyâh-ı fakîr… Gezdi yıllarca Diyar diyar… Anadolu ellerinde Bulamadı tutunacak yer… Erzurum’a uğradı, Oynadı Dadaşlar’la b...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Bicik']::text[], 8.5, '{"poet":"Mehmet Bicik","poet_slug":"mehmet-bicik","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/damga-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kediler', 'kediler-erdogan-ergin-nrp2b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bırak artık gitsin kediler,

Her biri birbirinden sevimliler,

İnsan değil bu, nerden bilsinler,

Senin etlerini çaldıklarını…

2002', 'Bırak artık gitsin kediler, Her biri birbirinden sevimliler, İnsan değil bu, nerden bilsinler, Senin etlerini çaldıklarını… 2002...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kediler-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Olmadığında', 'sen-olmadiginda-nursen-buluc-uvww9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Senin olmadıgın yerde, bana ne gerek neşe

Sen yanımdayken, aldırmam acı ve kedere

Haramdır bana, içtiğim su,aldıgım hava

Aradığımda,bulamazsam seni yanımda', 'Senin olmadıgın yerde, bana ne gerek neşe Sen yanımdayken, aldırmam acı ve kedere Haramdır bana, içtiğim su,aldıgım hava Aradığımda,bulamazs...', ARRAY['Türk Edebiyatı','Şiir','Nursen Buluc']::text[], 8.5, '{"poet":"Nursen Buluc","poet_slug":"nursen-buluc","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-olmadiginda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başörtülüm', 'basortulum-mehmet-celik-l8j9q', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mazlumun ahı kalmaz bunu bil bunu bil dünyada

Son pişmanlık fayda vermez bunu bil dünyada

Ne istersin ne istersin ulan ULAN çek elini tacımdan

O taclar tacı ki emreylemiş YARADAN

Kamusal alana başörtüsüz ladılar

Dargınım dünyaya beni niye saldılar

Başörtüsü ALLAH emri bunu söyler YARADAN

Bunu niye bilmezler söyle bana YARADAN

Başörtüsüz insan yaşar mı söyle bana? 

Şu güzelim dünyada niye zulmettin bana

Kabuksuz bir meyve yaratmış mı YARADAN? 

Bunu niye bilmezler söyle YARADAN

Dinini bilmeyen ŞEEREEFSİZ başörtüme karışır.

Bünah kazanmada birbiriyle yarışır

Mini etek, baş açık günahlıdır YARADAN.

Bunu niye bilmezler söyle bana YARADAN

Güzellik yarışması deyip kızımızı açtılar.

Sonrada bir çırpıda bir batağa saldılar

Du oyun BATININ amacıdır YARADAN

Bunu niye bilmezler söyle bana YARADAN

Nefis,Şeytan başörtünün düşmanıdır.

ÇELİK''im görüyorsun bu ne kötü beladır

Beladan uzak dur der YÜCE MEVLA YARADAN

Bunu niye bilmezler söyle bana YARADAN', 'Mazlumun ahı kalmaz bunu bil bunu bil dünyada Son pişmanlık fayda vermez bunu bil dünyada Ne istersin ne istersin ulan ULAN çek elini tacımd...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çelik']::text[], 8.5, '{"poet":"Mehmet Çelik","poet_slug":"mehmet-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/basortulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nefret', 'nefret-erdogan-ergin-i0t45', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Biliyor musunuz? Artık anladım,

İnsanların yaşamasının sırrını.

Sevgi, hoşgörü ve şefkat var içinde,

Birazcık da nefret.

Ama kirli kana gereksinim gibi,

Çamurun varlığı gibi bir şey nefret

O olmazsa eğer; 

Sevgi, hoşgörü ve şefkat,

Anlamsız ve gereksiz

Bilmem ki hangi hayra hikmet? 

2002', 'Biliyor musunuz? Artık anladım, İnsanların yaşamasının sırrını. Sevgi, hoşgörü ve şefkat var içinde, Birazcık da nefret. Ama kirli kana gere...', ARRAY['Türk Edebiyatı','Şiir','Erdoğan Ergin']::text[], 8.5, '{"poet":"Erdoğan Ergin","poet_slug":"erdogan-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/nefret-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Masaldı Herşey Yaşamak Gibi...', 'bir-masaldi-hersey-yasamak-gibi-ozgur-celik-zoc5q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'hep bir masal gibi yaşadık seninle,

gerçek olmayı hiç başaramadık

ben Don Kişot  oluyordum

sen yel değirmenleri

savaşıyorduk seninle

kaybeden hep ben oluyordum.

sonra sen Pinokyo oluyordun

yalanlar söylüyordun bana

burnun hiç uzamıyordu ama

ben isimsiz şövalye

sen ejderhaların koruduğu bir kalede

tüm cesaretimle kurtarıyordum seni

öpmeye hiç cesaret edemiyordum ama

sen poliyana

mutlu olacak birşeyler buluyordun illa

ben hep karamsar

imreniyordum sana

dedim ya; 

hep bir masal gibi yaşadık seninle

gerçek olmayı hiç başaramadık.

sen kaf dağı kadar uzaktın bana

ben zümrüd-ü anka

masallar mutlu biterdi oysa

mutlu son enaz senin kadar uzak 

bu sonu olmayan masala...', 'hep bir masal gibi yaşadık seninle, gerçek olmayı hiç başaramadık ben Don Kişot  oluyordum sen yel değirmenleri savaşıyorduk seninle kaybede...', ARRAY['Türk Edebiyatı','Şiir','Özgür Çelik']::text[], 8.5, '{"poet":"Özgür Çelik","poet_slug":"ozgur-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-masaldi-hersey-yasamak-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmralı Köpeği', 'i-mrali-kopegi-mehmet-celik-e0nha', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne ant içmiştim bu dünyaya gelince

Şehit MEHMET''im vücudunu görünce

İmralı imralı ''KÖPEĞİ'' bir elime düşünce

O yağlı urganla asmaz mıyım beyler? 

Şehidimin anası saçın başın yolarken

O minicik yavrusu naaşına bakarken

 Milletimin gözyaşı birdamlacık durmazken

O yağlı urgala asmaz mıyım beyler? 

Maraş''taki BEYOĞLU şehidini gömmeden

Beyoğlu''nun gözyaşı o toprağa düşmeden 

Bencileyin bu düyadan göçmeden

O yağlı urganla samaz mıyım beyler? 

Ulan APO ulan APO bu kellene ant içtim

Senin gibi bir Pİ... kefenini ben biçtim

O da yetmez oda yetmez urganını ben seçtim.

O yağlı urganla asmaz mıyım beyler', 'Ne ant içmiştim bu dünyaya gelince Şehit MEHMET''im vücudunu görünce İmralı imralı ''KÖPEĞİ'' bir elime düşünce O yağlı urganla asmaz mıyım bey...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çelik']::text[], 8.5, '{"poet":"Mehmet Çelik","poet_slug":"mehmet-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/imrali-kopegi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yabancı', 'yabanci-yesim-akyuz-4gw02', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen kimdin? 

Hangi mevsim yaşadın bende? 

Ve ne zaman gittin? 

Sonra niye döndün geri? 

Sen kimdin? 

İsmin neydi? 

Ben mutlumuydum o zamanlar? 

Neler konuşurduk seninle? 

Yalnız bir sözünü hatırlarım

Zaman zaman beni ağlatır beni

Sonrası korkunç bir boşluk

Ve karanlık herşey,

Bir güzel cümlenin son noktası gibi.

Sen hangi mevsim yaşadın? 

İsmin neydi? 

Sarı yapraklar yığın yığın köşelerde

Ağaçlar çıplaklığına ağlıyor.

Artık göremiyorum yeşilleri kışmı gelmiş hani? 

Bir ağaç kovuğuna gizlenmiş,

Menekşenin yaban şarkısı.

Nisan yağmurları incitmiş onu,

Rüzgarlar kokusunu çalmış gitmiş.

Küsmüş menekşe bahara ormanda,

O yaban şarkısı kalmış yalnız.

İçli bir çiğan müziği gibi

Sen gelmişsin bir mevsim

Sen gitmişsin...

Sen sen mi? 

Sen kimsin

İsmin neydi?', 'Sen kimdin?  Hangi mevsim yaşadın bende?  Ve ne zaman gittin?  Sonra niye döndün geri?  Sen kimdin?  İsmin neydi?  Ben mutlumuydum o zamanla...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/yabanci-54-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sürür Beni', 'surur-beni-fevzi-kunucen-v4gsx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Mecmun oldum çöle düştüm

Destan oldum dile düştüm

Yaprak oldum sele düştüm

Sular sürür sürür beni

Dertli gönlüm divanedir

Yansın bırak pervanedir

Onun yurdu meyhanedir

Meyler sürür sürür beni

Sevda doldu bu ser''ime

Bir dert oldu içerime

Bilin dostlar yar yoluna

Mezar sürür sürür beni', 'Mecmun oldum çöle düştüm Destan oldum dile düştüm Yaprak oldum sele düştüm Sular sürür sürür beni Dertli gönlüm divanedir Yansın bırak perva...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Künüçen']::text[], 8.5, '{"poet":"Fevzi Künüçen","poet_slug":"fevzi-kunucen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/surur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sende Düşünüyormusun Beni', 'sende-dusunuyormusun-beni-yesim-akyuz-dsvpm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sende düşünüyormusun beni

Benim seni düşündüğüm gibi 

Sende alıyormusun resimlerimi ellerine

Dalıyormusun benim gibi hayallere

Görebilmek için beni

Dolaşırmısın uzun sokaklarda

Sorarmısın her gördüğüne 

Onu gördünmü? diye

Yaklaştığı zaman kahrolası akşam vakti

Bir buruk acı kaplıyormu içini

Bir gün daha görememek beni 

Kahrediyormu seni

Bir umut rüyada görebilmek onu diyerek 

Uzanıyormusun yatağa

Uyanıveriyormusun birden saatin sesiyle

Sende lanetler yağdırıyormusun saate

Ve ardından ağlıyormusun sende', 'Sende düşünüyormusun beni Benim seni düşündüğüm gibi  Sende alıyormusun resimlerimi ellerine Dalıyormusun benim gibi hayallere Görebilmek iç...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sende-dusunuyormusun-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolayı Neydi Bu Hayatın', 'kolayi-neydi-bu-hayatin-kamil-boyraz-sv7yq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kolayı ne bu dünyanın 

Hayatın içinde mi,toprağın içinde mi gömülü olmak 

Aşkın denizinde mi, yalnızlığın pençesinde mi boğulmak 

Kolaylığı neydi bu yaşamın 

İnananıp koyuvermek mi, kendini korkup saklanmak mı 

Güvenip anlatmak mı, içine atıp kahrolmak mı 

Kolayı neydi... 

Fedakarlık yapıp uğraşmakmı sonuna kadar 

Ortalığı karıştırıp saklanmak mı bir kenara 

İçin kan ağlarken gülebilmek mi 

Sahtekar olup ağlar görünmek mi 

Kolayı neydi... 

Saplamak mı hançeri düşünmeden 

Sabredip didinmek mi 

Herşeye boyun eğip pusmak mı 

Yoksa dimdik savaşmak mı sonuna kadar 

Kolay olan neydi bu hayatta 

Bırakıp gitmek mi herşeyi 

Terkedilip beklemek mi 

Çaba harcayıp uğraşmak mı 

Aldırışsız olup umursamamakmı herşeyi 

Kolayı neydi bu dünyanın 

Yaşamak mı,ölmek mi 

Ölmeden gömülmek mi toprağa 

Kör olmak mı görmek mi 

Görüp bilmemek mi 

Bildiğin halde düşünmemek mi 

Düşünerek yitirmek mi aklını 

Umursamayıp yitirmekmi insanlığını 

Hiç kolayı yok mu bu dünyanın 

Kolayı neydi bu yaşamın 

Neydi... 

Hatice Kelleli', 'Kolayı ne bu dünyanın  Hayatın içinde mi,toprağın içinde mi gömülü olmak  Aşkın denizinde mi, yalnızlığın pençesinde mi boğulmak  Kolaylığı ...', ARRAY['Türk Edebiyatı','Şiir','Kamil Boyraz']::text[], 8.5, '{"poet":"Kamil Boyraz","poet_slug":"kamil-boyraz","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/kolayi-neydi-bu-hayatin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küskünüm', 'kuskunum-yesim-akyuz-6w7wc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaşamak gelmiyor içimden artık

Öylesine dertli, öylesine üzgünüm

Bu dünya hiç bir tad vermiyor artık

Aldığım nefese, cana küskünüm

Herşey boş anlamsız şimdi gözümde

Bin öfke, binbir nefret herbir sözümde 

Yılların acısı  belli yüzümde

Aynada baktığım yüze küskünüm', 'Yaşamak gelmiyor içimden artık Öylesine dertli, öylesine üzgünüm Bu dünya hiç bir tad vermiyor artık Aldığım nefese, cana küskünüm Herşey bo...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kuskunum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '***Zindandayım***', 'zindandayim-i-sa-tekin-axfat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gün  doğmuyor burada

Yıldızlar bir bir düşmüş

Zifiri karanlık yerdeyim

Yenik düştük hücredeyim

Bedenim yorgun gözlerim yaşlı

Ben düştüm kimseler düşmesin

Seyran Bağlar''dayım 

Kafesli hücrede beş noludayım

Ah anam! 

Ben böyle değildim

Kanattılar yüreğimi

Ben bende değilim

Zindandayım

Elim kolum zincirli

Ah anam vurgun yedim 

Kanlı kelepçe kolumda 

Ben beş noludayım

Haber salın dört yana

Bu acıya kim dayana

Vurgun yedim be anam

Şimdi Seyran Bağlar''dayım

Kafesli hücrede beş noludayım

Gözümde kanlı yaşlar

Ciğerim beni haşlar

Yanı başımda yoldaşlar

Söyleyin dosta arkadaşa

Vurgun yedik be ana! 

Beş noludayım Zindandayım', 'Gün  doğmuyor burada Yıldızlar bir bir düşmüş Zifiri karanlık yerdeyim Yenik düştük hücredeyim Bedenim yorgun gözlerim yaşlı Ben düştüm kims...', ARRAY['Türk Edebiyatı','Şiir','İsa Tekin']::text[], 8.5, '{"poet":"İsa Tekin","poet_slug":"i-sa-tekin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/zindandayim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-yesim-akyuz-yw3kz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni yaşadım dün yine

Yağan yağmur damlaları altında..

Islandıkça! 

Seviyordum yağmuru

Öyle bir histi ki..

Sanki gözyaşlarımla ıslanıyordum

Öyle ya! 

Hani hatırlarmısın bir bahar mevsimi

Ayrılık saatinde..

Hasretimize beraberce gözyaşı dökmüştük

Vedalaştığımızda! 

Son defa gözlerimiz karşılaşmış, dudaklarımız

sanki bir daha hiç ayrılmayacakmış gibi 

Birleşmişti! 

Şimdi yağmur dahada hızlandı

Sırılsıklam oldum fakat,

Hiç aldırmıyorum, çünki..

Yağan yağmur her damlasıyla

Seni yaşatıyor,

         Seni', 'Seni yaşadım dün yine Yağan yağmur damlaları altında.. Islandıkça!  Seviyordum yağmuru Öyle bir histi ki.. Sanki gözyaşlarımla ıslanıyordum ...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmur-216-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gurbet', 'gurbet-yesim-akyuz-8k6ql', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bakarım günlerdir tozlu yollara

İçimde sel olup çağlıyor gurbet

Kementmidir? urganmıdır bilinmez

Beni kollarımdan bağlıyor gurbet

Gün oldu zamanı vurup öldürdüm

Sıla yollarına çok selam durdum

Mektupları ahla ofla doldurdum

Hasretli kalbimi dağlıyor gurbet

Yürüdü yolumdan bir yoldaş gibi

Sarıldı boynuma arkadaş gibi,

Bazen dertleşiriz  bir sırdaş gibi

Benimle birlikte ağlıyor gurbet.', 'Bakarım günlerdir tozlu yollara İçimde sel olup çağlıyor gurbet Kementmidir? urganmıdır bilinmez Beni kollarımdan bağlıyor gurbet Gün oldu z...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gurbet-95-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt Değildir Şiirim', 'agit-degildir-siirim-zeki-ergin-uxys4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '_______sevgili Kazım Koyuncunun ardından

kara bir bulut geldi önce

karşı kıyıdan

devri Özal zamanıydı

ardından

Karadenizin ak yürekli insanlarını

bir bir aldı aramızdan

ocaklara kara bulutlar çöktü

çay fındık lahana

tüm doğayı daun tuttu

bahar tüm sevecenliğiyle 

ısıtmaya başlarken

yüzün solmaya başladı önce

sesin kısılmaya

oysa direndin

33 yaşına kadar

nasıl haksızlıklara direndinse

kara dauna öyle direndin

yüreğin Karadenizce coşkun

ve sevgi yüklü

ve de türkülerin isyan

susmadı inadına

en cesur şiirler

hep yaka cebindeydi

en cesur türküler

en cesur türküler

_erenköy 30haz05

_dağlara ver sırtını yt:haz09', '_______sevgili Kazım Koyuncunun ardından kara bir bulut geldi önce karşı kıyıdan devri Özal zamanıydı ardından Karadenizin ak yürekli insanl...', ARRAY['Türk Edebiyatı','Şiir','Zeki Ergin']::text[], 8.5, '{"poet":"Zeki Ergin","poet_slug":"zeki-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/agit-degildir-siirim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Beni Kavuşturur', 'olum-beni-kavusturur-mehmet-celik-gv1t2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ölmek ister naçar Çelik

Üç biçardan çekti Çelik

KARDELEN''i üzmez Çelik

Ölüm beni kavuşturur

Aşk aleme dalmıştım ben

Bir çırpıda yanmıştım ben

Acı sevda çekmiştim ben

Ölüm beni kavuşturur

Aşk ateşiyle yanar bu aşk

Sevgisiyle tüter bu aşk

Yağlı kurşun yedi bu aşk

Ölüm beni kavuşturur

Sutan''ımı severdim ben

Sevda sözü söylerdim ben

Aşk ateşi olurdum ben

Ölüm beni kavuşturur

Kumral saçlım ela gözlüm

Aşkım olan birtek sözlüm

Kara sevda çeken gözlüm

Ölüm beni kavuşturur.

Bahçemde çiçek solduramam

Bir zerre toz konduramam

Acı seda çektiremem

Ölüm beni kavuşturur

Aşk dediğin cesarettir

Gel gönlümde yer ettir.

Sevdalıma bir söz ettir

Ölüm beni kavuşturur

İmbik imbik kanar idim

Bir çırpıda yanar idim

Acı sevda çeker idim

Ölüm beni kavuşturur

Gönül kuşu sevda kuşum 

Soframdaki sevda aşım

Böyle bir aşk görmez başım

Ölüm beni kavuşturur', 'Ölmek ister naçar Çelik Üç biçardan çekti Çelik KARDELEN''i üzmez Çelik Ölüm beni kavuşturur Aşk aleme dalmıştım ben Bir çırpıda yanmıştım be...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Çelik']::text[], 8.5, '{"poet":"Mehmet Çelik","poet_slug":"mehmet-celik","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/olum-beni-kavusturur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazan', 'hazan-yesim-akyuz-prv4p', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Mutluluksa muradın, neredeydin bunca zaman

Seneler saçlarıma ak dökmeden gelmeliydin

Şehre koyu karanlık, yüce dağlara duman

Vücuda ihtiyarlık çökmeden gelmeliydin.

Zaman denen değirmen öğütmeden ömrümü,

Izdırap belimi bükmeden gelmeliydin

Ilık sevda rüzgarı terletmeden gönlümü

Fırtına son ağacı sökmeden gelmeliydin.', 'Mutluluksa muradın, neredeydin bunca zaman Seneler saçlarıma ak dökmeden gelmeliydin Şehre koyu karanlık, yüce dağlara duman Vücuda ihtiyarl...', ARRAY['Türk Edebiyatı','Şiir','Yeşim Akyüz']::text[], 8.5, '{"poet":"Yeşim Akyüz","poet_slug":"yesim-akyuz","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hazan-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İşte Öyle Bir Şey', 'i-ste-oyle-bir-sey-fidan-bulut-pd9f8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kör bir kuyu gibiyim,

Körü körüne kabullenişlere.

Sorgusuz almışım verileni, verilmeyeni

Yine sunarak sorgusuz derinleri.

Dibini bulmak zormuş kuyumun,

Erememişliği yaşamış, yaşatmışım.

Bahar bahçelerde dolu fırtına yağdırıp,

Çamur bataklarda nilüferler açtırmışım.

Ben yüzeye kürek cefasında,

Dibimde sefa seyri hayatlar barındırmışım.

Şaşılacak memnuniyetlerde cemil cümle,

Bir ben sıyrılmalı çabalarda boğulmuşum.

Peri kanadından yumruklar düğümlü,

Nefesime çit misali.

Üzerine yağmurlar yağmıyor ki; 

Kirpiklerim çölde kavruk.

Çarkı kopuk, dümensiz gemilerim,

Okyanuslar çağırıyor şimdi

Gidemem kiii.......

Yaksam, küskün göz kapaklarım yumamam ki.

Her kazanca güçlüyken olanca hırsımla,

Bir tık, bir atış peşine ziyan hıncım.

Geçirmişken candamarına tırnaklarımı var oluşun,

                            Bir meltem gölgesi zayıflığımda yitmişim........', 'Kör bir kuyu gibiyim, Körü körüne kabullenişlere. Sorgusuz almışım verileni, verilmeyeni Yine sunarak sorgusuz derinleri. Dibini bulmak zorm...', ARRAY['Türk Edebiyatı','Şiir','Fidan Bulut']::text[], 8.5, '{"poet":"Fidan Bulut","poet_slug":"fidan-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/iste-oyle-bir-sey-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle güle git.', 'gule-gule-git-zeynep-aydinlioglu-v3n1s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '----- 

Yaptıgın en güzel şey, gidiyorum demek, 

Git arkadaşım git,dönmemek üzere git. 

Acı tatlı paylaşılmış ne varsa unut,git. 

Sakın arkana bakma, 

Mazıyı silerek git. 

İçilen kahvenın hatrını unut, 

Sıcak sohbetlerımızı,hiç hatırlama, 

Bakışlardan okudugumuz sıkıntılı anlarımızı unut, 

Sevgiyle anma sakın,hepsını unut git. 

Hanı agladıgımız anı, başını omzuma yasladıgın günü, 

Canı yürekten (DOSTUMSUN)  dedigin günü unut. 

Yaptıgın en güzel sey,gidiyorum demek, 

Gıt dostum maziyi silerek git.', '-----  Yaptıgın en güzel şey, gidiyorum demek,  Git arkadaşım git,dönmemek üzere git.  Acı tatlı paylaşılmış ne varsa unut,git.  Sakın arkan...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Aydınlıoğlu']::text[], 8.5, '{"poet":"Zeynep Aydınlıoğlu","poet_slug":"zeynep-aydinlioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gule-gule-git-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
