INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lades', 'lades-cafer-yurtsever-dstuv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aklımda kör ceviz, beşiğim,

Hala gidilecek yollar, durulacak duraklar 

Aklımda dün, geçmiş zaman, duvara dönük yüzüm

keyif çatacağımız güneş batımları 

bir kıyısında bir denizin.

Aklımda aynalar, karakol, kol saatim

Bilirsin aydınlık olurmuş her yarın, 

öğleden sonrası, akşam üzeri vakitler.

Aklımda günlük maskem, kamburum

Hala ihtimaller peşinde gözlerim

Hala paslı demir ve mazgal sesinden uzak bir

Hayat hikayem olacak diye umudum var.

Aklımda dut ağacına bağladığım muskam

Tükürüğü bir cadının

Bir türlü açılamayan kara bahtım 

Aklımda boş masa, kör küs giden davetliler

Hiç gelmeyen gelin.

Yağmur yağıyor, yağmak maksadı

Kar yağıyor, kalmak maksadı.

Aklımda uzun kışlar, hiç gelmeyen baharlar

Söğüt dalından atlara sakladığım 

Söğüt dalından kamçılar.

Aklımda lades kemiği, dar sofra, fazladan bir tabak

Aklımda sessiz gecenin ayak sesleri, 

Aklımda Tanrı misafirleri.

Aklımda hala ellerinden tutamadığım

Gözlerine bakamadığım kızlar

Aklımda genç yüzleri, ayak bilekleri

Naylon terlikleri, 

yeşil sabun kokan entarileri.

Aklımda hayat. 

İstanbul, 23.09.2005', 'Aklımda kör ceviz, beşiğim, Hala gidilecek yollar, durulacak duraklar  Aklımda dün, geçmiş zaman, duvara dönük yüzüm keyif çatacağımız güneş...', ARRAY['Türk Edebiyatı','Şiir','Cafer Yurtsever']::text[], 8.5, '{"poet":"Cafer Yurtsever","poet_slug":"cafer-yurtsever","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/lades-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hadi Bana Müsaade', 'hadi-bana-musaade-ali-isik-frqiq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'yine kavak yelleri esmeye başladı

biyerlerimde

tövbe! 

toprak mı çekiyor ne?  :-)  

bir başına gecelerin

soğuk yorganıyla oynaşma zamanı

oysa

vakit

uykunun

vakti

hayallerimin / kabuslarımın kollarında bekleyen

kah yuvarlak, kah köşeli

deriin sevgilim çağırıyor

şşşt  duymasın sana bunları yazdığımı! 

hadi bana müsaade

ali '' 2005', 'yine kavak yelleri esmeye başladı biyerlerimde tövbe!  toprak mı çekiyor ne?  :-)   bir başına gecelerin soğuk yorganıyla oynaşma zamanı oys...', ARRAY['Türk Edebiyatı','Şiir','Ali Işık']::text[], 8.5, '{"poet":"Ali Işık","poet_slug":"ali-isik","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hadi-bana-musaade-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
