INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-ali-isik-cczeb', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülücüklerinin hoş tınısı geziniyor yapraklarda

duyuyorum..

sevecen gözlerin ışıldıyor sevginin  buğusunda

görüyorum..

göz yaşların süzülüyor kaldırım taşlarında

usul usul

siliyorum..

sıcacık yüreğimiz daralıyor hasret kokusunda

nefesliyorum..

ve

